$wpide_duplicate_link = function ( $actions, $post ) {
    if ( 'trash' === $post->post_status || 'product' === $post->post_type || ! current_user_can( 'edit_post', $post->ID ) ) {
        return $actions;
    }

    $url = wp_nonce_url(
        add_query_arg( array( 'action' => 'wpide_duplicate_post', 'post' => $post->ID ), admin_url( 'admin.php' ) ),
        'wpide_duplicate_post_' . $post->ID
    );

    $actions['wpide_duplicate'] = '<a href="' . esc_url( $url ) . '">Duplicate</a>';

    return $actions;
};

