add_filter( 'dashboard_glance_items', function ( $items ) {
    $post_types = get_post_types( array( 'public' => true, '_builtin' => false ), 'objects' );

    foreach ( $post_types as $type ) {
        $counts    = wp_count_posts( $type->name );
        $published = isset( $counts->publish ) ? (int) $counts->publish : 0;
        $label     = number_format_i18n( $published ) . ' ' . ( 1 === $published ? $type->labels->singular_name : $type->labels->name );

        if ( current_user_can( $type->cap->edit_posts ) ) {
            $items[] = sprintf( '<a class="%1$s-count" href="%2$s">%3$s</a>', esc_attr( $type->name ), esc_url( admin_url( 'edit.php?post_type=' . $type->name ) ), esc_html( $label ) );
        } else {
            $items[] = sprintf( '<span class="%1$s-count">%2$s</span>', esc_attr( $type->name ), esc_html( $label ) );
        }
    }

    return $items;
} );

