add_filter( 'rest_authentication_errors', function ( $result ) {
    if ( true === $result || is_wp_error( $result ) || is_user_logged_in() ) {
        return $result;
    }

    // Route prefixes that stay public. Add the namespaces your forms, shop or plugins use.
    $public = array( '/contact-form-7/', '/wc/store/', '/oembed/' );
    $route  = isset( $GLOBALS['wp']->query_vars['rest_route'] ) ? (string) $GLOBALS['wp']->query_vars['rest_route'] : '';

    foreach ( $public as $prefix ) {
        if ( 0 === strpos( $route, $prefix ) ) {
            return $result;
        }
    }

    return new WP_Error( 'rest_login_required', 'The REST API is only available to logged-in users.', array( 'status' => rest_authorization_required_code() ) );
} );

