$wpide_login_limit = array(
    'attempts' => 5,
    'window'   => 15 * MINUTE_IN_SECONDS,
);

$wpide_login_key = function () {
    $ip = isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : 'unknown';

    return 'wpide_login_fail_' . md5( $ip );
};

add_filter( 'authenticate', function ( $user, $username ) use ( $wpide_login_limit, $wpide_login_key ) {
    if ( empty( $username ) ) {
        return $user;
    }

    if ( (int) get_transient( $wpide_login_key() ) >= $wpide_login_limit['attempts'] ) {
        return new WP_Error(
            'wpide_too_many_attempts',
            sprintf( '<strong>Error:</strong> Too many failed login attempts. Please try again in %d minutes.', (int) ceil( $wpide_login_limit['window'] / MINUTE_IN_SECONDS ) )
        );
    }

    return $user;
}, 99, 2 );

add_action( 'wp_login_failed', function ( $username, $error = null ) use ( $wpide_login_limit, $wpide_login_key ) {
    if ( is_wp_error( $error ) && 'wpide_too_many_attempts' === $error->get_error_code() ) {
        return;
    }

    $key = $wpide_login_key();
    set_transient( $key, (int) get_transient( $key ) + 1, $wpide_login_limit['window'] );
}, 10, 2 );

add_action( 'wp_login', function () use ( $wpide_login_key ) {
    delete_transient( $wpide_login_key() );
} );

add_action( 'wp_login', function ( $user_login, $user ) {
    if ( ! user_can( $user, 'manage_options' ) ) {
        return;
    }

    $ip      = isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : 'unknown';
    $browser = isset( $_SERVER['HTTP_USER_AGENT'] ) ? sanitize_text_field( wp_unslash( $_SERVER['HTTP_USER_AGENT'] ) ) : 'unknown';
    $site    = wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES );

    $subject = sprintf( '[%s] Administrator login: %s', $site, $user->user_login );
    $message = sprintf(
        "The administrator account \"%s\" just logged in to %s.\n\nTime: %s\nIP address: %s\nBrowser: %s\n\nIf you do not recognize this login, change the password and review your users.",
        $user->user_login,
        home_url( '/' ),
        wp_date( 'Y-m-d H:i:s T' ),
        $ip,
        $browser
    );

    wp_mail( get_option( 'admin_email' ), $subject, $message );
}, 10, 2 );

