add_filter( 'preprocess_comment', function ( $commentdata ) {
    $min = 15;
    $max = 5000;

    $type = isset( $commentdata['comment_type'] ) ? $commentdata['comment_type'] : '';

    if ( ( '' !== $type && 'comment' !== $type ) || current_user_can( 'moderate_comments' ) ) {
        return $commentdata;
    }

    $text   = trim( wp_strip_all_tags( (string) $commentdata['comment_content'] ) );
    $length = function_exists( 'mb_strlen' ) ? mb_strlen( $text ) : strlen( $text );

    if ( $length < $min ) {
        wp_die( esc_html( sprintf( 'Your comment is too short. Please write at least %d characters.', $min ) ), 'Comment too short', array( 'response' => 400, 'back_link' => true ) );
    }

    if ( $length > $max ) {
        wp_die( esc_html( sprintf( 'Your comment is too long. Please keep it under %d characters.', $max ) ), 'Comment too long', array( 'response' => 400, 'back_link' => true ) );
    }

    return $commentdata;
} );

