add_shortcode( 'reading_time', function ( $atts ) {
    $atts = shortcode_atts( array(
        'wpm'   => 220,
        'label' => 'min read',
    ), $atts, 'reading_time' );

    $post = get_post();

    if ( ! $post ) {
        return '';
    }

    $words   = str_word_count( wp_strip_all_tags( strip_shortcodes( $post->post_content ) ) );
    $minutes = max( 1, (int) ceil( $words / max( 1, (int) $atts['wpm'] ) ) );

    return '<span class="reading-time">' . esc_html( $minutes . ' ' . $atts['label'] ) . '</span>';
} );

add_filter( 'the_content', function ( $content ) {
    $add_nofollow = false; // Set to true to also add rel="nofollow".

    if ( ! class_exists( 'WP_HTML_Tag_Processor' ) || false === stripos( $content, '<a ' ) ) {
        return $content;
    }

    $site_host = wp_parse_url( home_url(), PHP_URL_HOST );
    $tags      = new WP_HTML_Tag_Processor( $content );

    while ( $tags->next_tag( 'a' ) ) {
        $href = $tags->get_attribute( 'href' );

        if ( ! is_string( $href ) || ! preg_match( '#^https?://#i', $href ) ) {
            continue;
        }

        $host = wp_parse_url( $href, PHP_URL_HOST );

        if ( ! $host || strtolower( $host ) === strtolower( (string) $site_host ) ) {
            continue;
        }

        $rel   = $tags->get_attribute( 'rel' );
        $parts = is_string( $rel ) ? preg_split( '/\s+/', trim( $rel ) ) : array();
        $parts = array_merge( array_filter( $parts ), array( 'noopener', 'noreferrer' ) );

        if ( $add_nofollow ) {
            $parts[] = 'nofollow';
        }

        $tags->set_attribute( 'target', '_blank' );
        $tags->set_attribute( 'rel', implode( ' ', array_unique( $parts ) ) );
    }

    return $tags->get_updated_html();
}, 20 );

