    }

    if ( (int) get_the_modified_time( 'U' ) - (int) get_the_time( 'U' ) < DAY_IN_SECONDS ) {
        return $content;
    }

    return '<p class="last-updated"><em>Last updated on ' . esc_html( get_the_modified_date() ) . '</em></p>' . $content;
} );

add_shortcode( 'copyright_years', function ( $atts ) {
    $atts    = shortcode_atts( array( 'start' => '' ), $atts, 'copyright_years' );
    $current = (int) wp_date( 'Y' );
    $start   = (int) $atts['start'];

    if ( ! $start ) {
        $first = get_posts( array(
            'numberposts' => 1,
            'post_status' => 'publish',
            'orderby'     => 'date',
            'order'       => 'ASC',
            'fields'      => 'ids',
        ) );
        $start = $first ? (int) get_the_date( 'Y', $first[0] ) : $current;
    }

    $years = $start < $current ? $start . '&ndash;' . $current : (string) $current;

    return '&copy; ' . $years . ' ' . esc_html( get_bloginfo( 'name' ) );
} );

add_action( 'save_post', function ( $post_id, $post ) {
    if ( wp_is_post_revision( $post_id ) || wp_is_post_autosave( $post_id ) || 'auto-draft' === $post->post_status ) {
        return;
    }

    if ( ! post_type_supports( $post->post_type, 'thumbnail' ) || has_post_thumbnail( $post_id ) ) {
        return;
    }

    if ( preg_match( '/wp-image-(\d+)/', $post->post_content, $match ) && wp_attachment_is_image( (int) $match[1] ) ) {
        set_post_thumbnail( $post_id, (int) $match[1] );
        return;
    }

    $images = get_attached_media( 'image', $post_id );

    if ( $images ) {
        $first = reset( $images );
        set_post_thumbnail( $post_id, $first->ID );
    }
}, 10, 2 );

