add_filter( 'wp_check_filetype_and_ext', function ( $data, $file, $filename, $mimes ) {
    if ( ! current_user_can( 'manage_options' ) ) {
        return $data;
    }

    $check = wp_check_filetype( $filename, $mimes );

    if ( 'svg' !== $check['ext'] ) {
        return $data;
    }

    $contents = is_readable( $file ) ? (string) file_get_contents( $file, false, null, 0, 2 * MB_IN_BYTES ) : '';

    if ( '' === $contents || preg_match( '/<script|\son[a-z]+\s*=|javascript:|<foreignObject/i', $contents ) ) {
        return array( 'ext' => false, 'type' => false, 'proper_filename' => false );
    }

    $data['ext']  = 'svg';
    $data['type'] = 'image/svg+xml';

    return $data;
}, 10, 4 );

