add_action( 'add_attachment', function ( $attachment_id ) {
    if ( ! wp_attachment_is_image( $attachment_id ) ) {
        return;
    }

    if ( '' !== (string) get_post_meta( $attachment_id, '_wp_attachment_image_alt', true ) ) {
        return;
    }

    $alt = trim( preg_replace( '/[\s_-]+/', ' ', (string) get_the_title( $attachment_id ) ) );

    if ( '' !== $alt ) {
        update_post_meta( $attachment_id, '_wp_attachment_image_alt', sanitize_text_field( ucfirst( $alt ) ) );
    }
} );

add_action( 'template_redirect', function () {
    if ( ! is_attachment() ) {
        return;
    }

    $attachment = get_queried_object();
    $parent_id  = $attachment instanceof WP_Post ? (int) $attachment->post_parent : 0;
    $target     = ( $parent_id && 'publish' === get_post_status( $parent_id ) ) ? get_permalink( $parent_id ) : home_url( '/' );

    wp_safe_redirect( $target, 301 );
    exit;
} );

add_filter( 'sanitize_file_name', function ( $filename ) {
    $info      = pathinfo( $filename );
    $extension = isset( $info['extension'] ) && '' !== $info['extension'] ? '.' . strtolower( $info['extension'] ) : '';
    $name      = isset( $info['filename'] ) ? $info['filename'] : $filename;

    $name = remove_accents( $name );
    $name = strtolower( preg_replace( '/[^A-Za-z0-9]+/', '-', $name ) );
    $name = trim( $name, '-' );

    return ( '' === $name ? 'file' : $name ) . $extension;
} );

