add_action( 'manage_media_custom_column', function ( $column, $attachment_id ) {
    $meta = wp_get_attachment_metadata( $attachment_id );

    if ( 'wpide_filesize' === $column ) {
        $bytes = ! empty( $meta['filesize'] ) ? (int) $meta['filesize'] : 0;

        if ( ! $bytes ) {
            $file  = get_attached_file( $attachment_id );
            $bytes = ( $file && file_exists( $file ) ) ? (int) filesize( $file ) : 0;
        }

        echo $bytes ? esc_html( size_format( $bytes, 1 ) ) : '&mdash;';
    } elseif ( 'wpide_dimensions' === $column ) {
        echo ( ! empty( $meta['width'] ) && ! empty( $meta['height'] ) ) ? esc_html( $meta['width'] . ' x ' . $meta['height'] ) : '&mdash;';
    }
}, 10, 2 );

