add_filter( 'posts_where', function ( $where, $query ) {
    global $wpdb;

    if ( ! $query->is_main_query() || ! $query->is_feed() ) {
        return $where;
    }

    $minutes = 15;
    $cutoff  = gmdate( 'Y-m-d H:i:s', time() - $minutes * MINUTE_IN_SECONDS );

    return $where . $wpdb->prepare( " AND {$wpdb->posts}.post_date_gmt <= %s", $cutoff );
}, 10, 2 );

