$wpide_highlight_terms = function ( $text ) {
    if ( ! is_search() || ! in_the_loop() || ! is_string( $text ) ) {
        return $text;
    }

    $terms = array_filter( preg_split( '/\s+/', trim( get_search_query( false ) ) ), function ( $term ) {
        return strlen( $term ) > 1;
    } );

    if ( ! $terms ) {
        return $text;
    }

    $quoted  = array_map( function ( $term ) {
        return preg_quote( $term, '/' );
    }, $terms );
    $pattern = '/(' . implode( '|', $quoted ) . ')(?![^<]*>)/iu';
    $result  = preg_replace( $pattern, '<mark class="search-highlight">$1</mark>', $text );

    return null === $result ? $text : $result;
};

