// Post types that must have a featured image before they go live.
$wpide_require_image_types = array( 'post' );

foreach ( $wpide_require_image_types as $wpide_image_type ) {
    // Block editor (REST API) saves.
    add_filter( "rest_pre_insert_{$wpide_image_type}", function ( $prepared, $request ) {
        if ( false !== strpos( (string) $request->get_route(), '/autosaves' ) ) {
            return $prepared;
        }

        $status = isset( $prepared->post_status ) ? $prepared->post_status : get_post_status( (int) $request['id'] );

        if ( ! in_array( $status, array( 'publish', 'future' ), true ) ) {
            return $prepared;
        }

        if ( isset( $request['featured_media'] ) ) {
            $image = (int) $request['featured_media'];
        } else {
            $image = ! empty( $request['id'] ) ? (int) get_post_thumbnail_id( (int) $request['id'] ) : 0;
        }

        if ( $image > 0 ) {
            return $prepared;
        }

        return new WP_Error( 'wpide_featured_image_required', 'Please set a featured image before publishing.', array( 'status' => 400 ) );
    }, 10, 2 );
}

// Classic editor saves: keep the post as a draft and explain why.
add_filter( 'wp_insert_post_data', function ( $data, $postarr ) use ( $wpide_require_image_types ) {
    if ( ( defined( 'REST_REQUEST' ) && REST_REQUEST ) || empty( $postarr['ID'] ) || ! isset( $_POST['action'] ) || 'editpost' !== $_POST['action'] ) {
        return $data;
    }

    if ( ! in_array( $data['post_type'], $wpide_require_image_types, true ) || ! in_array( $data['post_status'], array( 'publish', 'future' ), true ) ) {
        return $data;
    }

    $image = isset( $_POST['_thumbnail_id'] ) ? (int) $_POST['_thumbnail_id'] : (int) get_post_thumbnail_id( (int) $postarr['ID'] );

    if ( $image > 0 ) {
        return $data;
    }

    $data['post_status'] = 'draft';

    add_filter( 'redirect_post_location', function ( $location ) {
        return add_query_arg( 'wpide_needs_image', 1, remove_query_arg( 'message', $location ) );
    } );

    return $data;
}, 10, 2 );

