add_action( 'admin_menu', function () {
    global $menu;

    if ( ! current_user_can( 'edit_others_posts' ) || ! is_array( $menu ) ) {
        return;
    }

    foreach ( $menu as $index => $item ) {
        if ( empty( $item[2] ) ) {
            continue;
        }

        if ( 'edit.php' === $item[2] ) {
            $post_type = 'post';
        } elseif ( 0 === strpos( $item[2], 'edit.php?post_type=' ) ) {
