            continue;
        }

        if ( ! post_type_exists( $post_type ) ) {
            continue;
        }

        $pending = (int) wp_count_posts( $post_type )->pending;

        if ( $pending > 0 ) {
            $menu[ $index ][0] .= sprintf( ' <span class="awaiting-mod count-%1$d"><span class="pending-count">%1$d</span></span>', $pending );
        }
    }
}, 999 );

