// Post types that get the bulk action.
$wpide_to_draft_types = array( 'post', 'page' );

foreach ( $wpide_to_draft_types as $wpide_draft_type ) {
    add_filter( "bulk_actions-edit-{$wpide_draft_type}", function ( $actions ) {
        $actions['wpide_to_draft'] = 'Move to draft';

        return $actions;
    } );

    // WordPress checks the bulk action nonce before this filter runs.
    add_filter( "handle_bulk_actions-edit-{$wpide_draft_type}", function ( $redirect, $action, $post_ids ) {
        if ( 'wpide_to_draft' !== $action ) {
            return $redirect;
        }

        $done = 0;

        foreach ( (array) $post_ids as $post_id ) {
            if ( current_user_can( 'edit_post', $post_id ) && 'draft' !== get_post_status( $post_id ) ) {
                $result = wp_update_post( array( 'ID' => (int) $post_id, 'post_status' => 'draft' ), true );
                $done  += is_wp_error( $result ) ? 0 : 1;
            }
        }

        return add_query_arg( 'wpide_drafted', $done, $redirect );
    }, 10, 3 );
}

