<p>Intro: what will the reader learn?</p>
<!-- /wp:paragraph -->

<!-- wp:heading -->
<h2 class="wp-block-heading">Main point</h2>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p></p>
<!-- /wp:paragraph -->",
);

add_filter( 'default_content', function ( $content, $post ) use ( $wpide_default_content ) {
    $type = $post ? get_post_type( $post ) : '';

    return ( '' === $content && isset( $wpide_default_content[ $type ] ) ) ? $wpide_default_content[ $type ] : $content;
}, 10, 2 );

// Column keys to remove: author, categories, tags, comments, date.
$wpide_remove_post_columns = array( 'comments', 'tags' );
$wpide_remove_page_columns = array( 'comments' );

add_filter( 'manage_posts_columns', function ( $columns ) use ( $wpide_remove_post_columns ) {
    return array_diff_key( $columns, array_flip( $wpide_remove_post_columns ) );
} );

add_filter( 'manage_pages_columns', function ( $columns ) use ( $wpide_remove_page_columns ) {
    return array_diff_key( $columns, array_flip( $wpide_remove_page_columns ) );
} );

add_filter( 'wp_terms_checklist_args', function ( $args ) {
    $args['checked_ontop'] = false;

    return $args;
} );

// How often to check, in seconds.
$wpide_missed_check_every = 5 * MINUTE_IN_SECONDS;

add_action( 'init', function () use ( $wpide_missed_check_every ) {
    if ( get_transient( 'wpide_missed_schedule_lock' ) ) {
        return;
    }

    set_transient( 'wpide_missed_schedule_lock', 1, $wpide_missed_check_every );

    $missed = get_posts( array(
        'post_type'        => 'any',
        'post_status'      => 'future',
        'date_query'       => array( array( 'column' => 'post_date_gmt', 'before' => gmdate( 'Y-m-d H:i:s' ) ) ),
        'numberposts'      => 10,
        'fields'           => 'ids',
        'suppress_filters' => true,
    ) );

    foreach ( $missed as $post_id ) {
        wp_publish_post( $post_id );
    }
}, 30 );

// Screen ID => columns hidden until the user changes Screen Options.
$wpide_default_hidden_columns = array(
    'edit-post' => array( 'tags', 'comments' ),
    'edit-page' => array( 'comments', 'author' ),
    'users'     => array( 'posts' ),
);

add_filter( 'default_hidden_columns', function ( $hidden, $screen ) use ( $wpide_default_hidden_columns ) {
    if ( $screen && isset( $wpide_default_hidden_columns[ $screen->id ] ) ) {
        $hidden = array_unique( array_merge( (array) $hidden, $wpide_default_hidden_columns[ $screen->id ] ) );
    }

    return $hidden;
}, 10, 2 );

add_action( 'set_object_terms', function ( $object_id, $terms, $tt_ids, $taxonomy ) {
    if ( 'category' !== $taxonomy || count( $tt_ids ) < 2 ) {
        return;
    }

    $default = (int) get_option( 'default_category' );
    $term    = get_term( $default, 'category' );

    if ( $term && ! is_wp_error( $term ) && in_array( (int) $term->term_taxonomy_id, array_map( 'intval', $tt_ids ), true ) ) {
        wp_remove_object_terms( $object_id, $default, 'category' );
    }
}, 10, 4 );

