add_action( 'admin_post_wpide_save_dashboard_notes', function () use ( $wpide_notes_capability ) {
    if ( ! current_user_can( $wpide_notes_capability ) ) {
        wp_die( 'You are not allowed to edit these notes.' );
    }

    check_admin_referer( 'wpide_save_dashboard_notes' );

    $notes = isset( $_POST['wpide_notes'] ) ? wp_kses_post( wp_unslash( $_POST['wpide_notes'] ) ) : '';
    update_option( 'wpide_dashboard_notes', $notes, false );

    wp_safe_redirect( admin_url( 'index.php' ) );
    exit;
} );

