add_action( 'wp_dashboard_setup', function () {
    if ( ! current_user_can( 'manage_options' ) ) {
        return;
    }

    wp_add_dashboard_widget( 'wpide_cron_events', 'Scheduled Tasks', function () {
        $crons = _get_cron_array();

        if ( empty( $crons ) ) {
            echo '<p>No scheduled tasks.</p>';
            return;
        }

        $now   = time();
        $shown = 0;

        echo '<table class="widefat striped"><tbody>';
        foreach ( $crons as $timestamp => $hooks ) {
            foreach ( $hooks as $hook => $events ) {
                foreach ( $events as $event ) {
                    if ( ++$shown > 12 ) {
                        break 3;
                    }
                    $late = $timestamp < $now - 10 * MINUTE_IN_SECONDS;
                    printf(
                        '<tr><td><code>%1$s</code><br><small>%2$s</small></td><td style="text-align:right;%3$s">%4$s</td></tr>',
                        esc_html( $hook ),
                        esc_html( ! empty( $event['schedule'] ) ? $event['schedule'] : 'once' ),
                        $late ? 'color:#d63638;font-weight:600' : '',
                        esc_html( ( $timestamp < $now ? 'overdue by ' : 'in ' ) . human_time_diff( $timestamp, $now ) )
                    );
                }
            }
        }
        echo '</tbody></table>';
    } );
} );

