$wpide_login_page_path = '/login/';

add_action( 'login_init', function () use ( $wpide_login_page_path ) {
    $action = isset( $_REQUEST['action'] ) ? sanitize_key( $_REQUEST['action'] ) : 'login';
    $method = isset( $_SERVER['REQUEST_METHOD'] ) ? strtoupper( sanitize_key( $_SERVER['REQUEST_METHOD'] ) ) : 'GET';

    // Leave logout, password reset, registration, re-authentication and form posts on wp-login.php.
    if ( 'login' !== $action || 'GET' !== $method || isset( $_GET['interim-login'] ) || isset( $_GET['reauth'] ) || isset( $_GET['loggedout'] ) || isset( $_GET['checkemail'] ) ) {
        return;
    }

    $target = home_url( $wpide_login_page_path );

    if ( ! empty( $_GET['redirect_to'] ) ) {
        $target = add_query_arg( 'redirect_to', rawurlencode( wp_validate_redirect( wp_unslash( $_GET['redirect_to'] ), admin_url() ) ), $target );
    }

    wp_safe_redirect( $target );
    exit;
} );

add_action( 'wp_login_failed', function () use ( $wpide_login_page_path ) {
    $referer = wp_get_referer();

    if ( ! $referer || false === strpos( $referer, $wpide_login_page_path ) || 'wp-login.php' !== ( isset( $GLOBALS['pagenow'] ) ? $GLOBALS['pagenow'] : '' ) ) {
