add_filter( 'authenticate', function ( $user ) {
    // Only the wp-login.php form; XML-RPC, REST and other login forms are left alone.
    if ( 'wp-login.php' !== ( isset( $GLOBALS['pagenow'] ) ? $GLOBALS['pagenow'] : '' ) || empty( $_POST['log'] ) ) {
        return $user;
    }

    $answer = isset( $_POST['wpide_math'] ) ? (int) $_POST['wpide_math'] : -1;
    $time   = isset( $_POST['wpide_math_time'] ) ? (int) $_POST['wpide_math_time'] : 0;
    $token  = isset( $_POST['wpide_math_token'] ) ? sanitize_text_field( wp_unslash( $_POST['wpide_math_token'] ) ) : '';

    $valid = $time > time() - HOUR_IN_SECONDS && hash_equals( hash_hmac( 'sha256', $answer . '|' . $time, wp_salt( 'nonce' ) ), $token );

    return $valid ? $user : new WP_Error( 'wpide_math', '<strong>Error:</strong> Please answer the math question correctly.' );
}, 25 );

// Trusted IPs. Single addresses or IPv4 ranges in CIDR form (203.0.113.0/24).
$wpide_admin_ips = array( '127.0.0.1', '203.0.113.0/24' );

$wpide_ip_in_list = function ( $ip, $list ) {
    foreach ( $list as $entry ) {
        if ( false === strpos( $entry, '/' ) ) {
            if ( $ip === $entry ) {
                return true;
            }
            continue;
        }

        list( $subnet, $bits ) = explode( '/', $entry, 2 );

        if ( filter_var( $ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4 ) && filter_var( $subnet, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4 ) ) {
            $mask = -1 << ( 32 - (int) $bits );
            if ( ( ip2long( $ip ) & $mask ) === ( ip2long( $subnet ) & $mask ) ) {
                return true;
            }
        }
    }

    return false;
};

add_filter( 'authenticate', function ( $user ) use ( $wpide_admin_ips, $wpide_ip_in_list ) {
    if ( ! ( $user instanceof WP_User ) || ! user_can( $user, 'manage_options' ) ) {
        return $user;
    }

    $ip = isset( $_SERVER['REMOTE_ADDR'] ) ? (string) $_SERVER['REMOTE_ADDR'] : '';

    if ( $wpide_ip_in_list( $ip, $wpide_admin_ips ) ) {
        return $user;
