$wpide_common_passwords = array(
    '123456', '1234567', '12345678', '123456789', '1234567890', 'password', 'password1', 'password123', 'qwerty', 'qwerty123',
    'abc123', '111111', '000000', 'iloveyou', 'letmein', 'welcome', 'welcome1', 'admin', 'admin123', 'monkey',
    'dragon', 'sunshine', 'football', 'baseball', 'master', 'login', 'princess', 'starwars', 'passw0rd', 'trustno1',
);

$wpide_password_problem = function ( $password, $username ) use ( $wpide_common_passwords ) {
    $lower = strtolower( (string) $password );

    if ( '' === $lower ) {
        return '';
    }

    if ( in_array( $lower, $wpide_common_passwords, true ) ) {
        return 'This password is one of the most common ones. Please choose something less predictable.';
    }

    foreach ( array( $username, get_bloginfo( 'name' ) ) as $word ) {
        $word = strtolower( trim( (string) $word ) );
        if ( strlen( $word ) >= 3 && false !== strpos( $lower, $word ) ) {
            return 'Your password must not contain your username or the site name.';
        }
    }

    return '';
};

