// Patterns checked against the decoded URL (path and query string).
$wpide_firewall_patterns = array(
    '#\.\./#',
    '#(?:/|%2f)etc/passwd#i',
    '#(?:php|phar|zip|data|expect)://#i',
    '#union(?:\s|\+|/\*.*\*/)+(?:all(?:\s|\+)+)?select#i',
    '#\b(?:base64_decode|eval|assert|shell_exec|passthru|system)\s*\(#i',
    '#<\s*script#i',
    '#(?:GLOBALS|_REQUEST|_SERVER)\s*\[#',
    '#wp-config\.php#i',
);

add_action( 'init', function () use ( $wpide_firewall_patterns ) {
    if ( empty( $_SERVER['REQUEST_URI'] ) || ( is_user_logged_in() && current_user_can( 'unfiltered_html' ) ) ) {
        return;
    }

    $uri = rawurldecode( rawurldecode( (string) wp_unslash( $_SERVER['REQUEST_URI'] ) ) );

    foreach ( $wpide_firewall_patterns as $pattern ) {
        if ( preg_match( $pattern, $uri ) ) {
            status_header( 403 );
            nocache_headers();
            exit( 'Forbidden' );
        }
    }
}, 0 );

// Case-insensitive parts of user agent strings to block. AI crawlers are listed but commented out.
$wpide_blocked_bots = array(
    'MJ12bot', 'AhrefsBot', 'SemrushBot', 'DotBot', 'BLEXBot', 'PetalBot', 'MegaIndex', 'serpstatbot',
    'DataForSeoBot', 'ZoominfoBot', 'SeekportBot', 'Barkrowler', 'Bytespider',
    // 'GPTBot', 'ClaudeBot', 'CCBot', 'Google-Extended',
);

add_action( 'init', function () use ( $wpide_blocked_bots ) {
    $agent = isset( $_SERVER['HTTP_USER_AGENT'] ) ? (string) $_SERVER['HTTP_USER_AGENT'] : '';

    if ( '' === $agent ) {
        return;
    }

    foreach ( $wpide_blocked_bots as $bot ) {
        if ( false !== stripos( $agent, $bot ) ) {
            status_header( 403 );
            header( 'Content-Type: text/plain; charset=utf-8' );
            exit( 'Forbidden' );
        }
    }
}, 0 );

// Single addresses (IPv4 or IPv6) or IPv4 ranges in CIDR form.
$wpide_blocked_ips = array( '192.0.2.10', '198.51.100.0/24' );

$wpide_visitor_ip = isset( $_SERVER['REMOTE_ADDR'] ) ? (string) $_SERVER['REMOTE_ADDR'] : '';

if ( $wpide_visitor_ip && ! ( defined( 'WP_CLI' ) && WP_CLI ) ) {
    foreach ( $wpide_blocked_ips as $wpide_entry ) {
        $wpide_match = false;

        if ( false === strpos( $wpide_entry, '/' ) ) {
            $wpide_match = ( $wpide_visitor_ip === $wpide_entry );
        } elseif ( filter_var( $wpide_visitor_ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4 ) ) {
            list( $wpide_subnet, $wpide_bits ) = explode( '/', $wpide_entry, 2 );
            $wpide_mask  = -1 << ( 32 - (int) $wpide_bits );
            $wpide_match = ( ip2long( $wpide_visitor_ip ) & $wpide_mask ) === ( ip2long( $wpide_subnet ) & $wpide_mask );
        }

        if ( $wpide_match ) {
            status_header( 403 );
            header( 'Content-Type: text/plain; charset=utf-8' );
            exit( 'Access denied.' );
        }
    }
}

add_action( 'init', function () {
    if ( is_ssl() || ( defined( 'WP_CLI' ) && WP_CLI ) || wp_doing_cron() || empty( $_SERVER['HTTP_HOST'] ) ) {
        return;
    }

    // Many proxies and load balancers terminate HTTPS and pass this header instead.
    if ( isset( $_SERVER['HTTP_X_FORWARDED_PROTO'] ) && 'https' === strtolower( (string) $_SERVER['HTTP_X_FORWARDED_PROTO'] ) ) {
        return;
    }

    $host = wp_parse_url( home_url(), PHP_URL_HOST );
    $uri  = isset( $_SERVER['REQUEST_URI'] ) ? (string) wp_unslash( $_SERVER['REQUEST_URI'] ) : '/';

    wp_safe_redirect( 'https://' . $host . $uri, 301 );
    exit;
}, 0 );

