add_action( 'wpide_core_integrity_check', function () {
    global $wp_version, $wp_local_package;

    require_once ABSPATH . 'wp-admin/includes/update.php';

    $checksums = get_core_checksums( $wp_version, isset( $wp_local_package ) ? $wp_local_package : 'en_US' );

    if ( ! is_array( $checksums ) ) {
        return; // The checksum service could not be reached; try again tomorrow.
    }

    $problems = array();
    $optional = array( 'readme.html', 'license.txt', 'wp-config-sample.php', 'xmlrpc.php' ); // Often removed on purpose.

    foreach ( $checksums as $file => $md5 ) {
        if ( 0 === strpos( $file, 'wp-content/' ) || ( in_array( $file, $optional, true ) && ! file_exists( ABSPATH . $file ) ) ) {
            continue;
        }

        $path = ABSPATH . $file;

        if ( ! file_exists( $path ) ) {
            $problems[] = 'Missing: ' . $file;
        } elseif ( md5_file( $path ) !== $md5 ) {
            $problems[] = 'Modified: ' . $file;
        }
    }

    if ( $problems ) {
        wp_mail(
            get_option( 'admin_email' ),
            sprintf( '[%s] WordPress core files changed', wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES ) ),
            "These core files differ from the official WordPress " . $wp_version . " release:\n\n" . implode( "\n", array_slice( $problems, 0, 100 ) ) . "\n\nIf you did not change them, reinstall WordPress from Dashboard > Updates and scan the site."
        );
    }
} );

$wpide_protect_emails = function ( $content ) {
    if ( false === strpos( (string) $content, '@' ) ) {
        return $content;
    }

    $parts     = preg_split( '/(<[^>]+>)/', $content, -1, PREG_SPLIT_DELIM_CAPTURE );
    $in_script = false;

    foreach ( $parts as $i => $part ) {
        if ( '' === $part ) {
            continue;
        }

        if ( '<' === $part[0] ) {
            if ( preg_match( '#^<(script|style|textarea)\b#i', $part ) ) {
                $in_script = true;
            } elseif ( preg_match( '#^</(script|style|textarea)>#i', $part ) ) {
                $in_script = false;
            }

            $parts[ $i ] = preg_replace_callback( '/href=(["\'])mailto:([^"\']+)\1/i', function ( $m ) {
                return 'href=' . $m[1] . 'mailto:' . antispambot( $m[2] ) . $m[1];
            }, $part );
            continue;
        }

        if ( ! $in_script ) {
            $parts[ $i ] = preg_replace_callback( '/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i', function ( $m ) {
                return antispambot( $m[0] );
            }, $part );
        }
    }

    return implode( '', $parts );
};

