add_filter( 'rest_pre_dispatch', function ( $result, $server, $request ) use ( $wpide_rest_limit ) {
    if ( null !== $result || is_user_logged_in() || empty( $_SERVER['REMOTE_ADDR'] ) ) {
        return $result;
    }

    $key  = 'wpide_rest_' . md5( (string) $_SERVER['REMOTE_ADDR'] . '|' . floor( time() / 60 ) );
    $hits = (int) get_transient( $key ) + 1;
    set_transient( $key, $hits, 2 * MINUTE_IN_SECONDS );

    if ( $hits > $wpide_rest_limit ) {
        return new WP_Error( 'wpide_rate_limited', 'Too many requests. Please slow down.', array( 'status' => 429 ) );
    }

    return $result;
}, 10, 3 );

add_action( 'init', function () {
    $agent = isset( $_SERVER['HTTP_USER_AGENT'] ) ? (string) $_SERVER['HTTP_USER_AGENT'] : '';
    $ip    = isset( $_SERVER['REMOTE_ADDR'] ) ? (string) $_SERVER['REMOTE_ADDR'] : '';

    if ( false === stripos( $agent, 'Googlebot' ) || ! filter_var( $ip, FILTER_VALIDATE_IP ) ) {
        return;
    }

    $key     = 'wpide_gbot_' . md5( $ip );
    $genuine = get_transient( $key );

    if ( false === $genuine ) {
        $host    = gethostbyaddr( $ip );
        $forward = array();

        if ( $host && preg_match( '/\.(googlebot|google)\.com$/i', $host ) ) {
            if ( filter_var( $ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4 ) ) {
                $forward = (array) gethostbynamel( $host );
            } else {
                foreach ( (array) dns_get_record( $host, DNS_AAAA ) as $record ) {
                    if ( ! empty( $record['ipv6'] ) ) {
                        $forward[] = inet_ntop( inet_pton( $record['ipv6'] ) );
                    }
                }
                $ip = inet_ntop( inet_pton( $ip ) );
            }
        }

        $genuine = in_array( $ip, $forward, true ) ? 'yes' : 'no';
        set_transient( $key, $genuine, DAY_IN_SECONDS );
    }

    if ( 'no' === $genuine ) {
        status_header( 403 );
        exit( 'Forbidden' );
    }
}, 0 );

