// Share of uppercase letters (0 to 1) above which a comment is held.
$wpide_caps_ratio = 0.7;

add_filter( 'pre_comment_approved', function ( $approved, $commentdata ) use ( $wpide_caps_ratio ) {
    if ( 1 !== $approved && '1' !== $approved ) {
        return $approved;
    }

    $letters = preg_replace( '/[^\p{L}]/u', '', (string) $commentdata['comment_content'] );
    $upper   = preg_replace( '/[^\p{Lu}]/u', '', $letters );

    if ( strlen( $letters ) >= 20 && strlen( $upper ) / strlen( $letters ) > $wpide_caps_ratio ) {
        return 0;
    }

    return $approved;
}, 20, 2 );

