// Reports after which a comment is unpublished until a moderator reviews it.
$wpide_report_threshold = 3;

add_filter( 'comment_text', function ( $text, $comment ) {
    if ( is_admin() || wp_is_json_request() || ! ( $comment instanceof WP_Comment ) || '1' !== (string) $comment->comment_approved || is_feed() ) {
