        fetch( <?php echo wp_json_encode( admin_url( 'admin-ajax.php' ) ); ?>, { method: 'POST', body: data, credentials: 'same-origin' } )
            .then( function () { link.replaceWith( document.createTextNode( 'Thanks, reported.' ) ); } );
