$wpide_handle_report = function () use ( $wpide_report_threshold ) {
    check_ajax_referer( 'wpide_report_comment', 'nonce' );

    $comment_id = isset( $_POST['comment_id'] ) ? absint( $_POST['comment_id'] ) : 0;
    $comment    = $comment_id ? get_comment( $comment_id ) : null;

    if ( ! $comment || '1' !== (string) $comment->comment_approved ) {
        wp_send_json_error( null, 404 );
    }

    $ip  = isset( $_SERVER['REMOTE_ADDR'] ) ? (string) $_SERVER['REMOTE_ADDR'] : '';
    $key = 'wpide_reported_' . md5( $ip . '|' . $comment_id );

    if ( get_transient( $key ) ) {
        wp_send_json_success(); // Already counted for this visitor.
    }

    set_transient( $key, 1, DAY_IN_SECONDS );
    $reports = (int) get_comment_meta( $comment_id, 'wpide_reports', true ) + 1;
    update_comment_meta( $comment_id, 'wpide_reports', $reports );

    if ( 1 === $reports ) {
        wp_mail(
            get_option( 'admin_email' ),
            'A comment was reported',
            sprintf( "A visitor reported this comment:\n\n%s\n\nReview it: %s", wp_trim_words( wp_strip_all_tags( $comment->comment_content ), 60 ), admin_url( 'comment.php?action=editcomment&c=' . $comment_id ) )
        );
    }

    if ( $reports >= $wpide_report_threshold ) {
        wp_set_comment_status( $comment_id, 'hold' );
    }

    wp_send_json_success();
};

add_action( 'wp_ajax_wpide_report_comment', $wpide_handle_report );
add_action( 'wp_ajax_nopriv_wpide_report_comment', $wpide_handle_report );

