// Posts older than this many years get the notice.
$wpide_old_post_years = 2;
// Message shown; %s becomes the age of the post.
$wpide_old_post_message = 'This article was published %s ago, so some details may be out of date.';

add_filter( 'the_content', function ( $content ) use ( $wpide_old_post_years, $wpide_old_post_message ) {
    if ( ! is_singular( 'post' ) || ! in_the_loop() || ! is_main_query() ) {
        return $content;
    }

    $published = (int) get_post_time( 'U', true );

    if ( ! $published || $published > strtotime( '-' . absint( $wpide_old_post_years ) . ' years' ) ) {
        return $content;
    }

    $notice = sprintf( $wpide_old_post_message, human_time_diff( $published, time() ) );

    return '<p class="wpide-old-post-notice" style="padding:.75em 1em;background:#fcf9e8;border-left:3px solid #dba617;color:#1d2327;">' . esc_html( $notice ) . '</p>' . $content;
}, 20 );

add_shortcode( 'scheduled', function ( $atts, $content = '' ) {
    $atts = shortcode_atts( array( 'from' => '', 'until' => '' ), $atts, 'scheduled' );
    $now  = time();

    if ( '' !== $atts['from'] ) {
        $from = date_create( $atts['from'], wp_timezone() );

        if ( $from && $now < $from->getTimestamp() ) {
            return '';
        }
    }

    if ( '' !== $atts['until'] ) {
        $until = date_create( $atts['until'], wp_timezone() );

        if ( $until && $now > $until->getTimestamp() ) {
            return '';
        }
    }

    return do_shortcode( (string) $content );
} );

add_shortcode( 'members_only', function ( $atts, $content = '' ) {
