// Text to find => replacement.
$wpide_replacements = array(
    'Old Brand Name' => 'New Brand Name',
    'old-product'    => 'new-product',
);

$wpide_replace_text = function ( $text ) use ( $wpide_replacements ) {
    if ( ! is_string( $text ) || '' === $text || is_admin() ) {
        return $text;
    }

    foreach ( $wpide_replacements as $find => $replace ) {
        $result = preg_replace( '/' . preg_quote( $find, '/' ) . '(?![^<]*>)/u', str_replace( array( '\\', '$' ), array( '\\\\', '\\$' ), $replace ), $text );
        $text   = null === $result ? $text : $result;
    }

    return $text;
};

