    if ( isset( $_GET['wpide_too_short'] ) ) {
        echo '<div class="notice notice-error"><p>' . esc_html( sprintf( 'The post was saved as a draft because it has fewer than %d words.', $wpide_min_words ) ) . '</p></div>';
    }
} );

