    return '<a href="mailto:' . antispambot( $address, 1 ) . '">' . $label . '</a>';
} );

// Use relative dates for posts newer than this many days.
$wpide_relative_days = 7;

add_filter( 'get_the_date', function ( $date, $format, $post ) use ( $wpide_relative_days ) {
    if ( is_admin() || is_feed() || ( '' !== $format && get_option( 'date_format' ) !== $format ) ) {
        return $date;
    }

    $timestamp = (int) get_post_time( 'U', true, $post );

    if ( ! $timestamp || time() - $timestamp > $wpide_relative_days * DAY_IN_SECONDS || $timestamp > time() ) {
        return $date;
    }

    return sprintf( '%s ago', human_time_diff( $timestamp, time() ) );
}, 10, 3 );

