// Posts newer than this many days get the badge.
$wpide_new_badge_days = 7;
// Badge text.
$wpide_new_badge_text = 'New';

add_filter( 'the_title', function ( $title, $id = 0 ) use ( $wpide_new_badge_days, $wpide_new_badge_text ) {
    if ( is_admin() || is_feed() || is_singular() || ! in_the_loop() || ! $id || 'post' !== get_post_type( $id ) ) {
        return $title;
    }

    $published = (int) get_post_time( 'U', true, $id );

    if ( $published && time() - $published < $wpide_new_badge_days * DAY_IN_SECONDS ) {
