add_shortcode( 'field', function ( $atts ) {
    $atts = shortcode_atts( array( 'name' => '', 'id' => 0, 'default' => '' ), $atts, 'field' );
    $key  = sanitize_key( $atts['name'] );

    if ( '' === $key || is_protected_meta( $key, 'post' ) ) {
        return '';
    }

    $post_id = $atts['id'] ? absint( $atts['id'] ) : get_the_ID();

    if ( ! $post_id || ( ! is_post_publicly_viewable( $post_id ) && ! current_user_can( 'read_post', $post_id ) ) ) {
