    return esc_html( $value );
} );

add_shortcode( 'countdown', function ( $atts ) {
    $atts = shortcode_atts( array( 'to' => '', 'expired' => 'Time is up!' ), $atts, 'countdown' );
    $date = date_create( $atts['to'], wp_timezone() );

    if ( ! $date ) {
        return '';
    }

    $id = wp_unique_id( 'wpide-countdown-' );

    $html  = '<span id="' . esc_attr( $id ) . '" class="wpide-countdown" data-end="' . esc_attr( $date->getTimestamp() * 1000 ) . '" data-expired="' . esc_attr( $atts['expired'] ) . '"></span>';
    $html .= '<script>(function(){var el=document.getElementById(' . wp_json_encode( $id ) . ');if(!el){return;}var end=parseInt(el.getAttribute("data-end"),10);function pad(n){return n<10?"0"+n:n;}function tick(){var left=end-Date.now();if(left<=0){el.textContent=el.getAttribute("data-expired");return;}var s=Math.floor(left/1000),d=Math.floor(s/86400),h=Math.floor(s%86400/3600),m=Math.floor(s%3600/60);el.textContent=d+"d "+pad(h)+"h "+pad(m)+"m "+pad(s%60)+"s";setTimeout(tick,1000);}tick();})();</script>';

    return $html;
} );

(function () {
    if (!navigator.clipboard) {
        return;
    }

    document.querySelectorAll('.entry-content pre, .wp-block-post-content pre, .wp-block-code').forEach(function (block) {
        if (block.tagName !== 'PRE') {
            return;
        }

        var button = document.createElement('button');
        button.type = 'button';
        button.className = 'wpide-copy-code';
        button.textContent = 'Copy';
        button.style.cssText = 'position:absolute;top:.5em;right:.5em;padding:.2em .6em;font-size:12px;cursor:pointer;';

        if (getComputedStyle(block).position === 'static') {
            block.style.position = 'relative';
        }

        button.addEventListener('click', function () {
            var code = block.querySelector('code') || block;

            navigator.clipboard.writeText(code.innerText.replace(/\n?Copied!$|\n?Copy$/, '')).then(function () {
                button.textContent = 'Copied!';
                setTimeout(function () {
                    button.textContent = 'Copy';
                }, 2000);
            });
        });

        block.appendChild(button);
    });
})();

add_filter( 'the_content', function ( $content ) {
    if ( false === stripos( $content, '.pdf' ) ) {
        return $content;
    }

    $result = preg_replace_callback( '/<a\s[^>]*href=["\'][^"\']+\.pdf(?:[?#][^"\']*)?["\'][^>]*>/i', function ( $m ) {
        if ( false !== stripos( $m[0], ' target=' ) ) {
            return $m[0];
        }

        return substr( $m[0], 0, -1 ) . ' target="_blank" rel="noopener">';
    }, $content );

    return null === $result ? $content : $result;
}, 20 );

add_filter( 'the_content', function ( $content ) {
    if ( is_singular() || is_feed() || ! in_the_loop() || ! is_main_query() || doing_filter( 'get_the_excerpt' ) ) {
        return $content;
    }

    static $running = false;

    if ( $running ) {
        return $content;
    }

    $running = true;
    $excerpt = get_the_excerpt();
    $running = false;

    return '<p>' . esc_html( $excerpt ) . '</p><p><a class="more-link" href="' . esc_url( get_permalink() ) . '">Read more<span class="screen-reader-text"> about ' . esc_html( get_the_title() ) . '</span></a></p>';
}, 1 );

