// Post type => number per page (-1 = all).
$wpide_archive_per_page = array(
    'portfolio'   => 12,
    'testimonial' => -1,
);

add_action( 'pre_get_posts', function ( $query ) use ( $wpide_archive_per_page ) {
    if ( is_admin() || ! $query->is_main_query() || ! $query->is_post_type_archive() ) {
        return;
    }

    foreach ( $wpide_archive_per_page as $post_type => $count ) {
        if ( $query->is_post_type_archive( $post_type ) ) {
            $query->set( 'posts_per_page', (int) $count );
            return;
        }
    }
} );

add_action( 'pre_get_posts', function ( $query ) {
    if ( is_admin() || ! $query->is_main_query() || ! ( $query->is_home() || $query->is_archive() ) || $query->get( 'orderby' ) ) {
        return;
    }

    $query->set( 'orderby', 'modified' );
