add_action( 'template_redirect', function () {
    global $wp_query;

    if ( ! ( is_category() || is_tag() ) || is_paged() || is_feed() ) {
        return;
    }

    if ( 1 === (int) $wp_query->found_posts && ! empty( $wp_query->posts[0] ) ) {
        wp_safe_redirect( get_permalink( $wp_query->posts[0] ), 302 );
        exit;
    }
} );

add_action( 'template_redirect', function () {
    global $wp_query;

    if ( ( is_category() || is_tag() || is_tax() ) && ! is_paged() && ! $wp_query->have_posts() ) {
        $wp_query->set_404();
        status_header( 404 );
        nocache_headers();
    }
}, 1 );

add_action( 'parse_tax_query', function ( $query ) {
    if ( is_admin() || ! $query->is_main_query() || ! $query->is_category() || empty( $query->tax_query->queries ) ) {
        return;
    }

    foreach ( $query->tax_query->queries as $index => $clause ) {
        if ( is_array( $clause ) && isset( $clause['taxonomy'] ) && 'category' === $clause['taxonomy'] ) {
            $query->tax_query->queries[ $index ]['include_children'] = false;
        }
    }
} );

add_action( 'loop_start', function ( $query ) {
    static $done = false;

    if ( $done || ! $query->is_main_query() || ! is_category() || is_paged() ) {
        return;
    }

    $done     = true;
    $children = get_categories( array(
        'parent'     => get_queried_object_id(),
        'hide_empty' => true,
    ) );

    if ( ! $children ) {
        return;
    }

    echo '<nav class="wpide-subcategories" aria-label="Subcategories"><ul style="list-style:none;margin:0 0 2em;padding:0;display:flex;flex-wrap:wrap;gap:.5em;">';

    foreach ( $children as $child ) {
        echo '<li><a href="' . esc_url( get_category_link( $child ) ) . '" style="display:inline-block;padding:.3em .8em;border:1px solid currentColor;border-radius:999px;text-decoration:none;">' . esc_html( $child->name ) . ' <span style="opacity:.6;">' . esc_html( number_format_i18n( $child->count ) ) . '</span></a></li>';
    }

    echo '</ul></nav>';
} );

add_filter( 'get_the_archive_title', function ( $title ) {
    global $wp_query;

    if ( ! is_archive() || is_post_type_archive() || ! $wp_query instanceof WP_Query ) {
        return $title;
    }

    return $title . ' <span class="wpide-archive-count">(' . esc_html( number_format_i18n( (int) $wp_query->found_posts ) ) . ')</span>';
}, 20 );

