        'limit'           => $atts['limit'] ? absint( $atts['limit'] ) : '',
        'show_post_count' => 'yes' === $atts['show_count'],
        'post_type'       => post_type_exists( $atts['post_type'] ) ? $atts['post_type'] : 'post',
        'echo'            => false,
    );

    if ( 'yes' === $atts['dropdown'] ) {
        $args['format'] = 'option';

        return '<select class="wpide-archives-dropdown" aria-label="Archives" onchange="if(this.value){window.location.href=this.value;}"><option value="">Select a period</option>' . wp_get_archives( $args ) . '</select>';
    }

    return '<ul class="wpide-archives">' . wp_get_archives( $args ) . '</ul>';
