// Number of posts on the first page of the blog.
$wpide_first_page_posts = 3;

add_action( 'pre_get_posts', function ( $query ) use ( $wpide_first_page_posts ) {
    if ( is_admin() || ! $query->is_main_query() || ! $query->is_home() ) {
        return;
    }

    $per_page = (int) get_option( 'posts_per_page' );
    $paged    = max( 1, (int) $query->get( 'paged' ) );

    if ( 1 === $paged ) {
        $query->set( 'posts_per_page', $wpide_first_page_posts );
    } else {
        $query->set( 'posts_per_page', $per_page );
        $query->set( 'offset', $wpide_first_page_posts + ( $paged - 2 ) * $per_page );
    }
} );

add_filter( 'found_posts', function ( $found, $query ) use ( $wpide_first_page_posts ) {
    if ( is_admin() || ! $query->is_main_query() || ! $query->is_home() ) {
        return $found;
    }

    $per_page = max( 1, (int) get_option( 'posts_per_page' ) );
    $pages    = 1 + (int) ceil( max( 0, $found - $wpide_first_page_posts ) / $per_page );

    if ( max( 1, (int) $query->get( 'paged' ) ) === 1 ) {
        return $pages * $wpide_first_page_posts;
    }

    return $found - $wpide_first_page_posts + $per_page;
}, 10, 2 );

add_action( 'pre_get_posts', function ( $query ) {
    if ( ! is_admin() && $query->is_main_query() && $query->is_home() ) {
        $query->set( 'ignore_sticky_posts', true );
    }
} );

add_filter( 'the_posts', function ( $posts, $query ) {
    if ( is_admin() || ! $query->is_main_query() || ! $query->is_category() || $query->is_paged() ) {
        return $posts;
    }

    $sticky = array_map( 'absint', (array) get_option( 'sticky_posts', array() ) );

    if ( ! $sticky ) {
        return $posts;
    }

    $pinned = get_posts( array(
        'post__in'            => $sticky,
        'category__in'        => array( $query->get_queried_object_id() ),
        'numberposts'         => count( $sticky ),
        'ignore_sticky_posts' => true,
        'no_found_rows'       => true,
    ) );

    if ( ! $pinned ) {
        return $posts;
    }

    $pinned_ids = wp_list_pluck( $pinned, 'ID' );
    $others     = array_filter( $posts, function ( $post ) use ( $pinned_ids ) {
        return ! in_array( $post->ID, $pinned_ids, true );
    } );

    return array_merge( $pinned, array_values( $others ) );
}, 10, 2 );

add_filter( 'get_the_archive_title', function ( $title ) {
    global $wp_query;

    $paged = (int) get_query_var( 'paged' );

    if ( $paged > 1 ) {
        $title .= sprintf( ' <span class="wpide-archive-page">&ndash; Page %1$d of %2$d</span>', $paged, max( $paged, (int) $wp_query->max_num_pages ) );
    }

    return $title;
}, 30 );

// Posts per page on author archives and date archives.
$wpide_author_per_page = 20;
$wpide_date_per_page   = 30;

add_action( 'pre_get_posts', function ( $query ) use ( $wpide_author_per_page, $wpide_date_per_page ) {
    if ( is_admin() || ! $query->is_main_query() ) {
        return;
    }

    if ( $query->is_author() ) {
        $query->set( 'posts_per_page', (int) $wpide_author_per_page );
    } elseif ( $query->is_date() ) {
        $query->set( 'posts_per_page', (int) $wpide_date_per_page );
    }
} );

