// Extension => MIME type allowed for administrators.
$wpide_extra_mimes = array(
    'woff'  => 'font/woff',
    'woff2' => 'font/woff2',
    'ttf'   => 'font/ttf',
    'otf'   => 'font/otf',
    'epub'  => 'application/epub+zip',
    'json'  => 'application/json',
    'gpx'   => 'application/gpx+xml',
);

add_filter( 'upload_mimes', function ( $mimes, $user = null ) use ( $wpide_extra_mimes ) {
    $user_id = $user instanceof WP_User ? $user->ID : ( $user ? (int) $user : get_current_user_id() );

    if ( user_can( $user_id, 'manage_options' ) ) {
