// Limits in pixels (0 = no limit).
$wpide_min_width  = 300;
$wpide_min_height = 0;
$wpide_max_width  = 8000;
$wpide_max_height = 8000;

add_filter( 'wp_handle_upload_prefilter', function ( $file ) use ( $wpide_min_width, $wpide_min_height, $wpide_max_width, $wpide_max_height ) {
    if ( ! empty( $file['error'] ) || empty( $file['type'] ) || 0 !== strpos( $file['type'], 'image/' ) || 'image/svg+xml' === $file['type'] ) {
        return $file;
    }

    $size = wp_getimagesize( $file['tmp_name'] );

    if ( ! $size ) {
        return $file;
    }

    list( $width, $height ) = $size;

    if ( ( $wpide_min_width && $width < $wpide_min_width ) || ( $wpide_min_height && $height < $wpide_min_height ) ) {
        $file['error'] = sprintf( 'This image is %1$d x %2$d pixels. Images must be at least %3$d x %4$d pixels.', $width, $height, $wpide_min_width, $wpide_min_height );
    } elseif ( ( $wpide_max_width && $width > $wpide_max_width ) || ( $wpide_max_height && $height > $wpide_max_height ) ) {
        $file['error'] = sprintf( 'This image is %1$d x %2$d pixels. Images can be at most %3$d x %4$d pixels.', $width, $height, $wpide_max_width, $wpide_max_height );
    }

    return $file;
} );

