// Domains whose links stay followed (your own domain is always followed).
$wpide_follow_domains = array( 'wordpress.org' );

add_filter( 'the_content', function ( $content ) use ( $wpide_follow_domains ) {
    if ( false === stripos( $content, '<a ' ) ) {
        return $content;
    }

    $own = wp_parse_url( home_url(), PHP_URL_HOST );

    $result = preg_replace_callback( '/<a\s[^>]*>/i', function ( $m ) use ( $own, $wpide_follow_domains ) {
        $tag = $m[0];

        if ( ! preg_match( '/href=["\'](https?:)?\/\/([^\/"\':?#]+)/i', $tag, $href ) ) {
            return $tag;
        }

        $host = strtolower( $href[2] );

        foreach ( array_merge( array( $own ), $wpide_follow_domains ) as $domain ) {
            $domain = strtolower( (string) $domain );

            if ( $host === $domain || substr( $host, -strlen( '.' . $domain ) ) === '.' . $domain ) {
                return $tag;
            }
        }

        if ( preg_match( '/\srel=(["\'])([^"\']*)\1/i', $tag, $rel ) ) {
            if ( preg_match( '/\bnofollow\b/i', $rel[2] ) ) {
                return $tag;
            }

            return str_replace( $rel[0], ' rel="' . esc_attr( trim( $rel[2] . ' nofollow' ) ) . '"', $tag );
        }

        return substr( $tag, 0, -1 ) . ' rel="nofollow">';
    }, $content );

    return null === $result ? $content : $result;
}, 20 );

// Affiliate domains (subdomains included).
$wpide_affiliate_domains = array( 'amzn.to', 'amazon.com', 'shareasale.com' );
// Paths on your own site used for cloaked affiliate links.
$wpide_affiliate_paths = array( '/go/', '/recommends/' );

add_filter( 'the_content', function ( $content ) use ( $wpide_affiliate_domains, $wpide_affiliate_paths ) {
    if ( false === stripos( $content, '<a ' ) ) {
        return $content;
    }

    $own = strtolower( (string) wp_parse_url( home_url(), PHP_URL_HOST ) );

    $result = preg_replace_callback( '/<a\s[^>]*href=(["\'])([^"\']+)\1[^>]*>/i', function ( $m ) use ( $own, $wpide_affiliate_domains, $wpide_affiliate_paths ) {
        $url  = $m[2];
        $host = strtolower( (string) wp_parse_url( $url, PHP_URL_HOST ) );
        $path = (string) wp_parse_url( $url, PHP_URL_PATH );
        $hit  = false;

        foreach ( $wpide_affiliate_domains as $domain ) {
            if ( $host && ( $host === $domain || substr( $host, -strlen( '.' . $domain ) ) === '.' . $domain ) ) {
                $hit = true;
            }
        }

        if ( ! $hit && ( ! $host || $host === $own ) ) {
            foreach ( $wpide_affiliate_paths as $prefix ) {
                if ( 0 === strpos( $path, $prefix ) ) {
                    $hit = true;
                }
            }
        }

        if ( ! $hit ) {
            return $m[0];
        }

        $tag = preg_replace( '/\srel=(["\'])[^"\']*\1/i', '', $m[0] );

        return substr( $tag, 0, -1 ) . ' rel="sponsored nofollow noopener">';
    }, $content );

    return null === $result ? $content : $result;
}, 21 );

// Label of the first link.
$wpide_crumb_home = 'Home';
// Separator between items.
$wpide_crumb_separator = '/';

add_shortcode( 'breadcrumbs', function () use ( $wpide_crumb_home, $wpide_crumb_separator ) {
    $items = array( array( $wpide_crumb_home, home_url( '/' ) ) );
    $link  = function ( $term ) {
        $url = get_term_link( $term );

        return is_wp_error( $url ) ? '' : $url;
    };

    if ( is_front_page() ) {
        return '';
    }

    if ( is_singular() ) {
        $post = get_queried_object();

        if ( 'post' === $post->post_type ) {
            $categories = get_the_category( $post->ID );

            if ( $categories ) {
                foreach ( array_reverse( get_ancestors( $categories[0]->term_id, 'category', 'taxonomy' ) ) as $ancestor ) {
                    $term    = get_term( $ancestor, 'category' );
                    $items[] = array( $term->name, $link( $term ) );
                }

                $items[] = array( $categories[0]->name, $link( $categories[0] ) );
            }
        } elseif ( is_post_type_hierarchical( $post->post_type ) ) {
            foreach ( array_reverse( get_post_ancestors( $post ) ) as $ancestor ) {
                $items[] = array( get_the_title( $ancestor ), get_permalink( $ancestor ) );
            }
        } elseif ( get_post_type_archive_link( $post->post_type ) ) {
            $items[] = array( get_post_type_object( $post->post_type )->labels->name, get_post_type_archive_link( $post->post_type ) );
        }

        $items[] = array( get_the_title( $post ), '' );
    } elseif ( is_category() || is_tag() || is_tax() ) {
        $term = get_queried_object();

        foreach ( array_reverse( get_ancestors( $term->term_id, $term->taxonomy, 'taxonomy' ) ) as $ancestor ) {
            $parent  = get_term( $ancestor, $term->taxonomy );
            $items[] = array( $parent->name, $link( $parent ) );
        }

        $items[] = array( $term->name, '' );
    } elseif ( is_search() ) {
        $items[] = array( sprintf( 'Search results for "%s"', get_search_query( false ) ), '' );
    } elseif ( is_404() ) {
        $items[] = array( 'Page not found', '' );
    } elseif ( is_home() ) {
        $items[] = array( single_post_title( '', false ), '' );
    } else {
        $items[] = array( wp_strip_all_tags( get_the_archive_title() ), '' );
    }

    $html = '<nav class="wpide-breadcrumbs" aria-label="Breadcrumb"><ol itemscope itemtype="https://schema.org/BreadcrumbList" style="list-style:none;margin:0 0 1em;padding:0;display:flex;flex-wrap:wrap;gap:.4em;">';
    $last = count( $items ) - 1;

    foreach ( $items as $position => $item ) {
        $name  = '<span itemprop="name">' . esc_html( $item[0] ) . '</span>';
        $inner = ( $item[1] && $position !== $last ) ? '<a itemprop="item" href="' . esc_url( $item[1] ) . '">' . $name . '</a>' : $name;
        $sep   = $position !== $last ? ' <span aria-hidden="true">' . esc_html( $wpide_crumb_separator ) . '</span>' : '';
        $html .= '<li itemprop="itemListElement" itemscope itemtype="https://schema.org/ListItem"' . ( $position === $last ? ' aria-current="page"' : '' ) . '>' . $inner . '<meta itemprop="position" content="' . ( $position + 1 ) . '" />' . $sep . '</li>';
    }

    return $html . '</ol></nav>';
} );

add_action( 'wp_head', function () {
    if ( ! is_singular() || is_front_page() || defined( 'WPSEO_VERSION' ) || defined( 'RANK_MATH_VERSION' ) || defined( 'AIOSEO_VERSION' ) || defined( 'SEOPRESS_VERSION' ) || defined( 'THE_SEO_FRAMEWORK_VERSION' ) ) {
        return;
    }

    $post  = get_queried_object();
    $trail = array( array( get_bloginfo( 'name' ), home_url( '/' ) ) );

    if ( 'post' === $post->post_type ) {
        $categories = get_the_category( $post->ID );

        if ( $categories ) {
            $ids = array_reverse( get_ancestors( $categories[0]->term_id, 'category', 'taxonomy' ) );
            $ids[] = $categories[0]->term_id;

            foreach ( $ids as $term_id ) {
                $url = get_term_link( (int) $term_id, 'category' );

                if ( ! is_wp_error( $url ) ) {
                    $trail[] = array( get_term( $term_id, 'category' )->name, $url );
                }
            }
        }
    } elseif ( is_post_type_hierarchical( $post->post_type ) ) {
        foreach ( array_reverse( get_post_ancestors( $post ) ) as $ancestor ) {
            $trail[] = array( get_the_title( $ancestor ), get_permalink( $ancestor ) );
        }
    }

    $trail[] = array( get_the_title( $post ), get_permalink( $post ) );
    $list    = array();

    foreach ( $trail as $index => $crumb ) {
        $list[] = array(
            '@type'    => 'ListItem',
            'position' => $index + 1,
            'name'     => wp_strip_all_tags( $crumb[0] ),
            'item'     => $crumb[1],
        );
    }

    $data = array(
        '@context'        => 'https://schema.org',
        '@type'           => 'BreadcrumbList',
        'itemListElement' => $list,
    );

    echo '<script type="application/ld+json">' . wp_json_encode( $data, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_HEX_TAG ) . "</script>\n";
} );

