add_action( 'save_post', function ( $post_id ) {
    if ( ! isset( $_POST['wpide_seo_nonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['wpide_seo_nonce'] ) ), 'wpide_seo_save' ) ) {
        return;
    }

    if ( ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) || wp_is_post_revision( $post_id ) || ! current_user_can( 'edit_post', $post_id ) ) {
        return;
    }

    $fields = array(
        '_wpide_seo_title'       => isset( $_POST['wpide_seo_title'] ) ? sanitize_text_field( wp_unslash( $_POST['wpide_seo_title'] ) ) : '',
        '_wpide_seo_description' => isset( $_POST['wpide_seo_description'] ) ? sanitize_textarea_field( wp_unslash( $_POST['wpide_seo_description'] ) ) : '',
        '_wpide_seo_noindex'     => empty( $_POST['wpide_seo_noindex'] ) ? '' : '1',
    );

    foreach ( $fields as $key => $value ) {
        if ( '' === $value ) {
            delete_post_meta( $post_id, $key );
        } else {
            update_post_meta( $post_id, $key, $value );
        }
    }
} );

