add_shortcode( 'html_sitemap', function ( $atts ) {
    $atts = shortcode_atts( array( 'show_posts' => 'yes', 'posts_per_category' => 50 ), $atts, 'html_sitemap' );
    $html = '<div class="wpide-html-sitemap"><h2>Pages</h2><ul>' . wp_list_pages( array( 'title_li' => '', 'echo' => false ) ) . '</ul>';

    if ( 'yes' === $atts['show_posts'] ) {
        foreach ( get_categories( array( 'hide_empty' => true ) ) as $category ) {
            $posts = get_posts( array(
                'numberposts'         => absint( $atts['posts_per_category'] ),
                'ignore_sticky_posts' => true,
                'no_found_rows'       => true,
                'category__in'        => array( $category->term_id ),
            ) );

            if ( ! $posts ) {
                continue;
            }

            $html .= '<h2><a href="' . esc_url( get_category_link( $category ) ) . '">' . esc_html( $category->name ) . '</a></h2><ul>';

