// Custom field names to include in search (empty = all fields not starting with an underscore).
$wpide_search_meta_keys = array( 'subtitle', 'location' );

add_filter( 'posts_search', function ( $search, $query ) use ( $wpide_search_meta_keys ) {
    global $wpdb;

    if ( '' === $search || is_admin() || ! $query->is_main_query() || ! $query->is_search() ) {
        return $search;
    }

    $key_sql = $wpide_search_meta_keys
        ? "AND pm.meta_key IN ('" . implode( "','", array_map( 'esc_sql', $wpide_search_meta_keys ) ) . "')"
        : "AND pm.meta_key NOT LIKE '\\_%'";

    $pattern = '/\(' . preg_quote( $wpdb->posts, '/' ) . '\.post_content LIKE (\'(?:[^\'\\\\]|\\\\.)*\')\)/';

    $result = preg_replace_callback( $pattern, function ( $m ) use ( $wpdb, $key_sql ) {
        return $m[0] . " OR ({$wpdb->posts}.ID IN (SELECT pm.post_id FROM {$wpdb->postmeta} pm WHERE pm.meta_value LIKE {$m[1]} {$key_sql}))";
    }, $search );

    return null === $result ? $search : $result;
}, 10, 2 );

// Taxonomies whose term names are searched.
$wpide_search_taxonomies = array( 'category', 'post_tag' );

add_filter( 'posts_search', function ( $search, $query ) use ( $wpide_search_taxonomies ) {
    global $wpdb;

    if ( '' === $search || is_admin() || ! $query->is_main_query() || ! $query->is_search() || ! $wpide_search_taxonomies ) {
        return $search;
    }

    $taxonomies = "'" . implode( "','", array_map( 'esc_sql', $wpide_search_taxonomies ) ) . "'";
    $pattern    = '/\(' . preg_quote( $wpdb->posts, '/' ) . '\.post_title LIKE (\'(?:[^\'\\\\]|\\\\.)*\')\)/';

    $result = preg_replace_callback( $pattern, function ( $m ) use ( $wpdb, $taxonomies ) {
        return $m[0] . " OR ({$wpdb->posts}.ID IN (SELECT tr.object_id FROM {$wpdb->term_relationships} tr INNER JOIN {$wpdb->term_taxonomy} tt ON tt.term_taxonomy_id = tr.term_taxonomy_id INNER JOIN {$wpdb->terms} t ON t.term_id = tt.term_id WHERE tt.taxonomy IN ({$taxonomies}) AND t.name LIKE {$m[1]}))";
    }, $search );

    return null === $result ? $search : $result;
}, 10, 2 );

// Category IDs to leave out of search results.
$wpide_search_excluded_categories = array( 0 );

add_action( 'pre_get_posts', function ( $query ) use ( $wpide_search_excluded_categories ) {
