// Minimum number of characters for a search.
$wpide_min_search_length = 3;

add_action( 'pre_get_posts', function ( $query ) use ( $wpide_min_search_length ) {
    if ( is_admin() || ! $query->is_main_query() || ! $query->is_search() ) {
        return;
    }

    $term   = trim( (string) $query->get( 's' ) );
    $length = function_exists( 'mb_strlen' ) ? mb_strlen( $term ) : strlen( $term );

    if ( '' !== $term && $length < $wpide_min_search_length ) {
        $query->set( 'post__in', array( 0 ) );
    }
} );

// Searches longer than this many characters are treated as spam.
$wpide_search_max_length = 80;
// Words that mark a search as spam.
$wpide_blocked_search_words = array( 'casino', 'viagra', 'crypto loan' );

add_action( 'template_redirect', function () use ( $wpide_search_max_length, $wpide_blocked_search_words ) {
    global $wp_query;

    if ( ! is_search() ) {
        return;
    }

    $term   = (string) get_search_query( false );
    $length = function_exists( 'mb_strlen' ) ? mb_strlen( $term ) : strlen( $term );
    $spam   = $length > $wpide_search_max_length || preg_match( '#https?://|www\.|[<>{}\[\]]#i', $term );

    foreach ( $wpide_blocked_search_words as $word ) {
        if ( '' !== $word && false !== stripos( $term, $word ) ) {
            $spam = true;
        }
    }

    if ( $spam ) {
        $wp_query->set_404();
        status_header( 404 );
        nocache_headers();
    }
}, 1 );

add_filter( 'wp_robots', function ( $robots ) {
    if ( is_search() ) {
        $robots['noindex'] = true;
        $robots['follow']  = true;
