add_action( 'template_redirect', function () {
    global $wp_query;

    if ( ! is_search() || is_paged() || current_user_can( 'edit_posts' ) ) {
        return;
    }

    $term = strtolower( trim( (string) get_search_query( false ) ) );

    if ( '' === $term || strlen( $term ) > 100 ) {
        return;
    }

    $log = get_option( 'wpide_search_log', array() );
    $log = is_array( $log ) ? $log : array();

    if ( ! isset( $log[ $term ] ) ) {
        $log[ $term ] = array( 'count' => 0, 'results' => 0, 'last' => 0 );
    }

    $log[ $term ]['count']++;
    $log[ $term ]['results'] = (int) $wp_query->found_posts;
    $log[ $term ]['last']    = time();

    if ( count( $log ) > 300 ) {
        uasort( $log, function ( $a, $b ) {
            return $b['last'] <=> $a['last'];
        } );
        $log = array_slice( $log, 0, 300, true );
    }

    update_option( 'wpide_search_log', $log, false );
} );

add_action( 'wp_dashboard_setup', function () {
    if ( ! current_user_can( 'manage_options' ) ) {
        return;
    }

    wp_add_dashboard_widget( 'wpide_search_log', 'Top Site Searches', function () {
        $log = get_option( 'wpide_search_log', array() );

        if ( ! is_array( $log ) || ! $log ) {
            echo '<p>No searches recorded yet.</p>';
            return;
        }

        uasort( $log, function ( $a, $b ) {
            return $b['count'] <=> $a['count'];
        } );

        echo '<table class="widefat striped"><thead><tr><th>Search</th><th>Times</th><th>Results</th></tr></thead><tbody>';

        foreach ( array_slice( $log, 0, 15, true ) as $term => $row ) {
            $results = (int) $row['results'];
            echo '<tr><td>' . esc_html( $term ) . '</td><td>' . esc_html( number_format_i18n( (int) $row['count'] ) ) . '</td><td' . ( 0 === $results ? ' style="color:#d63638;font-weight:600;"' : '' ) . '>' . esc_html( number_format_i18n( $results ) ) . '</td></tr>';
        }

        echo '</tbody></table>';
    } );
} );

add_action( 'loop_start', function ( $query ) {
    static $done = false;

    if ( $done || ! $query->is_main_query() || ! $query->is_search() ) {
        return;
    }

    $done  = true;
    $count = (int) $query->found_posts;
    $label = 1 === $count ? '%1$s result for "%2$s"' : '%1$s results for "%2$s"';

    echo '<p class="wpide-search-count">' . esc_html( sprintf( $label, number_format_i18n( $count ), get_search_query( false ) ) ) . '</p>';
} );

// Maximum searches per visitor per minute.
$wpide_search_rate_limit = 20;

add_action( 'template_redirect', function () use ( $wpide_search_rate_limit ) {
    if ( ! is_search() || current_user_can( 'edit_posts' ) ) {
        return;
    }

    $ip = isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : '';

    if ( '' === $ip ) {
        return;
    }

    $key   = 'wpide_search_rl_' . substr( wp_hash( $ip ), 0, 20 );
    $count = (int) get_transient( $key );

    if ( $count >= $wpide_search_rate_limit ) {
        header( 'Retry-After: 60' );
        wp_die( 'Too many searches in a short time. Please wait a minute and try again.', 'Too many requests', array( 'response' => 429 ) );
    }

    set_transient( $key, $count + 1, MINUTE_IN_SECONDS );
}, 1 );

add_action( 'pre_get_posts', function ( $query ) {
    if ( ! is_admin() && $query->is_main_query() && $query->is_search() ) {
        $query->set( 'sentence', true );
    }
