add_action( 'wp_footer', function () {
    ?>
    <style>
        .wpide-live-results{position:absolute;z-index:999;left:0;right:0;top:100%;margin:4px 0 0;padding:4px 0;list-style:none;background:#fff;color:#1d2327;border:1px solid rgba(0,0,0,.15);border-radius:6px;box-shadow:0 6px 20px rgba(0,0,0,.12);}
        .wpide-live-results a{display:block;padding:.45em .9em;color:inherit;text-decoration:none;}
        .wpide-live-results a:hover,.wpide-live-results a:focus{background:#f0f6fc;}
    </style>
    <script>
        (function () {
            var endpoint = <?php echo wp_json_encode( esc_url_raw( rest_url( 'wp/v2/search' ) ) ); ?>;

            function decode(text) {
                var area = document.createElement('textarea');
                area.innerHTML = text;
                return area.value;
            }

            document.querySelectorAll('form input[name="s"]').forEach(function (input) {
                var form = input.form;
                var box = document.createElement('ul');
                var timer;
                var controller;

                box.className = 'wpide-live-results';
                box.hidden = true;

                if (getComputedStyle(form).position === 'static') {
                    form.style.position = 'relative';
                }

                form.appendChild(box);
                input.setAttribute('autocomplete', 'off');

                input.addEventListener('input', function () {
                    var term = input.value.trim();

                    clearTimeout(timer);

                    if (term.length < 3) {
                        box.hidden = true;
                        return;
                    }

                    timer = setTimeout(function () {
                        if (controller) {
                            controller.abort();
                        }

                        controller = new AbortController();

                        fetch(endpoint + (endpoint.indexOf('?') === -1 ? '?' : '&') + 'per_page=6&search=' + encodeURIComponent(term), { signal: controller.signal })
                            .then(function (response) {
                                return response.json();
                            })
                            .then(function (items) {
                                box.innerHTML = '';

                                if (!Array.isArray(items) || !items.length) {
                                    box.hidden = true;
                                    return;
                                }

                                items.forEach(function (item) {
                                    var li = document.createElement('li');
                                    var link = document.createElement('a');
                                    link.href = item.url;
                                    link.textContent = decode(item.title);
                                    li.appendChild(link);
                                    box.appendChild(li);
                                });

                                box.hidden = false;
                            })
                            .catch(function () {});
                    }, 250);
                });

                input.addEventListener('keydown', function (event) {
                    if (event.key === 'Escape') {
                        box.hidden = true;
                    }
                });

                document.addEventListener('click', function (event) {
                    if (!form.contains(event.target)) {
                        box.hidden = true;
                    }
                });
            });
        })();
    </script>
    <?php
} );

document.addEventListener('keydown', function (event) {
    if (event.key !== '/' || event.ctrlKey || event.metaKey || event.altKey) {
        return;
    }

    var active = document.activeElement;

    if (active && (active.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(active.tagName))) {
        return;
    }

    var field = document.querySelector('input[type="search"], input[name="s"]');

    if (field) {
        event.preventDefault();
        field.focus();
        field.select();
    }
});

add_filter( 'get_the_excerpt', function ( $excerpt, $post = null ) {
    if ( is_admin() || ! is_search() || ! in_the_loop() || ! $post || ! function_exists( 'mb_stripos' ) ) {
        return $excerpt;
    }

    $terms = array_filter( preg_split( '/\s+/', trim( (string) get_search_query( false ) ) ), function ( $term ) {
        return mb_strlen( $term ) > 2;
    } );

    if ( ! $terms ) {
        return $excerpt;
    }

    $text = trim( preg_replace( '/\s+/u', ' ', wp_strip_all_tags( strip_shortcodes( excerpt_remove_blocks( $post->post_content ) ) ) ) );

    foreach ( $terms as $term ) {
        $position = mb_stripos( $text, $term );

        if ( false === $position ) {
            continue;
        }

        $start   = max( 0, $position - 100 );
        $passage = mb_substr( $text, $start, 260 );

        if ( $start > 0 ) {
            $passage = preg_replace( '/^\S*\s/u', '', $passage );
        }

        if ( $start + 260 < mb_strlen( $text ) ) {
            $passage = preg_replace( '/\s\S*$/u', '', $passage );
        }

        return ( $start > 0 ? '&hellip; ' : '' ) . esc_html( $passage ) . ( $start + 260 < mb_strlen( $text ) ? ' &hellip;' : '' );
    }

    return $excerpt;
}, 20, 2 );

add_filter( 'posts_search', function ( $search, $query ) {
    global $wpdb;

    if ( '' === $search || is_admin() || ! $query->is_main_query() || ! $query->is_search() ) {
        return $search;
    }

    $types = array_filter( (array) $query->get( 'post_type' ) );

    if ( $types && ! array_intersect( $types, array( 'product', 'any' ) ) ) {
        return $search;
    }

    $lookup  = $wpdb->prefix . 'wc_product_meta_lookup';
    $pattern = '/\(' . preg_quote( $wpdb->posts, '/' ) . '\.post_title LIKE (\'(?:[^\'\\\\]|\\\\.)*\')\)/';

    $result = preg_replace_callback( $pattern, function ( $m ) use ( $wpdb, $lookup ) {
        return $m[0] . " OR ({$wpdb->posts}.ID IN (SELECT IF(sku_posts.post_parent > 0, sku_posts.post_parent, sku_posts.ID) FROM {$lookup} sku_lookup INNER JOIN {$wpdb->posts} sku_posts ON sku_posts.ID = sku_lookup.product_id WHERE sku_lookup.sku LIKE {$m[1]}))";
    }, $search );

    return null === $result ? $search : $result;
}, 10, 2 );

