add_filter( 'dynamic_sidebar_params', function ( $params ) {
    global $wp_registered_widgets;

    $widget_id = isset( $params[0]['widget_id'] ) ? $params[0]['widget_id'] : '';
    $callback  = isset( $wp_registered_widgets[ $widget_id ]['callback'][0] ) ? $wp_registered_widgets[ $widget_id ]['callback'][0] : null;

    if ( ! $callback instanceof WP_Widget || ! isset( $params[1]['number'] ) ) {
        return $params;
    }

    $settings = $callback->get_settings();
    $classes  = isset( $settings[ $params[1]['number'] ]['wpide_css_class'] ) ? $settings[ $params[1]['number'] ]['wpide_css_class'] : '';

    if ( '' !== $classes ) {
        $params[0]['before_widget'] = preg_replace( '/class="/', 'class="' . esc_attr( $classes ) . ' ', $params[0]['before_widget'], 1 );
    }

    return $params;
} );

