add_filter( 'wp_theme_json_data_theme', function ( $theme_json ) use ( $wpide_brand_colors ) {
    $data    = $theme_json->get_data();
    $palette = isset( $data['settings']['color']['palette'] ) && is_array( $data['settings']['color']['palette'] ) ? $data['settings']['color']['palette'] : array();
    $palette = isset( $palette['theme'] ) && is_array( $palette['theme'] ) ? $palette['theme'] : $palette;
    $by_slug = array();

    foreach ( array_merge( $palette, $wpide_brand_colors ) as $color ) {
        if ( isset( $color['slug'], $color['color'] ) ) {
            $by_slug[ $color['slug'] ] = $color;
