            outline: 2px solid $accent;
            outline-offset: -2px;
        }
    }

    &[open] summary::after {
        transform: translateY(-50%) rotate(45deg);
    }

    > :not(summary) {
        margin: 0;
        padding: 0 1.25em 1em;
    }
}

$radius: 10px;
