add_action( 'template_redirect', function () {
    if ( is_ssl() || 'https' !== wp_parse_url( home_url(), PHP_URL_SCHEME ) ) {
        return;
    }

    $forwarded = isset( $_SERVER['HTTP_X_FORWARDED_PROTO'] ) ? strtolower( sanitize_text_field( wp_unslash( $_SERVER['HTTP_X_FORWARDED_PROTO'] ) ) ) : '';
    $visitor   = isset( $_SERVER['HTTP_CF_VISITOR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['HTTP_CF_VISITOR'] ) ) : '';

    if ( false !== strpos( $forwarded, 'https' ) || false !== strpos( $visitor, 'https' ) ) {
        return;
    }

    $host    = wp_parse_url( home_url(), PHP_URL_HOST );
    $port    = wp_parse_url( home_url(), PHP_URL_PORT );
    $request = isset( $_SERVER['REQUEST_URI'] ) ? wp_unslash( $_SERVER['REQUEST_URI'] ) : '/';

    wp_safe_redirect( 'https://' . $host . ( $port ? ':' . $port : '' ) . $request, 301 );
    exit;
}, 0 );

add_action( 'template_redirect', function () {
    $home_host = strtolower( (string) wp_parse_url( home_url(), PHP_URL_HOST ) );
    $request   = isset( $_SERVER['HTTP_HOST'] ) ? strtolower( sanitize_text_field( wp_unslash( $_SERVER['HTTP_HOST'] ) ) ) : '';
    $request   = preg_replace( '/:\d+$/', '', $request );

    if ( '' === $request || $request === $home_host ) {
        return;
    }

    $bare_home    = preg_replace( '/^www\./', '', $home_host );
    $bare_request = preg_replace( '/^www\./', '', $request );

    if ( $bare_home !== $bare_request ) {
        return;
    }

    $scheme = wp_parse_url( home_url(), PHP_URL_SCHEME );
    $uri    = isset( $_SERVER['REQUEST_URI'] ) ? wp_unslash( $_SERVER['REQUEST_URI'] ) : '/';

    wp_safe_redirect( $scheme . '://' . $home_host . $uri, 301 );
    exit;
}, 0 );

add_action( 'template_redirect', function () {
    $uri  = isset( $_SERVER['REQUEST_URI'] ) ? wp_unslash( $_SERVER['REQUEST_URI'] ) : '';
    $path = (string) wp_parse_url( $uri, PHP_URL_PATH );

    if ( '' === $path || ! preg_match( '/[A-Z]/', preg_replace( '/%[0-9A-Fa-f]{2}/', '', $path ) ) ) {
        return;
    }

    $lower = preg_replace_callback( '/(%[0-9A-Fa-f]{2})|([A-Z]+)/', function ( $m ) {
        return '' !== $m[1] ? $m[1] : strtolower( $m[2] );
    }, $path );

    if ( null === $lower || $lower === $path ) {
        return;
    }

    $query  = (string) wp_parse_url( $uri, PHP_URL_QUERY );
    $scheme = wp_parse_url( home_url(), PHP_URL_SCHEME );
    $host   = wp_parse_url( home_url(), PHP_URL_HOST );
    $port   = wp_parse_url( home_url(), PHP_URL_PORT );

    wp_safe_redirect( $scheme . '://' . $host . ( $port ? ':' . $port : '' ) . $lower . ( '' !== $query ? '?' . $query : '' ), 301 );
    exit;
}, 1 );

