add_action( 'template_redirect', function () {
    if ( ! is_page() || is_front_page() ) {
        return;
    }

    $page = get_queried_object();

    if ( ! $page instanceof WP_Post || '' !== trim( $page->post_content ) ) {
        return;
    }

    $children = get_posts( array(
        'post_type'   => 'page',
        'post_parent' => $page->ID,
        'post_status' => 'publish',
        'orderby'     => array( 'menu_order' => 'ASC', 'title' => 'ASC' ),
