    }
} );

// Pattern => target. * matches anything; $1, $2 ... insert the matched text. Examples:
// '/old-blog/*'         => '/blog/$1',
// '/products/*/manual/' => '/docs/$1/',
$wpide_wildcard_redirects = array();

add_action( 'template_redirect', function () use ( $wpide_wildcard_redirects ) {
    $path = isset( $_SERVER['REQUEST_URI'] ) ? (string) wp_parse_url( wp_unslash( $_SERVER['REQUEST_URI'] ), PHP_URL_PATH ) : '';

    if ( '' === $path ) {
        return;
    }

    foreach ( $wpide_wildcard_redirects as $pattern => $target ) {
        $regex = '#^' . str_replace( '\*', '(.*?)', preg_quote( $pattern, '#' ) ) . '$#i';

        if ( ! preg_match( $regex, $path, $matches ) ) {
            continue;
        }

        $url = preg_replace_callback( '/\$(\d+)/', function ( $ref ) use ( $matches ) {
            return isset( $matches[ (int) $ref[1] ] ) ? $matches[ (int) $ref[1] ] : '';
        }, $target );

        $url       = preg_match( '#^https?://#i', $url ) ? $url : home_url( $url );
        $same_host = ! wp_parse_url( $url, PHP_URL_HOST ) || wp_parse_url( $url, PHP_URL_HOST ) === wp_parse_url( home_url(), PHP_URL_HOST );

        if ( $same_host && untrailingslashit( (string) wp_parse_url( $url, PHP_URL_PATH ) ) === untrailingslashit( $path ) ) {
            return;
        }

        wp_safe_redirect( $url, 301 );
        exit;
    }
}, 1 );

add_action( 'template_redirect', function () {
    if ( ! is_404() ) {
        return;
    }

    $path = isset( $_SERVER['REQUEST_URI'] ) ? (string) wp_parse_url( wp_unslash( $_SERVER['REQUEST_URI'] ), PHP_URL_PATH ) : '';

    if ( '' === $path || preg_match( '/\.[a-z0-9]{2,5}$/i', $path ) ) {
        return;
    }

    $segments = array_filter( explode( '/', trim( rawurldecode( $path ), '/' ) ) );
    $last     = $segments ? end( $segments ) : '';
    $words    = trim( preg_replace( '/[^\p{L}\p{N}]+/u', ' ', (string) $last ) );

    if ( '' === $words || is_numeric( $words ) ) {
        return;
    }

    wp_safe_redirect( add_query_arg( 's', rawurlencode( $words ), home_url( '/' ) ), 302 );
    exit;
} );

add_action( 'template_redirect', function () {
    if ( ! is_404() ) {
        return;
    }

    $path = isset( $_SERVER['REQUEST_URI'] ) ? substr( sanitize_text_field( wp_unslash( $_SERVER['REQUEST_URI'] ) ), 0, 255 ) : '';

    if ( '' === $path ) {
        return;
    }

    $referrer = wp_get_raw_referer();
    $log      = get_option( 'wpide_404_log', array() );
    $log      = is_array( $log ) ? $log : array();
    $entry    = isset( $log[ $path ] ) ? $log[ $path ] : array( 'count' => 0, 'last' => 0, 'referrer' => '' );

    $entry['count']++;
    $entry['last'] = time();

    if ( $referrer ) {
        $entry['referrer'] = substr( esc_url_raw( $referrer ), 0, 255 );
    }

    $log[ $path ] = $entry;

    if ( count( $log ) > 200 ) {
        uasort( $log, function ( $a, $b ) {
            return $b['last'] <=> $a['last'];
        } );
        $log = array_slice( $log, 0, 200, true );
    }

    update_option( 'wpide_404_log', $log, false );
} );

add_action( 'admin_menu', function () {
