add_action( 'template_redirect', function () {
    global $wp_query;

    if ( ! is_404() || is_user_logged_in() ) {
        return;
    }

    $id   = (int) $wp_query->get( 'p' ) ? (int) $wp_query->get( 'p' ) : (int) $wp_query->get( 'page_id' );
    $post = $id ? get_post( $id ) : null;

    if ( ! $post ) {
        $name = $wp_query->get( 'pagename' ) ? $wp_query->get( 'pagename' ) : $wp_query->get( 'name' );
        $post = $name ? get_page_by_path( $name, OBJECT, array_values( get_post_types( array( 'public' => true ) ) ) ) : null;
    }

    if ( $post && 'private' === $post->post_status ) {
        wp_safe_redirect( wp_login_url( get_permalink( $post ) ) );
