} );

// Role => destination. {admin} means the wp-admin address.
$wpide_login_destinations = array(
    'administrator' => '{admin}',
    'editor'        => '{admin}edit.php',
    'author'        => '{admin}edit.php',
    'subscriber'    => '/',
);

add_filter( 'login_redirect', function ( $redirect_to, $requested, $user ) use ( $wpide_login_destinations ) {
    if ( ! $user instanceof WP_User ) {
        return $redirect_to;
    }

    if ( $requested && untrailingslashit( $requested ) !== untrailingslashit( admin_url() ) ) {
        return $redirect_to;
    }

    foreach ( (array) $user->roles as $role ) {
        if ( empty( $wpide_login_destinations[ $role ] ) ) {
            continue;
        }

        $target = $wpide_login_destinations[ $role ];

        return 0 === strpos( $target, '{admin}' ) ? admin_url( substr( $target, 7 ) ) : home_url( $target );
    }

    return $redirect_to;
}, 20, 3 );

