    $path = isset( $_SERVER['REQUEST_URI'] ) ? rawurldecode( (string) wp_parse_url( wp_unslash( $_SERVER['REQUEST_URI'] ), PHP_URL_PATH ) ) : '';

    if ( ! preg_match( '#^/?(.*?)([^/]+)\.(?:html?|php|aspx?)$#i', $path, $match ) ) {
