add_action( 'wp_footer', function () {
    ?>
<script>
(function () {
    var marks = [25, 50, 75, 90], sent = {};
    window.dataLayer = window.dataLayer || [];
    function check() {
        var doc = document.documentElement;
        var max = doc.scrollHeight - window.innerHeight;
        if (max <= 0) { return; }
        var percent = Math.round((window.pageYOffset || doc.scrollTop) / max * 100);
        marks.forEach(function (mark) {
            if (percent >= mark && !sent[mark]) {
                sent[mark] = true;
                window.dataLayer.push({ event: 'scroll_depth', scroll_percent: mark, page_path: location.pathname });
            }
        });
    }
    var ticking = false;
    window.addEventListener('scroll', function () {
        if (ticking) { return; }
        ticking = true;
        window.requestAnimationFrame(function () { check(); ticking = false; });
    }, { passive: true });
})();
</script>
    <?php
} );

