<script>
(function () {
    var keys = ['utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content', 'gclid', 'fbclid'];
    var params = new URLSearchParams(location.search), found = {}, has = false;
    keys.forEach(function (k) { var v = params.get(k); if (v) { found[k] = v.slice(0, 200); has = true; } });
    if (has) {
        document.cookie = 'wpide_utm=' + encodeURIComponent(JSON.stringify(found)) + ';path=/;max-age=' + (30 * 86400) + ';SameSite=Lax' + (location.protocol === 'https:' ? ';Secure' : '');
    }
    var match = document.cookie.match(/(?:^|; )wpide_utm=([^;]+)/), stored = {};
    try { stored = match ? JSON.parse(decodeURIComponent(match[1])) : {}; } catch (e) { stored = {}; }
    function fill(root) {
        Object.keys(stored).forEach(function (k) {
            root.querySelectorAll('input[name="' + k + '"], input[name$="[' + k + ']"], input.' + k).forEach(function (input) {
                if (!input.value) { input.value = stored[k]; }
            });
        });
    }
    fill(document);
    document.addEventListener('focusin', function (e) { if (e.target.form) { fill(e.target.form); } });
})();
</script>
