add_action( 'wp_footer', function () {
    if ( ! function_exists( 'edd_is_success_page' ) || ! edd_is_success_page() || ! function_exists( 'edd_get_order_by' ) ) {
        return;
    }

    $session = edd_get_purchase_session();

    if ( empty( $session['purchase_key'] ) ) {
        return;
    }

    $order = edd_get_order_by( 'payment_key', $session['purchase_key'] );

    if ( ! $order || ! in_array( $order->status, array( 'complete', 'publish' ), true ) || edd_get_order_meta( $order->id, '_wpide_ga4_sent', true ) ) {
        return;
    }

    $items = array();

    foreach ( $order->get_items() as $item ) {
        $items[] = array(
            'item_id'   => (string) $item->product_id,
            'item_name' => $item->product_name,
            'price'     => round( (float) $item->total / max( 1, (int) $item->quantity ), 2 ),
            'quantity'  => (int) $item->quantity,
        );
    }

    $data = array(
        'transaction_id' => (string) $order->get_number(),
        'value'          => round( (float) $order->total, 2 ),
        'tax'            => round( (float) $order->tax, 2 ),
        'currency'       => $order->currency,
        'items'          => $items,
    );

    echo "<script>window.dataLayer = window.dataLayer || []; function gtag(){dataLayer.push(arguments);} gtag('event', 'purchase', " . wp_json_encode( $data ) . ");</script>\n";

    edd_update_order_meta( $order->id, '_wpide_ga4_sent', time() );
} );

add_action( 'admin_menu', function () {
    add_management_page( 'Debug Log', 'Debug Log', 'manage_options', 'wpide-debug-log', function () {
        $lines = 200; // Number of lines to show from the end of the file.

        $file = WP_CONTENT_DIR . '/debug.log';

        if ( defined( 'WP_DEBUG_LOG' ) && is_string( WP_DEBUG_LOG ) && '' !== WP_DEBUG_LOG ) {
            $file = WP_DEBUG_LOG;
        }

        echo '<div class="wrap"><h1>Debug Log</h1>';

        if ( ! is_readable( $file ) ) {
            echo '<p>No log file found at <code>' . esc_html( $file ) . '</code>.</p></div>';
            return;
        }

        $size   = filesize( $file );
        $handle = fopen( $file, 'rb' ); // phpcs:ignore WordPress.WP.AlternativeFunctions
        $chunk  = min( $size, 256 * 1024 );

        fseek( $handle, -$chunk, SEEK_END );
        $content = (string) fread( $handle, $chunk ); // phpcs:ignore WordPress.WP.AlternativeFunctions
        fclose( $handle ); // phpcs:ignore WordPress.WP.AlternativeFunctions

        $rows = array_slice( explode( "\n", trim( $content ) ), -$lines );

        printf( '<p><code>%1$s</code> (%2$s, last modified %3$s)</p>', esc_html( $file ), esc_html( size_format( $size ) ), esc_html( wp_date( 'Y-m-d H:i:s', filemtime( $file ) ) ) );
        echo '<pre style="max-height:70vh;overflow:auto;padding:12px;background:#1e1e1e;color:#f0f0f1;font-size:12px;line-height:1.5;white-space:pre-wrap;">' . esc_html( implode( "\n", $rows ) ) . '</pre></div>';
    } );
} );

