add_filter( 'wp_redirect', function ( $location, $status ) {
    $source = '';

    foreach ( debug_backtrace( DEBUG_BACKTRACE_IGNORE_ARGS ) as $frame ) { // phpcs:ignore WordPress.PHP.DevelopmentFunctions
        if ( isset( $frame['file'] ) && false === strpos( $frame['file'], 'wp-includes' ) ) {
            $source = str_replace( ABSPATH, '', $frame['file'] ) . ':' . ( $frame['line'] ?? '?' );
            break;
        }
    }

    $from = isset( $_SERVER['REQUEST_URI'] ) ? esc_url_raw( wp_unslash( $_SERVER['REQUEST_URI'] ) ) : '';

    error_log( sprintf( '[redirect] %d %s -> %s (from %s)', $status, $from, $location, $source ) ); // phpcs:ignore WordPress.PHP.DevelopmentFunctions

    return $location;
}, 999, 2 );

