add_action( 'wp_footer', function () {
    global $wpdb;

    $limit = 10; // Number of slowest queries to list.

    if ( ! defined( 'SAVEQUERIES' ) || ! SAVEQUERIES || ! current_user_can( 'manage_options' ) || empty( $wpdb->queries ) ) {
        return;
    }

    $queries = $wpdb->queries;

    usort( $queries, function ( $a, $b ) {
        return $b[1] <=> $a[1];
    } );

    $lines = array( sprintf( 'Slowest %d of %d queries', min( $limit, count( $queries ) ), count( $queries ) ) );

    foreach ( array_slice( $queries, 0, $limit ) as $query ) {
        $lines[] = sprintf( '%.4fs | %s | %s', $query[1], preg_replace( '/\s+/', ' ', mb_substr( $query[0], 0, 300 ) ), $query[2] );
    }

    echo "\n<!--\n" . esc_html( str_replace( '--', '- -', implode( "\n", $lines ) ) ) . "\n-->\n";
}, 9999 );

