add_filter( 'wp_mail', function ( $atts ) {
    $test_address = ''; // Inbox that receives every email on non-production sites.

    if ( 'production' === wp_get_environment_type() || ! is_email( $test_address ) ) {
        return $atts;
    }

    $original        = implode( ', ', (array) $atts['to'] );
    $atts['to']      = $test_address;
    $atts['subject'] = '[To: ' . $original . '] ' . $atts['subject'];

    // Drop CC and BCC headers so nobody else gets a copy.
    if ( ! empty( $atts['headers'] ) ) {
        $headers         = is_array( $atts['headers'] ) ? $atts['headers'] : explode( "\n", str_replace( "\r\n", "\n", (string) $atts['headers'] ) );
        $atts['headers'] = array_values( array_filter( $headers, function ( $header ) {
            return ! preg_match( '/^\s*(cc|bcc)\s*:/i', (string) $header );
        } ) );
    }

    return $atts;
}, 999 );

