    $url = network_site_url( 'wp-login.php?action=rp&key=' . $key . '&login=' . rawurlencode( $user_login ), 'login' );

    return sprintf( "Hi %s,\n\n", $user->display_name ? $user->display_name : $user_login )
        . "We received a request to reset the password for your account.\n\n"
        . "Choose a new password here:\n" . $url . "\n\n"
        . "If you did not ask for this, you can ignore this email and your password will stay the same.\n";
}, 10, 4 );

add_action( 'transition_post_status', function ( $new_status, $old_status, $post ) {
    $roles = array( 'editor', 'administrator' ); // Roles that receive the email.

    if ( 'pending' !== $new_status || 'pending' === $old_status || wp_is_post_revision( $post ) ) {
        return;
    }

    $emails = get_users( array( 'role__in' => $roles, 'fields' => array( 'user_email' ) ) );
    $to     = wp_list_pluck( $emails, 'user_email' );

    if ( ! $to ) {
        return;
    }

    $author = get_the_author_meta( 'display_name', $post->post_author );

    wp_mail(
        $to,
        sprintf( 'Pending review: %s', wp_strip_all_tags( $post->post_title ) ),
        sprintf( "%s submitted \"%s\" for review.\n\nReview it here: %s\n", $author, wp_strip_all_tags( $post->post_title ), admin_url( 'post.php?post=' . $post->ID . '&action=edit' ) )
    );
}, 10, 3 );

add_action( 'transition_post_status', function ( $new_status, $old_status, $post ) {
    if ( 'publish' !== $new_status || 'publish' === $old_status || 'post' !== $post->post_type ) {
        return;
    }

    if ( (int) $post->post_author === get_current_user_id() ) {
        return;
    }

    $author = get_userdata( $post->post_author );

    if ( ! $author || ! is_email( $author->user_email ) ) {
        return;
    }

    wp_mail(
        $author->user_email,
        sprintf( 'Your post is live: %s', wp_strip_all_tags( $post->post_title ) ),
        sprintf( "Hi %s,\n\nGood news: \"%s\" is now published.\n\n%s\n", $author->display_name, wp_strip_all_tags( $post->post_title ), get_permalink( $post ) )
    );
}, 10, 3 );

add_action( 'set_user_role', function ( $user_id, $role, $old_roles ) {
    if ( empty( $old_roles ) ) {
        return; // New user, not a change.
    }

    $user  = get_userdata( $user_id );
    $actor = wp_get_current_user();

    if ( ! $user ) {
        return;
    }

    wp_mail(
        get_option( 'admin_email' ),
        sprintf( 'Role changed for %s', $user->user_login ),
        sprintf(
            "The role of %1\$s changed from %2\$s to %3\$s.\nChanged by: %4\$s\nTime: %5\$s\n",
            $user->user_login,
            implode( ', ', (array) $old_roles ),
            $role,
            $actor->exists() ? $actor->user_login : 'system',
            wp_date( 'Y-m-d H:i:s' )
        )
    );
}, 10, 3 );

add_filter( 'wp_mail', function ( $atts ) {
    $extra = array(); // For example array( 'ops@yourdomain.com', 'owner@yourdomain.com' ).

    $admin = strtolower( (string) get_option( 'admin_email' ) );
    $to    = array_map( 'trim', is_array( $atts['to'] ) ? $atts['to'] : explode( ',', (string) $atts['to'] ) );

    if ( ! $extra || ! in_array( $admin, array_map( 'strtolower', $to ), true ) ) {
        return $atts;
    }

    $atts['to'] = array_values( array_unique( array_merge( $to, array_filter( $extra, 'is_email' ) ) ) );

    return $atts;
} );

add_action( 'phpmailer_init', function ( $phpmailer ) {
    if ( empty( $phpmailer->Sender ) && is_email( $phpmailer->From ) ) {
        $phpmailer->Sender = $phpmailer->From;
    }
} );

add_action( 'phpmailer_init', function ( $phpmailer ) {
    if ( 'text/html' !== $phpmailer->ContentType || '' !== $phpmailer->AltBody ) {
        return;
    }

    $text = preg_replace( '#<a[^>]+href=["\']([^"\']+)["\'][^>]*>(.*?)</a>#is', '$2 ($1)', $phpmailer->Body );
    $text = preg_replace( '#<(br|/p|/div|/h[1-6]|/tr|/li)[^>]*>#i', "\n", $text );
    $text = wp_strip_all_tags( $text );
    $text = html_entity_decode( $text, ENT_QUOTES, 'UTF-8' );
    $text = preg_replace( "/\n{3,}/", "\n\n", $text );

    $phpmailer->AltBody = trim( $text );
} );

add_action( 'phpmailer_init', function ( $phpmailer ) {
    if ( ! defined( 'WPIDE_DKIM_DOMAIN' ) || ! defined( 'WPIDE_DKIM_SELECTOR' ) || ! defined( 'WPIDE_DKIM_PRIVATE_KEY' ) ) {
        return;
    }

    if ( ! is_readable( WPIDE_DKIM_PRIVATE_KEY ) ) {
        return;
    }

    $phpmailer->DKIM_domain   = WPIDE_DKIM_DOMAIN;
    $phpmailer->DKIM_selector = WPIDE_DKIM_SELECTOR;
    $phpmailer->DKIM_private  = WPIDE_DKIM_PRIVATE_KEY;
    $phpmailer->DKIM_identity = $phpmailer->From;

    if ( defined( 'WPIDE_DKIM_PASSPHRASE' ) ) {
        $phpmailer->DKIM_passphrase = WPIDE_DKIM_PASSPHRASE;
    }
} );

add_filter( 'comment_moderation_recipients', function ( $emails ) {
