add_filter( 'woocommerce_email_attachments', function ( $attachments, $email_id ) {
    $attachment_id = 0;  // Media Library attachment ID.
    $file_path     = ''; // Or an absolute path on the server.
    $email_ids     = array( 'customer_completed_order' ); // Emails that get the file.

    if ( ! in_array( $email_id, $email_ids, true ) ) {
        return $attachments;
