    $button = '<p><button type="button" class="wpide-listen" hidden style="padding:6px 14px;border:1px solid currentColor;border-radius:20px;background:transparent;cursor:pointer;">&#9654; Listen to this article</button></p>';

    $script = "<script>(function(){var b=document.querySelector('.wpide-listen');if(!b||!('speechSynthesis' in window)){return;}b.hidden=false;var playing=false;b.addEventListener('click',function(){if(playing){speechSynthesis.cancel();playing=false;b.innerHTML='&#9654; Listen to this article';return;}var c=b.closest('.entry-content,.wp-block-post-content')||document.querySelector('article');var u=new SpeechSynthesisUtterance((c?c.innerText:'').replace(b.innerText,''));u.lang=document.documentElement.lang||'en';u.onend=function(){playing=false;b.innerHTML='&#9654; Listen to this article';};speechSynthesis.cancel();speechSynthesis.speak(u);playing=true;b.innerHTML='&#9632; Stop';});})();</script>";

    return $button . $content . $script;
}, 25 );

