$spacers: (
    0: 0,
    1: .25rem,
    2: .5rem,
    3: 1rem,
    4: 1.5rem,
    5: 3rem
);

$properties: (
    m: margin,
    p: padding
);

$sides: (
    t: top,
    b: bottom,
    l: left,
    r: right
);

@each $abbr, $property in $properties {
    @each $key, $size in $spacers {
        .#{$abbr}-#{$key} {
            #{$property}: $size !important;
        }

        .#{$abbr}x-#{$key} {
            #{$property}-left: $size !important;
            #{$property}-right: $size !important;
        }

        .#{$abbr}y-#{$key} {
            #{$property}-top: $size !important;
            #{$property}-bottom: $size !important;
        }

        @each $side-abbr, $side in $sides {
            .#{$abbr}#{$side-abbr}-#{$key} {
                #{$property}-#{$side}: $size !important;
            }
        }
    }
}

