$min-viewport: 360px;
$max-viewport: 1200px;

// Heading => (min size, max size) in rem.
$headings: (
    h1: (2rem, 3.25rem),
    h2: (1.6rem, 2.4rem),
    h3: (1.3rem, 1.75rem),
    h4: (1.1rem, 1.35rem)
);

@function strip-unit($value) {
    @return $value / ($value * 0 + 1);
}

@mixin fluid-size($min, $max) {
    $slope: (strip-unit($max) - strip-unit($min)) * 16 / (strip-unit($max-viewport) - strip-unit($min-viewport));
    $base: strip-unit($min) - $slope * strip-unit($min-viewport) / 16;
    $base-rem: round($base * 1000) / 1000 * 1rem;
    $slope-vw: round($slope * 100000) / 1000 * 1vw;
    font-size: unquote("clamp(#{$min}, #{$base-rem} + #{$slope-vw}, #{$max})");
}

@each $tag, $sizes in $headings {
    #{$tag} {
        @include fluid-size(nth($sizes, 1), nth($sizes, 2));
        line-height: 1.2;
    }
}

