add_action( 'pre_get_posts', function ( $query ) {
    if ( is_admin() || ! $query->is_main_query() || ! $query->is_search() ) {
        return;
    }

    $meta_query   = (array) $query->get( 'meta_query' );
    $meta_query[] = array(
        'relation' => 'OR',
        array(
            'key'     => '_stock_status',
            'value'   => 'outofstock',
            'compare' => '!=',
        ),
        array(
            'key'     => '_stock_status',
            'compare' => 'NOT EXISTS',
        ),
    );

    $query->set( 'meta_query', $meta_query );
} );

add_filter( 'posts_clauses', function ( $clauses, $query ) {
    global $wpdb;

    if ( is_admin() || ! $query->is_main_query() ) {
        return $clauses;
    }

    if ( ! ( $query->is_post_type_archive( 'product' ) || $query->is_tax( get_object_taxonomies( 'product' ) ) ) ) {
        return $clauses;
    }

    $lookup = $wpdb->prefix . 'wc_product_meta_lookup';

    if ( false === strpos( $clauses['join'], 'wpide_stock_sort' ) ) {
        $clauses['join'] .= " LEFT JOIN {$lookup} AS wpide_stock_sort ON {$wpdb->posts}.ID = wpide_stock_sort.product_id ";
    }

    $order = "CASE WHEN wpide_stock_sort.stock_status = 'outofstock' THEN 1 ELSE 0 END ASC";
    $clauses['orderby'] = $clauses['orderby'] ? $order . ', ' . $clauses['orderby'] : $order;

    return $clauses;
}, 20, 2 );

add_filter( 'woocommerce_get_availability_text', function ( $text, $product ) {
    // Your wording for each stock status. Empty keeps the default.
    $messages = array(
        'outofstock'  => 'Sold out, back soon',
        'onbackorder' => 'Ships in 2-3 weeks',
    );

    if ( ! $product instanceof WC_Product ) {
        return $text;
    }

    $status = $product->get_stock_status();

    return ! empty( $messages[ $status ] ) ? $messages[ $status ] : $text;
}, 10, 2 );

add_filter( 'woocommerce_get_availability_text', function ( $text, $product ) {
    $threshold = 5; // Show the message at this many units or fewer.

    if ( ! $product instanceof WC_Product || ! $product->managing_stock() || ! $product->is_in_stock() ) {
        return $text;
    }

    $qty = (int) $product->get_stock_quantity();

    if ( $qty > 0 && $qty <= $threshold ) {
        return sprintf( 'Only %d left, order soon', $qty );
    }

    return $text;
}, 20, 2 );

