$wpide_min_qty = array(
    'minimum'     => 2,       // Minimum units per product.
    'product_ids' => array(), // Limit to these product IDs, empty for all.
);

$wpide_min_qty_applies = function ( $product_id ) use ( $wpide_min_qty ) {
    return empty( $wpide_min_qty['product_ids'] ) || in_array( (int) $product_id, array_map( 'intval', $wpide_min_qty['product_ids'] ), true );
};

add_filter( 'woocommerce_quantity_input_args', function ( $args, $product ) use ( $wpide_min_qty, $wpide_min_qty_applies ) {
    $id = $product->get_parent_id() ? $product->get_parent_id() : $product->get_id();

    if ( $product->is_sold_individually() || ! $wpide_min_qty_applies( $id ) ) {
        return $args;
    }

    $args['min_value'] = $wpide_min_qty['minimum'];

    if ( ! is_cart() && (int) $args['input_value'] < $wpide_min_qty['minimum'] ) {
        $args['input_value'] = $wpide_min_qty['minimum'];
    }

    return $args;
}, 10, 2 );

add_action( 'woocommerce_check_cart_items', function () use ( $wpide_min_qty, $wpide_min_qty_applies ) {
    foreach ( WC()->cart->get_cart() as $item ) {
        $product = $item['data'];

        if ( $product->is_sold_individually() || ! $wpide_min_qty_applies( $item['product_id'] ) ) {
            continue;
        }

        if ( (int) $item['quantity'] < $wpide_min_qty['minimum'] ) {
            wc_add_notice( sprintf( 'Please order at least %1$d of "%2$s".', $wpide_min_qty['minimum'], $product->get_name() ), 'error' );
        }
    }
} );

$wpide_qty_step = 6; // Products can only be bought in multiples of this number.

add_filter( 'woocommerce_quantity_input_args', function ( $args, $product ) use ( $wpide_qty_step ) {
    if ( $product->is_sold_individually() ) {
        return $args;
    }

    $args['step']      = $wpide_qty_step;
    $args['min_value'] = max( $wpide_qty_step, (int) $args['min_value'] );

    if ( (int) $args['input_value'] < $wpide_qty_step ) {
        $args['input_value'] = $wpide_qty_step;
    }

    return $args;
}, 10, 2 );

add_filter( 'woocommerce_add_to_cart_validation', function ( $passed, $product_id, $quantity ) use ( $wpide_qty_step ) {
    if ( $quantity % $wpide_qty_step ) {
        wc_add_notice( sprintf( 'This product is sold in packs of %d.', $wpide_qty_step ), 'error' );
        return false;
    }

    return $passed;
}, 10, 3 );

add_action( 'woocommerce_check_cart_items', function () use ( $wpide_qty_step ) {
    foreach ( WC()->cart->get_cart() as $item ) {
        if ( ! $item['data']->is_sold_individually() && $item['quantity'] % $wpide_qty_step ) {
            wc_add_notice( sprintf( '"%1$s" is sold in packs of %2$d. Please adjust the quantity.', $item['data']->get_name(), $wpide_qty_step ), 'error' );
        }
    }
} );

$wpide_max_cart_items = 10; // Largest total quantity allowed in the cart.

add_filter( 'woocommerce_add_to_cart_validation', function ( $passed, $product_id, $quantity ) use ( $wpide_max_cart_items ) {
    $in_cart = WC()->cart ? WC()->cart->get_cart_contents_count() : 0;

    if ( $in_cart + (int) $quantity > $wpide_max_cart_items ) {
        wc_add_notice( sprintf( 'You can have up to %d items in your cart.', $wpide_max_cart_items ), 'error' );
        return false;
    }

    return $passed;
}, 10, 3 );

add_action( 'woocommerce_check_cart_items', function () use ( $wpide_max_cart_items ) {
    if ( WC()->cart->get_cart_contents_count() > $wpide_max_cart_items ) {
        wc_add_notice( sprintf( 'Your cart can contain at most %d items. Please remove some before checking out.', $wpide_max_cart_items ), 'error' );
    }
} );

add_action( 'woocommerce_check_cart_items', function () {
    $maximum = 1000; // Highest subtotal allowed per order.

    $subtotal = (float) WC()->cart->get_subtotal();

    if ( $subtotal > $maximum ) {
        wc_add_notice( sprintf( 'Orders above %s cannot be placed online. Please contact us for a quote.', wc_price( $maximum ) ), 'error' );
    }
} );

add_filter( 'woocommerce_add_to_cart_validation', function ( $passed, $product_id ) {
    if ( $passed && WC()->cart && ! WC()->cart->is_empty() ) {
        foreach ( WC()->cart->get_cart() as $key => $item ) {
            if ( (int) $item['product_id'] !== (int) $product_id ) {
                WC()->cart->remove_cart_item( $key );
            }
        }
    }

    return $passed;
}, 20, 2 );

add_action( 'woocommerce_before_calculate_totals', function ( $cart ) {
    $gift_id   = 0;  // Product ID of the free gift.
    $threshold = 75; // Cart subtotal that unlocks the gift.

    static $running = false;

    if ( ! $gift_id || $running || ( is_admin() && ! wp_doing_ajax() ) ) {
        return;
    }

    $running = true;

    $subtotal = 0;
    $gift_key = '';

    foreach ( $cart->get_cart() as $key => $item ) {
        if ( (int) $item['product_id'] === $gift_id ) {
            $gift_key = $key;
            continue;
        }
        $subtotal += (float) $item['data']->get_price() * (int) $item['quantity'];
    }

    if ( $subtotal >= $threshold && ! $gift_key ) {
        $cart->add_to_cart( $gift_id, 1 );
    } elseif ( $subtotal < $threshold && $gift_key ) {
        $cart->remove_cart_item( $gift_key );
    }

    $running = false;
} );

add_action( 'wp_loaded', function () {
    $param = 'coupon'; // Query parameter that carries the coupon code.

    if ( is_admin() || empty( $_GET[ $param ] ) || ! function_exists( 'WC' ) ) { // phpcs:ignore WordPress.Security.NonceVerification
        return;
    }

    $code = wc_format_coupon_code( sanitize_text_field( wp_unslash( $_GET[ $param ] ) ) ); // phpcs:ignore WordPress.Security.NonceVerification

    if ( '' === $code || ! WC()->session ) {
        return;
    }

    if ( ! WC()->session->has_session() ) {
        WC()->session->set_customer_session_cookie( true );
    }

    WC()->session->set( 'wpide_pending_coupon', $code );
} );

add_action( 'woocommerce_cart_loaded_from_session', function ( $cart ) {
    if ( ! WC()->session ) {
        return;
    }

    $code = WC()->session->get( 'wpide_pending_coupon' );

    if ( ! $code || $cart->is_empty() ) {
        return;
    }

    if ( ! $cart->has_discount( $code ) ) {
        $cart->apply_coupon( $code );
    }

    WC()->session->set( 'wpide_pending_coupon', null );
} );

