add_action( 'woocommerce_cart_calculate_fees', function ( $cart ) {
    $threshold = 20;                  // Orders below this subtotal pay the fee.
    $fee       = 3.50;                // Fee amount.
    $label     = 'Small order fee';   // Name shown in the totals.
    $taxable   = false;               // Whether tax applies to the fee.

    if ( is_admin() && ! wp_doing_ajax() ) {
        return;
    }

    if ( $cart->get_subtotal() > 0 && $cart->get_subtotal() < $threshold ) {
