} );

add_action( 'woocommerce_cart_calculate_fees', function ( $cart ) {
    $gateway    = 'cod';                  // Payment method ID.
    $fixed      = 2.00;                   // Fixed fee, 0 for none.
    $percentage = 0;                      // Percentage of the cart total, 0 for none.
    $label      = 'Cash on delivery fee'; // Name shown in the totals.

    if ( ( is_admin() && ! wp_doing_ajax() ) || ! WC()->session ) {
        return;
    }

    if ( WC()->session->get( 'chosen_payment_method' ) !== $gateway ) {
        return;
    }

    $base   = (float) $cart->get_cart_contents_total() + (float) $cart->get_shipping_total();
    $amount = $fixed + ( $base * $percentage / 100 );

    if ( $amount > 0 ) {
        $cart->add_fee( $label, round( $amount, wc_get_price_decimals() ), true );
    }
} );

