add_action( 'woocommerce_cart_calculate_fees', function ( $cart ) {
    // Items in cart => percentage off. Highest matching tier wins.
    $tiers = array(
        5  => 10,
        10 => 15,
    );

    if ( is_admin() && ! wp_doing_ajax() ) {
        return;
    }

    $count   = $cart->get_cart_contents_count();
    $percent = 0;

    foreach ( $tiers as $qty => $off ) {
        if ( $count >= $qty ) {
            $percent = $off;
        }
    }

    if ( $percent > 0 ) {
        $discount = $cart->get_subtotal() * $percent / 100;
        $cart->add_fee( sprintf( 'Bulk discount (%d%%)', $percent ), -$discount );
    }
} );

$wpide_role_pricing = array(
    'role'    => 'wholesale_customer', // Role that gets the discount.
    'percent' => 20,                   // Discount in percent.
);

$wpide_role_price = function ( $price, $product ) use ( $wpide_role_pricing ) {
    if ( '' === $price || ! is_user_logged_in() ) {
        return $price;
    }

    $user = wp_get_current_user();

    if ( ! in_array( $wpide_role_pricing['role'], (array) $user->roles, true ) ) {
        return $price;
    }

    return (string) round( (float) $price * ( 100 - $wpide_role_pricing['percent'] ) / 100, wc_get_price_decimals() );
};

foreach ( array( 'woocommerce_product_get_price', 'woocommerce_product_get_regular_price', 'woocommerce_product_get_sale_price', 'woocommerce_product_variation_get_price', 'woocommerce_product_variation_get_regular_price', 'woocommerce_product_variation_get_sale_price', 'woocommerce_variation_prices_price', 'woocommerce_variation_prices_regular_price', 'woocommerce_variation_prices_sale_price' ) as $wpide_hook ) {
    add_filter( $wpide_hook, $wpide_role_price, 99, 2 );
}

