add_filter( 'woocommerce_package_rates', function ( $rates, $package ) {
    $shipping_class = 'bulky';       // Shipping class slug.
    $method         = 'free_shipping'; // Method ID to hide when the class is in the cart.

    $found = false;

    foreach ( (array) $package['contents'] as $item ) {
        if ( isset( $item['data'] ) && $item['data']->get_shipping_class() === $shipping_class ) {
            $found = true;
            break;
        }
    }

    if ( ! $found ) {
        return $rates;
    }

    foreach ( $rates as $id => $rate ) {
        if ( $rate->get_method_id() === $method ) {
            unset( $rates[ $id ] );
        }
    }

    return $rates;
}, 10, 2 );

