    if ( ! function_exists( 'is_wc_endpoint_url' ) || ! is_wc_endpoint_url( 'order-received' ) ) {
        return;
    }

    $order_id = absint( get_query_var( 'order-received' ) );
    $key      = isset( $_GET['key'] ) ? wc_clean( wp_unslash( $_GET['key'] ) ) : ''; // phpcs:ignore WordPress.Security.NonceVerification
    $order    = $order_id ? wc_get_order( $order_id ) : false;
    $page     = get_page_by_path( $page_slug );

    if ( ! $order || ! $page || ! hash_equals( $order->get_order_key(), $key ) || $order->has_status( 'failed' ) ) {
        return;
    }

    wp_safe_redirect( add_query_arg( 'order', $order->get_order_number(), get_permalink( $page ) ) );
    exit;
} );

