add_action( 'wp_dashboard_setup', function () {
    if ( ! current_user_can( 'view_woocommerce_reports' ) ) {
        return;
    }

    wp_add_dashboard_widget( 'wpide_todays_sales', 'Today\'s sales', function () {
        $start  = new DateTime( 'today', wp_timezone() );
        $orders = wc_get_orders( array(
            'status'       => array( 'wc-processing', 'wc-completed', 'wc-on-hold' ),
            'date_created' => '>=' . $start->getTimestamp(),
            'limit'        => -1,
            'type'         => 'shop_order',
        ) );

        $count   = count( $orders );
        $revenue = 0;

        foreach ( $orders as $order ) {
            $revenue += (float) $order->get_total() - (float) $order->get_total_refunded();
        }

        $average = $count ? $revenue / $count : 0;

        echo '<table class="widefat striped"><tbody>';
        printf( '<tr><td>Orders</td><td><strong>%d</strong></td></tr>', (int) $count );
        printf( '<tr><td>Revenue</td><td><strong>%s</strong></td></tr>', wp_kses_post( wc_price( $revenue ) ) );
        printf( '<tr><td>Average order</td><td><strong>%s</strong></td></tr>', wp_kses_post( wc_price( $average ) ) );
        echo '</tbody></table>';
        $hpos = class_exists( '\\Automattic\\WooCommerce\\Utilities\\OrderUtil' ) && \Automattic\WooCommerce\Utilities\OrderUtil::custom_orders_table_usage_is_enabled();
        printf( '<p><a href="%s">View orders</a></p>', esc_url( admin_url( $hpos ? 'admin.php?page=wc-orders' : 'edit.php?post_type=shop_order' ) ) );
    } );
} );

