add_action( 'woocommerce_admin_process_product_object', function ( $product ) {
    $prefix = 'SHOP-'; // Text before the number.
    $pad    = 4;       // Minimum number of digits.

    if ( '' !== $product->get_sku( 'edit' ) || ! $product->get_id() ) {
        return;
    }

    $sku = $prefix . str_pad( (string) $product->get_id(), $pad, '0', STR_PAD_LEFT );

    if ( ! wc_get_product_id_by_sku( $sku ) ) {
        try {
            $product->set_sku( $sku );
        } catch ( WC_Data_Exception $e ) {
            // SKU already in use: leave it empty.
        }
    }
} );

$wpide_opening_hours = array(
    // Day number => array( open, close ) in 24h format.
    1 => array( '09:00', '21:00' ),
    2 => array( '09:00', '21:00' ),
    3 => array( '09:00', '21:00' ),
    4 => array( '09:00', '21:00' ),
    5 => array( '09:00', '22:00' ),
    6 => array( '10:00', '22:00' ),
);

$wpide_store_is_open = function () use ( $wpide_opening_hours ) {
    $now = new DateTime( 'now', wp_timezone() );
    $day = (int) $now->format( 'N' );

    if ( empty( $wpide_opening_hours[ $day ] ) ) {
        return false;
    }

    $time = $now->format( 'H:i' );

    return $time >= $wpide_opening_hours[ $day ][0] && $time < $wpide_opening_hours[ $day ][1];
};

