add_action( 'woocommerce_admin_order_data_after_order_details', function ( $order ) {
    $email = $order->get_billing_email();

    if ( ! $email ) {
        return;
    }

    $args = array(
        'limit'   => -1,
        'return'  => 'ids',
        'type'    => 'shop_order',
        'status'  => array( 'wc-completed', 'wc-processing', 'wc-on-hold' ),
        'exclude' => array( $order->get_id() ),
    );

    if ( $order->get_customer_id() ) {
        $args['customer_id'] = $order->get_customer_id();
    } else {
        $args['billing_email'] = $email;
    }

    $ids   = wc_get_orders( $args );
    $spent = 0;

    foreach ( $ids as $id ) {
        $previous = wc_get_order( $id );
        $spent   += $previous ? (float) $previous->get_total() : 0;
    }

    echo '<p class="form-field form-field-wide" style="clear:both;padding-top:8px;">';

    if ( $ids ) {
        printf( '<strong>Returning customer:</strong> %1$d previous orders, %2$s spent.', count( $ids ), wp_kses_post( wc_price( $spent ) ) );
    } else {
        echo '<strong>New customer:</strong> first order.';
    }

    echo '</p>';
} );

add_action( 'woocommerce_single_product_summary', function () {
    $cutoff       = '14:00';                  // Daily dispatch cutoff.
    $working_days = array( 1, 2, 3, 4, 5 );   // Days you ship.

    global $product;

    if ( ! $product instanceof WC_Product || ! $product->is_in_stock() || $product->is_virtual() ) {
        return;
    }

    $now      = new DateTime( 'now', wp_timezone() );
    $deadline = new DateTime( 'today ' . $cutoff, wp_timezone() );

    if ( in_array( (int) $now->format( 'N' ), $working_days, true ) && $now < $deadline ) {
        $diff = $now->diff( $deadline );
        $text = sprintf( 'Order within %1$dh %2$dm for dispatch today.', $diff->h, $diff->i );
    } else {
        $text = 'Order now for dispatch on the next working day.';
    }

    echo '<p class="wpide-dispatch-notice" style="padding:8px 12px;border-radius:4px;background:#f0f6fc;">&#128666; ' . esc_html( $text ) . '</p>';
}, 25 );

