add_action( 'template_redirect', function () {
    if ( ! function_exists( 'is_product' ) || ! is_product() || headers_sent() ) {
        return;
    }

    $id     = (int) get_queried_object_id();
    $viewed = isset( $_COOKIE['wpide_viewed'] ) ? wp_parse_id_list( wp_unslash( $_COOKIE['wpide_viewed'] ) ) : array();
    $viewed = array_diff( $viewed, array( $id ) );
    array_unshift( $viewed, $id );
    $viewed = array_slice( $viewed, 0, 15 );

    setcookie( 'wpide_viewed', implode( ',', $viewed ), array(
        'expires'  => time() + 30 * DAY_IN_SECONDS,
        'path'     => COOKIEPATH ? COOKIEPATH : '/',
        'domain'   => COOKIE_DOMAIN,
        'secure'   => is_ssl(),
        'httponly' => true,
        'samesite' => 'Lax',
    ) );
}, 20 );

