add_filter( 'posts_search', function ( $search, $query ) {
    global $wpdb;

    if ( is_admin() || ! $query->is_main_query() || ! $query->is_search() || '' === $search ) {
        return $search;
    }

    $term = trim( (string) $query->get( 's' ) );

    if ( '' === $term || strlen( $term ) > 100 ) {
        return $search;
    }

    $id = wc_get_product_id_by_sku( $term );

    if ( ! $id ) {
        return $search;
    }

    $product = wc_get_product( $id );
    $id      = $product && $product->get_parent_id() ? $product->get_parent_id() : $id;

    // Wrap the original search clause and add the SKU match to it.
    $inner = preg_replace( '/^\s*AND\s*/', '', $search, 1, $replaced );

    if ( ! $replaced ) {
        return $search;
    }

    return ' AND ( ( ' . $inner . ' ) ' . $wpdb->prepare( "OR {$wpdb->posts}.ID = %d", $id ) . ' ) ';
}, 10, 2 );

$min_days     = 2;                      // Fastest delivery, in working days.
$max_days     = 4;                      // Slowest delivery, in working days.
$working_days = array( 1, 2, 3, 4, 5 ); // 1 = Monday ... 7 = Sunday.

$add_working_days = function ( $days ) use ( $working_days ) {
    $date = new DateTime( 'now', wp_timezone() );

    while ( $days > 0 ) {
        $date->modify( '+1 day' );

        if ( in_array( (int) $date->format( 'N' ), $working_days, true ) ) {
            $days--;
        }
    }

    return $date;
};

$from = $add_working_days( $min_days );
$to   = $add_working_days( $max_days );

