}, 1 );

// Point crawlers to the Markdown version from the normal page.
add_action( 'wp_head', function () use ( $wpide_md_post_types, $wpide_md_url ) {
    $post = get_queried_object();

    if ( ! is_singular( $wpide_md_post_types ) || ! $post instanceof WP_Post || ! is_post_publicly_viewable( $post ) || post_password_required( $post ) ) {
        return;
