} );

// The image link repeats the title link, so it is hidden from screen readers and skipped by the Tab key.
$wpide_featured_link_open = function ( $post_id ) {
    return '<a href="' . esc_url( get_permalink( $post_id ) ) . '" class="wpide-featured-image-link" aria-hidden="true" tabindex="-1">';
};

$wpide_featured_link_skip = function ( $post_id ) {
    return ! $post_id || is_admin() || is_feed() || ( is_singular() && (int) $post_id === get_queried_object_id() );
};

// Classic themes: the_post_thumbnail() and get_the_post_thumbnail().
add_filter( 'post_thumbnail_html', function ( $html, $post_id ) use ( $wpide_featured_link_open, $wpide_featured_link_skip ) {
    if ( '' === trim( (string) $html ) || wp_is_block_theme() || false !== stripos( $html, '<a ' ) || $wpide_featured_link_skip( $post_id ) ) {
