// Block themes: the Featured Image block when "Link to post" is switched off.
add_filter( 'render_block_core/post-featured-image', function ( $content, $block, $instance = null ) use ( $wpide_featured_link_open, $wpide_featured_link_skip ) {
    $post_id = ( $instance instanceof WP_Block && ! empty( $instance->context['postId'] ) ) ? (int) $instance->context['postId'] : 0;

    if ( '' === trim( (string) $content ) || ! empty( $block['attrs']['isLink'] ) || false !== stripos( $content, '<a ' ) || $wpide_featured_link_skip( $post_id ) ) {
        return $content;
    }

    return preg_replace_callback( '/<img\b[^>]*>/i', function ( $match ) use ( $wpide_featured_link_open, $post_id ) {
        return $wpide_featured_link_open( $post_id ) . $match[0] . '</a>';
    }, $content, 1 );
}, 10, 3 );

// Number of words in each automatic feed summary (posts with a written excerpt use it as is).
$wpide_feed_summary_words = 55;

// Link added after each summary. %s is replaced with the post title. Leave empty for no link.
$wpide_feed_continue_text = 'Continue reading: %s';

