// Who can see the box.
$wpide_meta_viewer_capability = 'manage_options';

// Also list hidden keys that start with an underscore (used by WordPress and plugins).
$wpide_meta_viewer_show_hidden = true;

// Post types that get the box. Leave empty for every post type with an edit screen.
$wpide_meta_viewer_post_types = array();

$wpide_meta_viewer_value = function ( $value ) {
    $value = (string) $value;

    if ( '' === $value ) {
        return '<em>(empty)</em>';
    }

    // Serialized data is unpacked for reading only. Objects are never rebuilt.
    if ( is_serialized( $value ) ) {
        $data = @unserialize( trim( $value ), array( 'allowed_classes' => false ) ); // phpcs:ignore WordPress.PHP.NoSilencedErrors, WordPress.PHP.DiscouragedPHPFunctions

        if ( false !== $data || 'b:0;' === trim( $value ) ) {
            return '<span class="wpide-meta-viewer__type">serialized ' . esc_html( gettype( $data ) ) . '</span><pre>' . esc_html( print_r( $data, true ) ) . '</pre>'; // phpcs:ignore WordPress.PHP.DevelopmentFunctions
        }
    }

    $first = substr( ltrim( $value ), 0, 1 );

    if ( '{' === $first || '[' === $first ) {
        $data = json_decode( $value, true );

        if ( null !== $data ) {
            return '<span class="wpide-meta-viewer__type">JSON</span><pre>' . esc_html( (string) wp_json_encode( $data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE ) ) . '</pre>';
        }
    }

    return '<pre>' . esc_html( $value ) . '</pre>';
};

$wpide_meta_viewer_render = function ( $post ) use ( $wpide_meta_viewer_show_hidden, $wpide_meta_viewer_value ) {
    $meta = get_post_meta( $post->ID );
    $meta = is_array( $meta ) ? $meta : array();

    if ( ! $wpide_meta_viewer_show_hidden ) {
        $meta = array_filter( $meta, function ( $key ) {
            return ! is_protected_meta( $key, 'post' );
        }, ARRAY_FILTER_USE_KEY );
    }

    uksort( $meta, 'strnatcasecmp' );

    if ( ! $meta ) {
        echo '<p>This post has no custom fields.</p>';
        return;
    }

    ?>
    <style>
        .wpide-meta-viewer { table-layout: fixed; }
        .wpide-meta-viewer th:first-child { width: 30%; }
        .wpide-meta-viewer td { vertical-align: top; overflow-wrap: anywhere; }
        .wpide-meta-viewer pre { margin: 0; max-height: 240px; overflow: auto; white-space: pre-wrap; word-break: break-word; font-size: 12px; }
        .wpide-meta-viewer__type { display: inline-block; margin-bottom: 4px; padding: 0 6px; border-radius: 3px; background: #f0f0f1; color: #50575e; font-size: 11px; }
        .wpide-meta-viewer-filter { margin: 4px 0 8px; }
    </style>
    <p class="wpide-meta-viewer-filter">
        <label for="wpide-meta-viewer-search"><?php echo esc_html( sprintf( '%d keys. Filter by key:', count( $meta ) ) ); ?></label>
        <input type="search" id="wpide-meta-viewer-search" class="regular-text">
    </p>
    <table class="widefat striped wpide-meta-viewer">
        <thead><tr><th scope="col">Key</th><th scope="col">Value</th></tr></thead>
        <tbody>
        <?php foreach ( $meta as $key => $values ) : ?>
            <?php foreach ( (array) $values as $value ) : ?>
                <tr data-key="<?php echo esc_attr( strtolower( $key ) ); ?>">
                    <td><code><?php echo esc_html( $key ); ?></code></td>
                    <td><?php echo $wpide_meta_viewer_value( $value ); // phpcs:ignore WordPress.Security.EscapeOutput -- escaped when built. ?></td>
                </tr>
            <?php endforeach; ?>
        <?php endforeach; ?>
        </tbody>
    </table>
    <script>
    ( function () {
        var search = document.getElementById( 'wpide-meta-viewer-search' );
        if ( ! search ) { return; }
        search.addEventListener( 'input', function () {
            var term = search.value.trim().toLowerCase();
            document.querySelectorAll( '.wpide-meta-viewer tbody tr' ).forEach( function ( row ) {
                row.hidden = term !== '' && row.getAttribute( 'data-key' ).indexOf( term ) === -1;
            } );
        } );
    } )();
    </script>
    <?php
};

add_action( 'add_meta_boxes', function ( $post_type, $post ) use ( $wpide_meta_viewer_capability, $wpide_meta_viewer_post_types, $wpide_meta_viewer_render ) {
    if ( ! $post instanceof WP_Post || ! current_user_can( $wpide_meta_viewer_capability ) ) {
        return;
    }

    if ( $wpide_meta_viewer_post_types && ! in_array( $post_type, $wpide_meta_viewer_post_types, true ) ) {
        return;
    }

    add_meta_box( 'wpide-post-meta-viewer', 'All Custom Fields (read-only)', $wpide_meta_viewer_render, $post_type, 'normal', 'low' );
}, 10, 2 );

// Users with this capability keep full access to wp-admin. 'edit_posts' covers contributors and up.
$wpide_admin_access_capability = 'edit_posts';

// Let everyone else still open Users > Profile to change their name, email or password.
$wpide_allow_profile_page = false;

// Where to send them. Leave empty for the WooCommerce My Account page (when WooCommerce is active) or the homepage.
// Must be an address on this site.
$wpide_admin_redirect_url = '';

// Also hide the admin bar from these users on the front end.
$wpide_hide_admin_bar_for_them = true;

$wpide_admin_destination = function ( $for_profile = false ) use ( $wpide_admin_redirect_url ) {
    if ( '' !== $wpide_admin_redirect_url ) {
        return $wpide_admin_redirect_url;
    }

    if ( function_exists( 'wc_get_page_id' ) && function_exists( 'wc_get_page_permalink' ) && wc_get_page_id( 'myaccount' ) > 0 ) {
        return ( $for_profile && function_exists( 'wc_get_account_endpoint_url' ) ) ? wc_get_account_endpoint_url( 'edit-account' ) : wc_get_page_permalink( 'myaccount' );
    }

    return home_url( '/' );
};

add_action( 'admin_init', function () use ( $wpide_admin_access_capability, $wpide_allow_profile_page, $wpide_admin_destination ) {
    global $pagenow;

    if ( wp_doing_ajax() || wp_doing_cron() || ! is_user_logged_in() || current_user_can( $wpide_admin_access_capability ) ) {
        return;
    }

    // Front-end forms post to these files.
    if ( in_array( $pagenow, array( 'admin-post.php', 'async-upload.php' ), true ) ) {
        return;
    }

    $is_profile = 'profile.php' === $pagenow;

    if ( $is_profile && $wpide_allow_profile_page ) {
        return;
    }

    wp_safe_redirect( $wpide_admin_destination( $is_profile ) );
    exit;
}, 1 );

// WooCommerce blocks wp-admin for customers on its own. Let the profile page through when it is allowed.
add_filter( 'woocommerce_prevent_admin_access', function ( $prevent ) use ( $wpide_allow_profile_page ) {
    return ( $wpide_allow_profile_page && isset( $GLOBALS['pagenow'] ) && 'profile.php' === $GLOBALS['pagenow'] ) ? false : $prevent;
} );

// "Edit Profile" links point to the front-end account page when the profile screen is closed.
add_filter( 'edit_profile_url', function ( $url, $user_id ) use ( $wpide_admin_access_capability, $wpide_allow_profile_page, $wpide_admin_destination ) {
    if ( $wpide_allow_profile_page || user_can( $user_id, $wpide_admin_access_capability ) ) {
        return $url;
    }

    return $wpide_admin_destination( true );
}, 10, 2 );

add_filter( 'show_admin_bar', function ( $show ) use ( $wpide_hide_admin_bar_for_them, $wpide_admin_access_capability ) {
    if ( $wpide_hide_admin_bar_for_them && is_user_logged_in() && ! current_user_can( $wpide_admin_access_capability ) ) {
        return false;
    }

    return $show;
} );

// Alt text for avatars that have none. %s is replaced with the person's display name.
$wpide_avatar_alt_pattern = '%s';

add_filter( 'get_avatar_data', function ( $args, $id_or_email ) use ( $wpide_avatar_alt_pattern ) {
    if ( ! empty( $args['alt'] ) ) {
        return $args;
    }

    $name = '';

    if ( $id_or_email instanceof WP_Comment ) {
        $name = $id_or_email->user_id ? get_the_author_meta( 'display_name', $id_or_email->user_id ) : $id_or_email->comment_author;
    } elseif ( $id_or_email instanceof WP_User ) {
        $name = $id_or_email->display_name;
    } elseif ( $id_or_email instanceof WP_Post ) {
        $name = get_the_author_meta( 'display_name', $id_or_email->post_author );
    } elseif ( is_numeric( $id_or_email ) ) {
        $name = get_the_author_meta( 'display_name', (int) $id_or_email );
    } elseif ( is_string( $id_or_email ) && is_email( $id_or_email ) ) {
        $user = get_user_by( 'email', $id_or_email );
        $name = $user ? $user->display_name : '';
    }

    $name = trim( wp_strip_all_tags( (string) $name ) );

    if ( '' !== $name ) {
        $args['alt'] = sprintf( $wpide_avatar_alt_pattern, $name );
    }

    return $args;
}, 10, 2 );

// Link text. Screen readers also hear the post title.
$wpide_listing_edit_text = 'Edit';

$wpide_listing_edit_link = function ( $post_id ) use ( $wpide_listing_edit_text ) {
    $url = get_edit_post_link( $post_id, 'raw' );

    if ( ! $url || ! current_user_can( 'edit_post', $post_id ) ) {
        return '';
    }

    $label = $wpide_listing_edit_text . ' “' . wp_strip_all_tags( get_the_title( $post_id ) ) . '”';

    return '<p class="wpide-edit-link"><a class="post-edit-link" href="' . esc_url( $url ) . '" aria-label="' . esc_attr( $label ) . '">' . esc_html( $wpide_listing_edit_text ) . '</a></p>';
};

// Classic themes: after the excerpt or content of each post on blog, archive and search pages.
$wpide_listing_edit_append = function ( $content ) use ( $wpide_listing_edit_link ) {
    if ( is_admin() || is_feed() || is_singular() || wp_is_block_theme() || ! in_the_loop() || doing_filter( 'get_the_excerpt' ) ) {
        return $content;
    }

