$wpide_page_logo_script = function () use ( $wpide_page_logo_post_types ) {
    $screen = get_current_screen();

    if ( ! $screen || ! in_array( $screen->post_type, $wpide_page_logo_post_types, true ) ) {
        return;
    }
    ?>
    <script>
    ( function () {
        var box = document.querySelector( '.wpide-page-logo' );
        if ( ! box || ! window.wp || ! wp.media ) {
            return;
        }

        var input = box.querySelector( 'input[name="wpide_page_logo_id"]' );
        var preview = box.querySelector( '.wpide-page-logo__preview' );
        var remove = box.querySelector( '.wpide-page-logo__remove' );
        var metaKey = box.getAttribute( 'data-meta-key' );
        var frame = null;

        // In the block editor, also store the value in the page itself so "Save" picks up the change.
        function setValue( id ) {
            input.value = id ? String( id ) : '';
            remove.hidden = ! id;
            if ( wp.data && wp.data.select( 'core/editor' ) ) {
                var meta = wp.data.select( 'core/editor' ).getEditedPostAttribute( 'meta' );
                if ( meta && Object.prototype.hasOwnProperty.call( meta, metaKey ) ) {
                    var change = {};
                    change[ metaKey ] = id || 0;
                    wp.data.dispatch( 'core/editor' ).editPost( { meta: change } );
                }
            }
        }

        box.querySelector( '.wpide-page-logo__choose' ).addEventListener( 'click', function () {
            if ( ! frame ) {
                frame = wp.media( {
                    title: 'Choose a logo for this page',
                    button: { text: 'Use as page logo' },
                    library: { type: 'image' },
                    multiple: false
                } );

                frame.on( 'select', function () {
                    var image = frame.state().get( 'selection' ).first().toJSON();
                    var img = document.createElement( 'img' );
                    img.src = image.sizes && image.sizes.medium ? image.sizes.medium.url : image.url;
                    img.alt = '';
                    img.style.maxWidth = '100%';
                    img.style.height = 'auto';
                    preview.textContent = '';
                    preview.appendChild( img );
                    setValue( image.id );
                } );
            }
            frame.open();
        } );

        remove.addEventListener( 'click', function () {
            preview.textContent = '';
            setValue( 0 );
        } );
    } )();
    </script>
    <?php
};

