add_action( 'admin_bar_menu', function ( $bar ) {
    if ( empty( $bar->user->blogs ) || count( $bar->user->blogs ) < 3 ) {
        return;
    }

    $main  = get_main_site_id();
    $blogs = $bar->user->blogs;

    uasort( $blogs, function ( $a, $b ) use ( $main ) {
        if ( (int) $a->userblog_id === $main ) {
            return -1;
        }
        if ( (int) $b->userblog_id === $main ) {
            return 1;
        }
        return strcasecmp( $a->blogname, $b->blogname );
    } );

    $bar->user->blogs = $blogs;
}, 19 ); // My Sites is built at priority 20.

