$wpide_fix = function ( $content ) use ( $wpide_old, $wpide_new ) {
    if ( ! is_string( $content ) || false === strpos( $content, $wpide_old ) ) {
        return $content;
    }

    $variants = array( $wpide_old, set_url_scheme( $wpide_old, 'http' ), str_replace( '/', '\/', $wpide_old ) );

    return str_replace( $variants, array( $wpide_new, $wpide_new, str_replace( '/', '\/', $wpide_new ) ), $content );
};

