    $lines = array();
    foreach ( preg_split( '/\R/', (string) wp_unslash( $_POST['wpide_hreflang'] ?? '' ) ) as $line ) {
        $parts = preg_split( '/\s+/', trim( $line ), 2 );
        if ( 2 === count( $parts ) && preg_match( '/^([a-zA-Z]{2,3}(-[a-zA-Z0-9]{2,8})?|x-default)$/', $parts[0] ) && wp_http_validate_url( $parts[1] ) ) {
