    if ( defined( 'ICL_LANGUAGE_CODE' ) && ICL_LANGUAGE_CODE ) {
        $code = ICL_LANGUAGE_CODE;
    } elseif ( function_exists( 'pll_current_language' ) && pll_current_language() ) {
        $code = pll_current_language();
    }

    $data = array(
        'locale' => $locale,
        'code'   => $code,
        'dir'    => is_rtl() ? 'rtl' : 'ltr',
    );

    echo '<script>window.wpideLang=' . wp_json_encode( $data ) . ';</script>' . "\n";
}, 1 );

add_filter( 'body_class', function ( $classes ) {
