add_shortcode( 'wpide_lang', function ( $atts, $content = '' ) {
    $atts   = shortcode_atts( array( 'only' => '', 'except' => '' ), $atts, 'wpide_lang' );
    $locale = strtolower( determine_locale() );
    $code   = strtok( $locale, '_' );

    if ( defined( 'ICL_LANGUAGE_CODE' ) && ICL_LANGUAGE_CODE ) {
        $code = strtolower( ICL_LANGUAGE_CODE );
    } elseif ( function_exists( 'pll_current_language' ) && pll_current_language() ) {
        $code = strtolower( pll_current_language() );
    }

    $matches = function ( $list ) use ( $code, $locale ) {
        $items = array_filter( array_map( 'trim', explode( ',', strtolower( $list ) ) ) );
        return in_array( $code, $items, true ) || in_array( $locale, $items, true );
    };

    if ( '' !== $atts['only'] && ! $matches( $atts['only'] ) ) {
        return '';
    }

    if ( '' !== $atts['except'] && $matches( $atts['except'] ) ) {
        return '';
    }

    return do_shortcode( $content );
} );

