        return;
    }

    wp_add_dashboard_widget( 'wpide_pll_progress', __( 'Translation progress' ), function () {
        $data = get_transient( 'wpide_pll_progress' );

        if ( false === $data ) {
            $data = array();
            foreach ( array( 'post', 'page' ) as $type ) {
                foreach ( pll_languages_list( array( 'fields' => 'slug' ) ) as $slug ) {
