        }

        $default = pll_default_language();

        foreach ( $data as $type => $counts ) {
            $base = max( 1, isset( $counts[ $default ] ) ? $counts[ $default ] : 1 );
            echo '<h3>' . esc_html( get_post_type_object( $type )->labels->name ) . '</h3>';
            foreach ( $counts as $slug => $count ) {
                $pct = min( 100, (int) round( $count / $base * 100 ) );
                printf(
                    '<div style="display:flex;align-items:center;gap:8px;margin:4px 0"><strong style="width:3em">%1$s</strong><span style="flex:1;background:#f0f0f1;height:8px;border-radius:4px;overflow:hidden" role="progressbar" aria-valuenow="%2$d" aria-valuemin="0" aria-valuemax="100" aria-label="%1$s"><span style="display:block;height:100%%;width:%2$d%%;background:#2271b1"></span></span><span style="width:4em;text-align:end">%3$s</span></div>',
                    esc_html( strtoupper( $slug ) ),
