add_filter( 'sanitize_title', function ( $title, $raw_title, $context ) {
    if ( 'save' !== $context || '' === $title || ! preg_match( '/[^\x00-\x7F]/', $title ) ) {
        return $title;
    }

    static $table = null;

    if ( class_exists( 'Transliterator' ) ) {
        $tr = Transliterator::create( 'Any-Latin; Latin-ASCII; Lower()' );
        if ( $tr ) {
            $out = $tr->transliterate( $title );
            if ( is_string( $out ) && '' !== $out ) {
                return $out;
            }
        }
    }

    if ( null === $table ) {
        $table = array(
            'а' => 'a', 'б' => 'b', 'в' => 'v', 'г' => 'g', 'ґ' => 'g', 'д' => 'd', 'е' => 'e', 'є' => 'ye', 'ё' => 'yo', 'ж' => 'zh', 'з' => 'z', 'и' => 'i', 'і' => 'i', 'ї' => 'yi', 'й' => 'y',
            'к' => 'k', 'л' => 'l', 'м' => 'm', 'н' => 'n', 'о' => 'o', 'п' => 'p', 'р' => 'r', 'с' => 's', 'т' => 't', 'у' => 'u', 'ф' => 'f', 'х' => 'h', 'ц' => 'ts', 'ч' => 'ch',
            'ш' => 'sh', 'щ' => 'shch', 'ъ' => '', 'ы' => 'y', 'ь' => '', 'э' => 'e', 'ю' => 'yu', 'я' => 'ya',
            'α' => 'a', 'β' => 'v', 'γ' => 'g', 'δ' => 'd', 'ε' => 'e', 'ζ' => 'z', 'η' => 'i', 'θ' => 'th', 'ι' => 'i', 'κ' => 'k', 'λ' => 'l', 'μ' => 'm', 'ν' => 'n', 'ξ' => 'x',
            'ο' => 'o', 'π' => 'p', 'ρ' => 'r', 'σ' => 's', 'ς' => 's', 'τ' => 't', 'υ' => 'y', 'φ' => 'f', 'χ' => 'ch', 'ψ' => 'ps', 'ω' => 'o',
            'ά' => 'a', 'έ' => 'e', 'ή' => 'i', 'ί' => 'i', 'ό' => 'o', 'ύ' => 'y', 'ώ' => 'o',
        );
    }

    return strtr( mb_strtolower( $title, 'UTF-8' ), $table );
}, 9, 3 );

$wpide_fallbacks = array( // Locale => fallback locale.
    'de_CH'          => 'de_DE',
    'de_CH_informal' => 'de_DE',
    'es_MX'          => 'es_ES',
    'fr_CA'          => 'fr_FR',
    'pt_PT'          => 'pt_BR',
);

add_filter( 'load_textdomain_mofile', function ( $mofile ) use ( $wpide_fallbacks ) {
    if ( is_readable( $mofile ) || is_readable( preg_replace( '/\.mo$/', '.l10n.php', $mofile ) ) ) {
        return $mofile;
    }

    foreach ( $wpide_fallbacks as $locale => $fallback ) {
        $suffix = $locale . '.mo';
        if ( substr( $mofile, -strlen( $suffix ) ) === $suffix ) {
            $candidate = substr( $mofile, 0, -strlen( $suffix ) ) . $fallback . '.mo';
            if ( is_readable( $candidate ) || is_readable( preg_replace( '/\.mo$/', '.l10n.php', $candidate ) ) ) {
                return $candidate;
            }
        }
    }

    return $mofile;
} );

add_shortcode( 'wpide_upcoming_events', function ( $atts ) {
    if ( ! function_exists( 'tribe_get_events' ) ) {
        return '';
    }

    $atts = shortcode_atts( array( 'number' => 5, 'category' => '', 'featured' => '' ), $atts, 'wpide_upcoming_events' );
    $key  = 'wpide_tec_upcoming_' . md5( wp_json_encode( $atts ) ) . '_' . (int) get_option( 'wpide_tec_ver', 1 );
    $html = get_transient( $key );

    if ( false !== $html ) {
        return $html;
    }

    $args = array(
        'posts_per_page' => min( 20, max( 1, absint( $atts['number'] ) ) ),
        'start_date'     => 'now',
        'eventDisplay'   => 'list',
    );

    if ( '' !== $atts['category'] ) {
        $args['tax_query'] = array( array( 'taxonomy' => 'tribe_events_cat', 'field' => 'slug', 'terms' => sanitize_title( $atts['category'] ) ) ); // phpcs:ignore WordPress.DB.SlowDBQuery
    }
    if ( $atts['featured'] ) {
        $args['featured'] = true;
    }

    $events = tribe_get_events( $args );
    $html   = '';

    if ( $events ) {
        $html = '<ul class="wpide-upcoming-events">';
        foreach ( $events as $event ) {
            $venue = function_exists( 'tribe_get_venue' ) ? tribe_get_venue( $event->ID ) : '';
            $html .= sprintf(
                '<li><a href="%1$s">%2$s</a><br><small>%3$s%4$s</small></li>',
                esc_url( get_permalink( $event ) ),
                esc_html( get_the_title( $event ) ),
                esc_html( tribe_get_start_date( $event, ! tribe_event_is_all_day( $event->ID ) ) ),
                $venue ? ' &middot; ' . esc_html( $venue ) : ''
            );
        }
        $html .= '</ul>';
    } else {
        $html = '<p class="wpide-upcoming-events-empty">' . esc_html__( 'No upcoming events right now.' ) . '</p>';
    }

    set_transient( $key, $html, 15 * MINUTE_IN_SECONDS );

    return $html;
} );

