$wpide_days = 90; // Redirect events that ended more than this many days ago.

add_action( 'template_redirect', function () use ( $wpide_days ) {
    if ( ! is_singular( 'tribe_events' ) || current_user_can( 'edit_posts' ) || ! function_exists( 'tribe_get_events_link' ) ) {
        return;
    }

    $end = strtotime( (string) get_post_meta( get_queried_object_id(), '_EventEndDate', true ) );

    if ( $end && $end < current_time( 'timestamp' ) - $wpide_days * DAY_IN_SECONDS ) { // phpcs:ignore WordPress.DateTime.CurrentTimeTimestamp.Requested -- event dates are stored in site time.
        wp_safe_redirect( tribe_get_events_link(), 301 );
        exit;
    }
} );

add_filter( 'tribe_json_ld_event_object', function ( $data, $args, $post ) {
    if ( ! is_object( $data ) || ! $post ) {
        return $data;
    }

    $statuses = array(
        'cancelled'   => 'https://schema.org/EventCancelled',
        'postponed'   => 'https://schema.org/EventPostponed',
        'rescheduled' => 'https://schema.org/EventRescheduled',
    );
    $status = strtolower( (string) get_post_meta( $post->ID, 'event_status', true ) );

    $data->eventStatus = isset( $statuses[ $status ] ) ? $statuses[ $status ] : 'https://schema.org/EventScheduled';

    $has_venue = (int) get_post_meta( $post->ID, '_EventVenueID', true ) > 0;
    $url       = get_post_meta( $post->ID, '_EventURL', true );

    if ( ! $has_venue && $url ) {
        $data->eventAttendanceMode = 'https://schema.org/OnlineEventAttendanceMode';
        $data->location            = (object) array( '@type' => 'VirtualLocation', 'url' => esc_url_raw( $url ) );
    } else {
        $data->eventAttendanceMode = 'https://schema.org/OfflineEventAttendanceMode';
    }

    return $data;
}, 10, 3 );

