add_filter( 'affwp_get_affiliate_rate', function ( $rate, $affiliate_id ) use ( $wpide_role, $wpide_rate ) {
    if ( ! function_exists( 'affwp_get_affiliate' ) ) {
        return $rate;
    }

    $affiliate = affwp_get_affiliate( $affiliate_id );

    if ( ! $affiliate || '' !== (string) $affiliate->rate ) {
        return $rate; // A custom rate on the affiliate wins.
    }

    $user = get_userdata( $affiliate->user_id );

    if ( $user && in_array( $wpide_role, (array) $user->roles, true ) ) {
        $type = function_exists( 'affwp_get_affiliate_rate_type' ) ? affwp_get_affiliate_rate_type( $affiliate_id ) : 'percentage';
        return 'percentage' === $type ? $wpide_rate / 100 : $wpide_rate;
    }

    return $rate;
}, 10, 2 );

