if ( ! function_exists( 'wpide_akismet_is_spam' ) ) {
    function wpide_akismet_is_spam( array $fields ) {
        if ( ! class_exists( 'Akismet' ) || ! Akismet::get_api_key() ) {
            return false;
        }

        $request = array(
            'blog'                 => home_url(),
            'blog_lang'            => get_locale(),
            'blog_charset'         => get_option( 'blog_charset' ),
            'user_ip'              => isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : '',
            'user_agent'           => isset( $_SERVER['HTTP_USER_AGENT'] ) ? sanitize_text_field( wp_unslash( $_SERVER['HTTP_USER_AGENT'] ) ) : '',
            'referrer'             => wp_get_raw_referer() ? wp_get_raw_referer() : '',
            'permalink'            => wp_get_referer() ? wp_get_referer() : home_url( '/' ),
            'comment_type'         => 'contact-form',
            'comment_author'       => isset( $fields['name'] ) ? (string) $fields['name'] : '',
            'comment_author_email' => isset( $fields['email'] ) ? (string) $fields['email'] : '',
            'comment_content'      => isset( $fields['message'] ) ? (string) $fields['message'] : '',
        );

        $response = Akismet::http_post( Akismet::build_query( $request ), 'comment-check' );

        return is_array( $response ) && isset( $response[1] ) && 'true' === trim( $response[1] );
    }
}

