            protected function register_controls() {
                $this->add_control( 'param', array( 'label' => 'Parameter name', 'type' => \Elementor\Controls_Manager::TEXT, 'default' => 'city' ) );
                $this->add_control( 'default_value', array( 'label' => 'When missing', 'type' => \Elementor\Controls_Manager::TEXT, 'default' => '' ) );
            }

            public function render() {
                $param = sanitize_key( (string) $this->get_settings( 'param' ) );
                $value = ( $param && isset( $_GET[ $param ] ) ) ? sanitize_text_field( wp_unslash( $_GET[ $param ] ) ) : ''; // phpcs:ignore WordPress.Security.NonceVerification.Recommended

                if ( '' === $value ) {
                    $value = (string) $this->get_settings( 'default_value' );
                }

                echo esc_html( mb_substr( $value, 0, 60 ) );
            }
        }
    }

    $dynamic_tags->register_group( 'wpide-visitor', array( 'title' => 'Visitor' ) );
