    if ( ! is_singular() ) {
        return;
    }

    $post_id = get_queried_object_id();
    $terms   = wp_get_post_terms( $post_id, 'category', array( 'fields' => 'ids' ) );

    if ( is_wp_error( $terms ) || empty( $terms ) ) {
        return;
    }

    $query->set( 'category__in', $terms );
    $query->set( 'post__not_in', array( $post_id ) );
