add_action( 'elementor_pro/forms/validation/email', function ( $field, $record, $ajax_handler ) use ( $wpide_el_free_domains, $wpide_el_free_message ) {
    $email = isset( $field['value'] ) ? strtolower( trim( (string) $field['value'] ) ) : '';

    if ( '' === $email || false === strpos( $email, '@' ) ) {
        return;
    }

    $domain = substr( strrchr( $email, '@' ), 1 );

    if ( in_array( $domain, $wpide_el_free_domains, true ) ) {
        $ajax_handler->add_error( $field['id'], $wpide_el_free_message );
    }
}, 10, 3 );

// How many links a message may contain.
$wpide_el_max_links    = 0;
$wpide_el_link_message = 'Please remove links from your message.';

add_action( 'elementor_pro/forms/validation', function ( $record, $ajax_handler ) use ( $wpide_el_max_links, $wpide_el_link_message ) {
    $fields = $record->get( 'fields' );

    foreach ( (array) $fields as $id => $field ) {
        if ( ! isset( $field['type'], $field['value'] ) || 'textarea' !== $field['type'] ) {
            continue;
        }

        $links = preg_match_all( '#(https?://|www\.)\S+#i', (string) $field['value'] );

        if ( $links > $wpide_el_max_links ) {
            $ajax_handler->add_error( $id, $wpide_el_link_message );
        }
    }
}, 10, 2 );

