    }

    if ( class_exists( '\Elementor\Plugin' ) && \Elementor\Plugin::$instance->editor && \Elementor\Plugin::$instance->editor->is_edit_mode() ) {
        return $should_render;
    }

    $classes = ' ' . $element->get_settings( '_css_classes' ) . ' ' . $element->get_settings( 'css_classes' ) . ' ';

    if ( false !== strpos( $classes, ' wpide-logged-in ' ) && ! is_user_logged_in() ) {
