add_filter( 'bricks/conditions/options', function ( $options ) {
    $options[] = array(
        'key'     => 'wpide_url_param',
        'label'   => 'URL parameter',
        'group'   => 'wpide',
        'compare' => array(
            'type'        => 'select',
            'options'     => array( '==' => 'is', '!=' => 'is not' ),
            'placeholder' => 'is',
        ),
        'value'   => array( 'type' => 'text', 'placeholder' => 'ref=newsletter' ),
    );

