    $classes = ' ' . $element->settings['_cssClasses'] . ' ';

    if ( false !== strpos( $classes, ' wpide-logged-in ' ) && ! is_user_logged_in() ) {
        return false;
    }

    if ( false !== strpos( $classes, ' wpide-logged-out ' ) && is_user_logged_in() ) {
