add_filter( 'bricks/form/validate', function ( $errors, $form ) use ( $wpide_bricks_free_domains, $wpide_bricks_free_message ) {
    if ( ! is_object( $form ) || ! method_exists( $form, 'get_fields' ) ) {
        return $errors;
    }

    foreach ( (array) $form->get_fields() as $key => $value ) {
        if ( 0 !== strpos( (string) $key, 'form-field-' ) || ! is_string( $value ) || ! is_email( $value ) ) {
            continue;
        }

        $domain = strtolower( substr( strrchr( $value, '@' ), 1 ) );

        if ( in_array( $domain, $wpide_bricks_free_domains, true ) ) {
            $errors[] = $wpide_bricks_free_message;
            break;
        }
    }

    return $errors;
}, 10, 2 );

