add_action( 'wp_enqueue_scripts', function () {
    if ( ! is_child_theme() || wp_style_is( 'parent-style', 'enqueued' ) ) {
        return;
    }

    $parent = wp_get_theme( get_template() );

    wp_enqueue_style( 'parent-style', get_template_directory_uri() . '/style.css', array(), $parent->get( 'Version' ) );

    // Make sure the child stylesheet loads after the parent one.
    $child = wp_styles()->query( get_stylesheet(), 'registered' ) ? get_stylesheet() : 'child-style';

    if ( wp_styles()->query( $child, 'registered' ) ) {
        wp_styles()->registered[ $child ]->deps[] = 'parent-style';
    } else {
        wp_enqueue_style( 'child-style', get_stylesheet_uri(), array( 'parent-style' ), wp_get_theme()->get( 'Version' ) );
    }
}, 5 );

