    $theme = false;

    if ( empty( $_GET['wpide_theme'] ) || ! function_exists( 'wp_get_current_user' ) || ! current_user_can( 'switch_themes' ) ) { // phpcs:ignore WordPress.Security.NonceVerification.Recommended
        return $theme;
    }

    $candidate = wp_get_theme( sanitize_file_name( wp_unslash( $_GET['wpide_theme'] ) ) ); // phpcs:ignore WordPress.Security.NonceVerification.Recommended

    if ( $candidate->exists() && ! $candidate->errors() ) {
        $theme = $candidate;
    }

    return $theme;
};

