add_filter( 'render_block_core/cover', function ( $content ) {
    static $done = false;

    if ( $done || is_admin() || ! class_exists( 'WP_HTML_Tag_Processor' ) ) {
        return $content;
    }

    $tags = new WP_HTML_Tag_Processor( $content );

    if ( $tags->next_tag( array( 'tag_name' => 'img', 'class_name' => 'wp-block-cover__image-background' ) ) ) {
        $tags->set_attribute( 'fetchpriority', 'high' );
        $tags->remove_attribute( 'loading' );
        $tags->set_attribute( 'decoding', 'async' );
        $done = true;

        return $tags->get_updated_html();
    }

    return $content;
} );

