// font-display value: swap, optional, fallback or block.
$wpide_font_display = 'swap';

add_filter( 'wp_theme_json_data_theme', function ( $theme_json ) use ( $wpide_font_display ) {
    $data     = $theme_json->get_data();
    $families = isset( $data['settings']['typography']['fontFamilies'] ) ? (array) $data['settings']['typography']['fontFamilies'] : array();
    $families = isset( $families['theme'] ) ? (array) $families['theme'] : $families;
    $changed  = false;

    foreach ( $families as $i => $family ) {
        if ( empty( $family['fontFace'] ) || ! is_array( $family['fontFace'] ) ) {
            continue;
        }

        foreach ( $family['fontFace'] as $j => $face ) {
            $families[ $i ]['fontFace'][ $j ]['fontDisplay'] = $wpide_font_display;
            $changed = true;
        }
    }

    if ( ! $changed ) {
        return $theme_json;
    }

    return $theme_json->update_with( array(
        'version'  => WP_Theme_JSON::LATEST_SCHEMA,
        'settings' => array( 'typography' => array( 'fontFamilies' => $families ) ),
    ) );
} );

// Font family slugs to keep.
$wpide_keep_font_slugs = array( 'manrope', 'fira-code' );

add_filter( 'wp_theme_json_data_theme', function ( $theme_json ) use ( $wpide_keep_font_slugs ) {
    $data     = $theme_json->get_data();
    $families = isset( $data['settings']['typography']['fontFamilies'] ) ? (array) $data['settings']['typography']['fontFamilies'] : array();
    $families = isset( $families['theme'] ) ? (array) $families['theme'] : $families;

    if ( ! $families ) {
        return $theme_json;
    }

    $kept = array_values( array_filter( $families, function ( $family ) use ( $wpide_keep_font_slugs ) {
        return isset( $family['slug'] ) && in_array( $family['slug'], $wpide_keep_font_slugs, true );
    } ) );

    // Never leave the theme without fonts because of a typo.
    if ( ! $kept ) {
        return $theme_json;
    }

    return $theme_json->update_with( array(
        'version'  => WP_Theme_JSON::LATEST_SCHEMA,
        'settings' => array( 'typography' => array( 'fontFamilies' => $kept ) ),
    ) );
} );

