add_action( 'wp_enqueue_scripts', function () {
    wp_register_script( 'wpide-counter', false, array(), '1.0', true );
    wp_add_inline_script( 'wpide-counter', <<<'JS'
(function () {
    var counters = document.querySelectorAll('.wpide-counter[data-to]');
    if (!counters.length) { return; }
    var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    function format(el, value) {
        var decimals = parseInt(el.getAttribute('data-decimals') || '0', 10);
        var text = value.toLocaleString(undefined, { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
        el.querySelector('.wpide-counter__value').textContent = text;
    }
    function run(el) {
        var from = parseFloat(el.getAttribute('data-from')) || 0;
        var to = parseFloat(el.getAttribute('data-to')) || 0;
        var duration = parseInt(el.getAttribute('data-duration') || '1600', 10);
        if (reduce) { format(el, to); return; }
        var start = null;
        function step(time) {
            if (start === null) { start = time; }
            var p = Math.min(1, (time - start) / duration);
            var eased = 1 - Math.pow(1 - p, 3);
            format(el, from + (to - from) * eased);
            if (p < 1) { requestAnimationFrame(step); }
        }
        requestAnimationFrame(step);
    }
    if (!('IntersectionObserver' in window)) { counters.forEach(run); return; }
    var io = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
            if (entry.isIntersecting) { io.unobserve(entry.target); run(entry.target); }
        });
    }, { threshold: 0.4 });
    counters.forEach(function (el) { format(el, parseFloat(el.getAttribute('data-from')) || 0); io.observe(el); });
})();
JS
    );
} );

