(function () {
    var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    document.querySelectorAll('.wpide-typing').forEach(function (el) {
        var words = JSON.parse(el.getAttribute('data-words') || '[]');
        var out = el.querySelector('.wpide-typing__text');
        if (!words.length || !out) { return; }
        if (reduce) { out.textContent = words[0]; return; }
        var w = 0, c = 0, deleting = false;
        function tick() {
            var word = words[w];
            c += deleting ? -1 : 1;
            out.textContent = word.slice(0, c);
            var delay = deleting ? 45 : 90;
            if (!deleting && c === word.length) { deleting = true; delay = 1600; }
            else if (deleting && c === 0) { deleting = false; w = (w + 1) % words.length; delay = 350; }
            setTimeout(tick, delay);
        }
        tick();
    });
})();
