document.addEventListener('click', function (e) {
    var link = e.target.closest ? e.target.closest('.wp-block-navigation__responsive-container.is-menu-open a[href*="#"]') : null;
    if (!link || link.pathname !== window.location.pathname || !link.hash) { return; }
    var container = link.closest('.wp-block-navigation__responsive-container');
    var close = container && container.querySelector('.wp-block-navigation__responsive-container-close');
    if (close) { close.click(); }
});

document.addEventListener('toggle', function (e) {
    var details = e.target;
    if (!details.matches || !details.matches('details.wp-block-details') || !details.open) { return; }
    var parent = details.parentElement;
    if (!parent || parent.classList.contains('wpide-multi-open')) { return; }
    Array.prototype.forEach.call(parent.children, function (sibling) {
        if (sibling !== details && sibling.matches('details.wp-block-details') && sibling.open) { sibling.open = false; }
    });
}, true);

