(function () {
    var els = document.querySelectorAll('[data-wpide-bg]');
    if (!els.length) { return; }
    function load(el) {
        var url = el.getAttribute('data-wpide-bg');
        if (url) { el.style.backgroundImage = 'url("' + url.replace(/["\\]/g, '') + '")'; }
        el.removeAttribute('data-wpide-bg');
    }
    if (!('IntersectionObserver' in window)) { els.forEach(load); return; }
    var io = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
            if (entry.isIntersecting) { io.unobserve(entry.target); load(entry.target); }
        });
    }, { rootMargin: '300px 0px' });
    els.forEach(function (el) { io.observe(el); });
})();

