document.querySelectorAll('.wpide-hover-play video').forEach(function (video) {
    video.muted = true;
    video.playsInline = true;
    video.preload = 'metadata';
    video.removeAttribute('autoplay');
    var play = function () { var p = video.play(); if (p && p.catch) { p.catch(function () {}); } };
    video.addEventListener('mouseenter', play);
    video.addEventListener('focus', play);
    video.addEventListener('mouseleave', function () { video.pause(); });
    video.addEventListener('blur', function () { video.pause(); });
    video.addEventListener('touchstart', function () { if (video.paused) { play(); } else { video.pause(); } }, { passive: true });
});

(function () {
    var videos = Array.prototype.filter.call(document.querySelectorAll('video[autoplay]'), function (v) { return v.muted; });
    if (!videos.length || !('IntersectionObserver' in window)) { return; }
    var visible = new Set();
    function resume(v) { var p = v.play(); if (p && p.catch) { p.catch(function () {}); } }
    var io = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
            if (entry.isIntersecting) { visible.add(entry.target); if (!document.hidden) { resume(entry.target); } }
            else { visible.delete(entry.target); entry.target.pause(); }
        });
    }, { threshold: 0.1 });
    videos.forEach(function (v) { io.observe(v); });
    document.addEventListener('visibilitychange', function () {
        videos.forEach(function (v) { if (document.hidden) { v.pause(); } else if (visible.has(v)) { resume(v); } });
    });
})();

