add_action( 'elementor_pro/forms/validation/tel', function ( $field, $record, $ajax_handler ) use ( $wpide_el_phone_min, $wpide_el_phone_max ) {
    $value = isset( $field['value'] ) ? trim( (string) $field['value'] ) : '';

    if ( '' === $value ) {
        return;
    }

    $digits = strlen( preg_replace( '/\D/', '', $value ) );

    if ( preg_match( '/[^0-9+()\.\-\s]/', $value ) || $digits < $wpide_el_phone_min || $digits > $wpide_el_phone_max ) {
        $ajax_handler->add_error( $field['id'], 'Please enter a valid phone number.' );
    }
}, 10, 3 );

