// How many days back to show.
$wpide_query_recent_days = 30;
$wpide_query_recent      = array( 'active' => false );

add_filter( 'pre_render_block', function ( $pre, $parsed ) use ( &$wpide_query_recent ) {
    if ( 'core/query' === $parsed['blockName'] ) {
        $classes = isset( $parsed['attrs']['className'] ) ? ' ' . $parsed['attrs']['className'] . ' ' : '';
        $wpide_query_recent['active'] = false !== strpos( $classes, ' wpide-recent ' );
    }

    return $pre;
}, 10, 2 );

add_filter( 'query_loop_block_query_vars', function ( $query ) use ( &$wpide_query_recent, $wpide_query_recent_days ) {
    if ( ! $wpide_query_recent['active'] ) {
        return $query;
    }

    $date_query   = isset( $query['date_query'] ) ? (array) $query['date_query'] : array();
    $date_query[] = array( 'after' => absint( $wpide_query_recent_days ) . ' days ago', 'inclusive' => true );

    $query['date_query'] = $date_query;

    return $query;
} );

// Custom field holding the date (Ymd).
$wpide_query_date_field = 'event_date';
$wpide_query_upcoming   = array( 'active' => false );

add_filter( 'pre_render_block', function ( $pre, $parsed ) use ( &$wpide_query_upcoming ) {
    if ( 'core/query' === $parsed['blockName'] ) {
        $classes = isset( $parsed['attrs']['className'] ) ? ' ' . $parsed['attrs']['className'] . ' ' : '';
        $wpide_query_upcoming['active'] = false !== strpos( $classes, ' wpide-upcoming ' );
    }

    return $pre;
}, 10, 2 );

add_filter( 'query_loop_block_query_vars', function ( $query ) use ( &$wpide_query_upcoming, $wpide_query_date_field ) {
    if ( ! $wpide_query_upcoming['active'] ) {
        return $query;
    }

    $meta_query   = isset( $query['meta_query'] ) ? (array) $query['meta_query'] : array();
    $meta_query[] = array(
        'key'     => $wpide_query_date_field,
        'value'   => wp_date( 'Ymd' ),
        'compare' => '>=',
        'type'    => 'NUMERIC',
    );

    $query['meta_query'] = $meta_query;
    $query['meta_key']   = $wpide_query_date_field;
    $query['orderby']    = 'meta_value_num';
    $query['order']      = 'ASC';

    return $query;
} );

// Blocks to look for.
$wpide_body_class_blocks = array( 'core/cover', 'core/gallery', 'core/table', 'core/video', 'core/embed', 'core/query' );

add_filter( 'body_class', function ( $classes ) use ( $wpide_body_class_blocks ) {
    if ( ! is_singular() ) {
        return $classes;
    }

    $post = get_queried_object();

    if ( ! $post instanceof WP_Post || ! has_blocks( $post ) ) {
        return $classes;
    }

    foreach ( $wpide_body_class_blocks as $block ) {
        if ( has_block( $block, $post ) ) {
            $name      = 0 === strpos( $block, 'core/' ) ? substr( $block, 5 ) : str_replace( '/', '-', $block );
            $classes[] = 'has-block-' . sanitize_html_class( $name );
        }
    }

    return $classes;
} );

// Credit phrases to remove (case-insensitive).
$wpide_credit_phrases = array( 'Designed with', 'Powered by', 'Proudly powered by' );

add_filter( 'render_block_core/paragraph', function ( $content ) use ( $wpide_credit_phrases ) {
    if ( false === stripos( $content, 'wordpress.org' ) ) {
        return $content;
    }

    $text = wp_strip_all_tags( $content );

    foreach ( $wpide_credit_phrases as $phrase ) {
        if ( false !== stripos( $text, $phrase ) && false !== stripos( $text, 'WordPress' ) && strlen( $text ) < 120 ) {
            return '';
        }
    }

    return $content;
} );

