document.addEventListener('submit', function (e) {
    var form = e.target;
    if (!form || form.nodeName !== 'FORM' || form.classList.contains('wpide-allow-resubmit') || e.defaultPrevented) { return; }
    if (form.checkValidity && !form.checkValidity()) { return; }
    var buttons = form.querySelectorAll('button[type="submit"], input[type="submit"], button:not([type])');
    // Wait a tick so the clicked button's name and value are still sent with the form.
    setTimeout(function () {
        buttons.forEach(function (btn) {
            btn.disabled = true;
            btn.setAttribute('aria-disabled', 'true');
            btn.setAttribute('data-wpide-label', btn.nodeName === 'INPUT' ? btn.value : btn.textContent);
            if (btn.nodeName === 'INPUT') { btn.value = 'Sending…'; } else { btn.textContent = 'Sending…'; }
        });
    }, 0);
    setTimeout(function () {
        buttons.forEach(function (btn) {
            btn.disabled = false;
            btn.removeAttribute('aria-disabled');
            var label = btn.getAttribute('data-wpide-label');
            if (btn.nodeName === 'INPUT') { btn.value = label; } else { btn.textContent = label; }
        });
    }, 8000);
});

