add_filter( 'woocommerce_package_rates', function ( $rates ) use ( $wpide_reserved_methods, $wpide_reserved_roles ) {
    $allowed = is_user_logged_in() && array_intersect( $wpide_reserved_roles, (array) wp_get_current_user()->roles );

    if ( $allowed ) {
        return $rates;
    }

    foreach ( $rates as $id => $rate ) {
        if ( in_array( $id, $wpide_reserved_methods, true ) || in_array( $rate->get_method_id(), $wpide_reserved_methods, true ) ) {
            unset( $rates[ $id ] );
