add_filter( 'woocommerce_package_rates', function ( $rates ) {
    if ( count( $rates ) < 2 ) {
        return $rates;
    }

    uasort( $rates, function ( $a, $b ) {
        return (float) $a->get_cost() <=> (float) $b->get_cost();
    } );

    return $rates;
}, 100 );

add_filter( 'woocommerce_shipping_chosen_method', function ( $default, $rates, $chosen ) {
    if ( $chosen && isset( $rates[ $chosen ] ) ) {
        return $chosen;
    }

    $cheapest = $default;
    $lowest   = null;

    foreach ( $rates as $id => $rate ) {
        $cost = (float) $rate->get_cost();

        if ( null === $lowest || $cost < $lowest ) {
            $lowest   = $cost;
            $cheapest = $id;
        }
    }

    return $cheapest;
}, 10, 3 );

