    $value = (string) ( $data['wpide_delivery_date'] ?? '' );

    if ( '' === $value ) {
        return;
    }

    $date = DateTime::createFromFormat( '!Y-m-d', $value, wp_timezone() );

    if ( ! $date || $date->format( 'Y-m-d' ) !== $value ) {
        $errors->add( 'validation', 'Please choose a valid delivery date.' );
