    $earliest = new DateTime( 'today +' . $wpide_delivery['lead_days'] . ' days', wp_timezone() );

    if ( $date < $earliest ) {
        $errors->add( 'validation', sprintf( 'The earliest delivery date is %s.', esc_html( wp_date( get_option( 'date_format' ), $earliest->getTimestamp() ) ) ) );
    } elseif ( $wpide_delivery['skip_weekends'] && (int) $date->format( 'N' ) >= 6 ) {
