    $day     = new DateTimeImmutable( 'today', wp_timezone() );
    $day     = $day->modify( '+' . (int) $wpide_delivery_days['lead_days'] . ' days' );

    while ( count( $options ) < $wpide_delivery_days['count'] ) {
        if ( $wpide_delivery_days['weekends'] || (int) $day->format( 'N' ) < 6 ) {
            $options[] = array( 'value' => $day->format( 'Y-m-d' ), 'label' => wp_date( 'l j F', $day->getTimestamp() ) );
        }

        $day = $day->modify( '+1 day' );
    }

    woocommerce_register_additional_checkout_field( array(
        'id'       => 'wpide/delivery-day',
        'label'    => 'Delivery day',
        'location' => 'order',
        'type'     => 'select',
        'required' => true,
        'options'  => $options,
    ) );
} );

