$wpide_vat_formats = array( // Country => pattern for the part after the country prefix.
    'AT' => 'U\d{8}', 'BE' => '[01]\d{9}', 'BG' => '\d{9,10}', 'CY' => '\d{8}[A-Z]', 'CZ' => '\d{8,10}',
    'DE' => '\d{9}', 'DK' => '\d{8}', 'EE' => '\d{9}', 'EL' => '\d{9}', 'ES' => '[A-Z0-9]\d{7}[A-Z0-9]',
    'FI' => '\d{8}', 'FR' => '[A-HJ-NP-Z0-9]{2}\d{9}', 'HR' => '\d{11}', 'HU' => '\d{8}', 'IE' => '\d{7}[A-W][A-I]?|\d[A-Z+*]\d{5}[A-W]',
    'IT' => '\d{11}', 'LT' => '\d{9}|\d{12}', 'LU' => '\d{8}', 'LV' => '\d{11}', 'MT' => '\d{8}', 'NL' => '\d{9}B\d{2}',
    'PL' => '\d{10}', 'PT' => '\d{9}', 'RO' => '\d{2,10}', 'SE' => '\d{12}', 'SI' => '\d{8}', 'SK' => '\d{10}', 'XI' => '\d{9}|\d{12}',
);

add_filter( 'woocommerce_billing_fields', function ( $fields ) {
    $fields['billing_vat_number'] = array(
        'type'     => 'text',
        'label'    => 'VAT number',
        'required' => false,
        'class'    => array( 'form-row-wide' ),
        'priority' => 35,
    );

    return $fields;
} );

add_action( 'woocommerce_after_checkout_validation', function ( $data, $errors ) use ( $wpide_vat_formats ) {
    $vat = strtoupper( preg_replace( '/[\s.\-]/', '', (string) ( $data['billing_vat_number'] ?? '' ) ) );

    if ( '' === $vat ) {
        return;
    }

    $country = (string) ( $data['billing_country'] ?? '' );
    $prefix  = 'GR' === $country ? 'EL' : $country;

    if ( ! isset( $wpide_vat_formats[ $prefix ] ) ) {
        return;
    }

    if ( 0 === strpos( $vat, $prefix ) ) {
        $vat = substr( $vat, strlen( $prefix ) );
    }

    if ( ! preg_match( '/^(' . $wpide_vat_formats[ $prefix ] . ')$/', $vat ) ) {
        $errors->add( 'validation', sprintf( 'The VAT number does not look like a valid %s VAT number. Please check it or leave the field empty.', esc_html( $prefix ) ) );
    }
}, 10, 2 );

