    'products' => array(),                              // Product IDs, empty for all.
);

$wpide_tier_percent = function ( $qty ) use ( $wpide_qty_tiers ) {
    $percent = 0;

    foreach ( $wpide_qty_tiers['tiers'] as $min => $off ) {
        if ( $qty >= $min ) {
            $percent = $off;
        }
    }

    return $percent;
};

$wpide_tier_applies = function ( $product_id ) use ( $wpide_qty_tiers ) {
    return empty( $wpide_qty_tiers['products'] ) || in_array( (int) $product_id, array_map( 'intval', $wpide_qty_tiers['products'] ), true );
};

add_action( 'woocommerce_before_calculate_totals', function ( $cart ) use ( $wpide_tier_percent, $wpide_tier_applies ) {
    static $base_prices = null;

    if ( is_admin() && ! wp_doing_ajax() ) {
        return;
    }

    $base_prices = $base_prices ?: new SplObjectStorage(); // Original prices, so repeated totals runs never stack.

    foreach ( $cart->get_cart() as $item ) {
        if ( ! $wpide_tier_applies( $item['product_id'] ) ) {
            continue;
        }

        if ( ! $base_prices->contains( $item['data'] ) ) {
            $base_prices[ $item['data'] ] = (float) $item['data']->get_price( 'edit' );
        }

        $base    = $base_prices[ $item['data'] ];
        $percent = $wpide_tier_percent( (int) $item['quantity'] );
        $item['data']->set_price( $percent ? round( $base * ( 100 - $percent ) / 100, wc_get_price_decimals() ) : $base );
    }
}, 20 );

