    echo '<table class="wpide-price-tiers shop_table"><thead><tr><th>' . esc_html( 'Quantity' ) . '</th><th>' . esc_html( 'Price each' ) . '</th></tr></thead><tbody>';

    foreach ( $wpide_qty_tiers['tiers'] as $min => $off ) {
        printf( '<tr><td>%s+</td><td>%s <small>(-%s%%)</small></td></tr>', esc_html( $min ), wp_kses_post( wc_price( $price * ( 100 - $off ) / 100 ) ), esc_html( $off ) );
