$wpide_bogo_prices = function ( $cart ) use ( $wpide_bogo ) {
    $prices = array();

    foreach ( $cart->get_cart() as $item ) {
        if ( $wpide_bogo['categories'] && ! has_term( $wpide_bogo['categories'], 'product_cat', $item['product_id'] ) ) {
            continue;
        }

        $unit = (float) wc_get_price_excluding_tax( $item['data'] );

        for ( $i = 0; $i < (int) $item['quantity']; $i++ ) {
            $prices[] = $unit;
        }
    }

    sort( $prices );

    return $prices;
};

add_action( 'woocommerce_cart_calculate_fees', function ( $cart ) use ( $wpide_bogo, $wpide_bogo_prices ) {
    if ( is_admin() && ! wp_doing_ajax() ) {
        return;
    }

    $prices = $wpide_bogo_prices( $cart );
    $free   = (int) floor( count( $prices ) / max( 1, $wpide_bogo['group'] ) );

    if ( $free > 0 ) {
        $cart->add_fee( $wpide_bogo['label'], -array_sum( array_slice( $prices, 0, $free ) ), true );
    }
} );

add_action( 'woocommerce_before_cart', function () use ( $wpide_bogo, $wpide_bogo_prices ) {
    $count = count( $wpide_bogo_prices( WC()->cart ) );
    $left  = $wpide_bogo['group'] - ( $count % $wpide_bogo['group'] );

    if ( $count > 0 && $left > 0 && $left < $wpide_bogo['group'] ) {
        wc_print_notice( sprintf( 'Add %1$d more qualifying item(s) to get one free (%2$s).', $left, esc_html( $wpide_bogo['label'] ) ), 'notice' );
    }
} );

$wpide_bundles = array(
    array(
        'name'     => 'Camera starter kit',
        'products' => array( 101, 102, 103 ), // Product IDs in the bundle.
        'discount' => 15,                     // Amount off when all are in the cart.
    ),
);

$wpide_bundle_status = function ( $bundle ) {
    $in_cart = array();

    foreach ( WC()->cart->get_cart() as $item ) {
        $in_cart[ $item['product_id'] ] = ( $in_cart[ $item['product_id'] ] ?? 0 ) + (int) $item['quantity'];
    }

    $sets    = PHP_INT_MAX;
    $missing = array();

    foreach ( $bundle['products'] as $id ) {
        $qty = $in_cart[ $id ] ?? 0;
        $sets = min( $sets, $qty );

        if ( ! $qty ) {
            $missing[] = $id;
        }
    }

    return array(
        'sets'    => PHP_INT_MAX === $sets ? 0 : $sets,
        'missing' => $missing,
        'partial' => count( $missing ) < count( $bundle['products'] ),
    );
};

add_action( 'woocommerce_cart_calculate_fees', function ( $cart ) use ( $wpide_bundles, $wpide_bundle_status ) {
    if ( is_admin() && ! wp_doing_ajax() ) {
        return;
    }

    foreach ( $wpide_bundles as $bundle ) {
        $status = $wpide_bundle_status( $bundle );

        if ( $status['sets'] > 0 ) {
            $cart->add_fee( $bundle['name'] . ' discount', -$bundle['discount'] * $status['sets'], true );
        }
    }
} );

add_action( 'woocommerce_before_cart', function () use ( $wpide_bundles, $wpide_bundle_status ) {
    foreach ( $wpide_bundles as $bundle ) {
        $status = $wpide_bundle_status( $bundle );

        if ( ! $status['partial'] || ! $status['missing'] ) {
            continue;
        }

        $links = array();

        foreach ( $status['missing'] as $id ) {
            $product = wc_get_product( $id );

            if ( $product && $product->is_purchasable() && $product->is_in_stock() ) {
                $links[] = sprintf( '<a href="%s">%s</a>', esc_url( $product->add_to_cart_url() ), esc_html( $product->get_name() ) );
            }
        }

        if ( $links ) {
            wc_print_notice( sprintf( 'Complete the %1$s and save %2$s: add %3$s.', esc_html( $bundle['name'] ), wc_price( $bundle['discount'] ), implode( ', ', $links ) ), 'notice' );
        }
    }
} );

