add_filter( 'posts_search', function ( $search, $query ) {
    global $wpdb;

    if ( is_admin() || ! $query->is_main_query() || ! $query->is_search() || 'product' !== $query->get( 'post_type' ) ) {
        return $search;
    }

    $terms = (array) $query->get( 'search_terms' );

    if ( ! $terms ) {
        return $search;
    }

    $clauses = array();

    foreach ( $terms as $term ) {
        $clauses[] = $wpdb->prepare( "{$wpdb->posts}.post_title LIKE %s", '%' . $wpdb->esc_like( $term ) . '%' );
    }

    return ' AND (' . implode( ' AND ', $clauses ) . ') ';
}, 20, 2 );

add_action( 'template_redirect', function () {
    if ( ! is_search() || 'product' !== get_query_var( 'post_type' ) || is_paged() ) {
        return;
    }

    $term = get_term_by( 'name', trim( get_search_query( false ) ), 'product_cat' );

    if ( ! $term ) {
        $term = get_term_by( 'slug', sanitize_title( get_search_query( false ) ), 'product_cat' );
    }

    if ( $term && ! is_wp_error( $term ) ) {
        $link = get_term_link( $term );

        if ( ! is_wp_error( $link ) ) {
            wp_safe_redirect( $link );
            exit;
        }
    }
} );

