add_filter( 'woocommerce_variation_option_name', function ( $name, $term = null, $attribute = '', $product = null ) use ( $wpide_oos_label ) {
    static $map = array();

    if ( ! $product instanceof WC_Product_Variable || ! $attribute ) {
        return $name;
    }

    $id = $product->get_id();

    if ( ! isset( $map[ $id ] ) ) {
        $map[ $id ] = false;
        $variation_attributes = $product->get_variation_attributes();

        if ( 1 === count( $variation_attributes ) ) {
            $map[ $id ] = array();

            foreach ( $product->get_children() as $child_id ) {
                $child = wc_get_product( $child_id );

                if ( $child ) {
                    foreach ( $child->get_attributes() as $value ) {
                        $map[ $id ][ strtolower( (string) $value ) ] = $child->is_in_stock();
                    }
                }
            }
        }
    }

    if ( ! is_array( $map[ $id ] ) ) {
        return $name;
    }

    $key = strtolower( $term instanceof WP_Term ? $term->slug : (string) $name );

    return ( isset( $map[ $id ][ $key ] ) && ! $map[ $id ][ $key ] ) ? $name . ' (' . $wpide_oos_label . ')' : $name;
}, 10, 4 );

