$wpide_first_order = array(
    'percent' => 10,                     // Percent off the products subtotal.
    'label'   => 'First order discount', // Line label.
);

add_action( 'woocommerce_cart_calculate_fees', function ( $cart ) use ( $wpide_first_order ) {
    if ( ( is_admin() && ! wp_doing_ajax() ) || ! WC()->customer || ! WC()->session ) {
        return;
    }

    $email = is_user_logged_in() ? wp_get_current_user()->user_email : WC()->customer->get_billing_email();

    if ( ! is_email( $email ) ) {
        return;
    }

    $cache = (array) WC()->session->get( 'wpide_first_order', array() );
    $key   = md5( strtolower( $email ) );

    if ( ! isset( $cache[ $key ] ) ) {
        $previous = wc_get_orders( array(
            'billing_email' => $email,
            'status'        => wc_get_is_paid_statuses(),
            'limit'         => 1,
            'return'        => 'ids',
        ) );

        if ( ! $previous && is_user_logged_in() ) {
            $previous = wc_get_orders( array( 'customer_id' => get_current_user_id(), 'status' => wc_get_is_paid_statuses(), 'limit' => 1, 'return' => 'ids' ) );
        }

        $cache[ $key ] = empty( $previous );
        WC()->session->set( 'wpide_first_order', $cache );
    }

    if ( $cache[ $key ] ) {
        $cart->add_fee( $wpide_first_order['label'], -$cart->get_subtotal() * $wpide_first_order['percent'] / 100, true );
    }
} );

$wpide_spend_tiers = array( 100 => 5, 200 => 10, 400 => 15 ); // Subtotal => percent off.

$wpide_spend_tier = function ( $subtotal ) use ( $wpide_spend_tiers ) {
    $current = array( 0, 0 );
    $next    = null;
    ksort( $wpide_spend_tiers );

    foreach ( $wpide_spend_tiers as $min => $off ) {
        if ( $subtotal >= $min ) {
            $current = array( $min, $off );
        } elseif ( null === $next ) {
            $next = array( $min, $off );
        }
    }

    return array( $current, $next );
};

add_action( 'woocommerce_cart_calculate_fees', function ( $cart ) use ( $wpide_spend_tier ) {
    if ( is_admin() && ! wp_doing_ajax() ) {
        return;
    }

    list( $current ) = $wpide_spend_tier( (float) $cart->get_subtotal() );

    if ( $current[1] > 0 ) {
        $cart->add_fee( sprintf( 'Spend discount (%d%%)', $current[1] ), -$cart->get_subtotal() * $current[1] / 100, true );
    }
} );

add_action( 'woocommerce_before_cart', function () use ( $wpide_spend_tier ) {
    $subtotal       = (float) WC()->cart->get_subtotal();
    list( , $next ) = $wpide_spend_tier( $subtotal );

    if ( $next ) {
        wc_print_notice( sprintf( 'Spend %1$s more to save %2$d%% on your order.', wc_price( $next[0] - $subtotal ), $next[1] ), 'notice' );
    }
} );

