$wpide_pickup_selected = function () {
    $chosen = WC()->session ? (array) WC()->session->get( 'chosen_shipping_methods', array() ) : array();

    // phpcs:ignore WordPress.Security.NonceVerification -- WooCommerce verifies the checkout nonce.
    if ( isset( $_POST['shipping_method'] ) ) {
        $chosen = array_map( 'wc_clean', (array) wp_unslash( $_POST['shipping_method'] ) );
    }

    foreach ( $chosen as $method ) {
        if ( 0 === strpos( (string) $method, 'local_pickup' ) ) {
            return true;
        }
    }

    return false;
};

add_filter( 'woocommerce_checkout_fields', function ( $fields ) use ( $wpide_pickup_hidden, $wpide_pickup_selected ) {
    if ( ! $wpide_pickup_selected() ) {
        return $fields;
    }

    foreach ( $wpide_pickup_hidden as $key ) {
        if ( isset( $fields['billing'][ 'billing_' . $key ] ) ) {
            $fields['billing'][ 'billing_' . $key ]['required'] = false;
