add_filter( 'woocommerce_checkout_posted_data', function ( $data ) {
    foreach ( array( 'billing', 'shipping' ) as $type ) {
        foreach ( array( 'first_name', 'last_name', 'city', 'address_1', 'address_2', 'company' ) as $field ) {
            $key = $type . '_' . $field;

            if ( empty( $data[ $key ] ) || ! is_string( $data[ $key ] ) ) {
                continue;
            }

            $value = trim( preg_replace( '/\s+/u', ' ', $data[ $key ] ) );

            if ( in_array( $field, array( 'first_name', 'last_name', 'city' ), true ) && ( mb_strtolower( $value ) === $value || mb_strtoupper( $value ) === $value ) ) {
                $value = mb_convert_case( mb_strtolower( $value ), MB_CASE_TITLE, 'UTF-8' );
            }

            $data[ $key ] = $value;
        }

        if ( ! empty( $data[ $type . '_postcode' ] ) && is_string( $data[ $type . '_postcode' ] ) ) {
            $data[ $type . '_postcode' ] = strtoupper( trim( preg_replace( '/\s+/', ' ', $data[ $type . '_postcode' ] ) ) );
        }
    }

    if ( ! empty( $data['billing_email'] ) && is_string( $data['billing_email'] ) ) {
        $data['billing_email'] = strtolower( trim( $data['billing_email'] ) );
    }

    return $data;
} );

$wpide_disposable_domains = array( 'mailinator.com', 'guerrillamail.com', '10minutemail.com', 'tempmail.com', 'yopmail.com', 'trashmail.com', 'sharklasers.com', 'getnada.com', 'temp-mail.org', 'dispostable.com' );

add_action( 'woocommerce_after_checkout_validation', function ( $data, $errors ) use ( $wpide_disposable_domains ) {
    $email = strtolower( (string) ( $data['billing_email'] ?? '' ) );

    if ( false === strpos( $email, '@' ) ) {
        return;
    }

    $domain = substr( strrchr( $email, '@' ), 1 );

    foreach ( $wpide_disposable_domains as $blocked ) {
        if ( $domain === $blocked || substr( $domain, -strlen( '.' . $blocked ) ) === '.' . $blocked ) {
            $errors->add( 'validation', 'Please use a permanent email address so we can send your order details.' );
            return;
        }
    }
}, 10, 2 );

$wpide_block_list = array(
    'emails'  => array( 'fraud@example.com' ),     // Full email addresses.
    'domains' => array( 'bad-domain.example' ),    // Email domains.
    'phones'  => array( '+44 7700 900123' ),       // Phone numbers.
);

add_action( 'woocommerce_after_checkout_validation', function ( $data, $errors ) use ( $wpide_block_list ) {
    $email  = strtolower( trim( (string) ( $data['billing_email'] ?? '' ) ) );
    $domain = false !== strpos( $email, '@' ) ? substr( strrchr( $email, '@' ), 1 ) : '';
    $phone  = preg_replace( '/\D/', '', (string) ( $data['billing_phone'] ?? '' ) );
    $phones = array_map( function ( $number ) {
        return preg_replace( '/\D/', '', $number );
    }, $wpide_block_list['phones'] );

    $blocked = in_array( $email, array_map( 'strtolower', $wpide_block_list['emails'] ), true )
        || ( $domain && in_array( $domain, array_map( 'strtolower', $wpide_block_list['domains'] ), true ) )
        || ( strlen( $phone ) > 5 && in_array( $phone, $phones, true ) );

    if ( $blocked ) {
        $errors->add( 'validation', 'Sorry, we are unable to process this order. Please contact us for help.' );
    }
}, 10, 2 );

