$wpide_latin_fields = array( 'first_name', 'last_name', 'address_1', 'address_2', 'city' ); // Fields to check.

add_action( 'woocommerce_after_checkout_validation', function ( $data, $errors ) use ( $wpide_latin_fields ) {
    foreach ( array( 'billing', 'shipping' ) as $type ) {
        if ( 'shipping' === $type && empty( $data['ship_to_different_address'] ) ) {
            continue;
        }

        foreach ( $wpide_latin_fields as $field ) {
            $value = (string) ( $data[ $type . '_' . $field ] ?? '' );

            if ( '' !== $value && ! preg_match( '/^[\p{Latin}\p{N}\s\'\-.,\/#&()]+$/u', $value ) ) {
                $errors->add( 'validation', 'Please enter your name and address using Latin letters (A to Z) so the courier can read the label.' );
                return;
            }
        }
    }
}, 10, 2 );

$wpide_house_number_skip = array( 'IE' ); // Countries to skip.

add_action( 'woocommerce_after_checkout_validation', function ( $data, $errors ) use ( $wpide_house_number_skip ) {
    if ( empty( WC()->cart ) || ! WC()->cart->needs_shipping() ) {
        return;
    }

    $prefix  = ! empty( $data['ship_to_different_address'] ) ? 'shipping_' : 'billing_';
    $country = (string) ( $data[ $prefix . 'country' ] ?? '' );
    $line    = trim( (string) ( $data[ $prefix . 'address_1' ] ?? '' ) . ' ' . (string) ( $data[ $prefix . 'address_2' ] ?? '' ) );

    if ( '' !== $line && ! in_array( $country, $wpide_house_number_skip, true ) && ! preg_match( '/\d/', $line ) ) {
        $errors->add( 'validation', 'Please include your house or building number in the street address.' );
    }
}, 10, 2 );

