add_filter( 'woocommerce_payment_complete_order_status', function ( $status, $order_id, $order = null ) use ( $wpide_review_amount ) {
    $order = $order instanceof WC_Order ? $order : wc_get_order( $order_id );

    if ( 'processing' === $status && $order && (float) $order->get_total() >= $wpide_review_amount ) {
        $order->add_order_note( sprintf( 'Held for manual review: order total is %s or more.', wc_price( $wpide_review_amount ) ) );

        return 'on-hold';
    }

    return $status;
}, 10, 3 );

$wpide_mismatch_hold = false; // Also set the order to On hold.

$wpide_check_mismatch = function ( $order ) use ( $wpide_mismatch_hold ) {
    if ( ! $order instanceof WC_Order || ! $order->has_shipping_address() ) {
        return;
    }

    $billing  = $order->get_billing_country();
    $shipping = $order->get_shipping_country();

    if ( $billing && $shipping && $billing !== $shipping ) {
        $order->add_order_note( sprintf( 'Check: billing country (%1$s) and shipping country (%2$s) differ.', $billing, $shipping ) );

        if ( $wpide_mismatch_hold && $order->has_status( array( 'processing', 'pending' ) ) ) {
            $order->update_status( 'on-hold', 'Held because the countries differ.' );
        }
    }
};

