$wpide_invoice = array(
    'prefix' => 'INV-{year}-', // {year} is replaced with the current year.
    'start'  => 1,             // First number used.
    'digits' => 4,             // Zero-padded length.
);

$wpide_invoice_assign = function ( $order_id, $order = null ) use ( $wpide_invoice ) {
    global $wpdb;

    $order = $order instanceof WC_Order ? $order : wc_get_order( $order_id );

    if ( ! $order || $order->get_meta( '_wpide_invoice_number' ) ) {
        return;
    }

    add_option( 'wpide_invoice_counter', (string) ( (int) $wpide_invoice['start'] - 1 ), '', false );
    // Atomic increment: LAST_INSERT_ID(expr) returns the new value to this connection only.
    $wpdb->query( $wpdb->prepare( "UPDATE {$wpdb->options} SET option_value = LAST_INSERT_ID(option_value + 1) WHERE option_name = %s", 'wpide_invoice_counter' ) );
    $number = (int) $wpdb->get_var( 'SELECT LAST_INSERT_ID()' );
    wp_cache_delete( 'wpide_invoice_counter', 'options' );

    if ( $number < 1 ) {
        return;
    }

    $invoice = str_replace( '{year}', wp_date( 'Y' ), $wpide_invoice['prefix'] ) . str_pad( (string) $number, $wpide_invoice['digits'], '0', STR_PAD_LEFT );
    $order->update_meta_data( '_wpide_invoice_number', $invoice );
    $order->update_meta_data( '_wpide_invoice_date', time() );
    $order->save_meta_data();
};

