add_action( 'admin_post_wpide_export_customers', function () {
    check_admin_referer( 'wpide_export_customers' );

    if ( ! current_user_can( 'manage_woocommerce' ) ) {
        wp_die( esc_html( 'You are not allowed to export customers.' ), 403 );
    }

    $cell = function ( $value ) {
        $value = (string) $value;

        return preg_match( '/^[=+\-@\t\r]/', $value ) ? "'" . $value : $value;
    };

    nocache_headers();
    header( 'Content-Type: text/csv; charset=utf-8' );
    header( 'Content-Disposition: attachment; filename=customers-' . gmdate( 'Y-m-d' ) . '.csv' );

    $out = fopen( 'php://output', 'w' );
    fwrite( $out, "\xEF\xBB\xBF" );
    fputcsv( $out, array( 'ID', 'First name', 'Last name', 'Email', 'Phone', 'City', 'Postcode', 'Country', 'Registered', 'Orders', 'Total spent' ) );

    $page = 1;

    do {
        $ids = get_users( array( 'role' => 'customer', 'fields' => 'ID', 'number' => 500, 'paged' => $page, 'orderby' => 'ID', 'count_total' => false ) );

        foreach ( $ids as $id ) {
            $customer = new WC_Customer( $id );

            fputcsv( $out, array_map( $cell, array(
                $id,
                $customer->get_first_name(),
                $customer->get_last_name(),
                $customer->get_email(),
                $customer->get_billing_phone(),
                $customer->get_billing_city(),
                $customer->get_billing_postcode(),
                $customer->get_billing_country(),
                $customer->get_date_created() ? $customer->get_date_created()->date( 'Y-m-d' ) : '',
                $customer->get_order_count(),
                wc_format_decimal( $customer->get_total_spent(), 2 ),
            ) ) );
        }

        $page++;
    } while ( count( $ids ) === 500 );

    fclose( $out );
    exit;
