add_action( 'admin_post_wpide_export_stock', function () {
    global $wpdb;

    check_admin_referer( 'wpide_export_stock' );

    if ( ! current_user_can( 'manage_woocommerce' ) ) {
        wp_die( esc_html( 'You are not allowed to export stock.' ), 403 );
    }

    $rows = $wpdb->get_results(
        "SELECT p.ID, p.post_title, p.post_parent, l.sku, l.stock_status, l.stock_quantity, l.min_price
         FROM {$wpdb->posts} p
         INNER JOIN {$wpdb->wc_product_meta_lookup} l ON l.product_id = p.ID
         WHERE p.post_type IN ('product','product_variation') AND p.post_status = 'publish'
         ORDER BY COALESCE(NULLIF(p.post_parent, 0), p.ID), p.post_parent, p.ID"
    );

    $cell = function ( $value ) {
        $value = (string) $value;

        return preg_match( '/^[=+\-@\t\r]/', $value ) ? "'" . $value : $value;
    };

    nocache_headers();
    header( 'Content-Type: text/csv; charset=utf-8' );
    header( 'Content-Disposition: attachment; filename=stock-' . gmdate( 'Y-m-d' ) . '.csv' );

    $out = fopen( 'php://output', 'w' );
    fwrite( $out, "\xEF\xBB\xBF" );
    fputcsv( $out, array( 'ID', 'Parent ID', 'Product', 'SKU', 'Stock status', 'Quantity', 'Price' ) );

    foreach ( $rows as $row ) {
        fputcsv( $out, array_map( $cell, array( $row->ID, $row->post_parent ? $row->post_parent : '', $row->post_title, $row->sku, $row->stock_status, null === $row->stock_quantity ? '' : (float) $row->stock_quantity, $row->min_price ) ) );
    }

    fclose( $out );
    exit;
} );

