add_action( 'wp_loaded', function () {
    if ( ! is_user_logged_in() || ! function_exists( 'WC' ) || ! WC()->cart ) {
        return;
    }

    if ( isset( $_POST['wpide_save_cart'], $_POST['woocommerce-cart-nonce'] ) && wp_verify_nonce( sanitize_key( $_POST['woocommerce-cart-nonce'] ), 'woocommerce-cart' ) ) {
        $saved = array();

        foreach ( WC()->cart->get_cart() as $item ) {
            $saved[] = array(
                'product_id'   => (int) $item['product_id'],
                'variation_id' => (int) $item['variation_id'],
                'quantity'     => (int) $item['quantity'],
                'variation'    => array_map( 'sanitize_text_field', (array) $item['variation'] ),
            );
        }

        update_user_meta( get_current_user_id(), '_wpide_saved_cart', array( 'time' => time(), 'items' => $saved ) );
        wc_add_notice( 'Your cart has been saved. Restore it any time from your account dashboard.' );
