    if ( isset( $_GET['wpide_restore_cart'], $_GET['_wpnonce'] ) && wp_verify_nonce( sanitize_key( $_GET['_wpnonce'] ), 'wpide_restore_cart' ) ) {
        $saved = get_user_meta( get_current_user_id(), '_wpide_saved_cart', true );

