add_action( 'wp_loaded', function () {
    if ( empty( $_GET['wpide_cart'] ) || ! function_exists( 'WC' ) || ! WC()->cart ) {
        return;
    }

    $lines = array_slice( explode( ',', sanitize_text_field( wp_unslash( $_GET['wpide_cart'] ) ) ), 0, 30 );

    foreach ( $lines as $line ) {
        list( $id, $qty ) = array_pad( array_map( 'absint', explode( ':', $line ) ), 2, 1 );
        $product          = $id ? wc_get_product( $id ) : null;

        if ( ! $product || ! $product->is_purchasable() || 'publish' !== get_post_status( $product->get_parent_id() ? $product->get_parent_id() : $id ) ) {
            continue;
        }

        if ( $product->is_type( 'variation' ) ) {
            WC()->cart->add_to_cart( $product->get_parent_id(), max( 1, $qty ), $id, $product->get_variation_attributes() );
        } else {
            WC()->cart->add_to_cart( $id, max( 1, $qty ) );
        }
    }

    wp_safe_redirect( remove_query_arg( 'wpide_cart' ) );
    exit;
}, 25 );

