add_filter( 'woocommerce_my_account_my_orders_actions', function ( $actions, $order ) use ( $wpide_refund_days ) {
    $completed = $order->get_date_completed();

    if ( $order->has_status( 'completed' ) && $completed && ( time() - $completed->getTimestamp() ) < $wpide_refund_days * DAY_IN_SECONDS && ! $order->get_meta( '_wpide_refund_requested' ) ) {
        $actions['wpide-refund'] = array(
            'url'  => wp_nonce_url( add_query_arg( 'wpide_refund_request', $order->get_id(), wc_get_account_endpoint_url( 'orders' ) ), 'wpide_refund_' . $order->get_id() ),
