add_action( 'template_redirect', function () {
    if ( empty( $_GET['wpide_refund_request'] ) || ! is_user_logged_in() ) {
        return;
    }

    $order_id = absint( $_GET['wpide_refund_request'] );
    $nonce    = isset( $_GET['_wpnonce'] ) ? sanitize_key( wp_unslash( $_GET['_wpnonce'] ) ) : '';
    $order    = wc_get_order( $order_id );

    if ( ! $order || ! wp_verify_nonce( $nonce, 'wpide_refund_' . $order_id ) || ! current_user_can( 'view_order', $order_id ) ) {
        wc_add_notice( 'Sorry, that refund request could not be sent.', 'error' );
    } elseif ( ! $order->get_meta( '_wpide_refund_requested' ) ) {
        $order->update_meta_data( '_wpide_refund_requested', time() );
        $order->add_order_note( 'The customer requested a refund from their account.' );
        $order->save();

        $mailer = WC()->mailer();
        $body   = sprintf( '%1$s asked for a refund on order #%2$s. Open the order: %3$s', $order->get_formatted_billing_full_name(), $order->get_order_number(), $order->get_edit_order_url() );
        $mailer->send( get_option( 'admin_email' ), sprintf( 'Refund request for order #%s', $order->get_order_number() ), $mailer->wrap_message( 'Refund request', wpautop( esc_html( $body ) ) ) );

        wc_add_notice( 'Thanks, we have received your refund request and will be in touch shortly.' );
    }

    wp_safe_redirect( wc_get_account_endpoint_url( 'orders' ) );
    exit;
} );

$wpide_digest_to = ''; // Recipient; empty uses the WooCommerce stock email recipient or admin email.

add_action( 'init', function () {
    if ( ! wp_next_scheduled( 'wpide_low_stock_digest' ) ) {
        wp_schedule_event( strtotime( 'tomorrow 07:00' ) - (int) ( get_option( 'gmt_offset' ) * HOUR_IN_SECONDS ), 'daily', 'wpide_low_stock_digest' );
    }
} );

add_action( 'wpide_low_stock_digest', function () use ( $wpide_digest_to ) {
    global $wpdb;

    if ( ! function_exists( 'WC' ) ) {
        return;
    }

    $threshold = (int) get_option( 'woocommerce_notify_low_stock_amount', 2 );
    $rows      = $wpdb->get_results( $wpdb->prepare(
        "SELECT l.product_id, l.sku, l.stock_quantity FROM {$wpdb->wc_product_meta_lookup} l
         INNER JOIN {$wpdb->posts} p ON p.ID = l.product_id AND p.post_status = 'publish'
         WHERE l.stock_quantity IS NOT NULL AND l.stock_quantity <= %d
         ORDER BY l.stock_quantity ASC LIMIT 200",
        $threshold
    ) );

    if ( ! $rows ) {
        return;
    }

    $lines = '';

    foreach ( $rows as $row ) {
        $lines .= sprintf( '<tr><td><a href="%1$s">%2$s</a></td><td>%3$s</td><td style="text-align:right">%4$s</td></tr>', esc_url( admin_url( 'post.php?action=edit&post=' . ( wp_get_post_parent_id( $row->product_id ) ?: $row->product_id ) ) ), esc_html( get_the_title( $row->product_id ) ), esc_html( $row->sku ), esc_html( wc_stock_amount( $row->stock_quantity ) ) );
    }

    $to      = $wpide_digest_to ? $wpide_digest_to : get_option( 'woocommerce_stock_email_recipient', get_option( 'admin_email' ) );
    $mailer  = WC()->mailer();
    $content = '<table style="width:100%;border-collapse:collapse" cellpadding="6"><tr><th style="text-align:left">Product</th><th style="text-align:left">SKU</th><th style="text-align:right">Stock</th></tr>' . $lines . '</table>';

    $mailer->send( $to, sprintf( '%d products are low on stock', count( $rows ) ), $mailer->wrap_message( 'Low stock digest', $content ) );
} );

