$wpide_stock_log = function ( $product ) use ( $wpide_stock_log_size ) {
    if ( ! $product instanceof WC_Product || ! $product->managing_stock() ) {
        return;
    }

    $parent = $product->get_parent_id() ? $product->get_parent_id() : $product->get_id();
    $user   = wp_get_current_user();
    $log    = (array) get_post_meta( $parent, '_wpide_stock_log', true );

    array_unshift( $log, array(
        'time' => time(),
        'id'   => $product->get_id(),
        'qty'  => wc_stock_amount( $product->get_stock_quantity() ),
        'by'   => $user->exists() ? $user->display_name : ( wp_doing_cron() ? 'Scheduled task' : 'System / order' ),
    ) );

    update_post_meta( $parent, '_wpide_stock_log', array_slice( array_filter( $log ), 0, $wpide_stock_log_size ) );
};

