$wpide_tracking_html = function ( $order ) use ( $wpide_carriers ) {
    $number  = $order->get_meta( '_wpide_tracking' );
    $carrier = $order->get_meta( '_wpide_carrier' );

    if ( ! $number ) {
        return '';
    }

    $label = $carrier ? $carrier . ': ' . $number : $number;
    $url   = isset( $wpide_carriers[ $carrier ] ) ? str_replace( '{number}', rawurlencode( $number ), $wpide_carriers[ $carrier ] ) : '';

