add_action( 'template_redirect', function () {
    if ( empty( $_GET['wpide_erase_request'] ) || ! is_user_logged_in() ) {
        return;
    }

    if ( ! isset( $_GET['_wpnonce'] ) || ! wp_verify_nonce( sanitize_key( $_GET['_wpnonce'] ), 'wpide_erase_request' ) ) {
        return;
    }

    $request_id = wp_create_user_request( wp_get_current_user()->user_email, 'remove_personal_data' );

    if ( is_wp_error( $request_id ) ) {
        wc_add_notice( 'A deletion request is already pending for your account. Please check your inbox for the confirmation email.', 'notice' );
    } else {
        wp_send_user_request( $request_id );
        wc_add_notice( 'Please check your inbox and click the link to confirm your account deletion request.' );
    }

    wp_safe_redirect( wc_get_account_endpoint_url( 'edit-account' ) );
    exit;
} );

