add_action( 'woocommerce_order_status_completed', function ( $order_id, $order = null ) use ( $wpide_thanks_coupon ) {
    $order = $order instanceof WC_Order ? $order : wc_get_order( $order_id );

    if ( ! $order || $order->get_meta( '_wpide_thanks_coupon' ) || ! $order->get_billing_email() ) {
