    }

    $code   = $wpide_thanks_coupon['prefix'] . strtoupper( wp_generate_password( 8, false, false ) );
    $coupon = new WC_Coupon();
    $coupon->set_code( $code );
    $coupon->set_discount_type( $wpide_thanks_coupon['type'] );
    $coupon->set_amount( $wpide_thanks_coupon['amount'] );
    $coupon->set_usage_limit( 1 );
    $coupon->set_individual_use( true );
    $coupon->set_email_restrictions( array( $order->get_billing_email() ) );
    $coupon->set_date_expires( time() + $wpide_thanks_coupon['days'] * DAY_IN_SECONDS );
    $coupon->set_description( 'Thank-you coupon for order #' . $order->get_order_number() );
    $coupon->save();

    $order->update_meta_data( '_wpide_thanks_coupon', $code );
    $order->save_meta_data();
