$wpide_bulk_sale_percent = 20; // Percent off the regular price.

add_filter( 'bulk_actions-edit-product', function ( $actions ) use ( $wpide_bulk_sale_percent ) {
    $actions['wpide_sale_on']  = sprintf( 'Put on sale (-%d%%)', $wpide_bulk_sale_percent );
    $actions['wpide_sale_off'] = 'Remove sale price';

    return $actions;
} );

add_filter( 'handle_bulk_actions-edit-product', function ( $redirect, $action, $ids ) use ( $wpide_bulk_sale_percent ) {
    if ( ! in_array( $action, array( 'wpide_sale_on', 'wpide_sale_off' ), true ) ) {
        return $redirect;
    }

    $changed = 0;

    foreach ( array_map( 'absint', (array) $ids ) as $id ) {
        $product = wc_get_product( $id );

        if ( ! $product || ! current_user_can( 'edit_product', $id ) ) {
            continue;
        }

        $targets = $product->is_type( 'variable' ) ? array_filter( array_map( 'wc_get_product', $product->get_children() ) ) : array( $product );

        foreach ( $targets as $target ) {
            $regular = (float) $target->get_regular_price( 'edit' );

            if ( 'wpide_sale_on' === $action && $regular > 0 ) {
                $target->set_sale_price( (string) round( $regular * ( 100 - $wpide_bulk_sale_percent ) / 100, wc_get_price_decimals() ) );
            } elseif ( 'wpide_sale_off' === $action ) {
                $target->set_sale_price( '' );
                $target->set_date_on_sale_from( null );
                $target->set_date_on_sale_to( null );
            }

            $target->save();
        }

        if ( $product->is_type( 'variable' ) ) {
            WC_Product_Variable::sync( $id );
        }

        $changed++;
    }

    return add_query_arg( 'wpide_sale_updated', $changed, $redirect );
}, 10, 3 );

