    $fields = array();

    foreach ( $wpide_rest_product_meta as $key ) {
        $fields[ ltrim( $key, '_' ) ] = $product->get_meta( $key );
    }

    $response->data['custom_fields'] = $fields;

    return $response;
}, 10, 2 );

add_action( 'woocommerce_rest_insert_product_object', function ( $product, $request ) use ( $wpide_rest_product_meta ) {
    $incoming = $request->get_param( 'custom_fields' );

    if ( ! is_array( $incoming ) ) {
        return;
    }

    foreach ( $wpide_rest_product_meta as $key ) {
        $name = ltrim( $key, '_' );

        if ( array_key_exists( $name, $incoming ) && is_scalar( $incoming[ $name ] ) ) {
            $product->update_meta_data( $key, sanitize_text_field( (string) $incoming[ $name ] ) );
        }
    }

    $product->save_meta_data();
}, 10, 2 );

