$wpide_auto_coupon = array(
    'code'    => 'spend100', // Existing coupon code.
    'minimum' => 100,        // Cart subtotal that triggers it.
);

add_action( 'woocommerce_before_calculate_totals', function ( $cart ) use ( $wpide_auto_coupon ) {
    static $running = false;

    if ( $running || ( is_admin() && ! wp_doing_ajax() ) || ! $cart instanceof WC_Cart ) {
        return;
    }

    $running  = true;
    $code     = wc_format_coupon_code( $wpide_auto_coupon['code'] );
    $subtotal = 0;

    foreach ( $cart->get_cart() as $item ) {
        $subtotal += (float) $item['data']->get_price() * (int) $item['quantity'];
    }

    if ( $subtotal >= $wpide_auto_coupon['minimum'] && ! $cart->has_discount( $code ) && wc_get_coupon_id_by_code( $code ) ) {
        $cart->apply_coupon( $code );
    } elseif ( $subtotal < $wpide_auto_coupon['minimum'] && $cart->has_discount( $code ) ) {
        $cart->remove_coupon( $code );
    }

    $running = false;
} );

$wpide_role_coupons = array( // Coupon code => allowed roles.
