);

add_filter( 'woocommerce_coupon_is_valid', function ( $valid, $coupon ) use ( $wpide_role_coupons ) {
    $code = wc_format_coupon_code( $coupon->get_code() );

    foreach ( $wpide_role_coupons as $restricted => $roles ) {
        if ( wc_format_coupon_code( $restricted ) !== $code ) {
            continue;
        }

        if ( ! is_user_logged_in() || ! array_intersect( $roles, (array) wp_get_current_user()->roles ) ) {
            throw new Exception( esc_html( 'Sorry, this coupon is not available for your account.' ), 100 );
