$wpide_omnibus_days = 30;

add_action( 'woocommerce_before_product_object_save', function ( $product ) {
    $price = $product->get_price( 'edit' );

    if ( '' === $price || null === $price ) {
        return;
    }

    $history = (array) $product->get_meta( '_wpide_price_history' );
    $today   = wp_date( 'Y-m-d' );
    $history = array_filter( $history, function ( $date ) {
        return strtotime( $date ) > strtotime( '-60 days' );
    }, ARRAY_FILTER_USE_KEY );

    if ( ! isset( $history[ $today ] ) || (float) $price < (float) $history[ $today ] ) {
        $history[ $today ] = (float) $price;
    }

    ksort( $history );
    $product->update_meta_data( '_wpide_price_history', $history );
} );

add_filter( 'woocommerce_get_price_html', function ( $html, $product ) use ( $wpide_omnibus_days ) {
    if ( ! $product->is_on_sale() || $product->is_type( 'variable' ) || ! is_product() ) {
        return $html;
    }

    $history = (array) $product->get_meta( '_wpide_price_history' );
    $from    = $product->get_date_on_sale_from() ? $product->get_date_on_sale_from()->getTimestamp() : time();
    $prices  = array();

    foreach ( $history as $date => $price ) {
        $time = strtotime( $date );

        if ( $time < $from && $time >= $from - $wpide_omnibus_days * DAY_IN_SECONDS ) {
            $prices[] = (float) $price;
        }
    }

    $prices[] = (float) $product->get_regular_price();
    $lowest   = min( array_filter( $prices ) );

    return $html . sprintf( '<br><small class="wpide-omnibus">%s</small>', wp_kses_post( sprintf( 'Lowest price in the %1$d days before the sale: %2$s', $wpide_omnibus_days, wc_price( wc_get_price_to_display( $product, array( 'price' => $lowest ) ) ) ) ) );
}, 20, 2 );

$wpide_schema_policy = array(
    'country'        => 'GB',  // Two-letter country code you ship to.
    'shipping_cost'  => '3.95',
    'handling_days'  => array( 0, 1 ),
    'transit_days'   => array( 1, 3 ),
