);

add_filter( 'woocommerce_structured_data_product', function ( $markup, $product ) use ( $wpide_schema_policy ) {
    if ( empty( $markup['offers'] ) || ! $product->needs_shipping() ) {
        return $markup;
    }

    $currency = get_woocommerce_currency();
    $shipping = array(
        '@type'               => 'OfferShippingDetails',
        'shippingRate'        => array( '@type' => 'MonetaryAmount', 'value' => $wpide_schema_policy['shipping_cost'], 'currency' => $currency ),
        'shippingDestination' => array( '@type' => 'DefinedRegion', 'addressCountry' => $wpide_schema_policy['country'] ),
        'deliveryTime'        => array(
            '@type'        => 'ShippingDeliveryTime',
            'handlingTime' => array( '@type' => 'QuantitativeValue', 'minValue' => $wpide_schema_policy['handling_days'][0], 'maxValue' => $wpide_schema_policy['handling_days'][1], 'unitCode' => 'DAY' ),
            'transitTime'  => array( '@type' => 'QuantitativeValue', 'minValue' => $wpide_schema_policy['transit_days'][0], 'maxValue' => $wpide_schema_policy['transit_days'][1], 'unitCode' => 'DAY' ),
        ),
    );
    $returns  = array(
        '@type'                => 'MerchantReturnPolicy',
        'applicableCountry'    => $wpide_schema_policy['country'],
        'returnPolicyCategory' => 'https://schema.org/MerchantReturnFiniteReturnWindow',
        'merchantReturnDays'   => $wpide_schema_policy['return_days'],
        'returnMethod'         => 'https://schema.org/ReturnByMail',
        'returnFees'           => $wpide_schema_policy['free_returns'] ? 'https://schema.org/FreeReturn' : 'https://schema.org/ReturnFeesCustomerResponsibility',
    );

    foreach ( $markup['offers'] as $i => $offer ) {
        $markup['offers'][ $i ]['shippingDetails']         = $shipping;
        $markup['offers'][ $i ]['hasMerchantReturnPolicy'] = $returns;
    }

    return $markup;
}, 10, 2 );

