add_action( 'wpide_unpaid_order_reminders', function () use ( $wpide_reminder_hours ) {
    if ( ! function_exists( 'wc_get_orders' ) ) {
        return;
    }

    $orders = wc_get_orders( array(
        'status'       => 'pending',
        'date_created' => ( time() - 3 * DAY_IN_SECONDS ) . '...' . ( time() - $wpide_reminder_hours * HOUR_IN_SECONDS ),
        'limit'        => 20,
        'meta_query'   => array( array( 'key' => '_wpide_payment_reminder', 'compare' => 'NOT EXISTS' ) ), // phpcs:ignore WordPress.DB.SlowDBQuery
    ) );

    $emails = WC()->mailer()->get_emails();

    foreach ( $orders as $order ) {
        if ( ! $order->get_billing_email() || ! $order->needs_payment() ) {
            continue;
        }

