    'best-sellers' => 20,
    'accessories'  => 5,
);

$wpide_cat_threshold = function ( $amount, $product ) use ( $wpide_cat_thresholds ) {
    if ( '' !== $product->get_low_stock_amount( 'edit' ) && null !== $product->get_low_stock_amount( 'edit' ) ) {
        return $amount;
    }

    $id = $product->get_parent_id() ? $product->get_parent_id() : $product->get_id();

    foreach ( $wpide_cat_thresholds as $slug => $threshold ) {
        if ( has_term( $slug, 'product_cat', $id ) ) {
            return $threshold;
        }
    }

    return $amount;
};

