$wpide_role_gateways = array( // Gateway ID => roles that may use it.
    'cheque' => array( 'wholesale_customer' ),
    'cod'    => array( 'wholesale_customer', 'customer' ),
);

add_filter( 'woocommerce_available_payment_gateways', function ( $gateways ) use ( $wpide_role_gateways ) {
    if ( is_admin() && ! wp_doing_ajax() ) {
        return $gateways;
    }

    $roles = is_user_logged_in() ? (array) wp_get_current_user()->roles : array();

    foreach ( $wpide_role_gateways as $id => $allowed ) {
        if ( isset( $gateways[ $id ] ) && ! array_intersect( $allowed, $roles ) ) {
            unset( $gateways[ $id ] );
        }
    }

    return $gateways;
} );

$wpide_gateway_cat_rules = array( // Gateway ID => category slugs that hide it.
    'cod' => array( 'gift-cards', 'digital' ),
);

add_filter( 'woocommerce_available_payment_gateways', function ( $gateways ) use ( $wpide_gateway_cat_rules ) {
    if ( ( is_admin() && ! wp_doing_ajax() ) || ! WC()->cart ) {
        return $gateways;
    }

    foreach ( WC()->cart->get_cart() as $item ) {
        foreach ( $wpide_gateway_cat_rules as $gateway => $categories ) {
            if ( isset( $gateways[ $gateway ] ) && has_term( $categories, 'product_cat', $item['product_id'] ) ) {
                unset( $gateways[ $gateway ] );
            }
        }
    }

    return $gateways;
} );

