    'contributor' => 'Guest Writer',
);

$wpide_role_rename = function ( $roles ) use ( $wpide_role_labels ) {
    if ( ! $roles instanceof WP_Roles ) {
        return;
    }

    foreach ( $wpide_role_labels as $role => $label ) {
        if ( isset( $roles->roles[ $role ] ) ) {
            $roles->roles[ $role ]['name'] = $label;
            $roles->role_names[ $role ]    = $label;
        }
    }
};

$wpide_role_rename( wp_roles() );
