// Capture the old values before the update is written.
add_filter( 'wp_pre_insert_user_data', function ( $data, $update, $user_id ) use ( $wpide_watch_fields, &$wpide_profile_before ) {
    if ( $update && $user_id && get_current_user_id() === (int) $user_id && ! current_user_can( 'edit_users' ) ) {
        $user = get_userdata( $user_id );

        foreach ( array_keys( $wpide_watch_fields ) as $field ) {
            $wpide_profile_before[ $user_id ][ $field ] = (string) $user->get( $field );
        }
    }

    return $data;
}, 10, 3 );

add_action( 'profile_update', function ( $user_id ) use ( $wpide_watch_fields, &$wpide_profile_before ) {
    if ( empty( $wpide_profile_before[ $user_id ] ) ) {
        return;
    }

    clean_user_cache( $user_id );
    $user    = get_userdata( $user_id );
    $changes = array();

    foreach ( $wpide_watch_fields as $field => $label ) {
        $old = $wpide_profile_before[ $user_id ][ $field ];
        $new = (string) $user->get( $field );

        if ( $old !== $new ) {
            $changes[] = sprintf( "%s: \"%s\" -> \"%s\"", $label, $old, $new );
        }
    }

    unset( $wpide_profile_before[ $user_id ] );

    if ( $changes ) {
        wp_mail(
            get_option( 'admin_email' ),
            sprintf( '[%s] %s updated their profile', wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES ), $user->user_login ),
            implode( "\n", $changes ) . "\n\n" . admin_url( 'user-edit.php?user_id=' . $user_id )
        );
    }
}, 20 );

