add_filter( 'registration_errors', function ( $errors ) use ( $wpide_invite_codes, $wpide_find_code ) {
    $entered = isset( $_POST['wpide_invite'] ) ? trim( sanitize_text_field( wp_unslash( $_POST['wpide_invite'] ) ) ) : '';
    $code    = '' !== $entered ? $wpide_find_code( $entered ) : '';

    if ( ! $code ) {
        $errors->add( 'wpide_invite', '<strong>Error:</strong> Please enter a valid invite code.' );
        return $errors;
