add_filter( 'authenticate', function ( $user ) {
    if ( $user instanceof WP_User && get_user_meta( $user->ID, 'wpide_email_verify', true ) ) {
        return new WP_Error( 'wpide_unverified', '<strong>Please confirm your email address.</strong> We sent you a link when you signed up.' );
    }

    return $user;
}, 60 );

add_action( 'login_init', function () use ( $wpide_verify_hours, $wpide_send_verify ) {
    if ( empty( $_GET['wpide_verify'] ) || empty( $_GET['key'] ) ) {
        return;
    }

    $user_id = absint( $_GET['wpide_verify'] );
    $data    = get_user_meta( $user_id, 'wpide_email_verify', true );
    $key     = sanitize_text_field( wp_unslash( $_GET['key'] ) );

    if ( ! is_array( $data ) ) {
        wp_safe_redirect( add_query_arg( 'wpide_verified', 'already', wp_login_url() ) );
        exit;
    }

    if ( time() - (int) $data['time'] > $wpide_verify_hours * HOUR_IN_SECONDS ) {
        $wpide_send_verify( $user_id );
        wp_safe_redirect( add_query_arg( 'wpide_verified', 'expired', wp_login_url() ) );
        exit;
    }

    if ( hash_equals( $data['hash'], wp_hash( $key ) ) ) {
        delete_user_meta( $user_id, 'wpide_email_verify' );
        wp_safe_redirect( add_query_arg( 'wpide_verified', 'yes', wp_login_url() ) );
        exit;
    }
} );

