// Minimum length for new passwords.
$wpide_new_pass_min = 10;
$wpide_pass_error   = '';

add_action( 'template_redirect', function () use ( $wpide_new_pass_min, &$wpide_pass_error ) {
    if ( empty( $_POST['wpide_pass_nonce'] ) || ! is_user_logged_in() ) {
        return;
    }

    if ( ! wp_verify_nonce( sanitize_key( $_POST['wpide_pass_nonce'] ), 'wpide_change_password' ) ) {
        $wpide_pass_error = 'The form expired. Please try again.';
        return;
    }

    $user    = wp_get_current_user();
    $current = isset( $_POST['wpide_current_pass'] ) ? (string) wp_unslash( $_POST['wpide_current_pass'] ) : '';
    $new     = isset( $_POST['wpide_new_pass'] ) ? (string) wp_unslash( $_POST['wpide_new_pass'] ) : '';
    $confirm = isset( $_POST['wpide_confirm_pass'] ) ? (string) wp_unslash( $_POST['wpide_confirm_pass'] ) : '';

    if ( ! wp_check_password( $current, $user->user_pass, $user->ID ) ) {
        $wpide_pass_error = 'Your current password is not correct.';
    } elseif ( strlen( $new ) < $wpide_new_pass_min ) {
        $wpide_pass_error = sprintf( 'The new password must be at least %d characters.', $wpide_new_pass_min );
    } elseif ( $new !== $confirm ) {
        $wpide_pass_error = 'The new passwords do not match.';
    }

    if ( $wpide_pass_error ) {
        return;
    }

    wp_set_password( $new, $user->ID );
    // Setting the password ends every session, so start a fresh one here.
    wp_set_current_user( $user->ID );
    wp_set_auth_cookie( $user->ID );

    wp_safe_redirect( add_query_arg( 'password-changed', 1 ) );
    exit;
} );

