add_filter( 'wp_nav_menu_objects', function ( $items ) {
    $logged_in = is_user_logged_in();
    $roles     = $logged_in ? (array) wp_get_current_user()->roles : array();
    $removed   = array();

    foreach ( $items as $key => $item ) {
        $classes = (array) $item->classes;
        $hide    = in_array( (int) $item->menu_item_parent, $removed, true );

        if ( in_array( 'wpide-logged-in', $classes, true ) && ! $logged_in ) {
            $hide = true;
        }

        if ( in_array( 'wpide-logged-out', $classes, true ) && $logged_in ) {
            $hide = true;
        }

        $role_classes = preg_grep( '/^wpide-role-/', $classes );

        if ( $role_classes ) {
            $wanted = array_map( function ( $class ) {
                return substr( $class, 11 );
            }, $role_classes );

            if ( ! array_intersect( $wanted, $roles ) && ! current_user_can( 'manage_options' ) ) {
                $hide = true;
            }
        }

        if ( $hide ) {
            $removed[] = (int) $item->ID;
            unset( $items[ $key ] );
        }
    }

    return $items;
}, 10 );

