add_action( 'wp_login', function ( $login, $user ) use ( $wpide_login_history_size ) {
    $history   = (array) get_user_meta( $user->ID, 'wpide_login_history', true );
    $history   = array_filter( $history, 'is_array' );
    array_unshift( $history, array(
        'time' => time(),
        'ip'   => isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : '',
        'ua'   => isset( $_SERVER['HTTP_USER_AGENT'] ) ? substr( sanitize_text_field( wp_unslash( $_SERVER['HTTP_USER_AGENT'] ) ), 0, 200 ) : '',
    ) );

    update_user_meta( $user->ID, 'wpide_login_history', array_slice( $history, 0, $wpide_login_history_size ) );
}, 10, 2 );

