// Role => maximum number of users.
$wpide_role_limits = array(
    'editor'        => 3,
    'administrator' => 2,
);

$wpide_role_full = function ( $role, $ignore_user = 0 ) use ( $wpide_role_limits ) {
    if ( empty( $wpide_role_limits[ $role ] ) ) {
        return false;
    }

    $count = count( get_users( array( 'role' => $role, 'fields' => 'ID', 'exclude' => array( (int) $ignore_user ), 'number' => $wpide_role_limits[ $role ] ) ) );

    return $count >= $wpide_role_limits[ $role ];
};

add_action( 'user_profile_update_errors', function ( $errors, $update, $user ) use ( $wpide_role_full ) {
    $role = isset( $_POST['role'] ) ? sanitize_key( $_POST['role'] ) : '';

    if ( ! $role ) {
        return;
    }

    $current = $update && ! empty( $user->ID ) ? (array) get_userdata( $user->ID )->roles : array();

    if ( ! in_array( $role, $current, true ) && $wpide_role_full( $role, $update ? (int) $user->ID : 0 ) ) {
        $errors->add( 'wpide_role_full', sprintf( '<strong>Error:</strong> The %s role has reached its user limit.', esc_html( $role ) ) );
    }
}, 10, 3 );

// Hide full roles from the role menus.
add_filter( 'editable_roles', function ( $roles ) use ( $wpide_role_full ) {
    $editing = isset( $_GET['user_id'] ) ? get_userdata( absint( $_GET['user_id'] ) ) : null;
    $keep    = $editing ? (array) $editing->roles : array();

    foreach ( array_keys( $roles ) as $role ) {
        if ( ! in_array( $role, $keep, true ) && $wpide_role_full( $role ) ) {
            unset( $roles[ $role ] );
        }
    }

    return $roles;
} );

add_filter( 'bulk_actions-users', function ( $actions ) {
    if ( ! current_user_can( 'promote_users' ) ) {
        return $actions;
    }

    foreach ( get_editable_roles() as $role => $details ) {
        if ( 'administrator' !== $role ) {
            $actions[ 'wpide_add_role_' . $role ] = sprintf( 'Add role: %s', translate_user_role( $details['name'] ) );
        }
    }

    return $actions;
} );

add_filter( 'handle_bulk_actions-users', function ( $redirect, $action, $user_ids ) {
    if ( 0 !== strpos( $action, 'wpide_add_role_' ) ) {
        return $redirect;
    }

    $role = substr( $action, 15 );

    if ( 'administrator' === $role || ! array_key_exists( $role, get_editable_roles() ) ) {
        return $redirect;
    }

    $done = 0;

    foreach ( array_map( 'intval', (array) $user_ids ) as $user_id ) {
        if ( current_user_can( 'promote_user', $user_id ) ) {
            ( new WP_User( $user_id ) )->add_role( $role );
            $done++;
        }
    }

    return add_query_arg( 'wpide_roles_added', $done, $redirect );
}, 10, 3 );

