add_filter( 'wp_nav_menu_objects', function ( $items ) {
    if ( is_user_logged_in() ) {
        return $items;
    }

    $removed = array();

    foreach ( $items as $key => $item ) {
        $hide = in_array( (int) $item->menu_item_parent, $removed, true );

        if ( ! $hide && 'post_type' === ( $item->type ?? '' ) && ! empty( $item->object_id ) ) {
            $object_id = (int) $item->object_id;
            $hide      = 'private' === get_post_status( $object_id ) || (bool) get_post_meta( $object_id, '_wpide_members_only', true );
        }

        if ( $hide ) {
            $removed[] = (int) $item->ID;
            unset( $items[ $key ] );
        }
    }

    return $items;
} );

add_action( 'user_register', function ( $user_id ) {
    if ( defined( 'WP_CLI' ) && WP_CLI ) {
        $source = 'WP-CLI';
    } elseif ( defined( 'REST_REQUEST' ) && REST_REQUEST ) {
        $source = 'REST API';
