// Roles that need the emailed code.
$wpide_code_roles = array( 'administrator', 'editor' );
$wpide_code_minutes = 10;

add_action( 'login_form', function () {
    if ( isset( $_POST['log'] ) || isset( $_GET['wpide_code'] ) ) {
        echo '<p><label for="wpide_login_code">Login code (if we emailed you one)</label><input type="text" name="wpide_login_code" id="wpide_login_code" class="input" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]*" maxlength="6"></p>';
    }
} );

add_filter( 'authenticate', function ( $user ) use ( $wpide_code_roles, $wpide_code_minutes ) {
    if ( ! $user instanceof WP_User || ! array_intersect( $wpide_code_roles, (array) $user->roles ) ) {
        return $user;
    }

    // Only the interactive login form gets the second step (not XML-RPC or application passwords).
    if ( ! isset( $_POST['log'], $_POST['pwd'] ) ) {
        return $user;
    }

    $entered = isset( $_POST['wpide_login_code'] ) ? preg_replace( '/\D/', '', (string) wp_unslash( $_POST['wpide_login_code'] ) ) : '';
    $stored  = get_user_meta( $user->ID, 'wpide_login_code', true );

    if ( $entered && is_array( $stored ) && time() < (int) $stored['expires'] && (int) $stored['tries'] < 5 ) {
        if ( hash_equals( $stored['hash'], wp_hash( $entered ) ) ) {
            delete_user_meta( $user->ID, 'wpide_login_code' );
            return $user;
        }

        $stored['tries']++;
        update_user_meta( $user->ID, 'wpide_login_code', $stored );

        return new WP_Error( 'wpide_code_wrong', '<strong>Error:</strong> That login code is not correct. Enter your password and the code again.' );
    }

    $code = (string) wp_rand( 100000, 999999 );
    update_user_meta( $user->ID, 'wpide_login_code', array( 'hash' => wp_hash( $code ), 'expires' => time() + $wpide_code_minutes * MINUTE_IN_SECONDS, 'tries' => 0 ) );

    wp_mail(
        $user->user_email,
        sprintf( '[%s] Your login code: %s', wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES ), $code ),
        sprintf( "Your login code is %s\n\nIt expires in %d minutes. If you did not try to log in, change your password now.", $code, $wpide_code_minutes )
    );

    return new WP_Error( 'wpide_code_sent', '<strong>Check your email.</strong> We sent you a 6-digit login code. Enter your password again together with the code.' );
}, 99 );

// How many known devices to remember per user.
$wpide_known_devices = 10;

add_action( 'wp_login', function ( $login, $user ) use ( $wpide_known_devices ) {
    $ip  = isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : '';
    $ua  = isset( $_SERVER['HTTP_USER_AGENT'] ) ? sanitize_text_field( wp_unslash( $_SERVER['HTTP_USER_AGENT'] ) ) : '';
    // Use the network part of the IP so a changing last digit does not count as new.
    $net = preg_replace( '/\.\d+$/', '', $ip );
    $key = wp_hash( $net . '|' . $ua );

    $known = get_user_meta( $user->ID, 'wpide_known_devices', true );
    $first = ! is_array( $known );
    $known = $first ? array() : $known;

    if ( in_array( $key, $known, true ) ) {
        return;
    }

    array_unshift( $known, $key );
    update_user_meta( $user->ID, 'wpide_known_devices', array_slice( $known, 0, $wpide_known_devices ) );

    if ( $first ) {
        return;
    }

    wp_mail(
        $user->user_email,
        sprintf( '[%s] New login to your account', wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES ) ),
        sprintf(
            "Hi %s,\n\nYour account was just used to log in from a new device.\n\nTime: %s\nIP address: %s\nBrowser: %s\n\nIf this was you, there is nothing to do. If not, reset your password now:\n%s",
            $user->display_name,
            wp_date( 'Y-m-d H:i' ),
            $ip,
            $ua,
            wp_lostpassword_url()
        )
    );
}, 10, 2 );

