// Roles whose passwords expire, and after how many days.
$wpide_expiring_roles  = array( 'administrator', 'editor', 'shop_manager' );
$wpide_password_days   = 90;

$wpide_mark_password_changed = function ( $user_id ) {
    update_user_meta( $user_id, 'wpide_password_changed', time() );
};

add_action( 'user_register', $wpide_mark_password_changed );
