// Roles limited to office hours, and the hours (24h clock, site time zone).
$wpide_office_roles = array( 'shop_manager', 'editor' );
$wpide_office_start = 8;
$wpide_office_end   = 18;
$wpide_office_days  = array( 1, 2, 3, 4, 5 ); // 1 = Monday ... 7 = Sunday.

$wpide_in_office_hours = function () use ( $wpide_office_start, $wpide_office_end, $wpide_office_days ) {
    $now  = current_datetime();
    $hour = (int) $now->format( 'G' );

    return in_array( (int) $now->format( 'N' ), $wpide_office_days, true ) && $hour >= $wpide_office_start && $hour < $wpide_office_end;
};

$wpide_is_office_user = function ( $user ) use ( $wpide_office_roles ) {
    return $user instanceof WP_User && ! user_can( $user, 'manage_options' ) && array_intersect( $wpide_office_roles, (array) $user->roles );
};

add_filter( 'authenticate', function ( $user ) use ( $wpide_in_office_hours, $wpide_is_office_user ) {
    if ( $wpide_is_office_user( $user ) && ! $wpide_in_office_hours() ) {
        return new WP_Error( 'wpide_office_hours', '<strong>Error:</strong> Your account can only be used during office hours.' );
    }

    return $user;
}, 60 );

add_action( 'init', function () use ( $wpide_in_office_hours, $wpide_is_office_user ) {
    if ( is_user_logged_in() && $wpide_is_office_user( wp_get_current_user() ) && ! $wpide_in_office_hours() ) {
        wp_logout();
    }
} );

$wpide_end_sessions = function ( $user_id ) {
    if ( (int) $user_id !== get_current_user_id() ) {
        WP_Session_Tokens::get_instance( (int) $user_id )->destroy_all();
    }
};

add_action( 'set_user_role', function ( $user_id, $role, $old_roles ) use ( $wpide_end_sessions ) {
    if ( $old_roles && ! in_array( $role, (array) $old_roles, true ) ) {
        $wpide_end_sessions( $user_id );
    }
}, 10, 3 );

add_action( 'remove_user_role', function ( $user_id ) use ( $wpide_end_sessions ) {
    $wpide_end_sessions( $user_id );
} );

// Days without activity before the account is locked.
$wpide_dormant_days = 180;

// Record activity at most once a day.
add_action( 'init', function () {
    $user_id = get_current_user_id();

    if ( ! $user_id ) {
        return;
    }

    $last = (int) get_user_meta( $user_id, 'wpide_last_active', true );

    if ( time() - $last > DAY_IN_SECONDS ) {
        update_user_meta( $user_id, 'wpide_last_active', time() );
    }
} );

add_action( 'after_password_reset', function ( $user ) {
    update_user_meta( $user->ID, 'wpide_last_active', time() );
} );

add_filter( 'authenticate', function ( $user ) use ( $wpide_dormant_days ) {
    if ( ! $user instanceof WP_User || user_can( $user, 'manage_options' ) ) {
        return $user;
    }

    $last = (int) get_user_meta( $user->ID, 'wpide_last_active', true );

    if ( ! $last ) {
        update_user_meta( $user->ID, 'wpide_last_active', time() );
        return $user;
    }

    if ( time() - $last > $wpide_dormant_days * DAY_IN_SECONDS ) {
        return new WP_Error( 'wpide_dormant', sprintf( '<strong>Your account was locked after a long time without use.</strong> Please <a href="%s">reset your password</a> to unlock it.', esc_url( wp_lostpassword_url() ) ) );
    }

    return $user;
}, 60 );

add_action( 'lostpassword_post', function ( $errors ) {
    $value = isset( $_POST['user_login'] ) ? sanitize_text_field( wp_unslash( $_POST['user_login'] ) ) : '';

    if ( '' !== $value && ! is_email( $value ) ) {
        $errors->add( 'wpide_email_only', '<strong>Error:</strong> Please enter the email address of your account.' );
    }
} );

add_filter( 'gettext', function ( $translation, $text, $domain ) {
    if ( 'default' === $domain && 'Username or Email Address' === $text && isset( $GLOBALS['pagenow'] ) && 'wp-login.php' === $GLOBALS['pagenow'] && isset( $_GET['action'] ) && 'lostpassword' === $_GET['action'] ) {
        return 'Email address';
    }

    return $translation;
}, 10, 3 );

// Post types that get the box.
$wpide_mo_post_types = array( 'post', 'page' );

$wpide_mo_can_view = function ( $post_id ) {
    if ( ! get_post_meta( $post_id, '_wpide_members_only', true ) ) {
        return true;
    }

    if ( ! is_user_logged_in() ) {
        return false;
    }

    $roles = (array) get_post_meta( $post_id, '_wpide_members_roles', true );
    $roles = array_filter( $roles );

    return ! $roles || array_intersect( $roles, (array) wp_get_current_user()->roles ) || current_user_can( 'edit_post', $post_id );
};

add_action( 'add_meta_boxes', function () use ( $wpide_mo_post_types ) {
    add_meta_box( 'wpide-members-only', 'Members only', function ( $post ) {
        $roles = array_filter( (array) get_post_meta( $post->ID, '_wpide_members_roles', true ) );
        wp_nonce_field( 'wpide_members_only', 'wpide_members_only_nonce' );
        printf( '<p><label><input type="checkbox" name="wpide_members_only" value="1" %s> Only logged-in members can read this</label></p><p>Limit to these roles (optional):</p>', checked( (bool) get_post_meta( $post->ID, '_wpide_members_only', true ), true, false ) );

        foreach ( wp_roles()->role_names as $role => $name ) {
            printf( '<label style="display:block"><input type="checkbox" name="wpide_members_roles[]" value="%1$s" %2$s> %3$s</label>', esc_attr( $role ), checked( in_array( $role, $roles, true ), true, false ), esc_html( translate_user_role( $name ) ) );
        }
    }, $wpide_mo_post_types, 'side' );
} );

add_action( 'save_post', function ( $post_id ) {
    if ( ! isset( $_POST['wpide_members_only_nonce'] ) || ! wp_verify_nonce( sanitize_key( $_POST['wpide_members_only_nonce'] ), 'wpide_members_only' ) ) {
        return;
    }

    if ( wp_is_post_autosave( $post_id ) || wp_is_post_revision( $post_id ) || ! current_user_can( 'edit_post', $post_id ) ) {
        return;
    }

    if ( empty( $_POST['wpide_members_only'] ) ) {
        delete_post_meta( $post_id, '_wpide_members_only' );
        delete_post_meta( $post_id, '_wpide_members_roles' );
        return;
    }

    $roles = isset( $_POST['wpide_members_roles'] ) ? array_map( 'sanitize_key', (array) wp_unslash( $_POST['wpide_members_roles'] ) ) : array();
    update_post_meta( $post_id, '_wpide_members_only', 1 );
    update_post_meta( $post_id, '_wpide_members_roles', array_values( array_intersect( $roles, array_keys( wp_roles()->role_names ) ) ) );
} );

$wpide_mo_message = function () {
    $login = wp_login_url( get_permalink() );

    if ( is_user_logged_in() ) {
        return '<div class="wpide-members-only"><p>This content is not available with your current membership.</p></div>';
    }

    $html = '<div class="wpide-members-only"><p>This content is for members. <a href="' . esc_url( $login ) . '">Log in</a>';

    if ( get_option( 'users_can_register' ) ) {
        $html .= ' or <a href="' . esc_url( wp_registration_url() ) . '">create a free account</a>';
    }

    return $html . ' to keep reading.</p></div>';
};

add_filter( 'the_content', function ( $content ) use ( $wpide_mo_can_view, $wpide_mo_message ) {
    $post = get_post();

    return ( $post && ! $wpide_mo_can_view( $post->ID ) ) ? $wpide_mo_message() : $content;
}, 1 );

add_filter( 'get_the_excerpt', function ( $excerpt, $post ) use ( $wpide_mo_can_view ) {
    return ( $post && ! $wpide_mo_can_view( $post->ID ) ) ? '' : $excerpt;
}, 10, 2 );

// Keep restricted items out of search results and feeds for visitors.
add_action( 'pre_get_posts', function ( $query ) {
    if ( is_admin() || is_user_logged_in() || ! $query->is_main_query() || ! ( $query->is_search() || $query->is_feed() ) ) {
        return;
    }

    $meta   = (array) $query->get( 'meta_query' );
    $meta[] = array( 'key' => '_wpide_members_only', 'compare' => 'NOT EXISTS' );
    $query->set( 'meta_query', $meta );
} );

// Category slug that holds members-only posts, and how many words visitors see.
$wpide_members_category = 'members';
$wpide_teaser_words     = 60;

add_filter( 'the_content', function ( $content ) use ( $wpide_members_category, $wpide_teaser_words ) {
    if ( is_user_logged_in() || ! in_the_loop() || ! has_category( $wpide_members_category ) ) {
        return $content;
    }

    $teaser = wp_trim_words( wp_strip_all_tags( strip_shortcodes( get_post_field( 'post_content', get_the_ID() ) ) ), $wpide_teaser_words );
    $box    = '<div class="wpide-teaser-box" style="border:1px solid currentColor;padding:1em 1.25em;margin-top:1.5em;border-radius:6px">'
        . '<p><strong>Keep reading with a free membership.</strong></p><p><a href="' . esc_url( wp_login_url( get_permalink() ) ) . '">Log in</a>';

    if ( get_option( 'users_can_register' ) ) {
        $box .= ' &middot; <a href="' . esc_url( wp_registration_url() ) . '">Create an account</a>';
    }

    return '<p>' . esc_html( $teaser ) . '</p>' . $box . '</p></div>';
}, 1 );

add_filter( 'the_content_feed', function ( $content ) use ( $wpide_members_category ) {
    return has_category( $wpide_members_category ) ? '<p>' . esc_html( get_the_excerpt() ) . '</p>' : $content;
} );

add_shortcode( 'wpide_drip', function ( $atts, $content = '' ) {
    $atts = shortcode_atts( array( 'days' => 0, 'locked' => 'This part unlocks on %s.' ), $atts, 'wpide_drip' );

    if ( ! is_user_logged_in() ) {
        return '<p class="wpide-drip-locked">Please <a href="' . esc_url( wp_login_url( get_permalink() ) ) . '">log in</a> to see this content.</p>';
    }

    if ( current_user_can( 'edit_others_posts' ) ) {
        return do_shortcode( $content );
    }

    $unlocks = strtotime( wp_get_current_user()->user_registered . ' UTC' ) + max( 0, (int) $atts['days'] ) * DAY_IN_SECONDS;

    if ( time() >= $unlocks ) {
        return do_shortcode( $content );
    }

    return '<p class="wpide-drip-locked">' . esc_html( sprintf( $atts['locked'], wp_date( get_option( 'date_format' ), $unlocks ) ) ) . '</p>';
} );

// Post types that get the field.
$wpide_drip_post_types = array( 'post', 'page' );

add_action( 'add_meta_boxes', function () use ( $wpide_drip_post_types ) {
    add_meta_box( 'wpide-drip', 'Drip schedule', function ( $post ) {
        wp_nonce_field( 'wpide_drip', 'wpide_drip_nonce' );
        printf(
            '<p><label for="wpide-drip-days">Unlock this many days after a member joins</label><br><input type="number" min="0" step="1" id="wpide-drip-days" name="wpide_drip_days" value="%s" style="width:6em"></p>',
            esc_attr( get_post_meta( $post->ID, '_wpide_drip_days', true ) )
        );
    }, $wpide_drip_post_types, 'side' );
} );

add_action( 'save_post', function ( $post_id ) {
    if ( ! isset( $_POST['wpide_drip_nonce'] ) || ! wp_verify_nonce( sanitize_key( $_POST['wpide_drip_nonce'] ), 'wpide_drip' ) || ! current_user_can( 'edit_post', $post_id ) || wp_is_post_revision( $post_id ) ) {
        return;
    }

    $days = isset( $_POST['wpide_drip_days'] ) ? sanitize_text_field( wp_unslash( $_POST['wpide_drip_days'] ) ) : '';

    if ( '' === $days ) {
        delete_post_meta( $post_id, '_wpide_drip_days' );
    } else {
        update_post_meta( $post_id, '_wpide_drip_days', absint( $days ) );
    }
} );

add_filter( 'the_content', function ( $content ) {
    $post = get_post();

    if ( ! $post ) {
        return $content;
    }

    $days = get_post_meta( $post->ID, '_wpide_drip_days', true );

    if ( '' === $days || current_user_can( 'edit_post', $post->ID ) ) {
        return $content;
    }

    if ( ! is_user_logged_in() ) {
        return '<p class="wpide-drip-locked">This lesson is for members. <a href="' . esc_url( wp_login_url( get_permalink( $post ) ) ) . '">Log in</a> to continue.</p>';
    }

    $unlocks = strtotime( wp_get_current_user()->user_registered . ' UTC' ) + (int) $days * DAY_IN_SECONDS;

    if ( time() >= $unlocks ) {
        return $content;
    }

    return '<p class="wpide-drip-locked">' . esc_html( sprintf( 'This lesson unlocks on %s. See you then!', wp_date( get_option( 'date_format' ), $unlocks ) ) ) . '</p>';
}, 1 );

// Free posts per visitor every 30 days.
$wpide_free_articles = 3;

$wpide_meter_read = array();

add_action( 'template_redirect', function () use ( $wpide_free_articles, &$wpide_meter_read ) {
    if ( is_user_logged_in() || ! is_singular( 'post' ) ) {
        return;
    }

    $read = isset( $_COOKIE['wpide_meter'] ) ? array_map( 'absint', explode( '.', sanitize_text_field( wp_unslash( $_COOKIE['wpide_meter'] ) ) ) ) : array();
    $read = array_values( array_filter( array_unique( $read ) ) );
    $id   = get_queried_object_id();

    if ( ! in_array( $id, $read, true ) && count( $read ) < $wpide_free_articles ) {
        $read[] = $id;
        setcookie( 'wpide_meter', implode( '.', $read ), array(
            'expires'  => time() + 30 * DAY_IN_SECONDS,
            'path'     => COOKIEPATH ? COOKIEPATH : '/',
            'domain'   => COOKIE_DOMAIN,
            'secure'   => is_ssl(),
            'httponly' => true,
            'samesite' => 'Lax',
        ) );
    }

    $wpide_meter_read = $read;
    nocache_headers();
} );

add_filter( 'the_content', function ( $content ) use ( $wpide_free_articles, &$wpide_meter_read ) {
    if ( is_user_logged_in() || ! is_singular( 'post' ) || ! in_the_loop() || ! is_main_query() ) {
        return $content;
    }

    $id = get_the_ID();

    if ( in_array( $id, $wpide_meter_read, true ) ) {
        $left = $wpide_free_articles - count( $wpide_meter_read );

        return '<p class="wpide-meter-note"><small>' . esc_html( sprintf( _n( '%d free article left this month.', '%d free articles left this month.', $left ), $left ) ) . '</small></p>' . $content;
    }

    $html = '<p>' . esc_html( wp_trim_words( wp_strip_all_tags( strip_shortcodes( get_post_field( 'post_content', $id ) ) ), 40 ) ) . '</p>'
        . '<div class="wpide-meter-wall"><p><strong>You have read your free articles for this month.</strong></p><p><a href="' . esc_url( wp_login_url( get_permalink() ) ) . '">Log in</a>';

    if ( get_option( 'users_can_register' ) ) {
        $html .= ' or <a href="' . esc_url( wp_registration_url() ) . '">sign up for free</a>';
    }

    return $html . ' to keep reading.</p></div>';
}, 1 );

add_filter( 'render_block', function ( $html, $block ) {
    $classes = isset( $block['attrs']['className'] ) ? preg_split( '/\s+/', (string) $block['attrs']['className'] ) : array();

    if ( ! $classes || false === strpos( $block['attrs']['className'], 'wpide-' ) ) {
        return $html;
    }

    $logged_in = is_user_logged_in();

    if ( in_array( 'wpide-members-only', $classes, true ) && ! $logged_in ) {
        return '';
    }

    if ( in_array( 'wpide-guests-only', $classes, true ) && $logged_in ) {
        return '';
    }

    $wanted = array();

    foreach ( $classes as $class ) {
        if ( 0 === strpos( $class, 'wpide-role-' ) ) {
            $wanted[] = substr( $class, 11 );
        }
    }

    if ( $wanted && ! array_intersect( $wanted, $logged_in ? (array) wp_get_current_user()->roles : array() ) ) {
        return '';
    }

    return $html;
}, 10, 2 );

add_shortcode( 'wpide_member_download', function ( $atts ) {
    $atts = shortcode_atts( array( 'id' => 0, 'label' => 'Download' ), $atts, 'wpide_member_download' );
    $id   = absint( $atts['id'] );

    if ( ! $id || 'attachment' !== get_post_type( $id ) ) {
        return '';
    }

    if ( ! is_user_logged_in() ) {
        return '<a class="wpide-member-download is-locked" href="' . esc_url( wp_login_url( get_permalink() ) ) . '">' . esc_html( 'Log in to download' ) . '</a>';
    }

    $url = wp_nonce_url( add_query_arg( 'wpide_download', $id, home_url( '/' ) ), 'wpide_download_' . $id );

    return '<a class="wpide-member-download" href="' . esc_url( $url ) . '">' . esc_html( $atts['label'] ) . '</a>';
} );

add_action( 'init', function () {
    if ( empty( $_GET['wpide_download'] ) ) {
        return;
    }

    $id = absint( $_GET['wpide_download'] );

    if ( ! is_user_logged_in() ) {
        auth_redirect();
    }

    if ( ! isset( $_GET['_wpnonce'] ) || ! wp_verify_nonce( sanitize_key( $_GET['_wpnonce'] ), 'wpide_download_' . $id ) ) {
        wp_die( 'This download link has expired. Please go back and click it again.', 'Download', array( 'response' => 403 ) );
    }

    $file    = get_attached_file( $id );
    $uploads = wp_get_upload_dir();

    if ( 'attachment' !== get_post_type( $id ) || ! $file || ! is_readable( $file ) || 0 !== strpos( wp_normalize_path( realpath( $file ) ), wp_normalize_path( realpath( $uploads['basedir'] ) ) ) ) {
        wp_die( 'File not found.', 'Download', array( 'response' => 404 ) );
    }

    nocache_headers();
    header( 'Content-Type: ' . ( get_post_mime_type( $id ) ? get_post_mime_type( $id ) : 'application/octet-stream' ) );
    header( 'Content-Disposition: attachment; filename="' . sanitize_file_name( wp_basename( $file ) ) . '"' );
    header( 'Content-Length: ' . filesize( $file ) );
    header( 'X-Content-Type-Options: nosniff' );

    while ( ob_get_level() ) {
        ob_end_clean();
    }

    readfile( $file );
    exit;
} );

add_action( 'add_meta_boxes_page', function ( $post ) {
