            'show_option_none'  => 'Everyone (not private)',
            'option_none_value' => 0,
        ) );
    }, 'page', 'side' );
} );

add_action( 'save_post_page', function ( $post_id ) {
    if ( ! isset( $_POST['wpide_page_owner_nonce'] ) || ! wp_verify_nonce( sanitize_key( $_POST['wpide_page_owner_nonce'] ), 'wpide_page_owner' ) || ! current_user_can( 'edit_post', $post_id ) ) {
        return;
    }

    $owner = isset( $_POST['wpide_page_owner'] ) ? absint( $_POST['wpide_page_owner'] ) : 0;

