$wpide_feed_key = function ( $user_id, $reset = false ) {
    $key = get_user_meta( $user_id, 'wpide_feed_key', true );

    if ( ! $key || $reset ) {
        $key = wp_generate_password( 24, false );
        update_user_meta( $user_id, 'wpide_feed_key', $key );
    }

    return $key;
};

// Treat a feed request with a valid key as that member, for this request only.
add_filter( 'determine_current_user', function ( $user_id ) {
    $uri = isset( $_SERVER['REQUEST_URI'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REQUEST_URI'] ) ) : '';

    if ( $user_id || empty( $_GET['member_key'] ) || ( empty( $_GET['feed'] ) && false === strpos( $uri, '/feed' ) ) ) {
        return $user_id;
    }

    $key   = sanitize_text_field( wp_unslash( $_GET['member_key'] ) );
    $users = get_users( array( 'meta_key' => 'wpide_feed_key', 'meta_value' => $key, 'fields' => 'ID', 'number' => 1 ) );

    if ( $users && ! user_can( (int) $users[0], 'edit_posts' ) ) {
        add_action( 'template_redirect', function () {
            if ( ! is_feed() ) {
                wp_die( 'This key only works for feeds.', 'Forbidden', array( 'response' => 403 ) );
            }
        }, 0 );
        return (int) $users[0];
    }

    return $user_id;
}, 30 );

$wpide_feed_profile = function ( $user ) use ( $wpide_feed_key ) {
    if ( get_current_user_id() !== $user->ID || user_can( $user, 'edit_posts' ) ) {
        return;
    }

    $url = add_query_arg( 'member_key', $wpide_feed_key( $user->ID ), get_feed_link() );
