add_shortcode( 'wpide_ld_best_score', function ( $atts ) {
    $atts    = shortcode_atts( array( 'quiz_id' => 0 ), $atts, 'wpide_ld_best_score' );
    $user_id = get_current_user_id();
    $quiz_id = $atts['quiz_id'] ? absint( $atts['quiz_id'] ) : ( 'sfwd-quiz' === get_post_type() ? get_the_ID() : 0 );

    if ( ! $user_id || ! $quiz_id ) {
        return '';
    }

    $best   = null;
    $passed = false;

    foreach ( (array) get_user_meta( $user_id, '_sfwd-quizzes', true ) as $attempt ) {
        if ( ! is_array( $attempt ) || (int) ( $attempt['quiz'] ?? 0 ) !== $quiz_id ) {
            continue;
        }

        $best   = max( (float) $best, (float) ( $attempt['percentage'] ?? 0 ) );
        $passed = $passed || ! empty( $attempt['pass'] );
    }

    if ( null === $best ) {
        return '<span class="wpide-ld-score">Not attempted yet</span>';
    }

    return '<span class="wpide-ld-score">' . esc_html( sprintf( 'Best score: %s%% (%s)', round( $best ), $passed ? 'passed' : 'not passed yet' ) ) . '</span>';
} );

