            sprintf( '%s completed %s', $data['user']->display_name, get_the_title( $data['course'] ) ),
            sprintf( "Hi %s,\n\n%s from your group has completed \"%s\".", $leader->display_name, $data['user']->display_name, get_the_title( $data['course'] ) )
        );
