add_action( 'template_redirect', function () {
    if ( empty( $_POST['wpide_complete_nonce'] ) || ! is_user_logged_in() ) {
        return;
    }

    $post_id = isset( $_POST['wpide_lesson'] ) ? absint( $_POST['wpide_lesson'] ) : 0;

    if ( ! $post_id || ! wp_verify_nonce( sanitize_key( $_POST['wpide_complete_nonce'] ), 'wpide_complete_' . $post_id ) || 'publish' !== get_post_status( $post_id ) ) {
        return;
    }

    $done = array_map( 'intval', (array) get_user_meta( get_current_user_id(), 'wpide_completed_lessons', true ) );

    if ( in_array( $post_id, $done, true ) ) {
        $done = array_diff( $done, array( $post_id ) );
    } else {
        $done[] = $post_id;
    }

    update_user_meta( get_current_user_id(), 'wpide_completed_lessons', array_values( array_unique( $done ) ) );

    wp_safe_redirect( get_permalink( $post_id ) );
    exit;
} );

add_shortcode( 'wpide_mark_complete', function () {
    $post_id = get_the_ID();

    if ( ! $post_id ) {
        return '';
