    if ( ! is_user_logged_in() ) {
        return '<p class="wpide-complete"><a href="' . esc_url( wp_login_url( get_permalink() ) ) . '">Log in</a> to track your progress.</p>';
    }

    $done = in_array( $post_id, array_map( 'intval', (array) get_user_meta( get_current_user_id(), 'wpide_completed_lessons', true ) ), true );

    return '<form method="post" class="wpide-complete' . ( $done ? ' is-done' : '' ) . '">'
        . wp_nonce_field( 'wpide_complete_' . $post_id, 'wpide_complete_nonce', true, false )
        . '<input type="hidden" name="wpide_lesson" value="' . (int) $post_id . '">'
        . '<button type="submit" aria-pressed="' . ( $done ? 'true' : 'false' ) . '">' . ( $done ? '&#10003; Completed (undo)' : 'Mark as complete' ) . '</button></form>';
} );

add_shortcode( 'wpide_series_progress', function ( $atts ) {
    $atts = shortcode_atts( array( 'category' => '', 'list' => 'yes' ), $atts, 'wpide_series_progress' );

    if ( '' === $atts['category'] ) {
        return '';
    }

    $lessons = get_posts( array(
        'category_name' => sanitize_title( $atts['category'] ),
        'numberposts'   => 100,
        'orderby'       => 'date',
        'order'         => 'ASC',
        'fields'        => 'ids',
        'no_found_rows' => true,
    ) );

    if ( ! $lessons ) {
        return '';
    }

    $done    = is_user_logged_in() ? array_map( 'intval', (array) get_user_meta( get_current_user_id(), 'wpide_completed_lessons', true ) ) : array();
    $count   = count( array_intersect( $lessons, $done ) );
    $percent = (int) round( $count / count( $lessons ) * 100 );

    $html = sprintf(
        '<div class="wpide-series"><div role="progressbar" aria-valuenow="%1$d" aria-valuemin="0" aria-valuemax="100" aria-label="Series progress" style="height:10px;border-radius:5px;background:rgba(127,127,127,.25);overflow:hidden"><div style="width:%1$d%%;height:100%%;background:currentColor"></div></div><p style="margin:.4em 0">%2$s</p>',
        $percent,
        esc_html( sprintf( '%1$d of %2$d lessons complete', $count, count( $lessons ) ) )
    );

    if ( 'yes' === $atts['list'] ) {
        $html .= '<ol class="wpide-series__list">';
        foreach ( $lessons as $id ) {
            $is_done = in_array( $id, $done, true );
            $html   .= '<li' . ( $is_done ? ' class="is-done"' : '' ) . '><a href="' . esc_url( get_permalink( $id ) ) . '">' . esc_html( get_the_title( $id ) ) . '</a>' . ( $is_done ? ' <span aria-label="completed">&#10003;</span>' : '' ) . '</li>';
        }
        $html .= '</ol>';
    }

    return $html . '</div>';
} );

// Category slugs that hold lesson series.
$wpide_course_categories = array( 'course-1' );

add_filter( 'the_content', function ( $content ) use ( $wpide_course_categories ) {
    if ( ! is_singular( 'post' ) || ! in_the_loop() || ! is_main_query() || ! has_category( $wpide_course_categories ) ) {
        return $content;
    }

    $prev = get_adjacent_post( true, '', true, 'category' );
    $next = get_adjacent_post( true, '', false, 'category' );

    if ( ! $prev && ! $next ) {
        return $content;
    }

    $nav = '<nav class="wpide-lesson-nav" aria-label="Lesson navigation" style="display:flex;flex-wrap:wrap;justify-content:space-between;gap:1em;margin-top:2em">';
    $nav .= $prev ? '<a rel="prev" href="' . esc_url( get_permalink( $prev ) ) . '">&larr; ' . esc_html( get_the_title( $prev ) ) . '</a>' : '<span></span>';
    $nav .= $next ? '<a rel="next" href="' . esc_url( get_permalink( $next ) ) . '">' . esc_html( get_the_title( $next ) ) . ' &rarr;</a>' : '';

    return $content . $nav . '</nav>';
} );

