// Members registered fewer than this many days ago cannot post links.
$wpide_bp_link_days = 7;

add_action( 'bp_activity_before_save', function ( $activity ) use ( $wpide_bp_link_days ) {
    if ( empty( $activity->user_id ) || empty( $activity->content ) || user_can( $activity->user_id, 'bp_moderate' ) ) {
        return;
    }

    $user = get_userdata( $activity->user_id );

    if ( ! $user || time() - strtotime( $user->user_registered . ' UTC' ) > $wpide_bp_link_days * DAY_IN_SECONDS ) {
        return;
    }

    $content = preg_replace( '#<a\b[^>]*>(.*?)</a>#is', '$1', $activity->content );
    $content = preg_replace( '#\bhttps?://#i', '', $content );
    $activity->content = preg_replace( '#\bwww\.#i', 'www ', $content );
} );

