// Words or phrases that mark an update as spam.
$wpide_bp_blocked_words = array( 'casino', 'free followers', 'crypto giveaway' );

add_action( 'bp_activity_before_save', function ( $activity ) use ( $wpide_bp_blocked_words ) {
    if ( empty( $activity->content ) || ! empty( $activity->is_spam ) || user_can( (int) $activity->user_id, 'bp_moderate' ) ) {
        return;
    }

    $text = wp_strip_all_tags( $activity->content );

    foreach ( $wpide_bp_blocked_words as $word ) {
        if ( preg_match( '/\b' . preg_quote( $word, '/' ) . '\b/iu', $text ) ) {
            $activity->is_spam = 1;
            return;
        }
    }
} );

