// Hold posts until the member is this many days old or has this many approved replies.
$wpide_bbp_trust_days    = 3;
$wpide_bbp_trust_replies = 2;

$wpide_bbp_hold = function ( $data ) use ( $wpide_bbp_trust_days, $wpide_bbp_trust_replies ) {
    $author = isset( $data['post_author'] ) ? (int) $data['post_author'] : 0;

    if ( ! $author || user_can( $author, 'moderate' ) ) {
        return $data;
    }

    $user = get_userdata( $author );

    if ( ! $user || time() - strtotime( $user->user_registered . ' UTC' ) > $wpide_bbp_trust_days * DAY_IN_SECONDS ) {
        return $data;
    }

    if ( (int) bbp_get_user_reply_count( $author, true ) >= $wpide_bbp_trust_replies ) {
        return $data;
    }

    $data['post_status'] = bbp_get_pending_status_id();

    return $data;
};

add_filter( 'bbp_new_topic_pre_insert', $wpide_bbp_hold );
