$wpide_bbp_link_days = 7;

$wpide_bbp_check_links = function ( $content ) use ( $wpide_bbp_link_days ) {
    $user = wp_get_current_user();

    if ( ! $user->exists() || current_user_can( 'moderate' ) ) {
        return $content;
    }

    $is_new = time() - strtotime( $user->user_registered . ' UTC' ) < $wpide_bbp_link_days * DAY_IN_SECONDS;

    if ( $is_new && preg_match( '#(https?://|www\.|<a\s)#i', $content ) ) {
        bbp_add_error( 'wpide_bbp_links', sprintf( '<strong>Error:</strong> New members can post links after %d days. Please remove the link and try again.', $wpide_bbp_link_days ) );
    }

    return $content;
};

