// Words or phrases to block.
$wpide_bbp_blocked = array( 'casino', 'cheap pills', 'crypto giveaway' );

$wpide_bbp_scan = function ( $text ) use ( $wpide_bbp_blocked ) {
    if ( current_user_can( 'moderate' ) ) {
        return $text;
    }

    $plain = wp_strip_all_tags( (string) $text );

    foreach ( $wpide_bbp_blocked as $word ) {
        if ( preg_match( '/\b' . preg_quote( $word, '/' ) . '\b/iu', $plain ) ) {
            bbp_add_error( 'wpide_bbp_blocked', '<strong>Error:</strong> Your post contains words that are not allowed in these forums.' );
            break;
        }
    }

    return $text;
};

