// Forum ID => roles allowed in it.
$wpide_bbp_forum_roles = array(
    123 => array( 'editor', 'administrator' ),
);

add_action( 'template_redirect', function () use ( $wpide_bbp_forum_roles ) {
    if ( ! is_bbpress() || current_user_can( 'keep_gate' ) ) {
        return;
    }

    if ( bbp_is_single_topic() ) {
        $forum_id = (int) bbp_get_topic_forum_id( bbp_get_topic_id() );
    } elseif ( bbp_is_single_forum() ) {
        $forum_id = (int) bbp_get_forum_id();
    } else {
        return;
    }

    // Check the forum and its parent forums.
    $chain = array_merge( array( $forum_id ), array_map( 'intval', get_post_ancestors( $forum_id ) ) );

    foreach ( $chain as $id ) {
        if ( empty( $wpide_bbp_forum_roles[ $id ] ) ) {
            continue;
        }

        if ( ! is_user_logged_in() ) {
            wp_safe_redirect( wp_login_url( get_permalink( $id ) ) );
            exit;
        }

        if ( ! array_intersect( $wpide_bbp_forum_roles[ $id ], (array) wp_get_current_user()->roles ) ) {
            wp_safe_redirect( bbp_get_forums_url() );
            exit;
        }
    }
} );

