add_filter( 'wp_nav_menu_objects', function ( $items ) {
    $member  = is_user_logged_in() ? new MeprUser( get_current_user_id() ) : null;
    $removed = array();

    foreach ( $items as $key => $item ) {
        $wanted = array();

        foreach ( (array) $item->classes as $class ) {
            if ( preg_match( '/^wpide-mepr-(\d+)$/', $class, $m ) ) {
                $wanted[] = (int) $m[1];
            }
        }

        $hide = in_array( (int) $item->menu_item_parent, $removed, true );

        if ( $wanted && ! current_user_can( 'manage_options' ) ) {
            $allowed = false;

            foreach ( $wanted as $membership_id ) {
                if ( $member && $member->is_already_subscribed_to( $membership_id ) ) {
                    $allowed = true;
                    break;
                }
            }

            $hide = $hide || ! $allowed;
        }

        if ( $hide ) {
            $removed[] = (int) $item->ID;
            unset( $items[ $key ] );
        }
    }

    return $items;
} );

