add_filter( 'wp_nav_menu_objects', function ( $items ) {
    $removed = array();

    foreach ( $items as $key => $item ) {
        $wanted = array();

        foreach ( (array) $item->classes as $class ) {
            if ( 'wpide-level-any' === $class ) {
                $wanted[] = 'any';
            } elseif ( preg_match( '/^wpide-level-(\d+)$/', $class, $m ) ) {
                $wanted[] = (int) $m[1];
            }
        }

        $hide = in_array( (int) $item->menu_item_parent, $removed, true );

        if ( $wanted && ! current_user_can( 'manage_options' ) ) {
            $levels = in_array( 'any', $wanted, true ) ? null : array_filter( $wanted, 'is_int' );
            $hide   = $hide || ! pmpro_hasMembershipLevel( $levels );
        }

        if ( $hide ) {
            $removed[] = (int) $item->ID;
            unset( $items[ $key ] );
        }
    }

    return $items;
} );

