    printf(
        '<div class="wpide-pmpro-renew" role="status" style="padding:.75em 1em;text-align:center;background:#fff4ce;color:#3c2f00">%1$s <a href="%2$s" style="color:inherit;font-weight:600">Renew now</a></div>',
        esc_html( sprintf( 'Your %1$s membership ends on %2$s.', $level->name, wp_date( get_option( 'date_format' ), (int) $level->enddate ) ) ),
        esc_url( pmpro_url( 'checkout', '?level=' . (int) $level->id ) )
