add_filter( 'wpseo_schema_person', function ( $data ) {
    if ( ! is_array( $data ) || empty( $data['@id'] ) ) {
        return $data;
    }

    // Find the user this Person piece describes: the post author or the author archive.
    $user_id = 0;

    if ( is_author() ) {
        $user_id = get_queried_object_id();
    } elseif ( is_singular() ) {
        $user_id = (int) get_post_field( 'post_author', get_queried_object_id() );
    }

    if ( ! $user_id ) {
        return $data;
    }

    $job = get_the_author_meta( 'wpide_job_title', $user_id );
    $knows = array_filter( array_map( 'trim', explode( ',', (string) get_the_author_meta( 'wpide_knows_about', $user_id ) ) ) );

    if ( $job ) {
        $data['jobTitle'] = $job;
    }

    if ( $knows ) {
        $data['knowsAbout'] = array_values( $knows );
    }

    return $data;
} );

