add_filter( 'wpseo_breadcrumb_links', function ( $links ) {
    $blog_id = (int) get_option( 'page_for_posts' );

    if ( ! $blog_id || ! is_array( $links ) || ! ( is_singular( 'post' ) || is_category() || is_tag() || is_date() ) ) {
        return $links;
    }

    foreach ( $links as $link ) {
        if ( isset( $link['id'] ) && (int) $link['id'] === $blog_id ) {
            return $links;
        }
    }

    array_splice( $links, 1, 0, array( array( 'url' => get_permalink( $blog_id ), 'text' => get_the_title( $blog_id ), 'id' => $blog_id ) ) );

    return $links;
} );

