// Entries not modified for this many years are dropped.
$wpide_aioseo_max_age = 3;

add_filter( 'aioseo_sitemap_posts', function ( $entries, $post_type ) use ( $wpide_aioseo_max_age ) {
    if ( 'post' !== $post_type || ! is_array( $entries ) ) {
        return $entries;
    }

    $cutoff = strtotime( '-' . absint( $wpide_aioseo_max_age ) . ' years' );

    return array_values( array_filter( $entries, function ( $entry ) use ( $cutoff ) {
        $time = isset( $entry['lastmod'] ) ? strtotime( (string) $entry['lastmod'] ) : false;

        return ! $time || $time >= $cutoff;
    } ) );
}, 10, 2 );

// Maximum description length.
$wpide_aioseo_desc_length = 155;

add_filter( 'aioseo_description', function ( $description ) use ( $wpide_aioseo_desc_length ) {
    if ( '' !== trim( (string) $description ) || ! is_singular() ) {
        return $description;
    }

    $post = get_queried_object();

    if ( ! $post instanceof WP_Post ) {
        return $description;
    }

    $text = has_excerpt( $post ) ? $post->post_excerpt : strip_shortcodes( $post->post_content );
    $text = trim( preg_replace( '/\s+/', ' ', wp_strip_all_tags( $text ) ) );

    if ( mb_strlen( $text ) > $wpide_aioseo_desc_length ) {
        $text = rtrim( mb_substr( $text, 0, $wpide_aioseo_desc_length - 1 ), " ,.;:-" ) . '…';
    }

    return $text;
} );

