add_shortcode( 'acf_option', function ( $atts ) {
    $atts = shortcode_atts( array( 'name' => '', 'default' => '' ), $atts, 'acf_option' );
    $name = sanitize_key( $atts['name'] );

    if ( '' === $name || ! function_exists( 'get_field' ) ) {
        return '';
    }

    $value = get_field( $name, 'option' );

    if ( is_array( $value ) ) {
        $value = isset( $value['label'] ) ? $value['label'] : implode( ', ', array_filter( $value, 'is_scalar' ) );
    }

    if ( is_bool( $value ) ) {
        $value = $value ? 'Yes' : 'No';
    }

    return esc_html( '' === (string) $value ? $atts['default'] : (string) $value );
