add_shortcode( 'field_value', function ( $atts ) {
    $atts    = shortcode_atts( array( 'name' => '', 'post_id' => 0, 'size' => 'medium', 'sep' => ', ' ), $atts, 'field_value' );
    $name    = sanitize_key( $atts['name'] );
    $post_id = $atts['post_id'] ? absint( $atts['post_id'] ) : get_the_ID();

    if ( '' === $name || ! $post_id || ! function_exists( 'get_field' ) || ! is_post_publicly_viewable( $post_id ) ) {
        return '';
    }

    $value = get_field( $name, $post_id );

    $render = function ( $v ) use ( $atts, &$render ) {
        if ( $v instanceof WP_Post ) {
            return '<a href="' . esc_url( get_permalink( $v ) ) . '">' . esc_html( get_the_title( $v ) ) . '</a>';
        }

        if ( $v instanceof WP_Term ) {
            return '<a href="' . esc_url( get_term_link( $v ) ) . '">' . esc_html( $v->name ) . '</a>';
        }

        if ( is_array( $v ) ) {
            if ( isset( $v['ID'], $v['url'] ) && isset( $v['mime_type'] ) && 0 === strpos( $v['mime_type'], 'image/' ) ) {
                return wp_get_attachment_image( (int) $v['ID'], sanitize_key( $atts['size'] ) );
            }

            if ( isset( $v['url'], $v['title'] ) ) {
                $target = ! empty( $v['target'] ) ? ' target="_blank" rel="noopener"' : '';

                return '<a href="' . esc_url( $v['url'] ) . '"' . $target . '>' . esc_html( $v['title'] ? $v['title'] : $v['url'] ) . '</a>';
            }

            if ( isset( $v['label'] ) ) {
                return esc_html( $v['label'] );
            }

            return implode( esc_html( $atts['sep'] ), array_map( $render, $v ) );
        }

        if ( is_bool( $v ) ) {
            return $v ? 'Yes' : 'No';
        }

        return esc_html( (string) $v );
    };

    return null === $value || '' === $value || false === $value ? '' : '<span class="field-' . esc_attr( $name ) . '">' . $render( $value ) . '</span>';
} );

add_shortcode( 'acf_image', function ( $atts ) {
    $atts    = shortcode_atts( array( 'name' => '', 'size' => 'large', 'post_id' => 0, 'class' => '' ), $atts, 'acf_image' );
    $post_id = $atts['post_id'] ? absint( $atts['post_id'] ) : get_the_ID();

    if ( ! $post_id || ! function_exists( 'get_field' ) || ! is_post_publicly_viewable( $post_id ) ) {
        return '';
    }

    $value = get_field( sanitize_key( $atts['name'] ), $post_id, false ); // Raw value: the attachment ID.
    $id    = is_array( $value ) ? (int) ( $value['ID'] ?? 0 ) : absint( $value );

    if ( ! $id ) {
        return '';
    }

    return wp_get_attachment_image( $id, sanitize_key( $atts['size'] ), false, array( 'class' => sanitize_html_class( $atts['class'] ) ) );
} );

add_shortcode( 'acf_list', function ( $atts ) {
    $atts    = shortcode_atts( array( 'name' => '', 'sub' => '', 'label' => '', 'post_id' => 0 ), $atts, 'acf_list' );
    $post_id = $atts['post_id'] ? absint( $atts['post_id'] ) : get_the_ID();

    if ( ! $post_id || ! function_exists( 'get_field' ) || ! is_post_publicly_viewable( $post_id ) ) {
        return '';
    }

    $rows = get_field( sanitize_key( $atts['name'] ), $post_id );

    if ( ! is_array( $rows ) || ! $rows ) {
        return '';
    }

    $sub   = sanitize_key( $atts['sub'] );
    $label = sanitize_key( $atts['label'] );
    $items = '';

    foreach ( $rows as $row ) {
        if ( ! is_array( $row ) || ! isset( $row[ $sub ] ) || ! is_scalar( $row[ $sub ] ) ) {
            continue;
        }

        $prefix = ( $label && isset( $row[ $label ] ) && is_scalar( $row[ $label ] ) ) ? '<strong>' . esc_html( $row[ $label ] ) . ':</strong> ' : '';
        $items .= '<li>' . $prefix . esc_html( $row[ $sub ] ) . '</li>';
    }

    return $items ? '<ul class="acf-list acf-list-' . esc_attr( sanitize_html_class( $atts['name'] ) ) . '">' . $items . '</ul>' : '';
} );

add_shortcode( 'acf_gallery', function ( $atts ) {
    $atts    = shortcode_atts( array( 'name' => 'gallery', 'columns' => 3, 'size' => 'medium_large', 'post_id' => 0 ), $atts, 'acf_gallery' );
    $post_id = $atts['post_id'] ? absint( $atts['post_id'] ) : get_the_ID();

    if ( ! $post_id || ! function_exists( 'get_field' ) || ! is_post_publicly_viewable( $post_id ) ) {
        return '';
    }

    $ids = get_field( sanitize_key( $atts['name'] ), $post_id, false ); // Raw value: attachment IDs.
    $ids = array_filter( array_map( 'absint', is_array( $ids ) ? $ids : explode( ',', (string) $ids ) ) );

    if ( ! $ids ) {
        return '';
    }

    $cols = min( 6, max( 1, absint( $atts['columns'] ) ) );
    $html = '<div class="acf-gallery-grid" style="display:grid;gap:12px;grid-template-columns:repeat(auto-fill,minmax(min(100%,' . (int) floor( 960 / $cols ) . 'px),1fr))">';

    foreach ( $ids as $id ) {
        $full = wp_get_attachment_image_url( $id, 'full' );

        if ( $full ) {
            $html .= '<a href="' . esc_url( $full ) . '">' . wp_get_attachment_image( $id, sanitize_key( $atts['size'] ), false, array( 'loading' => 'lazy', 'style' => 'width:100%;height:auto;display:block' ) ) . '</a>';
        }
    }

    return $html . '</div>';
} );

add_shortcode( 'acf_button', function ( $atts ) {
    $atts    = shortcode_atts( array( 'name' => 'cta', 'post_id' => 0 ), $atts, 'acf_button' );
    $post_id = $atts['post_id'] ? absint( $atts['post_id'] ) : get_the_ID();

