// Name of the phone field.
$wpide_acf_phone_field = 'phone';

add_filter( 'acf/validate_value/name=' . $wpide_acf_phone_field, function ( $valid, $value ) {
    if ( true !== $valid || '' === trim( (string) $value ) ) {
        return $valid;
    }

    $digits = preg_replace( '/\D/', '', (string) $value );

    if ( ! preg_match( '/^\+?[\d\s().-]+$/', (string) $value ) || strlen( $digits ) < 7 || strlen( $digits ) > 15 ) {
        return 'Enter a valid phone number, for example +1 555 010 0199.';
    }

    return $valid;
}, 10, 2 );

// End date field name, and the start date field's key.
$wpide_acf_end_field = 'end_date';
$wpide_acf_start_key = 'field_start_date';

add_filter( 'acf/validate_value/name=' . $wpide_acf_end_field, function ( $valid, $value ) use ( $wpide_acf_start_key ) {
    if ( true !== $valid || '' === (string) $value || empty( $_POST['acf'][ $wpide_acf_start_key ] ) ) { // phpcs:ignore WordPress.Security.NonceVerification -- ACF verifies its own nonce.
        return $valid;
    }

    $start = sanitize_text_field( wp_unslash( $_POST['acf'][ $wpide_acf_start_key ] ) ); // phpcs:ignore WordPress.Security.NonceVerification

    // ACF date and date-time pickers submit sortable values (Ymd or Y-m-d H:i:s).
    if ( strtotime( (string) $value ) < strtotime( $start ) ) {
        return 'The end date must be on or after the start date.';
    }

    return $valid;
}, 10, 2 );

// Field that must be unique, and the post type it belongs to.
$wpide_acf_unique_field = 'reference_code';
$wpide_acf_unique_type  = 'post';

add_filter( 'acf/validate_value/name=' . $wpide_acf_unique_field, function ( $valid, $value ) use ( $wpide_acf_unique_field, $wpide_acf_unique_type ) {
    if ( true !== $valid || '' === trim( (string) $value ) ) {
        return $valid;
    }

    $current = isset( $_POST['_acf_post_id'] ) ? absint( $_POST['_acf_post_id'] ) : 0; // phpcs:ignore WordPress.Security.NonceVerification -- ACF verifies its own nonce.

    $existing = get_posts( array(
        'post_type'      => $wpide_acf_unique_type,
        'post_status'    => array( 'publish', 'pending', 'draft', 'future', 'private' ),
        'meta_key'       => $wpide_acf_unique_field,
        'meta_value'     => sanitize_text_field( (string) $value ),
        'post__not_in'   => $current ? array( $current ) : array(),
        'fields'         => 'ids',
        'posts_per_page' => 1,
        'no_found_rows'  => true,
    ) );

    return $existing ? sprintf( 'This value is already used by "%s".', get_the_title( $existing[0] ) ) : $valid;
}, 10, 2 );

// Field name and maximum words.
$wpide_acf_words_field = 'summary';
$wpide_acf_words_max   = 60;

add_filter( 'acf/validate_value/name=' . $wpide_acf_words_field, function ( $valid, $value ) use ( $wpide_acf_words_max ) {
    if ( true !== $valid ) {
        return $valid;
    }

    $words = str_word_count( wp_strip_all_tags( (string) $value ) );

    if ( $words > $wpide_acf_words_max ) {
        return sprintf( 'Please keep this under %1$d words (currently %2$d).', $wpide_acf_words_max, $words );
    }

    return $valid;
}, 10, 2 );

// Field name and minimum size in pixels.
$wpide_acf_image_field = 'hero_image';
$wpide_acf_min_width   = 1600;
$wpide_acf_min_height  = 600;

add_filter( 'acf/upload_prefilter/name=' . $wpide_acf_image_field, function ( $errors, $file ) use ( $wpide_acf_min_width, $wpide_acf_min_height ) {
    $size = ! empty( $file['tmp_name'] ) ? wp_getimagesize( $file['tmp_name'] ) : false;

    if ( $size && ( $size[0] < $wpide_acf_min_width || $size[1] < $wpide_acf_min_height ) ) {
        $errors['min_dimensions'] = sprintf( 'Images must be at least %1$d × %2$d pixels; this one is %3$d × %4$d.', $wpide_acf_min_width, $wpide_acf_min_height, $size[0], $size[1] );
    }

    return $errors;
}, 10, 2 );

