// Sort with a LEFT JOIN so posts without a value stay in the list (at the end).
add_filter( 'posts_clauses', function ( $clauses, $query ) use ( $wpide_acf_col ) {
    global $wpdb;

    if ( ! is_admin() || ! $query->is_main_query() || 'acf_' . $wpide_acf_col['field'] !== $query->get( 'orderby' ) ) {
        return $clauses;
    }

    $order = 'DESC' === strtoupper( (string) $query->get( 'order' ) ) ? 'DESC' : 'ASC';
    $value = 'meta_value_num' === $wpide_acf_col['orderby'] ? 'CAST(wpide_acf_sort.meta_value AS DECIMAL(20,4))' : 'wpide_acf_sort.meta_value';

    $clauses['join']   .= $wpdb->prepare( " LEFT JOIN {$wpdb->postmeta} AS wpide_acf_sort ON ( wpide_acf_sort.post_id = {$wpdb->posts}.ID AND wpide_acf_sort.meta_key = %s )", $wpide_acf_col['field'] );
    $clauses['orderby'] = "( wpide_acf_sort.meta_value IS NULL OR wpide_acf_sort.meta_value = '' ) ASC, {$value} {$order}";

    return $clauses;
}, 10, 2 );

