// Name of the relationship field used on both sides.
$wpide_acf_two_way_field = 'related_items';

add_filter( 'acf/update_value/name=' . $wpide_acf_two_way_field, function ( $value, $post_id, $field ) {
    static $running = false;

    if ( $running || ! is_numeric( $post_id ) || ! function_exists( 'update_field' ) ) {
        return $value;
    }

    $running = true;
    $post_id = (int) $post_id;
    $new     = array_filter( array_map( 'intval', (array) $value ) );
    $old     = array_filter( array_map( 'intval', (array) get_post_meta( $post_id, $field['name'], true ) ) );

    // Add this post to newly linked posts.
    foreach ( array_diff( $new, $old ) as $target ) {
        $links = array_filter( array_map( 'intval', (array) get_post_meta( $target, $field['name'], true ) ) );

        if ( ! in_array( $post_id, $links, true ) ) {
            $links[] = $post_id;
            update_field( $field['key'], array_values( array_filter( $links ) ), $target );
        }
    }

    // Remove this post from posts that were unlinked.
    foreach ( array_diff( $old, $new ) as $target ) {
        $links = array_filter( array_map( 'intval', (array) get_post_meta( $target, $field['name'], true ) ) );
        update_field( $field['key'], array_values( array_diff( $links, array( $post_id ) ) ), $target );
    }

    $running = false;

    return $value;
}, 10, 3 );

