add_shortcode( 'acf_posts', function ( $atts ) {
    $atts = shortcode_atts( array( 'field' => '', 'value' => '', 'post_type' => 'post', 'limit' => 5 ), $atts, 'acf_posts' );
    $atts['field'] = sanitize_key( $atts['field'] );

    if ( '' === $atts['field'] || ! post_type_exists( $atts['post_type'] ) ) {
        return '';
    }

    $cache_key = 'wpide_acf_posts_' . md5( wp_json_encode( $atts ) . get_option( 'wpide_acf_posts_ver_' . $atts['post_type'], '1' ) );
    $ids       = get_transient( $cache_key );

    if ( false === $ids ) {
        $ids = get_posts( array(
            'post_type'      => $atts['post_type'],
            'posts_per_page' => min( 50, absint( $atts['limit'] ) ),
            'meta_key'       => $atts['field'],
            'meta_value'     => sanitize_text_field( $atts['value'] ),
            'fields'         => 'ids',
            'no_found_rows'  => true,
        ) );
        set_transient( $cache_key, $ids, HOUR_IN_SECONDS );
    }

    if ( ! $ids ) {
        return '';
    }

    $html = '<ul class="acf-posts">';

    foreach ( $ids as $id ) {
        $html .= '<li><a href="' . esc_url( get_permalink( $id ) ) . '">' . esc_html( get_the_title( $id ) ) . '</a></li>';
    }

    return $html . '</ul>';
} );

