add_action( 'acf/save_post', function ( $post_id ) use ( $wpide_acf_title_type, $wpide_acf_title_fields ) {
    if ( ! is_numeric( $post_id ) || get_post_type( $post_id ) !== $wpide_acf_title_type || ! function_exists( 'get_field' ) || wp_is_post_revision( $post_id ) ) {
        return;
    }

    $parts = array();

    foreach ( $wpide_acf_title_fields as $name ) {
        $value = get_field( $name, $post_id );

        if ( is_scalar( $value ) && '' !== trim( (string) $value ) ) {
            $parts[] = trim( (string) $value );
        }
    }

    $title = sanitize_text_field( implode( ' ', $parts ) );

    if ( '' === $title || get_the_title( $post_id ) === $title ) {
        return;
    }

    wp_update_post( array(
        'ID'         => (int) $post_id,
        'post_title' => $title,
        'post_name'  => wp_unique_post_slug( sanitize_title( $title ), (int) $post_id, get_post_status( $post_id ), $wpide_acf_title_type, 0 ),
    ) );
}, 20 );

