    $dir    = add_query_arg( array( 'api' => 1, 'destination' => $coords ), 'https://www.google.com/maps/dir/' );

    return '<div class="acf-map-embed"><iframe src="' . esc_url( $src ) . '" title="' . esc_attr( 'Map: ' . $label ) . '" loading="lazy" referrerpolicy="no-referrer-when-downgrade" style="width:100%;height:' . absint( $atts['height'] ) . 'px;border:0"></iframe>'
        . '<p><a href="' . esc_url( $dir ) . '" target="_blank" rel="noopener">Get directions</a> — ' . esc_html( $label ) . '</p></div>';
} );

add_action( 'init', function () {
    if ( ! function_exists( 'register_block_bindings_source' ) ) {
        return;
    }

    register_block_bindings_source( 'wpide/acf', array(
        'label'              => 'ACF field',
        'uses_context'       => array( 'postId', 'postType' ),
        'get_value_callback' => function ( $source_args, $block_instance, $attribute_name ) {
            $key     = isset( $source_args['key'] ) ? sanitize_key( $source_args['key'] ) : '';
            $post_id = isset( $block_instance->context['postId'] ) ? (int) $block_instance->context['postId'] : get_the_ID();

            if ( '' === $key || '_' === $key[0] || ! $post_id || ! function_exists( 'get_field' ) || ( ! is_post_publicly_viewable( $post_id ) && ! current_user_can( 'read_post', $post_id ) ) ) {
                return null;
            }

            $value = get_field( $key, $post_id );

            if ( is_array( $value ) ) {
                $value = $value['url'] ?? ( $value['label'] ?? '' );
            }

            if ( ! is_scalar( $value ) ) {
                return null;
            }

            return in_array( $attribute_name, array( 'url', 'href' ), true ) ? esc_url( (string) $value ) : esc_html( (string) $value );
        },
    ) );
} );

