add_shortcode( 'acf_faq', function ( $atts ) {
    $atts    = shortcode_atts( array( 'name' => 'faqs', 'question' => 'question', 'answer' => 'answer' ), $atts, 'acf_faq' );
    $post_id = get_the_ID();

    if ( ! $post_id || ! function_exists( 'get_field' ) ) {
        return '';
    }

    $rows = get_field( sanitize_key( $atts['name'] ), $post_id );

    if ( ! is_array( $rows ) || ! $rows ) {
        return '';
    }

    $html   = '<div class="acf-faq">';
    $schema = array( '@context' => 'https://schema.org', '@type' => 'FAQPage', 'mainEntity' => array() );

    foreach ( $rows as $row ) {
        $q = isset( $row[ $atts['question'] ] ) && is_string( $row[ $atts['question'] ] ) ? trim( $row[ $atts['question'] ] ) : '';
        $a = isset( $row[ $atts['answer'] ] ) && is_string( $row[ $atts['answer'] ] ) ? trim( $row[ $atts['answer'] ] ) : '';

        if ( '' === $q || '' === $a ) {
            continue;
        }

        $html .= '<details class="acf-faq-item"><summary>' . esc_html( $q ) . '</summary><div class="acf-faq-answer">' . wp_kses_post( wpautop( $a ) ) . '</div></details>';
        $schema['mainEntity'][] = array(
            '@type'          => 'Question',
            'name'           => wp_strip_all_tags( $q ),
            'acceptedAnswer' => array( '@type' => 'Answer', 'text' => wp_kses( $a, array( 'a' => array( 'href' => true ), 'strong' => array(), 'em' => array(), 'br' => array(), 'p' => array(), 'ul' => array(), 'ol' => array(), 'li' => array() ) ) ),
        );
    }

    if ( ! $schema['mainEntity'] ) {
        return '';
    }

    return $html . '</div><script type="application/ld+json">' . wp_json_encode( $schema, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_HEX_TAG ) . '</script>';
} );

// Image field used as the fallback.
$wpide_acf_thumb_field = 'hero_image';

add_filter( 'post_thumbnail_id', function ( $thumbnail_id, $post ) use ( $wpide_acf_thumb_field ) {
    if ( $thumbnail_id || ! $post instanceof WP_Post ) {
        return $thumbnail_id;
    }

    // Read the raw meta (the attachment ID) to avoid loading ACF on every thumbnail call.
    $id = absint( get_post_meta( $post->ID, $wpide_acf_thumb_field, true ) );

    return ( $id && wp_attachment_is_image( $id ) ) ? $id : $thumbnail_id;
}, 10, 2 );

