// Aspect ratio of the container.
$wpide_acf_embed_ratio = '16 / 9';

add_filter( 'acf/format_value/type=oembed', function ( $value ) use ( $wpide_acf_embed_ratio ) {
    if ( ! is_string( $value ) || false === strpos( $value, '<iframe' ) ) {
        return $value;
    }

    $value = preg_replace( '/<iframe(?![^>]*\sloading=)/', '<iframe loading="lazy"', $value );
    $value = preg_replace( '/\s(width|height)="\d+"/', '', $value );

    return '<div class="acf-embed" style="aspect-ratio:' . esc_attr( $wpide_acf_embed_ratio ) . ';width:100%">' . str_replace( '<iframe', '<iframe style="width:100%;height:100%;border:0"', $value ) . '</div>';
} );

