add_shortcode( 'job_details', function () use ( $wpide_box ) {
    $id = get_the_ID();

    if ( ! $id || 'job' !== get_post_type( $id ) ) {
        return '';
    }

    $get  = function ( $key ) use ( $id ) { return (string) get_post_meta( $id, '_' . $key, true ); };
    $rows = array();

    if ( $get( 'job_type' ) ) {
        $rows['Type'] = $wpide_box['fields']['job_type']['options'][ $get( 'job_type' ) ] ?? $get( 'job_type' );
    }

    $where = $get( 'job_remote' ) ? 'Remote' : '';
    $where = trim( $where . ( $get( 'job_city' ) ? ( $where ? ' / ' : '' ) . $get( 'job_city' ) : '' ) );

    if ( $where ) {
        $rows['Location'] = $where;
    }

    if ( $get( 'job_salary_min' ) ) {
        $rows['Salary'] = trim( number_format_i18n( (float) $get( 'job_salary_min' ) ) . ( $get( 'job_salary_max' ) ? ' – ' . number_format_i18n( (float) $get( 'job_salary_max' ) ) : '' ) . ' ' . $get( 'job_currency' ) ) . ' per ' . strtolower( $get( 'job_salary_unit' ) ? $get( 'job_salary_unit' ) : 'year' );
    }

    if ( $get( 'job_valid_through' ) ) {
        $rows['Apply by'] = wp_date( get_option( 'date_format' ), strtotime( $get( 'job_valid_through' ) . ' 12:00' ) );
    }

    $html = '';

    foreach ( $rows as $label => $value ) {
        $html .= '<dt>' . esc_html( $label ) . '</dt><dd>' . esc_html( $value ) . '</dd>';
    }

    $apply = $get( 'job_apply_url' ) ? '<p><a class="wp-block-button__link wp-element-button" href="' . esc_url( $get( 'job_apply_url' ) ) . '">Apply now</a></p>' : '';

    return ( $html ? '<dl class="job-details">' . $html . '</dl>' : '' ) . $apply;
} );

