    $id = get_the_ID();

    if ( ! $id || 'recipe' !== get_post_type( $id ) ) {
        return '';
    }

    $get   = function ( $key ) use ( $id ) { return (string) get_post_meta( $id, '_recipe_' . $key, true ); };
    $lines = function ( $text ) { return array_filter( array_map( 'trim', explode( "\n", $text ) ) ); };
    $facts = array_filter( array(
        'Prep'     => $get( 'prep' ) ? (int) $get( 'prep' ) . ' min' : '',
        'Cook'     => $get( 'cook' ) ? (int) $get( 'cook' ) . ' min' : '',
        'Serves'   => $get( 'servings' ),
        'Calories' => $get( 'calories' ),
    ) );

    $html = '<div class="recipe-card">';

    if ( $facts ) {
        $html .= '<ul class="recipe-facts">';
        foreach ( $facts as $label => $value ) {
            $html .= '<li><strong>' . esc_html( $label ) . ':</strong> ' . esc_html( $value ) . '</li>';
        }
        $html .= '</ul>';
    }

    if ( $lines( $get( 'ingredients' ) ) ) {
        $html .= '<h3>Ingredients</h3><ul class="recipe-ingredients"><li>' . implode( '</li><li>', array_map( 'esc_html', $lines( $get( 'ingredients' ) ) ) ) . '</li></ul>';
