    if ( $lines( $get( 'steps' ) ) ) {
        $html .= '<h3>Method</h3><ol class="recipe-steps"><li>' . implode( '</li><li>', array_map( 'esc_html', $lines( $get( 'steps' ) ) ) ) . '</li></ol>';
