// Sort with a LEFT JOIN so events without a date stay in the list.
add_filter( 'posts_clauses', function ( $clauses, $query ) {
    global $wpdb;

    if ( ! is_admin() || ! $query->is_main_query() || 'event' !== $query->get( 'post_type' ) || ! in_array( $query->get( 'orderby' ), array( '', 'event_start' ), true ) ) {
        return $clauses;
    }

    $order = 'ASC' === strtoupper( (string) $query->get( 'order' ) ) ? 'ASC' : 'DESC';

    $clauses['join']   .= $wpdb->prepare( " LEFT JOIN {$wpdb->postmeta} AS wpide_ev ON ( wpide_ev.post_id = {$wpdb->posts}.ID AND wpide_ev.meta_key = %s )", '_event_start' );
    $clauses['orderby'] = "wpide_ev.meta_value {$order}, {$wpdb->posts}.post_date DESC";

    return $clauses;
}, 10, 2 );

add_action( 'template_redirect', function () {
    if ( ! isset( $_GET['ical'] ) || ! is_singular( 'event' ) ) { // phpcs:ignore WordPress.Security.NonceVerification -- read-only download.
        return;
    }

    $post  = get_queried_object();
    $tz    = wp_timezone();
    $start = date_create_immutable( (string) get_post_meta( $post->ID, '_event_start', true ), $tz );

    if ( ! $start || ! get_post_meta( $post->ID, '_event_start', true ) ) {
        return;
    }

    $end_raw = (string) get_post_meta( $post->ID, '_event_end', true );
    $end     = $end_raw ? date_create_immutable( $end_raw, $tz ) : false;
    $end     = ( $end && $end > $start ) ? $end : $start->modify( '+1 hour' );
    $utc     = new DateTimeZone( 'UTC' );
    $text    = function ( $value ) {
        return addcslashes( str_replace( array( "\r\n", "\n" ), '\n', wp_strip_all_tags( (string) $value ) ), ',;\\' );
    };
    $where   = trim( get_post_meta( $post->ID, '_event_venue', true ) . ', ' . get_post_meta( $post->ID, '_event_address', true ), ', ' );

    $lines = array(
        'BEGIN:VCALENDAR',
        'VERSION:2.0',
        'PRODID:-//' . $text( get_bloginfo( 'name' ) ) . '//Events//EN',
        'CALSCALE:GREGORIAN',
        'BEGIN:VEVENT',
        'UID:event-' . $post->ID . '@' . wp_parse_url( home_url(), PHP_URL_HOST ),
        'DTSTAMP:' . gmdate( 'Ymd\THis\Z' ),
        'DTSTART:' . $start->setTimezone( $utc )->format( 'Ymd\THis\Z' ),
        'DTEND:' . $end->setTimezone( $utc )->format( 'Ymd\THis\Z' ),
        'SUMMARY:' . $text( get_the_title( $post ) ),
        'URL:' . esc_url_raw( get_permalink( $post ) ),
        'DESCRIPTION:' . $text( get_the_excerpt( $post ) ),
        'LOCATION:' . $text( $where ),
        'END:VEVENT',
        'END:VCALENDAR',
    );

    nocache_headers();
    header( 'Content-Type: text/calendar; charset=utf-8' );
    header( 'Content-Disposition: attachment; filename="' . sanitize_file_name( $post->post_name ) . '.ics"' );
    echo implode( "\r\n", $lines ) . "\r\n"; // phpcs:ignore WordPress.Security.EscapeOutput -- calendar format, escaped above.
    exit;
} );

