add_action( 'save_post', function ( $post_id, $post ) use ( $wpide_featured_types ) {
    if ( ! in_array( $post->post_type, $wpide_featured_types, true ) || ! isset( $_POST['wpide_featured_nonce'] ) || ! wp_verify_nonce( sanitize_key( $_POST['wpide_featured_nonce'] ), 'wpide_featured_save' ) ) {
        return;
    }

    if ( wp_is_post_autosave( $post_id ) || ! current_user_can( 'edit_post', $post_id ) ) {
        return;
    }

