add_filter( 'posts_clauses', function ( $clauses, $query ) use ( $wpide_featured_types ) {
    global $wpdb;

    if ( is_admin() || ! $query->is_main_query() || ! $query->is_post_type_archive( $wpide_featured_types ) ) {
        return $clauses;
    }

    // Join the flag once and sort flagged items first, keeping the existing order after that.
    $clauses['join']   .= $wpdb->prepare( " LEFT JOIN {$wpdb->postmeta} AS wpide_feat ON ( wpide_feat.post_id = {$wpdb->posts}.ID AND wpide_feat.meta_key = %s )", '_wpide_featured' );
    $clauses['orderby'] = "( wpide_feat.meta_value = '1' ) DESC" . ( $clauses['orderby'] ? ', ' . $clauses['orderby'] : '' );

    return $clauses;
}, 10, 2 );

add_shortcode( 'post_grid', function ( $atts ) {
    $atts = shortcode_atts( array( 'type' => 'post', 'limit' => 9, 'columns' => 3, 'taxonomy' => '', 'term' => '', 'orderby' => 'date' ), $atts, 'post_grid' );
    $type = sanitize_key( $atts['type'] );
    $obj  = get_post_type_object( $type );

    if ( ! $obj || ! $obj->public ) {
        return '';
    }

    $key  = 'wpide_grid_' . md5( wp_json_encode( $atts ) . get_option( 'wpide_grid_ver_' . $type, '1' ) );
    $html = get_transient( $key );

    if ( false !== $html ) {
        return $html;
    }

    $orderby = in_array( $atts['orderby'], array( 'date', 'title', 'menu_order' ), true ) ? $atts['orderby'] : 'date';
    $args    = array(
        'post_type'           => $type,
        'posts_per_page'      => min( 48, max( 1, absint( $atts['limit'] ) ) ),
        'orderby'             => $orderby,
        'order'               => 'date' === $orderby ? 'DESC' : 'ASC',
        'ignore_sticky_posts' => true,
        'no_found_rows'       => true,
    );

    if ( $atts['taxonomy'] && $atts['term'] && is_object_in_taxonomy( $type, $atts['taxonomy'] ) ) {
        $args['tax_query'] = array( array( 'taxonomy' => sanitize_key( $atts['taxonomy'] ), 'field' => 'slug', 'terms' => array_map( 'sanitize_title', explode( ',', $atts['term'] ) ) ) );
    }

    $posts = get_posts( $args );
    $min   = (int) floor( 1000 / min( 4, max( 1, absint( $atts['columns'] ) ) ) ) - 24;
    $html  = '';

    foreach ( $posts as $post ) {
        $html .= '<article class="post-grid-card">'
            . ( has_post_thumbnail( $post ) ? '<a href="' . esc_url( get_permalink( $post ) ) . '" tabindex="-1" aria-hidden="true">' . get_the_post_thumbnail( $post, 'medium_large', array( 'loading' => 'lazy', 'style' => 'width:100%;height:auto;aspect-ratio:3/2;object-fit:cover' ) ) . '</a>' : '' )
            . '<h3 class="post-grid-title"><a href="' . esc_url( get_permalink( $post ) ) . '">' . esc_html( get_the_title( $post ) ) . '</a></h3>'
            . '<p class="post-grid-excerpt">' . esc_html( wp_trim_words( get_the_excerpt( $post ), 24 ) ) . '</p></article>';
    }

    $html = $html ? '<div class="post-grid" style="display:grid;gap:24px;grid-template-columns:repeat(auto-fill,minmax(min(100%,' . $min . 'px),1fr))">' . $html . '</div>' : '';
    set_transient( $key, $html, DAY_IN_SECONDS );

    return $html;
} );

add_action( 'clean_post_cache', function ( $post_id, $post ) {
    if ( $post && ! wp_is_post_revision( $post ) ) {
