// Post types that get related items, how many, and the heading.
$wpide_related_types   = array( 'recipe', 'case_study', 'service' );
$wpide_related_count   = 3;
$wpide_related_heading = 'You may also like';

add_filter( 'the_content', function ( $content ) use ( $wpide_related_types, $wpide_related_count, $wpide_related_heading ) {
    if ( ! is_singular( $wpide_related_types ) || ! in_the_loop() || ! is_main_query() ) {
        return $content;
    }

    $post = get_post();
    $key  = 'wpide_related_' . $post->ID . '_' . get_option( 'wpide_related_ver_' . $post->post_type, '1' );
    $ids  = get_transient( $key );

    if ( false === $ids ) {
        $tax_query = array( 'relation' => 'OR' );

        foreach ( get_object_taxonomies( $post->post_type, 'objects' ) as $taxonomy ) {
            if ( ! $taxonomy->public ) {
                continue;
            }

            $terms = wp_get_object_terms( $post->ID, $taxonomy->name, array( 'fields' => 'ids' ) );

            if ( $terms && ! is_wp_error( $terms ) ) {
                $tax_query[] = array( 'taxonomy' => $taxonomy->name, 'terms' => $terms );
            }
        }

        $ids = count( $tax_query ) > 1 ? get_posts( array(
            'post_type'      => $post->post_type,
            'posts_per_page' => $wpide_related_count,
            'post__not_in'   => array( $post->ID ),
            'tax_query'      => $tax_query,
            'fields'         => 'ids',
            'no_found_rows'  => true,
        ) ) : array();

        set_transient( $key, $ids, DAY_IN_SECONDS );
    }

    if ( ! $ids ) {
        return $content;
    }

    $list = '';

    foreach ( $ids as $id ) {
        $list .= '<li><a href="' . esc_url( get_permalink( $id ) ) . '">' . esc_html( get_the_title( $id ) ) . '</a></li>';
    }

    return $content . '<nav class="related-items" aria-label="' . esc_attr( $wpide_related_heading ) . '"><h2>' . esc_html( $wpide_related_heading ) . '</h2><ul>' . $list . '</ul></nav>';
} );

