    'base'      => 'books',
    'fallback'  => 'general',
);

add_filter( 'register_post_type_args', function ( $args, $post_type ) use ( $wpide_term_url ) {
    if ( $wpide_term_url['post_type'] === $post_type ) {
        $args['rewrite']     = array( 'slug' => $wpide_term_url['base'] . '/%' . $wpide_term_url['taxonomy'] . '%', 'with_front' => false );
        $args['has_archive'] = $wpide_term_url['base'];
    }

    return $args;
}, 10, 2 );

add_filter( 'post_type_link', function ( $link, $post ) use ( $wpide_term_url ) {
    $tag = '%' . $wpide_term_url['taxonomy'] . '%';

    if ( $wpide_term_url['post_type'] !== $post->post_type || false === strpos( $link, $tag ) ) {
        return $link;
    }

    $terms = get_the_terms( $post, $wpide_term_url['taxonomy'] );
    $slug  = ( $terms && ! is_wp_error( $terms ) ) ? $terms[0]->slug : $wpide_term_url['fallback'];

    return str_replace( $tag, $slug, $link );
}, 10, 2 );

// Post type and its current slug.
$wpide_short_urls = array(
    'post_type' => 'service',
    'slug'      => 'services',
);

add_filter( 'post_type_link', function ( $link, $post ) use ( $wpide_short_urls ) {
    if ( $wpide_short_urls['post_type'] === $post->post_type && 'publish' === $post->post_status ) {
        $link = str_replace( '/' . trim( $wpide_short_urls['slug'], '/' ) . '/', '/', $link );
    }

    return $link;
}, 10, 2 );

add_action( 'pre_get_posts', function ( $query ) use ( $wpide_short_urls ) {
    if ( is_admin() || ! $query->is_main_query() ) {
        return;
    }

    // A plain /name/ request is parsed as a post name: also look for it in the custom post type.
    $vars = $query->query;
    unset( $vars['page'] );

    if ( 1 === count( $vars ) && ! empty( $vars['name'] ) ) {
        $query->set( 'post_type', array( 'post', 'page', $wpide_short_urls['post_type'] ) );
    }
} );

add_filter( 'archive_template_hierarchy', function ( $templates ) {
    if ( ! is_post_type_archive() || is_post_type_archive( 'post' ) ) {
        return $templates;
    }

    $pos = array_search( 'archive.php', $templates, true );
    array_splice( $templates, false === $pos ? count( $templates ) : $pos, 0, array( 'archive-custom.php' ) );

    return $templates;
} );

add_filter( 'single_template_hierarchy', function ( $templates ) {
    $type = get_post_type( get_queried_object_id() );

