// Post types only logged-in users may see.
$wpide_members_types = array( 'resource' );

add_action( 'template_redirect', function () use ( $wpide_members_types ) {
    if ( is_user_logged_in() || ! ( is_singular( $wpide_members_types ) || is_post_type_archive( $wpide_members_types ) ) ) {
        return;
    }

    $requested = home_url( add_query_arg( array() ) );
    wp_safe_redirect( wp_login_url( $requested ) );
    exit;
} );

foreach ( $wpide_members_types as $wpide_members_type ) {
    add_filter( "rest_{$wpide_members_type}_query", function ( $args ) {
        if ( ! is_user_logged_in() ) {
            $args['post__in'] = array( 0 );
        }

        return $args;
    } );
}

add_filter( 'rest_request_before_callbacks', function ( $response, $handler, $request ) use ( $wpide_members_types ) {
    if ( is_user_logged_in() || is_wp_error( $response ) ) {
        return $response;
    }

    foreach ( $wpide_members_types as $type ) {
        $object = get_post_type_object( $type );

        if ( $object && $object->show_in_rest && 0 === strpos( $request->get_route(), '/' . ( $object->rest_namespace ?: 'wp/v2' ) . '/' . ( $object->rest_base ?: $type ) . '/' ) ) {
            return new WP_Error( 'rest_forbidden', 'Please log in to view this content.', array( 'status' => 401 ) );
        }
    }

    return $response;
}, 10, 3 );

add_action( 'pre_get_posts', function ( $query ) use ( $wpide_members_types ) {
    // Keep these entries out of search results and feeds for guests.
    if ( is_admin() || is_user_logged_in() || ! ( $query->is_search() || $query->is_feed() ) || ! $query->is_main_query() ) {
        return;
    }

    $types = $query->get( 'post_type' );

    if ( $types && 'any' !== $types ) {
        $query->set( 'post_type', array_values( array_diff( (array) $types, $wpide_members_types ) ) );
    } else {
        $query->set( 'post_type', array_values( array_diff( get_post_types( array( 'exclude_from_search' => false ) ), $wpide_members_types ) ) );
    }
} );

// Post type, its capability names, and the roles that manage it.
$wpide_cpt_caps = array(
    'post_type' => 'event',
    'singular'  => 'event',
    'plural'    => 'events',
    'roles'     => array( 'administrator', 'editor', 'author' ),
);

add_filter( 'register_post_type_args', function ( $args, $post_type ) use ( $wpide_cpt_caps ) {
    if ( $wpide_cpt_caps['post_type'] === $post_type ) {
        $args['capability_type'] = array( $wpide_cpt_caps['singular'], $wpide_cpt_caps['plural'] );
        $args['map_meta_cap']    = true;
    }

    return $args;
}, 10, 2 );

add_filter( 'user_has_cap', function ( $allcaps, $caps, $args, $user ) use ( $wpide_cpt_caps ) {
    if ( ! $user instanceof WP_User || ! array_intersect( (array) $user->roles, $wpide_cpt_caps['roles'] ) ) {
        return $allcaps;
    }

    $object = get_post_type_object( $wpide_cpt_caps['post_type'] );

    if ( ! $object ) {
        return $allcaps;
    }

    // Grant every primitive capability of this post type (edit_events, publish_events, ...).
    foreach ( (array) $object->cap as $meta => $primitive ) {
        if ( ! in_array( $meta, array( 'edit_post', 'read_post', 'delete_post' ), true ) ) {
            $allcaps[ $primitive ] = true;
        }
    }

    return $allcaps;
}, 10, 4 );

