add_action( 'rest_api_init', function () {
    $types = get_post_types( array( 'show_in_rest' => true, 'public' => true ) );

    register_rest_field( array_values( $types ), 'term_names', array(
        'get_callback' => function ( $object ) {
            $names = array();

            foreach ( get_object_taxonomies( $object['type'] ?? '', 'objects' ) as $taxonomy ) {
                if ( ! $taxonomy->show_in_rest ) {
                    continue;
                }

                $terms = get_the_terms( (int) $object['id'], $taxonomy->name );
                $names[ $taxonomy->name ] = ( $terms && ! is_wp_error( $terms ) ) ? wp_list_pluck( $terms, 'name' ) : array();
            }

            return $names;
        },
        'schema'       => array( 'description' => 'Term names keyed by taxonomy.', 'type' => 'object', 'context' => array( 'view', 'edit' ), 'readonly' => true ),
    ) );
} );

