// Post type, currency and the custom fields holding product details.
$wpide_product_schema = array(
    'post_type'    => 'catalog_item',
    'currency'     => 'USD',
    'price'        => 'price',
    'sku'          => 'sku',
    'brand'        => 'brand',
    'availability' => 'availability', // in_stock, out_of_stock or preorder.
);

add_action( 'wp_head', function () use ( $wpide_product_schema ) {
    if ( ! is_singular( $wpide_product_schema['post_type'] ) ) {
        return;
    }

    $post = get_queried_object();

    if ( ! $post instanceof WP_Post ) {
        return;
    }

    $meta = function ( $field ) use ( $post, $wpide_product_schema ) {
        return trim( (string) get_post_meta( $post->ID, $wpide_product_schema[ $field ], true ) );
    };

    $data = array(
        '@context'    => 'https://schema.org',
        '@type'       => 'Product',
        'name'        => wp_strip_all_tags( get_the_title( $post ) ),
        'description' => wp_strip_all_tags( get_the_excerpt( $post ) ),
        'url'         => get_permalink( $post ),
        'image'       => get_the_post_thumbnail_url( $post, 'full' ),
        'sku'         => $meta( 'sku' ),
    );

    if ( $meta( 'brand' ) ) {
        $data['brand'] = array( '@type' => 'Brand', 'name' => $meta( 'brand' ) );
    }

    if ( is_numeric( $meta( 'price' ) ) ) {
        $map = array( 'out_of_stock' => 'OutOfStock', 'preorder' => 'PreOrder' );

        $data['offers'] = array(
            '@type'         => 'Offer',
            'price'         => (string) ( 0 + $meta( 'price' ) ),
            'priceCurrency' => $wpide_product_schema['currency'],
            'availability'  => 'https://schema.org/' . ( $map[ $meta( 'availability' ) ] ?? 'InStock' ),
            'url'           => get_permalink( $post ),
        );
    }

    echo '<script type="application/ld+json">' . wp_json_encode( array_filter( $data ), JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_HEX_TAG ) . "</script>\n";
} );

// Currency for ticket prices.
$wpide_event_currency = 'USD';

add_action( 'wp_head', function () use ( $wpide_event_currency ) {
    if ( ! is_singular( 'event' ) ) {
        return;
    }

    $post = get_queried_object();
    $get  = function ( $key ) use ( $post ) {
        return trim( (string) get_post_meta( $post->ID, '_event_' . $key, true ) );
    };

    $start = $get( 'start' ) ? date_create_immutable( $get( 'start' ), wp_timezone() ) : false;

    if ( ! $start ) {
        return;
    }

    $url   = get_permalink( $post );
    $place = array(
        '@type'   => 'Place',
        'name'    => $get( 'venue' ) ? $get( 'venue' ) : $get( 'address' ),
        'address' => $get( 'address' ),
    );
    $online = array( '@type' => 'VirtualLocation', 'url' => $get( 'tickets' ) ? $get( 'tickets' ) : $url );
    $mode   = $get( 'mode' ) ? $get( 'mode' ) : 'offline';
    $modes  = array( 'offline' => 'OfflineEventAttendanceMode', 'online' => 'OnlineEventAttendanceMode', 'mixed' => 'MixedEventAttendanceMode' );

    $data = array(
        '@context'            => 'https://schema.org',
        '@type'               => 'Event',
        'name'                => wp_strip_all_tags( get_the_title( $post ) ),
        'description'         => wp_strip_all_tags( get_the_excerpt( $post ) ),
        'url'                 => $url,
        'startDate'           => $start->format( DATE_W3C ),
        'eventStatus'         => 'https://schema.org/EventScheduled',
        'eventAttendanceMode' => 'https://schema.org/' . ( $modes[ $mode ] ?? $modes['offline'] ),
        'location'            => 'online' === $mode ? $online : ( 'mixed' === $mode ? array( $place, $online ) : $place ),
        'image'               => get_the_post_thumbnail_url( $post, 'full' ),
        'organizer'           => array( '@type' => 'Organization', 'name' => get_bloginfo( 'name' ), 'url' => home_url( '/' ) ),
    );

    $end = $get( 'end' ) ? date_create_immutable( $get( 'end' ), wp_timezone() ) : false;

    if ( $end && $end > $start ) {
        $data['endDate'] = $end->format( DATE_W3C );
    }

    if ( is_numeric( $get( 'price' ) ) ) {
        $data['offers'] = array(
            '@type'         => 'Offer',
            'price'         => (string) ( 0 + $get( 'price' ) ),
            'priceCurrency' => $wpide_event_currency,
            'url'           => $get( 'tickets' ) ? $get( 'tickets' ) : $url,
            'availability'  => 'https://schema.org/InStock',
        );
    }

    echo '<script type="application/ld+json">' . wp_json_encode( array_filter( $data ), JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_HEX_TAG ) . "</script>\n";
} );

add_action( 'wp_head', function () {
    if ( ! is_singular( 'recipe' ) ) {
        return;
    }

    $post  = get_queried_object();
    $get   = function ( $key ) use ( $post ) {
        return trim( (string) get_post_meta( $post->ID, '_recipe_' . $key, true ) );
    };
    $lines = function ( $text ) {
        return array_values( array_filter( array_map( 'trim', explode( "\n", $text ) ) ) );
    };
    $terms = function ( $taxonomy ) use ( $post ) {
        $list = taxonomy_exists( $taxonomy ) ? get_the_terms( $post, $taxonomy ) : false;

        return ( $list && ! is_wp_error( $list ) ) ? implode( ', ', wp_list_pluck( $list, 'name' ) ) : '';
    };

    $prep = absint( $get( 'prep' ) );
    $cook = absint( $get( 'cook' ) );

    $data = array(
        '@context'           => 'https://schema.org',
        '@type'              => 'Recipe',
        'name'               => wp_strip_all_tags( get_the_title( $post ) ),
        'description'        => wp_strip_all_tags( get_the_excerpt( $post ) ),
        'image'              => get_the_post_thumbnail_url( $post, 'full' ),
        'author'             => array( '@type' => 'Person', 'name' => get_the_author_meta( 'display_name', $post->post_author ) ),
        'datePublished'      => get_the_date( DATE_W3C, $post ),
        'prepTime'           => $prep ? 'PT' . $prep . 'M' : '',
        'cookTime'           => $cook ? 'PT' . $cook . 'M' : '',
        'totalTime'          => ( $prep + $cook ) ? 'PT' . ( $prep + $cook ) . 'M' : '',
        'recipeYield'        => $get( 'servings' ) ? $get( 'servings' ) . ' servings' : '',
        'recipeCuisine'      => $terms( 'cuisine' ),
        'recipeCategory'     => $terms( 'recipe_course' ),
        'recipeIngredient'   => $lines( $get( 'ingredients' ) ),
        'recipeInstructions' => array_map( function ( $step ) {
            return array( '@type' => 'HowToStep', 'text' => $step );
        }, $lines( $get( 'steps' ) ) ),
    );

    if ( $get( 'calories' ) ) {
        $data['nutrition'] = array( '@type' => 'NutritionInformation', 'calories' => absint( $get( 'calories' ) ) . ' calories' );
    }

    echo '<script type="application/ld+json">' . wp_json_encode( array_filter( $data ), JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_HEX_TAG ) . "</script>\n";
} );

