        $robots['noindex'] = true;
        $robots['follow']  = true;
    }

    return $robots;
} );

// Query parameters that make a page a duplicate (a trailing _ matches any name starting with it).
$wpide_noindex_params = array( 'orderby', 'order', 'sort', 'view', 'per_page', 'min_price', 'max_price', 'rating_filter', 'filter_', 'query_type_' );

add_filter( 'wp_robots', function ( $robots ) use ( $wpide_noindex_params ) {
    if ( empty( $_GET ) ) { // phpcs:ignore WordPress.Security.NonceVerification
        return $robots;
    }

    foreach ( array_keys( $_GET ) as $param ) { // phpcs:ignore WordPress.Security.NonceVerification
        foreach ( $wpide_noindex_params as $blocked ) {
            if ( $param === $blocked || ( '_' === substr( $blocked, -1 ) && 0 === strpos( (string) $param, $blocked ) ) ) {
                $robots['noindex'] = true;
                $robots['follow']  = true;

                return $robots;
            }
        }
    }

    return $robots;
} );

add_action( 'wp_head', function () {
    global $wp_query;

    if ( is_singular() || is_404() || ! ( is_home() || is_archive() || is_search() ) ) {
        return;
    }

    $paged = max( 1, (int) get_query_var( 'paged' ) );
    $max   = (int) $wp_query->max_num_pages;

    if ( $paged > 1 ) {
        echo '<link rel="prev" href="' . esc_url( get_pagenum_link( $paged - 1 ) ) . '">' . "\n";
    }

    if ( $paged < $max ) {
        echo '<link rel="next" href="' . esc_url( get_pagenum_link( $paged + 1 ) ) . '">' . "\n";
    }
} );

