// Phrase => URL, and the maximum number of automatic links per post.
$wpide_auto_links = array(
    'technical SEO'   => home_url( '/services/technical-seo/' ),
    'content audit'   => home_url( '/guides/content-audit/' ),
    'local business'  => home_url( '/local-seo/' ),
);
$wpide_auto_links_max = 5;

add_filter( 'the_content', function ( $content ) use ( $wpide_auto_links, $wpide_auto_links_max ) {
    if ( ! is_singular( 'post' ) || ! in_the_loop() || ! is_main_query() || ! $wpide_auto_links ) {
        return $content;
    }

    $current = untrailingslashit( get_permalink() );
    $parts   = preg_split( '/(<[^>]+>)/', $content, -1, PREG_SPLIT_DELIM_CAPTURE );
    $skip    = 0;
    $used    = array();
    $count   = 0;

    foreach ( $parts as $i => $part ) {
        if ( '' === $part ) {
            continue;
        }

        if ( '<' === $part[0] ) {
            // Track whether we are inside an element whose text must not be linked.
            if ( preg_match( '#^<(a|h[1-6]|code|pre|button|script|style|textarea|figcaption)\b#i', $part ) ) {
                $skip++;
            } elseif ( preg_match( '#^</(a|h[1-6]|code|pre|button|script|style|textarea|figcaption)>#i', $part ) ) {
                $skip = max( 0, $skip - 1 );
            }
            continue;
        }

        if ( $skip || $count >= $wpide_auto_links_max ) {
            continue;
        }

        foreach ( $wpide_auto_links as $phrase => $url ) {
            if ( isset( $used[ $phrase ] ) || $count >= $wpide_auto_links_max || untrailingslashit( $url ) === $current ) {
                continue;
            }

            $pattern = '/(?<![\p{L}\p{N}])(' . preg_quote( $phrase, '/' ) . ')(?![\p{L}\p{N}])/iu';

            if ( preg_match( $pattern, $part ) ) {
                $part = preg_replace( $pattern, '<a href="' . esc_url( $url ) . '" class="auto-link">$1</a>', $part, 1 );
                $used[ $phrase ] = true;
                $count++;
            }
        }

        $parts[ $i ] = $part;
    }

    return implode( '', $parts );
}, 20 );

add_action( 'admin_menu', function () {
    add_management_page( 'Orphaned Content', 'Orphaned Content', 'edit_others_posts', 'wpide-orphans', function () {
        global $wpdb;

        if ( isset( $_POST['wpide_orphans_refresh'] ) && check_admin_referer( 'wpide_orphans_refresh' ) ) {
            delete_transient( 'wpide_orphans' );
        }

        $orphans = get_transient( 'wpide_orphans' );

        if ( false === $orphans ) {
            $rows   = $wpdb->get_results( "SELECT ID FROM {$wpdb->posts} WHERE post_status = 'publish' AND post_type IN ('post','page') ORDER BY post_date DESC LIMIT 3000" );
            $ids    = wp_list_pluck( $rows, 'ID' );
            $by_url = array();
            _prime_post_caches( $ids, false, false );

            foreach ( $ids as $id ) {
                $by_url[ untrailingslashit( (string) wp_parse_url( get_permalink( $id ), PHP_URL_PATH ) ) ] = (int) $id;
            }

            $linked = array();
            $front  = (int) get_option( 'page_on_front' );
            $host   = wp_parse_url( home_url(), PHP_URL_HOST );

            foreach ( array_chunk( $ids, 200 ) as $chunk ) {
                $contents = $wpdb->get_results( "SELECT ID, post_content FROM {$wpdb->posts} WHERE ID IN (" . implode( ',', array_map( 'intval', $chunk ) ) . ')' );

                foreach ( $contents as $row ) {
                    if ( ! preg_match_all( '#href=["\']([^"\'\#]+)#i', $row->post_content, $m ) ) {
                        continue;
                    }

                    foreach ( $m[1] as $href ) {
                        $parts = wp_parse_url( $href );

                        if ( ! empty( $parts['host'] ) && $parts['host'] !== $host ) {
                            continue;
                        }

                        parse_str( $parts['query'] ?? '', $query );
                        $target = isset( $query['p'] ) ? (int) $query['p'] : ( isset( $query['page_id'] ) ? (int) $query['page_id'] : ( $by_url[ untrailingslashit( $parts['path'] ?? '' ) ] ?? 0 ) );

                        if ( $target && $target !== (int) $row->ID ) {
                            $linked[ $target ] = true;
                        }
                    }
                }
            }

            $orphans = array_values( array_diff( array_map( 'intval', $ids ), array_keys( $linked ), array( $front ) ) );
            set_transient( 'wpide_orphans', $orphans, 12 * HOUR_IN_SECONDS );
        }

        echo '<div class="wrap"><h1>Orphaned Content</h1><p>' . esc_html( sprintf( '%d published posts and pages have no internal links pointing to them.', count( $orphans ) ) ) . '</p>';
        echo '<form method="post">';
        wp_nonce_field( 'wpide_orphans_refresh' );
        echo '<p><button class="button" name="wpide_orphans_refresh" value="1">Refresh</button></p></form>';

        if ( $orphans ) {
            echo '<table class="widefat striped"><thead><tr><th>Title</th><th>Type</th><th>Published</th></tr></thead><tbody>';

            foreach ( array_slice( $orphans, 0, 500 ) as $id ) {
                printf( '<tr><td><a href="%1$s">%2$s</a></td><td>%3$s</td><td>%4$s</td></tr>', esc_url( get_edit_post_link( $id ) ), esc_html( get_the_title( $id ) ), esc_html( get_post_type( $id ) ), esc_html( get_the_date( '', $id ) ) );
            }

            echo '</tbody></table>';
        }

        echo '</div>';
    } );
} );

add_action( 'enqueue_block_editor_assets', function () {
    wp_register_script( 'wpide-h1-warning', false, array( 'wp-data', 'wp-notices', 'wp-block-editor' ), '1.0', true );
    wp_enqueue_script( 'wpide-h1-warning' );
    wp_add_inline_script( 'wpide-h1-warning', <<<'JS'
( function ( wp ) {
    var id = 'wpide-h1-warning', last = null, timer = null;
    var hasH1 = function ( blocks ) {
        return blocks.some( function ( block ) {
            return ( block.name === 'core/heading' && block.attributes.level === 1 ) || ( block.innerBlocks && hasH1( block.innerBlocks ) );
        } );
    };
    wp.data.subscribe( function () {
        clearTimeout( timer );
        timer = setTimeout( function () {
            var editor = wp.data.select( 'core/block-editor' );
            var found = editor ? hasH1( editor.getBlocks() ) : false;
            if ( found === last ) {
                return;
            }
            last = found;
            if ( found ) {
                wp.data.dispatch( 'core/notices' ).createWarningNotice( 'This post contains an H1 heading. The title is already the H1, so use H2 for main sections.', { id: id, isDismissible: true } );
            } else {
                wp.data.dispatch( 'core/notices' ).removeNotice( id );
            }
        }, 400 );
    } );
} )( window.wp );
JS
    );
} );

