add_action( 'template_redirect', function () {
    if ( ! is_singular() || is_user_logged_in() || is_preview() || headers_sent() || post_password_required() ) {
        return;
    }

    $post     = get_queried_object();
    $modified = (int) get_post_modified_time( 'U', true, $post );

    // A new approved comment also counts as a change.
    if ( $post->comment_count > 0 ) {
        $latest = get_comments( array( 'post_id' => $post->ID, 'status' => 'approve', 'number' => 1, 'orderby' => 'comment_date_gmt', 'order' => 'DESC' ) );

        if ( $latest ) {
            $modified = max( $modified, (int) strtotime( $latest[0]->comment_date_gmt . ' UTC' ) );
        }
    }

    if ( ! $modified ) {
        return;
    }

    header( 'Last-Modified: ' . gmdate( 'D, d M Y H:i:s', $modified ) . ' GMT' );

    $since = isset( $_SERVER['HTTP_IF_MODIFIED_SINCE'] ) ? strtotime( sanitize_text_field( wp_unslash( $_SERVER['HTTP_IF_MODIFIED_SINCE'] ) ) ) : false;

    if ( $since && $since >= $modified ) {
        status_header( 304 );
        exit;
    }
}, 1 );

// Words removed from new slugs, and the maximum number of words kept.
$wpide_stop_words = array( 'a', 'an', 'and', 'are', 'as', 'at', 'be', 'by', 'for', 'from', 'how', 'in', 'into', 'is', 'it', 'of', 'on', 'or', 'our', 'the', 'this', 'that', 'to', 'what', 'when', 'why', 'with', 'you', 'your' );
$wpide_slug_max_words = 6;

add_filter( 'wp_insert_post_data', function ( $data, $postarr ) use ( $wpide_stop_words, $wpide_slug_max_words ) {
    if ( ! empty( $postarr['post_name'] ) || empty( $data['post_name'] ) || in_array( $data['post_status'], array( 'draft', 'auto-draft', 'pending', 'inherit', 'trash' ), true ) || 'attachment' === $data['post_type'] ) {
        return $data;
    }

    $words = explode( '-', $data['post_name'] );
    $kept  = array_values( array_diff( $words, $wpide_stop_words ) );

    if ( count( $kept ) < 2 ) {
        return $data;
    }

    $slug = implode( '-', array_slice( $kept, 0, $wpide_slug_max_words ) );

    if ( $slug !== $data['post_name'] ) {
        $data['post_name'] = wp_unique_post_slug( $slug, (int) ( $postarr['ID'] ?? 0 ), $data['post_status'], $data['post_type'], (int) $data['post_parent'] );
    }

    return $data;
}, 10, 2 );

