// Post type => meta keys that may be used as REST filters.
$wpide_rest_meta_filters = array(
    'post' => array( 'location', 'featured' ),
);

foreach ( $wpide_rest_meta_filters as $wpide_rest_type => $wpide_rest_keys ) {
    add_filter( "rest_{$wpide_rest_type}_query", function ( $args, $request ) use ( $wpide_rest_keys ) {
        $key   = $request->get_param( 'meta_key' );
        $value = $request->get_param( 'meta_value' );

        if ( is_string( $key ) && in_array( $key, $wpide_rest_keys, true ) && is_scalar( $value ) && '' !== (string) $value ) {
            $args['meta_query']   = isset( $args['meta_query'] ) ? (array) $args['meta_query'] : array();
            $args['meta_query'][] = array( 'key' => $key, 'value' => sanitize_text_field( (string) $value ) );
        }

        return $args;
    }, 10, 2 );

    add_filter( "rest_{$wpide_rest_type}_collection_params", function ( $params ) use ( $wpide_rest_keys ) {
        $params['meta_key']   = array( 'description' => 'Custom field to filter by.', 'type' => 'string', 'enum' => array_values( $wpide_rest_keys ) );
        $params['meta_value'] = array( 'description' => 'Value the custom field must have.', 'type' => 'string' );

        return $params;
    } );
}

add_action( 'wp_loaded', function () {
    $fingerprint = array();

    foreach ( get_post_types( array(), 'objects' ) as $type ) {
        if ( $type->rewrite ) {
            $fingerprint[] = $type->name . ':' . ( $type->rewrite['slug'] ?? '' ) . ':' . (string) $type->has_archive;
        }
    }

    foreach ( get_taxonomies( array(), 'objects' ) as $taxonomy ) {
        if ( $taxonomy->rewrite ) {
            $fingerprint[] = $taxonomy->name . ':' . ( $taxonomy->rewrite['slug'] ?? '' );
        }
    }

    sort( $fingerprint );
    $hash = md5( implode( '|', $fingerprint ) );

    if ( get_option( 'wpide_rewrite_fingerprint' ) !== $hash ) {
        flush_rewrite_rules( false );
        update_option( 'wpide_rewrite_fingerprint', $hash, true );
    }
}, 99 );

add_action( 'admin_menu', function () {
    add_management_page( 'Rewrite Rules', 'Rewrite Rules', 'manage_options', 'wpide-rewrite-rules', function () {
        $rules = (array) get_option( 'rewrite_rules' );
        $test  = isset( $_GET['wpide_path'] ) ? sanitize_text_field( wp_unslash( $_GET['wpide_path'] ) ) : ''; // phpcs:ignore WordPress.Security.NonceVerification -- read-only.
        $path  = trim( (string) wp_parse_url( $test, PHP_URL_PATH ), '/' );

        echo '<div class="wrap"><h1>Rewrite Rules</h1>';

        if ( ! get_option( 'permalink_structure' ) ) {
            echo '<div class="notice notice-warning"><p>Plain permalinks are active, so WordPress uses no rewrite rules.</p></div>';
        }

        echo '<form method="get"><input type="hidden" name="page" value="wpide-rewrite-rules"><label for="wpide-path"><strong>Test a path</strong></label> <input type="text" id="wpide-path" name="wpide_path" class="regular-text" value="' . esc_attr( $test ) . '" placeholder="/category/news/page/2/"> <button class="button">Test</button></form>';

        $matched = '';

        if ( '' !== $test ) {
            foreach ( $rules as $regex => $query ) {
                if ( preg_match( '#^' . str_replace( '#', '\#', $regex ) . '#', $path, $m ) || preg_match( '#^' . str_replace( '#', '\#', $regex ) . '#', urldecode( $path ), $m ) ) {
                    $matched  = $regex;
                    $resolved = preg_replace_callback( '/\$matches\[(\d+)\]/', function ( $x ) use ( $m ) {
                        return $m[ (int) $x[1] ] ?? '';
                    }, $query );
                    echo '<p>Matches <code>' . esc_html( $regex ) . '</code> → <code>' . esc_html( $resolved ) . '</code></p>';
                    break;
                }
            }

            if ( '' === $matched ) {
                echo '<p>No rule matches this path, so it would return a 404 unless a plugin handles it.</p>';
            }
        }

        echo '<p>' . esc_html( count( $rules ) ) . ' rules, in the order WordPress checks them.</p><table class="widefat striped"><thead><tr><th>Rule</th><th>Query</th></tr></thead><tbody>';

        foreach ( $rules as $regex => $query ) {
            printf( '<tr%1$s><td><code>%2$s</code></td><td><code>%3$s</code></td></tr>', $regex === $matched ? ' style="outline:2px solid #2271b1"' : '', esc_html( $regex ), esc_html( $query ) );
        }

        echo '</tbody></table></div>';
    } );
} );

