$wpide_cf7_trap_name = 'wpide_company_url'; // Name of the hidden trap field.

add_filter( 'wpcf7_form_elements', function ( $html ) use ( $wpide_cf7_trap_name ) {
    $field = sprintf(
        '<span class="wpide-cf7-trap" aria-hidden="true" style="position:absolute!important;left:-9999px!important;width:1px;height:1px;overflow:hidden;"><label>Leave this field empty <input type="text" name="%1$s" value="" tabindex="-1" autocomplete="off"></label></span>',
        esc_attr( $wpide_cf7_trap_name )
    );

    return $field . $html;
} );

add_filter( 'wpcf7_spam', function ( $spam, $submission = null ) use ( $wpide_cf7_trap_name ) {
    if ( $spam || empty( $_POST[ $wpide_cf7_trap_name ] ) ) {
        return $spam;
    }

    if ( $submission && method_exists( $submission, 'add_spam_log' ) ) {
        $submission->add_spam_log( array( 'agent' => 'wpide-honeypot', 'reason' => 'The hidden trap field was filled in.' ) );
    }

    return true;
}, 10, 2 );

$wpide_cf7_min_seconds = 4; // Minimum time between showing the form and submitting it.

add_filter( 'wpcf7_form_hidden_fields', function ( $fields ) {
    $time = (string) time();
    $fields['wpide_cf7_ts'] = $time . '.' . wp_hash( 'cf7-ts-' . $time );

    return $fields;
} );

add_filter( 'wpcf7_spam', function ( $spam, $submission = null ) use ( $wpide_cf7_min_seconds ) {
    if ( $spam ) {
        return $spam;
    }

    $stamp = isset( $_POST['wpide_cf7_ts'] ) ? sanitize_text_field( wp_unslash( $_POST['wpide_cf7_ts'] ) ) : '';
    $parts = explode( '.', $stamp, 2 );
    $valid = 2 === count( $parts ) && ctype_digit( $parts[0] ) && hash_equals( wp_hash( 'cf7-ts-' . $parts[0] ), $parts[1] );

    if ( $valid && time() - (int) $parts[0] >= $wpide_cf7_min_seconds ) {
        return false;
    }

    if ( $submission && method_exists( $submission, 'add_spam_log' ) ) {
        $submission->add_spam_log( array( 'agent' => 'wpide-time-trap', 'reason' => $valid ? 'Submitted too quickly.' : 'Missing or forged time stamp.' ) );
    }

    return true;
}, 10, 2 );

// Words and phrases that mark a submission as spam.
$wpide_cf7_blocked_words = array( 'seo services', 'backlinks', 'crypto', 'casino', 'guest post', 'rank your website', 'viagra' );

add_filter( 'wpcf7_spam', function ( $spam, $submission = null ) use ( $wpide_cf7_blocked_words ) {
    if ( $spam || ! $submission || ! $wpide_cf7_blocked_words ) {
        return $spam;
    }

    $text = '';
    foreach ( (array) $submission->get_posted_data() as $value ) {
        $text .= ' ' . ( is_array( $value ) ? implode( ' ', $value ) : (string) $value );
    }

    foreach ( $wpide_cf7_blocked_words as $word ) {
        if ( preg_match( '/\b' . preg_quote( $word, '/' ) . '\b/iu', $text ) ) {
            $submission->add_spam_log( array( 'agent' => 'wpide-blocked-words', 'reason' => sprintf( 'Contains "%s".', $word ) ) );
            return true;
        }
    }

    return false;
}, 10, 2 );

// Domains that may not be used in email fields.
$wpide_cf7_blocked_domains = array( 'mailinator.com', 'yopmail.com', 'tempmail.com', 'guerrillamail.com' );

$wpide_cf7_check_domain = function ( $result, $tag ) use ( $wpide_cf7_blocked_domains ) {
    $email  = isset( $_POST[ $tag->name ] ) ? strtolower( trim( sanitize_email( wp_unslash( $_POST[ $tag->name ] ) ) ) ) : '';
    $domain = substr( strrchr( $email, '@' ), 1 );

    if ( '' === (string) $domain ) {
        return $result;
    }

    foreach ( $wpide_cf7_blocked_domains as $blocked ) {
        if ( $domain === $blocked || substr( $domain, -strlen( '.' . $blocked ) ) === '.' . $blocked ) {
            $result->invalidate( $tag, 'Please use a different email address.' );
            break;
        }
    }

    return $result;
};

add_filter( 'wpcf7_validate_email', $wpide_cf7_check_domain, 20, 2 );
add_filter( 'wpcf7_validate_email*', $wpide_cf7_check_domain, 20, 2 );

$wpide_cf7_free_providers = array( 'gmail.com', 'googlemail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'live.com', 'aol.com', 'icloud.com', 'gmx.com', 'proton.me', 'protonmail.com', 'mail.com', 'yandex.com' );
$wpide_cf7_business_fields = array(); // Field names to check, e.g. array( 'work-email' ). Empty = all email fields.

$wpide_cf7_business_check = function ( $result, $tag ) use ( $wpide_cf7_free_providers, $wpide_cf7_business_fields ) {
    if ( $wpide_cf7_business_fields && ! in_array( $tag->name, $wpide_cf7_business_fields, true ) ) {
        return $result;
    }

    $email  = isset( $_POST[ $tag->name ] ) ? strtolower( sanitize_email( wp_unslash( $_POST[ $tag->name ] ) ) ) : '';
    $domain = (string) substr( strrchr( $email, '@' ), 1 );

    if ( $domain && in_array( $domain, $wpide_cf7_free_providers, true ) ) {
        $result->invalidate( $tag, 'Please use your work email address.' );
    }

    return $result;
};

add_filter( 'wpcf7_validate_email', $wpide_cf7_business_check, 20, 2 );
add_filter( 'wpcf7_validate_email*', $wpide_cf7_business_check, 20, 2 );

$wpide_cf7_max_links = 0; // Links allowed in a textarea field.

$wpide_cf7_link_check = function ( $result, $tag ) use ( $wpide_cf7_max_links ) {
    $text = isset( $_POST[ $tag->name ] ) ? (string) wp_unslash( $_POST[ $tag->name ] ) : '';

    if ( '' === $text ) {
        return $result;
    }

    $links = preg_match_all( '#(https?://|www\.|\[url|<a\s)#i', $text );

    if ( $links > $wpide_cf7_max_links ) {
        $result->invalidate( $tag, 0 === $wpide_cf7_max_links ? 'Please remove the links from your message.' : sprintf( 'Please include no more than %d link(s).', $wpide_cf7_max_links ) );
    }

    return $result;
};

add_filter( 'wpcf7_validate_textarea', $wpide_cf7_link_check, 20, 2 );
add_filter( 'wpcf7_validate_textarea*', $wpide_cf7_link_check, 20, 2 );

$wpide_cf7_blocked_scripts = array( 'Cyrillic', 'Han', 'Arabic', 'Hangul', 'Thai' ); // Unicode script names.
$wpide_cf7_script_share    = 0.3; // Share of letters in those scripts that marks a message as spam.

add_filter( 'wpcf7_spam', function ( $spam, $submission = null ) use ( $wpide_cf7_blocked_scripts, $wpide_cf7_script_share ) {
    if ( $spam || ! $submission ) {
        return $spam;
    }

    $text = '';
    foreach ( (array) $submission->get_posted_data() as $value ) {
        $text .= ' ' . ( is_array( $value ) ? implode( ' ', $value ) : (string) $value );
    }

    $letters = preg_match_all( '/\p{L}/u', $text );
    if ( $letters < 10 ) {
        return false;
    }

    $foreign = 0;
    foreach ( $wpide_cf7_blocked_scripts as $script ) {
        $foreign += (int) preg_match_all( '/\p{' . $script . '}/u', $text );
    }

    if ( $foreign / $letters >= $wpide_cf7_script_share ) {
        $submission->add_spam_log( array( 'agent' => 'wpide-script-filter', 'reason' => 'Message is mostly in a blocked script.' ) );
        return true;
    }

    return false;
}, 10, 2 );

$wpide_cf7_phone_min_digits = 7;
$wpide_cf7_phone_max_digits = 15;

$wpide_cf7_phone_check = function ( $result, $tag ) use ( $wpide_cf7_phone_min_digits, $wpide_cf7_phone_max_digits ) {
    $phone = isset( $_POST[ $tag->name ] ) ? trim( (string) wp_unslash( $_POST[ $tag->name ] ) ) : '';

    if ( '' === $phone ) {
        return $result;
    }

    $digits = strlen( preg_replace( '/\D/', '', $phone ) );

    if ( ! preg_match( '/^\+?[0-9\s().\-]+$/', $phone ) || $digits < $wpide_cf7_phone_min_digits || $digits > $wpide_cf7_phone_max_digits ) {
        $result->invalidate( $tag, 'Please enter a valid phone number.' );
    }

    return $result;
};

add_filter( 'wpcf7_validate_tel', $wpide_cf7_phone_check, 20, 2 );
add_filter( 'wpcf7_validate_tel*', $wpide_cf7_phone_check, 20, 2 );

$wpide_cf7_email_field   = 'your-email';
$wpide_cf7_confirm_field = 'your-email-confirm';

$wpide_cf7_confirm_check = function ( $result, $tag ) use ( $wpide_cf7_email_field, $wpide_cf7_confirm_field ) {
    if ( $tag->name !== $wpide_cf7_confirm_field ) {
        return $result;
    }

    $email   = isset( $_POST[ $wpide_cf7_email_field ] ) ? strtolower( trim( (string) wp_unslash( $_POST[ $wpide_cf7_email_field ] ) ) ) : '';
    $confirm = isset( $_POST[ $wpide_cf7_confirm_field ] ) ? strtolower( trim( (string) wp_unslash( $_POST[ $wpide_cf7_confirm_field ] ) ) ) : '';

    if ( $email !== $confirm ) {
        $result->invalidate( $tag, 'The email addresses do not match.' );
    }

    return $result;
};

add_filter( 'wpcf7_validate_email', $wpide_cf7_confirm_check, 20, 2 );
add_filter( 'wpcf7_validate_email*', $wpide_cf7_confirm_check, 20, 2 );

$wpide_cf7_min_words = 5; // Minimum number of words in textarea fields.

$wpide_cf7_words_check = function ( $result, $tag ) use ( $wpide_cf7_min_words ) {
    $text = isset( $_POST[ $tag->name ] ) ? trim( wp_strip_all_tags( (string) wp_unslash( $_POST[ $tag->name ] ) ) ) : '';

    if ( '' === $text && ! $tag->is_required() ) {
        return $result;
    }

    $words = preg_match_all( '/[\p{L}\p{N}\']+/u', $text );

    if ( $words < $wpide_cf7_min_words ) {
        $result->invalidate( $tag, sprintf( 'Please write at least %d words so we can help you.', $wpide_cf7_min_words ) );
    }

    return $result;
};

add_filter( 'wpcf7_validate_textarea', $wpide_cf7_words_check, 20, 2 );
add_filter( 'wpcf7_validate_textarea*', $wpide_cf7_words_check, 20, 2 );

// Field name => array( pattern, error message ).
$wpide_cf7_patterns = array(
    'postcode'     => array( '/^[A-Za-z0-9 \-]{3,10}$/', 'Please enter a valid postcode.' ),
    'order-number' => array( '/^#?\d{4,10}$/', 'Order numbers contain 4 to 10 digits.' ),
);

$wpide_cf7_pattern_check = function ( $result, $tag ) use ( $wpide_cf7_patterns ) {
    if ( ! isset( $wpide_cf7_patterns[ $tag->name ] ) ) {
        return $result;
    }

    $value = isset( $_POST[ $tag->name ] ) ? trim( (string) wp_unslash( $_POST[ $tag->name ] ) ) : '';

    if ( '' !== $value && ! preg_match( $wpide_cf7_patterns[ $tag->name ][0], $value ) ) {
        $result->invalidate( $tag, $wpide_cf7_patterns[ $tag->name ][1] );
    }

    return $result;
};

add_filter( 'wpcf7_validate_text', $wpide_cf7_pattern_check, 20, 2 );
add_filter( 'wpcf7_validate_text*', $wpide_cf7_pattern_check, 20, 2 );

$wpide_cf7_max_per_hour = 3; // Submissions allowed per IP address per hour.

$wpide_cf7_rate_key = function () {
    $ip = isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : '';

    return 'wpide_cf7_rate_' . md5( wp_salt() . $ip );
};

add_filter( 'wpcf7_spam', function ( $spam, $submission = null ) use ( $wpide_cf7_max_per_hour, $wpide_cf7_rate_key ) {
    if ( $spam ) {
        return $spam;
    }

    if ( (int) get_transient( $wpide_cf7_rate_key() ) >= $wpide_cf7_max_per_hour ) {
        if ( $submission && method_exists( $submission, 'add_spam_log' ) ) {
            $submission->add_spam_log( array( 'agent' => 'wpide-rate-limit', 'reason' => 'Too many submissions from this IP address.' ) );
        }
        return true;
    }

    return false;
}, 20, 2 );

add_action( 'wpcf7_mail_sent', function () use ( $wpide_cf7_rate_key ) {
    $key = $wpide_cf7_rate_key();
    set_transient( $key, (int) get_transient( $key ) + 1, HOUR_IN_SECONDS );
} );

// Form field name => user detail (display_name, user_email, first_name, last_name).
$wpide_cf7_user_map = array(
    'your-name'  => 'display_name',
    'your-email' => 'user_email',
);

add_filter( 'wpcf7_form_tag', function ( $tag ) use ( $wpide_cf7_user_map ) {
    if ( ! is_user_logged_in() || empty( $tag->name ) || ! isset( $wpide_cf7_user_map[ $tag->name ] ) || ! empty( $tag->values ) ) {
        return $tag;
    }

    $user  = wp_get_current_user();
    $value = (string) $user->get( $wpide_cf7_user_map[ $tag->name ] );

    if ( '' !== $value ) {
        $tag->values     = array( $value );
        $tag->raw_values = array( $value );
    }

    return $tag;
} );

$wpide_cf7_select_field = 'menu-service'; // Name of the select tag to fill.
$wpide_cf7_select_type  = 'page';         // Post type to list.

add_filter( 'wpcf7_form_tag', function ( $tag ) use ( $wpide_cf7_select_field, $wpide_cf7_select_type ) {
    if ( empty( $tag->name ) || $tag->name !== $wpide_cf7_select_field || 'select' !== $tag->basetype ) {
        return $tag;
    }

    $titles = get_transient( 'wpide_cf7_select_' . $wpide_cf7_select_type );

    if ( false === $titles ) {
        $ids    = get_posts( array( 'post_type' => $wpide_cf7_select_type, 'post_status' => 'publish', 'numberposts' => 100, 'orderby' => 'title', 'order' => 'ASC', 'fields' => 'ids', 'no_found_rows' => true ) );
        $titles = array_values( array_filter( array_map( function ( $id ) {
            return wp_strip_all_tags( get_the_title( $id ) );
        }, $ids ) ) );
        set_transient( 'wpide_cf7_select_' . $wpide_cf7_select_type, $titles, HOUR_IN_SECONDS );
    }

    if ( $titles ) {
        $tag->values     = $titles;
        $tag->raw_values = $titles;
        $tag->labels     = $titles;
    }

    return $tag;
} );

add_action( 'save_post_' . $wpide_cf7_select_type, function () use ( $wpide_cf7_select_type ) {
    delete_transient( 'wpide_cf7_select_' . $wpide_cf7_select_type );
} );

// Form ID => thank-you URL. "default" applies to all other forms.
$wpide_cf7_redirects = array(
