} );

add_action( 'init', function () {
    register_post_type( 'wpide_cf7_message', array(
        'labels'          => array( 'name' => 'Form Messages', 'singular_name' => 'Form Message', 'menu_name' => 'Form Messages' ),
        'public'          => false,
        'show_ui'         => true,
        'show_in_menu'    => true,
        'menu_icon'       => 'dashicons-email-alt',
        'supports'        => array( 'title', 'editor' ),
        'capability_type' => 'post',
        'capabilities'    => array( 'create_posts' => 'do_not_allow' ),
        'map_meta_cap'    => true,
    ) );
} );

add_action( 'wpcf7_mail_sent', function ( $contact_form ) {
    $submission = class_exists( 'WPCF7_Submission' ) ? WPCF7_Submission::get_instance() : null;

    if ( ! $submission ) {
        return;
    }

    $lines = array();
    foreach ( (array) $submission->get_posted_data() as $key => $value ) {
        if ( 0 === strpos( $key, '_' ) ) {
            continue;
        }
        $lines[] = '<strong>' . esc_html( $key ) . ':</strong> ' . nl2br( esc_html( is_array( $value ) ? implode( ', ', $value ) : (string) $value ) );
    }
    $lines[] = '<strong>Page:</strong> ' . esc_url( (string) $submission->get_meta( 'url' ) );

    wp_insert_post( array(
        'post_type'    => 'wpide_cf7_message',
        'post_status'  => 'private',
        'post_title'   => sprintf( '%s – %s', $contact_form->title(), wp_date( 'Y-m-d H:i' ) ),
        'post_content' => wp_kses_post( implode( "<br>\n", $lines ) ),
        'meta_input'   => array( '_wpide_cf7_form_id' => (int) $contact_form->id() ),
    ) );
} );

$wpide_cf7_webhook_forms = array(); // Form IDs to send; empty = all forms.

add_action( 'wpcf7_mail_sent', function ( $contact_form ) use ( $wpide_cf7_webhook_forms ) {
    $url = defined( 'WPIDE_CF7_WEBHOOK_URL' ) ? (string) WPIDE_CF7_WEBHOOK_URL : '';

    if ( ! in_array( wp_parse_url( $url, PHP_URL_SCHEME ), array( 'https', 'http' ), true ) ) {
        return;
    }
    if ( $wpide_cf7_webhook_forms && ! in_array( (int) $contact_form->id(), array_map( 'intval', $wpide_cf7_webhook_forms ), true ) ) {
        return;
    }

    $submission = WPCF7_Submission::get_instance();
    if ( ! $submission ) {
        return;
    }

    $fields = array();
    foreach ( (array) $submission->get_posted_data() as $key => $value ) {
        if ( 0 !== strpos( $key, '_' ) ) {
            $fields[ $key ] = $value;
        }
    }

    $body = wp_json_encode( array(
        'form_id'    => (int) $contact_form->id(),
        'form_title' => $contact_form->title(),
        'fields'     => $fields,
        'page_url'   => (string) $submission->get_meta( 'url' ),
        'submitted'  => gmdate( 'c' ),
        'site'       => home_url(),
    ) );

    $headers = array( 'Content-Type' => 'application/json' );
    if ( defined( 'WPIDE_CF7_WEBHOOK_SECRET' ) && WPIDE_CF7_WEBHOOK_SECRET ) {
        $headers['X-Signature'] = hash_hmac( 'sha256', $body, WPIDE_CF7_WEBHOOK_SECRET );
    }

    wp_remote_post( $url, array( 'body' => $body, 'headers' => $headers, 'timeout' => 5, 'blocking' => false ) );
} );

$wpide_cf7_slack_fields = array( 'your-name', 'your-email', 'your-subject', 'your-message' ); // Fields to include.

add_action( 'wpcf7_mail_sent', function ( $contact_form ) use ( $wpide_cf7_slack_fields ) {
    $url = defined( 'WPIDE_SLACK_WEBHOOK_URL' ) ? (string) WPIDE_SLACK_WEBHOOK_URL : '';
    $submission = WPCF7_Submission::get_instance();

    if ( 0 !== strpos( $url, 'https://hooks.slack.com/' ) || ! $submission ) {
        return;
    }

    $lines = array( sprintf( '*New message from "%s"*', $contact_form->title() ) );
    foreach ( $wpide_cf7_slack_fields as $name ) {
        $value = $submission->get_posted_data( $name );
        if ( null !== $value && '' !== $value ) {
            $value   = is_array( $value ) ? implode( ', ', $value ) : (string) $value;
            $lines[] = sprintf( '*%s:* %s', $name, wp_html_excerpt( str_replace( array( '<', '>', '&' ), array( '&lt;', '&gt;', '&amp;' ), $value ), 500, '…' ) );
        }
    }

    wp_safe_remote_post( $url, array(
        'body'     => wp_json_encode( array( 'text' => implode( "\n", $lines ) ) ),
        'headers'  => array( 'Content-Type' => 'application/json' ),
        'timeout'  => 5,
        'blocking' => false,
    ) );
} );

