add_filter( 'wpcf7_mail_components', function ( $components, $contact_form = null, $mail = null ) use ( $wpide_cf7_route_field, $wpide_cf7_routes ) {
    $submission = class_exists( 'WPCF7_Submission' ) ? WPCF7_Submission::get_instance() : null;

    if ( ! $submission || ( $mail && method_exists( $mail, 'name' ) && 'mail' !== $mail->name() ) ) {
        return $components;
    }

    $choice = $submission->get_posted_data( $wpide_cf7_route_field );
    $choice = is_array( $choice ) ? reset( $choice ) : (string) $choice;

    if ( isset( $wpide_cf7_routes[ $choice ] ) && is_email( $wpide_cf7_routes[ $choice ] ) ) {
        $components['recipient'] = $wpide_cf7_routes[ $choice ];
    }

    return $components;
}, 10, 3 );

$wpide_cf7_author_post_types = array( 'post' ); // Post types whose author receives the message.

add_filter( 'wpcf7_mail_components', function ( $components, $contact_form = null, $mail = null ) use ( $wpide_cf7_author_post_types ) {
    $submission = class_exists( 'WPCF7_Submission' ) ? WPCF7_Submission::get_instance() : null;

    if ( ! $submission || ( $mail && method_exists( $mail, 'name' ) && 'mail' !== $mail->name() ) ) {
        return $components;
    }

    $post = get_post( (int) $submission->get_meta( 'container_post_id' ) );

    if ( ! $post || ! in_array( $post->post_type, $wpide_cf7_author_post_types, true ) ) {
        return $components;
    }

    $author = get_userdata( (int) $post->post_author );

    if ( $author && is_email( $author->user_email ) ) {
        $components['recipient'] = $author->user_email;
    }

    return $components;
}, 10, 3 );

$wpide_cf7_subject_format = '[%1$s #%2$s] '; // Prefix format.

add_filter( 'wpcf7_mail_components', function ( $components, $contact_form = null ) use ( $wpide_cf7_subject_format ) {
    if ( ! $contact_form || ! method_exists( $contact_form, 'title' ) ) {
        return $components;
    }

    $reference = strtoupper( substr( base_convert( (string) ( time() . wp_rand( 10, 99 ) ), 10, 36 ), -6 ) );
    $components['subject'] = sprintf( $wpide_cf7_subject_format, $contact_form->title(), $reference ) . $components['subject'];

    return $components;
}, 10, 2 );

add_filter( 'wpcf7_mail_components', function ( $components, $contact_form = null, $mail = null ) {
    $submission = class_exists( 'WPCF7_Submission' ) ? WPCF7_Submission::get_instance() : null;

    if ( ! $submission || ( $mail && method_exists( $mail, 'name' ) && 'mail' !== $mail->name() ) ) {
        return $components;
    }

    $details = array(
        'Page'    => (string) $submission->get_meta( 'url' ),
        'Date'    => wp_date( get_option( 'date_format' ) . ' ' . get_option( 'time_format' ), (int) $submission->get_meta( 'timestamp' ) ),
        'Browser' => (string) $submission->get_meta( 'user_agent' ),
        'IP'      => (string) $submission->get_meta( 'remote_ip' ),
    );

    $html = $mail && method_exists( $mail, 'get' ) && $mail->get( 'use_html' );
    $text = '';
    foreach ( $details as $label => $value ) {
        $text .= $html ? '<br>' . esc_html( $label . ': ' . $value ) : "\n" . $label . ': ' . $value;
    }

    $components['body'] .= ( $html ? '<hr>' : "\n\n--" ) . $text;

    return $components;
}, 10, 3 );

