add_filter( 'wpcf7_form_tag', function ( $tag ) use ( $wpide_cf7_upload_types, $wpide_cf7_upload_limit ) {
    if ( empty( $tag->basetype ) || 'file' !== $tag->basetype ) {
        return $tag;
    }

    $options = (array) $tag->options;

    if ( ! $tag->has_option( 'filetypes' ) ) {
