add_action( 'wpcf7_mail_sent', function ( $contact_form ) use ( $wpide_cf7_limits ) {
    $id = (int) $contact_form->id();
    if ( isset( $wpide_cf7_limits[ $id ] ) ) {
        update_option( 'wpide_cf7_count_' . $id, (int) get_option( 'wpide_cf7_count_' . $id, 0 ) + 1, false );
    }
} );

add_filter( 'wpcf7_validate', function ( $result ) use ( $wpide_cf7_limits, $wpide_cf7_closed_message ) {
    $form = function_exists( 'wpcf7_get_current_contact_form' ) ? wpcf7_get_current_contact_form() : null;
    $id   = $form ? (int) $form->id() : 0;

    if ( isset( $wpide_cf7_limits[ $id ] ) && (int) get_option( 'wpide_cf7_count_' . $id, 0 ) >= $wpide_cf7_limits[ $id ] ) {
        $tags = $form->scan_form_tags();
        if ( $tags ) {
            $result->invalidate( $tags[0], $wpide_cf7_closed_message );
        }
    }

    return $result;
} );

add_filter( 'do_shortcode_tag', function ( $output, $tag, $attr ) use ( $wpide_cf7_limits, $wpide_cf7_closed_message ) {
    if ( 'contact-form-7' !== $tag || empty( $attr['id'] ) ) {
        return $output;
    }

    $form = function_exists( 'wpcf7_contact_form' ) ? wpcf7_contact_form( $attr['id'] ) : null;
    $id   = $form ? (int) $form->id() : 0;

    if ( isset( $wpide_cf7_limits[ $id ] ) && (int) get_option( 'wpide_cf7_count_' . $id, 0 ) >= $wpide_cf7_limits[ $id ] ) {
        return '<p class="wpide-form-closed" role="status">' . esc_html( $wpide_cf7_closed_message ) . '</p>';
    }

    return $output;
}, 10, 3 );

// Form ID => array( start, end ).
$wpide_cf7_windows = array(
    // 123 => array( '', '2026-12-31 23:59' ),
);
$wpide_cf7_window_message = 'This form is not accepting submissions at the moment.';

$wpide_cf7_is_open = function ( $id ) use ( $wpide_cf7_windows ) {
    if ( ! isset( $wpide_cf7_windows[ $id ] ) ) {
        return true;
    }

    $now   = current_time( 'timestamp' );
    $start = $wpide_cf7_windows[ $id ][0] ? strtotime( $wpide_cf7_windows[ $id ][0] ) : 0;
    $end   = $wpide_cf7_windows[ $id ][1] ? strtotime( $wpide_cf7_windows[ $id ][1] ) : PHP_INT_MAX;

    return $now >= $start && $now <= $end;
};

add_filter( 'do_shortcode_tag', function ( $output, $tag, $attr ) use ( $wpide_cf7_is_open, $wpide_cf7_window_message ) {
    if ( 'contact-form-7' !== $tag || empty( $attr['id'] ) || ! function_exists( 'wpcf7_contact_form' ) ) {
        return $output;
    }

    $form = wpcf7_contact_form( $attr['id'] );

    return $form && ! $wpide_cf7_is_open( (int) $form->id() ) ? '<p class="wpide-form-closed" role="status">' . esc_html( $wpide_cf7_window_message ) . '</p>' : $output;
}, 10, 3 );

add_filter( 'wpcf7_spam', function ( $spam ) use ( $wpide_cf7_is_open ) {
    $form = function_exists( 'wpcf7_get_current_contact_form' ) ? wpcf7_get_current_contact_form() : null;

    return ( $form && ! $wpide_cf7_is_open( (int) $form->id() ) ) ? true : $spam;
}, 30 );

$wpide_cf7_blocked_ips = array( '203.0.113.7', '198.51.100.' ); // Exact IPs or prefixes.

add_filter( 'wpcf7_spam', function ( $spam, $submission = null ) use ( $wpide_cf7_blocked_ips ) {
    if ( $spam || ! $submission ) {
        return $spam;
    }

    $ip = (string) $submission->get_meta( 'remote_ip' );

    foreach ( $wpide_cf7_blocked_ips as $blocked ) {
        $prefix = in_array( substr( $blocked, -1 ), array( '.', ':' ), true );
        if ( ( $prefix && 0 === strpos( $ip, $blocked ) ) || $ip === $blocked ) {
            $submission->add_spam_log( array( 'agent' => 'wpide-ip-block', 'reason' => 'Blocked IP address.' ) );
            return true;
        }
    }

    return false;
}, 10, 2 );

add_filter( 'wpcf7_posted_data', function ( $data ) {
    foreach ( (array) $data as $key => $value ) {
        if ( is_array( $value ) || 0 === strpos( $key, '_' ) ) {
            continue;
        }

        $value = trim( preg_replace( "/(\r?\n){3,}/", "\n\n", (string) $value ) );

        if ( false !== stripos( $key, 'email' ) ) {
            $value = strtolower( $value );
        }

        $data[ $key ] = $value;
    }

    return $data;
} );

$wpide_cf7_recaptcha_pages = array(); // Extra page IDs that show a form outside the content.

add_action( 'wp_enqueue_scripts', function () use ( $wpide_cf7_recaptcha_pages ) {
    $post = get_post();
    $uses = $post && is_singular() && ( has_shortcode( $post->post_content, 'contact-form-7' ) || has_block( 'contact-form-7/contact-form-selector', $post ) );

    if ( $uses || ( $wpide_cf7_recaptcha_pages && is_page( $wpide_cf7_recaptcha_pages ) ) ) {
        return;
    }

    wp_dequeue_script( 'wpcf7-recaptcha' );
    wp_dequeue_script( 'google-recaptcha' );
}, 50 );

