// Domains that may not be used in email fields.
$wpide_gf_blocked_domains = array( 'mailinator.com', 'yopmail.com', 'tempmail.com', 'guerrillamail.com', 'sharklasers.com' );

add_filter( 'gform_field_validation', function ( $result, $value, $form, $field ) use ( $wpide_gf_blocked_domains ) {
    if ( 'email' !== $field->type || ! $result['is_valid'] ) {
        return $result;
    }

    $email  = strtolower( trim( is_array( $value ) ? (string) reset( $value ) : (string) $value ) );
    $domain = (string) substr( strrchr( $email, '@' ), 1 );

    foreach ( $wpide_gf_blocked_domains as $blocked ) {
        if ( $domain && ( $domain === $blocked || substr( $domain, -strlen( '.' . $blocked ) ) === '.' . $blocked ) ) {
            $result['is_valid'] = false;
            $result['message']  = 'Please use a different email address.';
            break;
        }
    }

    return $result;
}, 10, 4 );

$wpide_gf_free_providers = array( 'gmail.com', 'googlemail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'live.com', 'aol.com', 'icloud.com', 'gmx.com', 'proton.me', 'protonmail.com', 'mail.com', 'yandex.com' );

add_filter( 'gform_field_validation', function ( $result, $value, $form, $field ) use ( $wpide_gf_free_providers ) {
    if ( 'email' !== $field->type || ! $result['is_valid'] ) {
        return $result;
    }

    $classed = false;
    foreach ( $form['fields'] as $f ) {
        if ( false !== strpos( ' ' . $f->cssClass . ' ', ' work-email ' ) ) {
            $classed = true;
            break;
        }
    }
    if ( $classed && false === strpos( ' ' . $field->cssClass . ' ', ' work-email ' ) ) {
        return $result;
    }

    $email  = strtolower( trim( is_array( $value ) ? (string) reset( $value ) : (string) $value ) );
    $domain = (string) substr( strrchr( $email, '@' ), 1 );

    if ( $domain && in_array( $domain, $wpide_gf_free_providers, true ) ) {
        $result['is_valid'] = false;
        $result['message']  = 'Please use your work email address.';
    }

    return $result;
}, 10, 4 );

$wpide_gf_link_field_types = array( 'text', 'textarea', 'name' ); // Field types to check.

add_filter( 'gform_field_validation', function ( $result, $value, $form, $field ) use ( $wpide_gf_link_field_types ) {
    if ( ! $result['is_valid'] || ! in_array( $field->type, $wpide_gf_link_field_types, true ) || false !== strpos( ' ' . $field->cssClass . ' ', ' allow-links ' ) ) {
        return $result;
    }

    $text = is_array( $value ) ? implode( ' ', $value ) : (string) $value;

    if ( preg_match( '#(https?://|www\.|\[url|<a\s)#i', $text ) ) {
        $result['is_valid'] = false;
        $result['message']  = 'Please remove links from this field.';
    }

    return $result;
}, 10, 4 );

$wpide_gf_spam_words = array( 'seo services', 'backlinks', 'crypto', 'casino', 'guest post', 'web design offer', 'loan' );

add_filter( 'gform_entry_is_spam', function ( $is_spam, $form, $entry ) use ( $wpide_gf_spam_words ) {
    if ( $is_spam ) {
        return $is_spam;
    }

    $text = '';
    foreach ( $form['fields'] as $field ) {
        $text .= ' ' . (string) $field->get_value_export( $entry );
    }

    foreach ( $wpide_gf_spam_words as $word ) {
        if ( preg_match( '/\b' . preg_quote( $word, '/' ) . '\b/iu', $text ) ) {
            if ( method_exists( 'GFCommon', 'set_spam_filter' ) ) {
                GFCommon::set_spam_filter( rgar( $form, 'id' ), 'WPIDE blocked words', sprintf( 'Contains "%s".', $word ) );
            }
            return true;
        }
    }

    return false;
}, 10, 3 );

$wpide_gf_min_seconds = 4; // Minimum seconds between page load and submit.

add_filter( 'gform_form_tag', function ( $tag, $form ) {
    $time = (string) time();
    $tag .= '<input type="hidden" name="wpide_gf_ts" value="' . esc_attr( $time . '.' . wp_hash( 'gf-ts-' . $time ) ) . '">';

    return $tag;
}, 10, 2 );

add_filter( 'gform_entry_is_spam', function ( $is_spam, $form, $entry ) use ( $wpide_gf_min_seconds ) {
    if ( $is_spam ) {
        return $is_spam;
    }

    $stamp = isset( $_POST['wpide_gf_ts'] ) ? sanitize_text_field( wp_unslash( $_POST['wpide_gf_ts'] ) ) : '';
    $parts = explode( '.', $stamp, 2 );
    $valid = 2 === count( $parts ) && ctype_digit( $parts[0] ) && hash_equals( wp_hash( 'gf-ts-' . $parts[0] ), $parts[1] );

    if ( $valid && time() - (int) $parts[0] >= $wpide_gf_min_seconds ) {
        return false;
    }

    if ( method_exists( 'GFCommon', 'set_spam_filter' ) ) {
        GFCommon::set_spam_filter( rgar( $form, 'id' ), 'WPIDE time trap', $valid ? 'Submitted too quickly.' : 'Missing time stamp.' );
    }

    return true;
}, 10, 3 );

$wpide_gf_honeypot_skip = array(); // Form IDs to leave alone.

add_filter( 'gform_form_post_get_meta', function ( $form ) use ( $wpide_gf_honeypot_skip ) {
    if ( is_array( $form ) && ! in_array( (int) rgar( $form, 'id' ), array_map( 'intval', $wpide_gf_honeypot_skip ), true ) ) {
        $form['enableHoneypot'] = true;
    }

    return $form;
} );

$wpide_gf_blocked_scripts = array( 'Cyrillic', 'Han', 'Arabic', 'Hangul', 'Thai' );
$wpide_gf_script_share    = 0.3; // Share of letters that marks the entry as spam.

add_filter( 'gform_entry_is_spam', function ( $is_spam, $form, $entry ) use ( $wpide_gf_blocked_scripts, $wpide_gf_script_share ) {
    if ( $is_spam ) {
        return $is_spam;
    }

    $text = '';
    foreach ( $form['fields'] as $field ) {
        if ( in_array( $field->type, array( 'text', 'textarea', 'name' ), true ) ) {
            $text .= ' ' . (string) $field->get_value_export( $entry );
        }
    }

    $letters = preg_match_all( '/\p{L}/u', $text );
    if ( $letters < 10 ) {
        return false;
    }

    $foreign = 0;
    foreach ( $wpide_gf_blocked_scripts as $script ) {
        $foreign += (int) preg_match_all( '/\p{' . $script . '}/u', $text );
    }

    return $foreign / $letters >= $wpide_gf_script_share;
}, 10, 3 );

$wpide_gf_max_entries = 3;       // Entries allowed per IP...
$wpide_gf_window      = '1 hour'; // ...within this period.
$wpide_gf_limit_forms = array(); // Form IDs to limit; empty = all.

add_filter( 'gform_validation', function ( $validation ) use ( $wpide_gf_max_entries, $wpide_gf_window, $wpide_gf_limit_forms ) {
    $form = $validation['form'];

    if ( ! $validation['is_valid'] || ( $wpide_gf_limit_forms && ! in_array( (int) $form['id'], array_map( 'intval', $wpide_gf_limit_forms ), true ) ) ) {
        return $validation;
    }

    $count = GFAPI::count_entries( $wpide_gf_limit_forms ? (int) $form['id'] : 0, array(
        'status'        => 'active',
        'start_date'    => wp_date( 'Y-m-d H:i:s', strtotime( '-' . $wpide_gf_window ) ),
        'field_filters' => array( array( 'key' => 'ip', 'value' => GFFormsModel::get_ip() ) ),
    ) );

    if ( $count >= $wpide_gf_max_entries ) {
        $validation['is_valid'] = false;
        foreach ( $form['fields'] as $field ) {
            if ( ! in_array( $field->type, array( 'hidden', 'html', 'section', 'page' ), true ) ) {
                $field->failed_validation  = true;
                $field->validation_message = 'You have sent several messages recently. Please try again later.';
                break;
            }
        }
        $validation['form'] = $form;
    }

    return $validation;
} );

$wpide_gf_daily_forms = array(); // Form IDs to protect, e.g. array( 1 ).
$wpide_gf_daily_hours = 24;

add_filter( 'gform_field_validation', function ( $result, $value, $form, $field ) use ( $wpide_gf_daily_forms, $wpide_gf_daily_hours ) {
    if ( 'email' !== $field->type || ! $result['is_valid'] || ! in_array( (int) $form['id'], array_map( 'intval', $wpide_gf_daily_forms ), true ) ) {
        return $result;
    }

    $email = strtolower( trim( is_array( $value ) ? (string) reset( $value ) : (string) $value ) );
    if ( ! is_email( $email ) ) {
        return $result;
    }

    $count = GFAPI::count_entries( (int) $form['id'], array(
        'status'        => 'active',
        'start_date'    => wp_date( 'Y-m-d H:i:s', time() - $wpide_gf_daily_hours * HOUR_IN_SECONDS ),
        'field_filters' => array( array( 'key' => (string) $field->id, 'value' => $email ) ),
    ) );

    if ( $count > 0 ) {
        $result['is_valid'] = false;
        $result['message']  = 'This email address has already been used today.';
    }

    return $result;
}, 10, 4 );

$wpide_gf_phone_min = 7;
$wpide_gf_phone_max = 15;

add_filter( 'gform_field_validation', function ( $result, $value, $form, $field ) use ( $wpide_gf_phone_min, $wpide_gf_phone_max ) {
    if ( 'phone' !== $field->type || ! $result['is_valid'] || ( ! empty( $field->phoneFormat ) && 'standard' === $field->phoneFormat ) ) {
        return $result;
    }

    $phone = trim( (string) $value );
    if ( '' === $phone ) {
        return $result;
    }

    $digits = strlen( preg_replace( '/\D/', '', $phone ) );

    if ( ! preg_match( '/^\+?[0-9\s().\-]+$/', $phone ) || $digits < $wpide_gf_phone_min || $digits > $wpide_gf_phone_max ) {
        $result['is_valid'] = false;
        $result['message']  = 'Please enter a valid phone number, including the country code.';
    }

    return $result;
}, 10, 4 );

$wpide_gf_min_age = 18;

add_filter( 'gform_field_validation', function ( $result, $value, $form, $field ) use ( $wpide_gf_min_age ) {
    if ( 'date' !== $field->type || ! $result['is_valid'] || false === strpos( ' ' . $field->cssClass . ' ', ' date-of-birth ' ) ) {
        return $result;
    }

    if ( is_array( $value ) ) {
        $value = implode( '/', array_values( $value ) );
    }

    $format = ! empty( $field->dateFormat ) ? $field->dateFormat : 'mdy';
    $parts  = preg_split( '/[\/\-.]/', (string) $value );

    if ( 3 !== count( $parts ) ) {
        return $result;
    }

    $map = array( 'mdy' => array( 2, 0, 1 ), 'dmy' => array( 2, 1, 0 ), 'dmy_dash' => array( 2, 1, 0 ), 'dmy_dot' => array( 2, 1, 0 ), 'ymd_slash' => array( 0, 1, 2 ), 'ymd_dash' => array( 0, 1, 2 ), 'ymd_dot' => array( 0, 1, 2 ) );
    $idx = isset( $map[ $format ] ) ? $map[ $format ] : $map['mdy'];

    $birth = sprintf( '%04d-%02d-%02d', (int) $parts[ $idx[0] ], (int) $parts[ $idx[1] ], (int) $parts[ $idx[2] ] );
    $limit = wp_date( 'Y-m-d', strtotime( '-' . $wpide_gf_min_age . ' years' ) );

    if ( $birth > $limit ) {
        $result['is_valid'] = false;
        $result['message']  = sprintf( 'You must be at least %d years old.', $wpide_gf_min_age );
    }

    return $result;
}, 10, 4 );

$wpide_gf_user_params = array(
