$wpide_gf_users = function ( $form ) {
    foreach ( $form['fields'] as $field ) {
        if ( ! in_array( $field->type, array( 'select', 'radio' ), true ) || ! preg_match( '/\bpopulate-role-([a-z0-9_-]+)\b/', (string) $field->cssClass, $m ) ) {
            continue;
        }

        $users = get_users( array( 'role' => $m[1], 'orderby' => 'display_name', 'fields' => array( 'ID', 'display_name' ), 'number' => 200 ) );

        $field->choices = array_map( function ( $user ) {
            return array( 'text' => $user->display_name, 'value' => (string) $user->ID );
        }, $users );
    }

    return $form;
};

