$wpide_gf_webhook_forms = array(); // Form IDs to send; empty = all forms.

add_action( 'gform_after_submission', function ( $entry, $form ) use ( $wpide_gf_webhook_forms ) {
    $url = defined( 'WPIDE_GF_WEBHOOK_URL' ) ? (string) WPIDE_GF_WEBHOOK_URL : '';

    if ( ! in_array( wp_parse_url( $url, PHP_URL_SCHEME ), array( 'https', 'http' ), true ) || 'spam' === rgar( $entry, 'status' ) ) {
        return;
    }
    if ( $wpide_gf_webhook_forms && ! in_array( (int) $form['id'], array_map( 'intval', $wpide_gf_webhook_forms ), true ) ) {
        return;
    }

    $fields = array();
    foreach ( $form['fields'] as $field ) {
        if ( in_array( $field->type, array( 'html', 'section', 'page', 'captcha' ), true ) ) {
            continue;
        }
        $label            = $field->adminLabel ? $field->adminLabel : $field->label;
        $fields[ $label ] = $field->get_value_export( $entry );
    }

    $body = wp_json_encode( array(
        'form_id'    => (int) $form['id'],
        'form_title' => $form['title'],
        'entry_id'   => (int) rgar( $entry, 'id' ),
        'fields'     => $fields,
        'source_url' => rgar( $entry, 'source_url' ),
        'created'    => rgar( $entry, 'date_created' ),
        'site'       => home_url(),
    ) );

    $headers = array( 'Content-Type' => 'application/json' );
    if ( defined( 'WPIDE_GF_WEBHOOK_SECRET' ) && WPIDE_GF_WEBHOOK_SECRET ) {
        $headers['X-Signature'] = hash_hmac( 'sha256', $body, WPIDE_GF_WEBHOOK_SECRET );
    }

    wp_remote_post( $url, array( 'body' => $body, 'headers' => $headers, 'timeout' => 5, 'blocking' => false ) );
}, 10, 2 );

add_action( 'gform_after_submission', function ( $entry, $form ) {
    $url = defined( 'WPIDE_SLACK_WEBHOOK_URL' ) ? (string) WPIDE_SLACK_WEBHOOK_URL : '';

    if ( 0 !== strpos( $url, 'https://hooks.slack.com/' ) || 'spam' === rgar( $entry, 'status' ) ) {
        return;
    }

    $escape = function ( $text ) {
        return str_replace( array( '&', '<', '>' ), array( '&amp;', '&lt;', '&gt;' ), (string) $text );
    };

    $lines = array( sprintf( '*New entry in "%s"*', $escape( $form['title'] ) ) );
    foreach ( $form['fields'] as $field ) {
        $value = trim( wp_strip_all_tags( (string) $field->get_value_export( $entry ) ) );
        if ( '' !== $value && count( $lines ) < 6 ) {
            $lines[] = sprintf( '*%s:* %s', $escape( $field->label ), $escape( wp_html_excerpt( $value, 300, '…' ) ) );
        }
    }
    $lines[] = '<' . admin_url( 'admin.php?page=gf_entries&view=entry&id=' . (int) $form['id'] . '&lid=' . (int) rgar( $entry, 'id' ) ) . '|Open the entry>';

    wp_safe_remote_post( $url, array(
        'body'     => wp_json_encode( array( 'text' => implode( "\n", $lines ) ) ),
        'headers'  => array( 'Content-Type' => 'application/json' ),
        'timeout'  => 5,
        'blocking' => false,
    ) );
}, 10, 2 );

$wpide_gf_author_notifications = array( 'Admin Notification' ); // Notification names to reroute.

add_filter( 'gform_notification', function ( $notification, $form, $entry ) use ( $wpide_gf_author_notifications ) {
    if ( ! in_array( rgar( $notification, 'name' ), $wpide_gf_author_notifications, true ) ) {
