    $post_id = url_to_postid( (string) rgar( $entry, 'source_url' ) );
    $post    = $post_id ? get_post( $post_id ) : null;
    $author  = $post ? get_userdata( (int) $post->post_author ) : false;

    if ( $author && is_email( $author->user_email ) ) {
        $notification['toType'] = 'email';
        $notification['to']     = $author->user_email;
    }

    return $notification;
}, 10, 3 );

$wpide_gf_archive_email = 'forms-archive@example.com';

add_filter( 'gform_notification', function ( $notification ) use ( $wpide_gf_archive_email ) {
    if ( ! is_email( $wpide_gf_archive_email ) ) {
