            break;
        }
    }

    return $notification;
}, 10, 3 );

$wpide_gf_button_classes = 'wp-element-button';

add_filter( 'gform_submit_button', function ( $button, $form ) use ( $wpide_gf_button_classes ) {
    if ( false === stripos( $button, '<input' ) ) {
        return $button;
    }

    $processor = class_exists( 'WP_HTML_Tag_Processor' ) ? new WP_HTML_Tag_Processor( $button ) : null;
    if ( ! $processor || ! $processor->next_tag( 'input' ) ) {
        return $button;
    }

    $attributes = array();
    foreach ( (array) $processor->get_attribute_names_with_prefix( '' ) as $name ) {
        if ( 'type' === $name || 'value' === $name ) {
            continue;
        }
        $value = $processor->get_attribute( $name );
        $attributes[] = true === $value ? esc_attr( $name ) : sprintf( '%s="%s"', esc_attr( $name ), esc_attr( 'class' === $name ? $value . ' ' . $wpide_gf_button_classes : $value ) );
    }

    $label = (string) $processor->get_attribute( 'value' );

    return sprintf( '<button type="submit" %1$s><span>%2$s</span></button>', implode( ' ', $attributes ), esc_html( $label ) );
}, 10, 2 );

$wpide_gf_error_text = 'Almost there! Please fix the %d highlighted field(s) below.';

add_filter( 'gform_validation_message', function ( $message, $form ) use ( $wpide_gf_error_text ) {
