} );

add_filter( 'gform_save_field_value', function ( $value, $entry, $field, $form, $input_id ) {
    if ( ! is_string( $value ) || ! is_object( $field ) ) {
        return $value;
    }

    $value = trim( $value );

    if ( 'email' === $field->type ) {
        return strtolower( $value );
    }

    if ( 'name' === $field->type && ( $value === strtolower( $value ) || $value === strtoupper( $value ) ) ) {
        return function_exists( 'mb_convert_case' ) ? mb_convert_case( $value, MB_CASE_TITLE, 'UTF-8' ) : ucwords( strtolower( $value ) );
    }

    return $value;
}, 10, 5 );

$wpide_gf_upload_ext = 'pdf,doc,docx,jpg,jpeg,png'; // Allowed extensions.
