add_filter( 'gform_custom_merge_tags', function ( $tags ) {
    $tags[] = array( 'label' => 'Site name', 'tag' => '{site_name}' );
    $tags[] = array( 'label' => 'Site URL', 'tag' => '{site_url}' );
    $tags[] = array( 'label' => 'Entries in this form', 'tag' => '{form_entry_count}' );
    $tags[] = array( 'label' => 'Current year', 'tag' => '{current_year}' );

    return $tags;
} );

add_filter( 'gform_replace_merge_tags', function ( $text, $form, $entry, $url_encode = false, $esc_html = false ) {
    if ( false === strpos( (string) $text, '{' ) ) {
        return $text;
    }

    $values = array(
        '{site_name}'    => wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES ),
        '{site_url}'     => home_url( '/' ),
        '{current_year}' => wp_date( 'Y' ),
    );

    if ( false !== strpos( $text, '{form_entry_count}' ) && is_array( $form ) && class_exists( 'GFAPI' ) ) {
        $values['{form_entry_count}'] = (string) GFAPI::count_entries( (int) $form['id'], array( 'status' => 'active' ) );
    }

    foreach ( $values as $tag => $value ) {
        if ( $esc_html ) {
            $value = esc_html( $value );
        }
        $text = str_replace( $tag, $url_encode ? rawurlencode( $value ) : $value, $text );
    }

    return $text;
}, 10, 5 );

