$wpide_gf_blocked_ips = array( '203.0.113.7', '198.51.100.' );

add_filter( 'gform_entry_is_spam', function ( $is_spam, $form, $entry ) use ( $wpide_gf_blocked_ips ) {
    if ( $is_spam ) {
        return $is_spam;
    }

    $ip = (string) rgar( $entry, 'ip' );

    foreach ( $wpide_gf_blocked_ips as $blocked ) {
        $prefix = in_array( substr( $blocked, -1 ), array( '.', ':' ), true );
        if ( $ip === $blocked || ( $prefix && 0 === strpos( $ip, $blocked ) ) ) {
            return true;
        }
    }

    return false;
}, 10, 3 );

add_filter( 'gform_field_validation', function ( $result, $value, $form, $field ) {
    if ( 'textarea' !== $field->type || ! $result['is_valid'] || ! preg_match( '/\bwords-(\d+)-(\d+)\b/', (string) $field->cssClass, $m ) ) {
        return $result;
    }

    $text  = trim( wp_strip_all_tags( (string) $value ) );
    if ( '' === $text && ! $field->isRequired ) {
        return $result;
    }

    $words = preg_match_all( '/[\p{L}\p{N}\']+/u', $text );
    $min   = (int) $m[1];
    $max   = (int) $m[2];

    if ( $words < $min ) {
        $result = array( 'is_valid' => false, 'message' => sprintf( 'Please write at least %1$d words (currently %2$d).', $min, $words ) );
    } elseif ( $max > 0 && $words > $max ) {
        $result = array( 'is_valid' => false, 'message' => sprintf( 'Please keep it under %1$d words (currently %2$d).', $max, $words ) );
    }

    return $result;
}, 10, 4 );

$wpide_gf_notice_days = 1; // Days of notice required; 0 allows today.

add_filter( 'gform_field_validation', function ( $result, $value, $form, $field ) use ( $wpide_gf_notice_days ) {
    if ( 'date' !== $field->type || ! $result['is_valid'] || false === strpos( ' ' . $field->cssClass . ' ', ' future-date ' ) || empty( $value ) ) {
        return $result;
    }

    if ( is_array( $value ) ) {
        $value = implode( '/', array_values( $value ) );
    }

    $format = ! empty( $field->dateFormat ) ? $field->dateFormat : 'mdy';
    $parts  = preg_split( '/[\/\-.]/', (string) $value );
    if ( 3 !== count( $parts ) ) {
        return $result;
    }

    $map  = array( 'mdy' => array( 2, 0, 1 ), 'dmy' => array( 2, 1, 0 ), 'dmy_dash' => array( 2, 1, 0 ), 'dmy_dot' => array( 2, 1, 0 ), 'ymd_slash' => array( 0, 1, 2 ), 'ymd_dash' => array( 0, 1, 2 ), 'ymd_dot' => array( 0, 1, 2 ) );
    $idx  = isset( $map[ $format ] ) ? $map[ $format ] : $map['mdy'];
    $date = sprintf( '%04d-%02d-%02d', (int) $parts[ $idx[0] ], (int) $parts[ $idx[1] ], (int) $parts[ $idx[2] ] );

    if ( $date < wp_date( 'Y-m-d', time() + $wpide_gf_notice_days * DAY_IN_SECONDS ) ) {
        $result['is_valid'] = false;
        $result['message']  = $wpide_gf_notice_days ? sprintf( 'Please choose a date at least %d day(s) from today.', $wpide_gf_notice_days ) : 'Please choose today or a later date.';
    }

    return $result;
}, 10, 4 );

$wpide_gf_no_storage_forms = array(); // Form IDs whose entries should not be kept, e.g. array( 3 ).

