$wpide_wpf_spam_words = array( 'seo services', 'backlinks', 'crypto', 'casino', 'guest post', 'rank your website' );

add_filter( 'wpforms_process_honeypot', function ( $honeypot, $fields, $entry, $form_data ) use ( $wpide_wpf_spam_words ) {
    if ( $honeypot ) {
        return $honeypot;
    }

    $text = '';
    foreach ( (array) $fields as $field ) {
        $text .= ' ' . ( isset( $field['value'] ) ? (string) $field['value'] : '' );
    }
    if ( '' === trim( $text ) && ! empty( $entry['fields'] ) ) {
        foreach ( (array) $entry['fields'] as $value ) {
            $text .= ' ' . ( is_array( $value ) ? implode( ' ', $value ) : (string) $value );
        }
    }

    foreach ( $wpide_wpf_spam_words as $word ) {
        if ( preg_match( '/\b' . preg_quote( $word, '/' ) . '\b/iu', $text ) ) {
            return 'Your message contains words we do not accept.';
        }
    }

    return $honeypot;
}, 10, 4 );

$wpide_wpf_max_links = 0;

add_action( 'wpforms_process_validate_textarea', function ( $field_id, $field_submit, $form_data ) use ( $wpide_wpf_max_links ) {
    $links = preg_match_all( '#(https?://|www\.|\[url|<a\s)#i', (string) $field_submit );

    if ( $links > $wpide_wpf_max_links ) {
        $process = method_exists( wpforms(), 'obj' ) ? wpforms()->obj( 'process' ) : wpforms()->process;
        $process->errors[ $form_data['id'] ][ $field_id ] = 0 === $wpide_wpf_max_links ? 'Please remove the links from your message.' : sprintf( 'Please include no more than %d link(s).', $wpide_wpf_max_links );
    }
}, 10, 3 );

$wpide_wpf_blocked_scripts = array( 'Cyrillic', 'Han', 'Arabic', 'Hangul', 'Thai' );
$wpide_wpf_script_share    = 0.3;

add_filter( 'wpforms_process_honeypot', function ( $honeypot, $fields, $entry, $form_data ) use ( $wpide_wpf_blocked_scripts, $wpide_wpf_script_share ) {
    if ( $honeypot || empty( $entry['fields'] ) ) {
        return $honeypot;
    }

    $text = '';
    foreach ( (array) $entry['fields'] as $value ) {
        $text .= ' ' . ( is_array( $value ) ? implode( ' ', $value ) : (string) $value );
    }

    $letters = preg_match_all( '/\p{L}/u', $text );
    if ( $letters < 10 ) {
        return $honeypot;
    }

    $foreign = 0;
    foreach ( $wpide_wpf_blocked_scripts as $script ) {
        $foreign += (int) preg_match_all( '/\p{' . $script . '}/u', $text );
    }

    return $foreign / $letters >= $wpide_wpf_script_share ? 'Your message could not be sent.' : $honeypot;
}, 10, 4 );

$wpide_wpf_max_per_hour = 3;

$wpide_wpf_rate_key = function () {
    $ip = isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : '';

    return 'wpide_wpf_rate_' . md5( wp_salt() . $ip );
};

add_action( 'wpforms_process_before', function ( $entry, $form_data ) use ( $wpide_wpf_max_per_hour, $wpide_wpf_rate_key ) {
    if ( (int) get_transient( $wpide_wpf_rate_key() ) >= $wpide_wpf_max_per_hour ) {
        $process = method_exists( wpforms(), 'obj' ) ? wpforms()->obj( 'process' ) : wpforms()->process;
        $process->errors[ $form_data['id'] ]['header'] = 'You have sent several messages recently. Please try again later.';
    }
}, 10, 2 );

add_action( 'wpforms_process_complete', function () use ( $wpide_wpf_rate_key ) {
    $key = $wpide_wpf_rate_key();
    set_transient( $key, (int) get_transient( $key ) + 1, HOUR_IN_SECONDS );
} );

$wpide_wpf_min_words = 5;

add_action( 'wpforms_process_validate_textarea', function ( $field_id, $field_submit, $form_data ) use ( $wpide_wpf_min_words ) {
    $text     = trim( wp_strip_all_tags( (string) $field_submit ) );
    $required = ! empty( $form_data['fields'][ $field_id ]['required'] );

    if ( '' === $text && ! $required ) {
        return;
    }

    if ( preg_match_all( '/[\p{L}\p{N}\']+/u', $text ) < $wpide_wpf_min_words ) {
        $process = method_exists( wpforms(), 'obj' ) ? wpforms()->obj( 'process' ) : wpforms()->process;
        $process->errors[ $form_data['id'] ][ $field_id ] = sprintf( 'Please write at least %d words so we can help.', $wpide_wpf_min_words );
    }
}, 10, 3 );

add_filter( 'wpforms_field_properties', function ( $properties, $field, $form_data ) {
    if ( ! is_user_logged_in() || ! in_array( $field['type'], array( 'name', 'email' ), true ) ) {
        return $properties;
    }

    $user = wp_get_current_user();

    if ( 'email' === $field['type'] && empty( $properties['inputs']['primary']['attr']['value'] ) ) {
        $properties['inputs']['primary']['attr']['value'] = $user->user_email;
    }

    if ( 'name' === $field['type'] && ( empty( $field['format'] ) || 'simple' === $field['format'] ) && empty( $properties['inputs']['primary']['attr']['value'] ) ) {
        $properties['inputs']['primary']['attr']['value'] = $user->display_name;
    }

    return $properties;
}, 10, 3 );

$wpide_wpf_post_choices = function ( $type ) {
    $cache   = 'wpide_wpf_choices_' . $type;
    $choices = get_transient( $cache );

    if ( false === $choices ) {
        $choices = array();
        $ids     = get_posts( array( 'post_type' => $type, 'post_status' => 'publish', 'numberposts' => 200, 'orderby' => 'title', 'order' => 'ASC', 'fields' => 'ids', 'no_found_rows' => true ) );
        foreach ( $ids as $i => $id ) {
            $choices[ $i + 1 ] = array( 'label' => wp_strip_all_tags( get_the_title( $id ) ), 'value' => '', 'image' => '' );
        }
        set_transient( $cache, $choices, HOUR_IN_SECONDS );
    }

    return $choices;
};

$wpide_wpf_fill = function ( $form_data ) use ( $wpide_wpf_post_choices ) {
    if ( empty( $form_data['fields'] ) || ! is_array( $form_data['fields'] ) ) {
        return $form_data;
    }

    foreach ( $form_data['fields'] as $id => $field ) {
        if ( 'select' === $field['type'] && ! empty( $field['css'] ) && preg_match( '/\bwpide-posts-([a-z0-9_-]+)\b/', $field['css'], $m ) && post_type_exists( $m[1] ) ) {
            $form_data['fields'][ $id ]['choices'] = $wpide_wpf_post_choices( $m[1] );
        }
    }

    return $form_data;
};

add_filter( 'wpforms_frontend_form_data', $wpide_wpf_fill );
add_filter( 'wpforms_process_before_form_data', $wpide_wpf_fill );

add_action( 'save_post', function ( $post_id, $post ) {
    delete_transient( 'wpide_wpf_choices_' . $post->post_type );
}, 10, 2 );

$wpide_wpf_redirect_form  = 0; // Form ID (0 = off until you set it).
$wpide_wpf_redirect_field = 6; // Field ID with the answer.
// Answer label => URL.
$wpide_wpf_redirect_map = array(
    'Sales'   => '/thank-you-sales/',
    'Support' => '/thank-you-support/',
);

add_filter( 'wpforms_process_redirect_url', function ( $url, $form_id, $fields ) use ( $wpide_wpf_redirect_form, $wpide_wpf_redirect_field, $wpide_wpf_redirect_map ) {
    if ( (int) $form_id !== $wpide_wpf_redirect_form ) {
        return $url;
    }

    $answer = isset( $fields[ $wpide_wpf_redirect_field ]['value'] ) ? (string) $fields[ $wpide_wpf_redirect_field ]['value'] : '';

    return isset( $wpide_wpf_redirect_map[ $answer ] ) ? esc_url_raw( home_url( $wpide_wpf_redirect_map[ $answer ] ) ) : $url;
}, 10, 3 );

$wpide_wpf_webhook_forms = array(); // Form IDs to send; empty = all.

add_action( 'wpforms_process_complete', function ( $fields, $entry, $form_data, $entry_id ) use ( $wpide_wpf_webhook_forms ) {
    $url = defined( 'WPIDE_WPFORMS_WEBHOOK_URL' ) ? (string) WPIDE_WPFORMS_WEBHOOK_URL : '';

    if ( ! in_array( wp_parse_url( $url, PHP_URL_SCHEME ), array( 'https', 'http' ), true ) ) {
        return;
    }
    if ( $wpide_wpf_webhook_forms && ! in_array( (int) $form_data['id'], array_map( 'intval', $wpide_wpf_webhook_forms ), true ) ) {
        return;
    }

    $data = array();
    foreach ( (array) $fields as $field ) {
        $label          = ! empty( $field['name'] ) ? $field['name'] : 'field_' . $field['id'];
        $data[ $label ] = isset( $field['value'] ) ? $field['value'] : '';
    }

    $body = wp_json_encode( array(
        'form_id'    => (int) $form_data['id'],
        'form_title' => isset( $form_data['settings']['form_title'] ) ? $form_data['settings']['form_title'] : '',
        'entry_id'   => (int) $entry_id,
        'fields'     => $data,
        'submitted'  => gmdate( 'c' ),
        'site'       => home_url(),
    ) );

    $headers = array( 'Content-Type' => 'application/json' );
    if ( defined( 'WPIDE_WPFORMS_WEBHOOK_SECRET' ) && WPIDE_WPFORMS_WEBHOOK_SECRET ) {
        $headers['X-Signature'] = hash_hmac( 'sha256', $body, WPIDE_WPFORMS_WEBHOOK_SECRET );
    }

    wp_remote_post( $url, array( 'body' => $body, 'headers' => $headers, 'timeout' => 5, 'blocking' => false ) );
}, 10, 4 );

add_action( 'wpforms_process_complete', function ( $fields, $entry, $form_data ) {
    $url = defined( 'WPIDE_SLACK_WEBHOOK_URL' ) ? (string) WPIDE_SLACK_WEBHOOK_URL : '';

    if ( 0 !== strpos( $url, 'https://hooks.slack.com/' ) ) {
        return;
    }

    $escape = function ( $text ) {
        return str_replace( array( '&', '<', '>' ), array( '&amp;', '&lt;', '&gt;' ), (string) $text );
    };

    $title = isset( $form_data['settings']['form_title'] ) ? $form_data['settings']['form_title'] : 'WPForms';
    $lines = array( sprintf( '*New submission: %s*', $escape( $title ) ) );

    foreach ( (array) $fields as $field ) {
        $value = isset( $field['value'] ) ? trim( wp_strip_all_tags( (string) $field['value'] ) ) : '';
        if ( '' !== $value && count( $lines ) < 7 ) {
            $lines[] = sprintf( '*%s:* %s', $escape( $field['name'] ), $escape( wp_html_excerpt( $value, 300, '…' ) ) );
        }
    }

    wp_safe_remote_post( $url, array(
        'body'     => wp_json_encode( array( 'text' => implode( "\n", $lines ) ) ),
        'headers'  => array( 'Content-Type' => 'application/json' ),
        'timeout'  => 5,
        'blocking' => false,
    ) );
}, 10, 3 );

