$wpide_wpf_author_forms = array(); // Form IDs, e.g. array( 1 ).

add_filter( 'wpforms_entry_email_atts', function ( $email, $fields, $entry, $form_data ) use ( $wpide_wpf_author_forms ) {
    if ( ! in_array( (int) $form_data['id'], array_map( 'intval', $wpide_wpf_author_forms ), true ) ) {
