$wpide_wpf_subject_format = '[%1$s] %2$s – '; // %1$s form title, %2$s submitter name.

add_filter( 'wpforms_entry_email_atts', function ( $email, $fields, $entry, $form_data ) use ( $wpide_wpf_subject_format ) {
    $name = '';
    foreach ( (array) $fields as $field ) {
