$wpide_wpf_upload_ext = 'pdf,doc,docx,jpg,jpeg,png'; // Allowed extensions.
$wpide_wpf_upload_mb  = 5;                           // Maximum size in MB.

$wpide_wpf_upload_defaults = function ( $form_data ) use ( $wpide_wpf_upload_ext, $wpide_wpf_upload_mb ) {
    if ( empty( $form_data['fields'] ) || ! is_array( $form_data['fields'] ) ) {
        return $form_data;
    }

    foreach ( $form_data['fields'] as $id => $field ) {
        if ( 'file-upload' !== $field['type'] ) {
            continue;
        }
        if ( empty( $field['extensions'] ) ) {
            $form_data['fields'][ $id ]['extensions'] = $wpide_wpf_upload_ext;
        }
        if ( empty( $field['max_size'] ) ) {
            $form_data['fields'][ $id ]['max_size'] = $wpide_wpf_upload_mb;
        }
    }

    return $form_data;
};

