add_filter( 'wpforms_process_filter', function ( $fields ) {
    foreach ( (array) $fields as $id => $field ) {
        if ( ! isset( $field['value'] ) || ! is_string( $field['value'] ) ) {
            continue;
        }

        $value = trim( $field['value'] );

        if ( 'email' === $field['type'] ) {
            $value = strtolower( $value );
        } elseif ( 'name' === $field['type'] && ( $value === strtolower( $value ) || $value === strtoupper( $value ) ) ) {
            $value = mb_convert_case( $value, MB_CASE_TITLE, 'UTF-8' );
        }

        $fields[ $id ]['value'] = $value;
    }

    return $fields;
} );

$wpide_wpf_blocked_ips = array( '203.0.113.7', '198.51.100.' );

add_filter( 'wpforms_process_honeypot', function ( $honeypot ) use ( $wpide_wpf_blocked_ips ) {
    if ( $honeypot ) {
        return $honeypot;
    }

    $ip = isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : '';

    foreach ( $wpide_wpf_blocked_ips as $blocked ) {
        $prefix = in_array( substr( $blocked, -1 ), array( '.', ':' ), true );
        if ( $ip === $blocked || ( $prefix && 0 === strpos( $ip, $blocked ) ) ) {
            return 'Submissions from your network are not accepted.';
        }
    }

    return $honeypot;
} );

$wpide_wpf_daily_forms = array(); // Form IDs to protect, e.g. array( 1 ).
$wpide_wpf_daily_hours = 24;

add_action( 'wpforms_process_validate_email', function ( $field_id, $field_submit, $form_data ) use ( $wpide_wpf_daily_forms ) {
    if ( ! in_array( (int) $form_data['id'], array_map( 'intval', $wpide_wpf_daily_forms ), true ) ) {
        return;
    }

    $email = strtolower( trim( is_array( $field_submit ) ? (string) reset( $field_submit ) : (string) $field_submit ) );

    if ( is_email( $email ) && get_transient( 'wpide_wpf_once_' . md5( $form_data['id'] . '|' . $email ) ) ) {
        $process = method_exists( wpforms(), 'obj' ) ? wpforms()->obj( 'process' ) : wpforms()->process;
        $process->errors[ $form_data['id'] ][ $field_id ] = 'This email address has already been used today.';
    }
}, 10, 3 );

add_action( 'wpforms_process_complete', function ( $fields, $entry, $form_data ) use ( $wpide_wpf_daily_forms, $wpide_wpf_daily_hours ) {
    if ( ! in_array( (int) $form_data['id'], array_map( 'intval', $wpide_wpf_daily_forms ), true ) ) {
        return;
    }

    foreach ( (array) $fields as $field ) {
        if ( isset( $field['type'] ) && 'email' === $field['type'] && is_email( $field['value'] ) ) {
            set_transient( 'wpide_wpf_once_' . md5( $form_data['id'] . '|' . strtolower( trim( $field['value'] ) ) ), 1, $wpide_wpf_daily_hours * HOUR_IN_SECONDS );
        }
    }
}, 10, 3 );

