$wpide_ff_email_fields     = array( 'email' ); // Email field names to check.
$wpide_ff_blocked_domains  = array( 'mailinator.com', 'yopmail.com', 'tempmail.com', 'guerrillamail.com', 'sharklasers.com' );

add_filter( 'fluentform/validation_errors', function ( $errors, $data, $form, $fields ) use ( $wpide_ff_email_fields, $wpide_ff_blocked_domains ) {
    foreach ( $wpide_ff_email_fields as $name ) {
        if ( empty( $data[ $name ] ) || ! is_string( $data[ $name ] ) ) {
            continue;
        }

        $domain = strtolower( (string) substr( strrchr( trim( $data[ $name ] ), '@' ), 1 ) );

        foreach ( $wpide_ff_blocked_domains as $blocked ) {
            if ( $domain && ( $domain === $blocked || substr( $domain, -strlen( '.' . $blocked ) ) === '.' . $blocked ) ) {
                $errors[ $name ] = array( 'Please use a different email address.' );
                break;
            }
        }
    }

    return $errors;
}, 10, 4 );

$wpide_ff_work_forms      = array();           // Form IDs; empty = all forms.
