$wpide_ff_free_providers  = array( 'gmail.com', 'googlemail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'live.com', 'aol.com', 'icloud.com', 'gmx.com', 'proton.me', 'protonmail.com', 'mail.com', 'yandex.com' );

add_filter( 'fluentform/validation_errors', function ( $errors, $data, $form ) use ( $wpide_ff_work_forms, $wpide_ff_work_field, $wpide_ff_free_providers ) {
    if ( $wpide_ff_work_forms && ! in_array( (int) $form->id, array_map( 'intval', $wpide_ff_work_forms ), true ) ) {
        return $errors;
    }

    $email  = isset( $data[ $wpide_ff_work_field ] ) && is_string( $data[ $wpide_ff_work_field ] ) ? strtolower( trim( $data[ $wpide_ff_work_field ] ) ) : '';
    $domain = (string) substr( strrchr( $email, '@' ), 1 );

    if ( $domain && in_array( $domain, $wpide_ff_free_providers, true ) ) {
