}, 10, 3 );

$wpide_ff_spam_words = array( 'seo services', 'backlinks', 'crypto', 'casino', 'guest post', 'rank your website' );

add_filter( 'fluentform/validation_errors', function ( $errors, $data ) use ( $wpide_ff_spam_words ) {
    foreach ( (array) $data as $name => $value ) {
        if ( ! is_string( $value ) || 0 === strpos( (string) $name, '_' ) ) {
            continue;
        }

        foreach ( $wpide_ff_spam_words as $word ) {
            if ( preg_match( '/\b' . preg_quote( $word, '/' ) . '\b/iu', $value ) ) {
                $errors[ $name ] = array( 'Your message contains words we do not accept.' );
                return $errors;
            }
        }
    }

    return $errors;
}, 10, 2 );

$wpide_ff_link_fields = array( 'message', 'description' ); // Field names to check.
$wpide_ff_max_links   = 0;

add_filter( 'fluentform/validation_errors', function ( $errors, $data ) use ( $wpide_ff_link_fields, $wpide_ff_max_links ) {
    foreach ( $wpide_ff_link_fields as $name ) {
        if ( empty( $data[ $name ] ) || ! is_string( $data[ $name ] ) ) {
            continue;
        }

        if ( preg_match_all( '#(https?://|www\.|\[url|<a\s)#i', $data[ $name ] ) > $wpide_ff_max_links ) {
            $errors[ $name ] = array( 'Please remove the links from your message.' );
        }
    }

    return $errors;
}, 10, 2 );

$wpide_ff_blocked_scripts = array( 'Cyrillic', 'Han', 'Arabic', 'Hangul', 'Thai' );
$wpide_ff_script_share    = 0.3;

add_filter( 'fluentform/validation_errors', function ( $errors, $data ) use ( $wpide_ff_blocked_scripts, $wpide_ff_script_share ) {
    $text = '';
    foreach ( (array) $data as $name => $value ) {
        if ( is_string( $value ) && 0 !== strpos( (string) $name, '_' ) ) {
            $text .= ' ' . $value;
        }
    }

    $letters = preg_match_all( '/\p{L}/u', $text );
    if ( $letters < 10 ) {
        return $errors;
    }

    $foreign = 0;
    foreach ( $wpide_ff_blocked_scripts as $script ) {
        $foreign += (int) preg_match_all( '/\p{' . $script . '}/u', $text );
    }

    if ( $foreign / $letters >= $wpide_ff_script_share ) {
        $errors['message'] = array( 'Your message could not be sent.' );
    }

    return $errors;
}, 10, 2 );

$wpide_ff_max_per_hour = 3;

$wpide_ff_rate_key = function () {
    $ip = isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : '';

