        return $errors;
    }

    if ( preg_match_all( '/[\p{L}\p{N}\']+/u', wp_strip_all_tags( $data[ $wpide_ff_words_field ] ) ) < $wpide_ff_min_words ) {
        $errors[ $wpide_ff_words_field ] = array( sprintf( 'Please write at least %d words so we can help.', $wpide_ff_min_words ) );
