$wpide_ff_phone_fields = array( 'phone' );
$wpide_ff_phone_min    = 7;
$wpide_ff_phone_max    = 15;

add_filter( 'fluentform/validation_errors', function ( $errors, $data ) use ( $wpide_ff_phone_fields, $wpide_ff_phone_min, $wpide_ff_phone_max ) {
    foreach ( $wpide_ff_phone_fields as $name ) {
        $phone = isset( $data[ $name ] ) && is_string( $data[ $name ] ) ? trim( $data[ $name ] ) : '';
        if ( '' === $phone ) {
            continue;
        }

        $digits = strlen( preg_replace( '/\D/', '', $phone ) );

        if ( ! preg_match( '/^\+?[0-9\s().\-]+$/', $phone ) || $digits < $wpide_ff_phone_min || $digits > $wpide_ff_phone_max ) {
            $errors[ $name ] = array( 'Please enter a valid phone number.' );
        }
    }

    return $errors;
}, 10, 2 );

$wpide_ff_redirect_form  = 0;            // Form ID (0 = off until you set it).
$wpide_ff_redirect_field = 'department'; // Field name holding the answer.
$wpide_ff_redirect_map   = array(
    'sales'   => '/thank-you-sales/',
    'support' => '/thank-you-support/',
);

add_filter( 'fluentform/form_submission_confirmation', function ( $confirmation, $data, $form ) use ( $wpide_ff_redirect_form, $wpide_ff_redirect_field, $wpide_ff_redirect_map ) {
    if ( (int) $form->id !== $wpide_ff_redirect_form || ! is_array( $confirmation ) ) {
        return $confirmation;
    }

    $answer = isset( $data[ $wpide_ff_redirect_field ] ) && is_scalar( $data[ $wpide_ff_redirect_field ] ) ? (string) $data[ $wpide_ff_redirect_field ] : '';

    if ( isset( $wpide_ff_redirect_map[ $answer ] ) ) {
        $confirmation['redirectTo']          = 'customUrl';
        $confirmation['customUrl']           = esc_url_raw( home_url( $wpide_ff_redirect_map[ $answer ] ) );
        $confirmation['enable_query_string'] = 'no';
    }

    return $confirmation;
}, 10, 3 );

$wpide_ff_webhook_forms = array(); // Form IDs to send; empty = all.

add_action( 'fluentform/submission_inserted', function ( $entry_id, $form_data, $form ) use ( $wpide_ff_webhook_forms ) {
    $url = defined( 'WPIDE_FLUENT_WEBHOOK_URL' ) ? (string) WPIDE_FLUENT_WEBHOOK_URL : '';

    if ( ! in_array( wp_parse_url( $url, PHP_URL_SCHEME ), array( 'https', 'http' ), true ) ) {
        return;
    }
    if ( $wpide_ff_webhook_forms && ! in_array( (int) $form->id, array_map( 'intval', $wpide_ff_webhook_forms ), true ) ) {
        return;
    }

    $fields = array();
    foreach ( (array) $form_data as $key => $value ) {
        if ( 0 !== strpos( (string) $key, '_' ) ) {
            $fields[ $key ] = $value;
        }
    }

    $body = wp_json_encode( array(
        'form_id'    => (int) $form->id,
        'form_title' => isset( $form->title ) ? $form->title : '',
        'entry_id'   => (int) $entry_id,
        'fields'     => $fields,
        'submitted'  => gmdate( 'c' ),
        'site'       => home_url(),
    ) );

    $headers = array( 'Content-Type' => 'application/json' );
    if ( defined( 'WPIDE_FLUENT_WEBHOOK_SECRET' ) && WPIDE_FLUENT_WEBHOOK_SECRET ) {
        $headers['X-Signature'] = hash_hmac( 'sha256', $body, WPIDE_FLUENT_WEBHOOK_SECRET );
    }

    wp_remote_post( $url, array( 'body' => $body, 'headers' => $headers, 'timeout' => 5, 'blocking' => false ) );
}, 10, 3 );

