$accent: #059669;
$radius: 10px;
$border: #d1d5db;
$error: #dc2626;
$gap: 1.2rem;

.fluentform {
    .ff-el-group {
        margin-bottom: $gap;
    }

    .ff-el-form-control {
        width: 100%;
        padding: 0.75em 1em;
        border: 1px solid $border;
        border-radius: $radius;
        font-size: max(16px, 1em);
        transition: border-color 0.15s, box-shadow 0.15s;

        &:focus {
            outline: none;
            border-color: $accent;
            box-shadow: 0 0 0 3px rgba($accent, 0.2);
        }
    }

    input[type="checkbox"],
    input[type="radio"] {
        accent-color: $accent;
    }

    .ff-btn-submit {
        padding: 0.8em 1.8em;
        border: 0;
        border-radius: $radius;
        background: $accent;
        color: #fff;
        font-weight: 600;

        &:hover {
            background: darken($accent, 8%);
        }
    }

    .ff-el-is-error .ff-el-form-control {
        border-color: $error;
    }

    .text-danger {
        color: $error;
    }

    @media (prefers-color-scheme: dark) {
        .ff-el-form-control {
            background: #111827;
            color: #f9fafb;
            border-color: #374151;
        }
    }

    @media (prefers-reduced-motion: reduce) {
        .ff-el-form-control {
            transition: none;
        }
    }
}

add_filter( 'fluentform/insert_response_data', function ( $data ) {
    foreach ( (array) $data as $key => $value ) {
        if ( ! is_string( $value ) || 0 === strpos( (string) $key, '_' ) ) {
            continue;
        }

        $value        = trim( $value );
        $data[ $key ] = false !== stripos( (string) $key, 'email' ) ? strtolower( $value ) : $value;
    }

    return $data;
} );

$wpide_ff_blocked_ips = array( '203.0.113.7', '198.51.100.' );

add_filter( 'fluentform/validation_errors', function ( $errors ) use ( $wpide_ff_blocked_ips ) {
    $ip = isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : '';

    foreach ( $wpide_ff_blocked_ips as $blocked ) {
        $prefix = in_array( substr( $blocked, -1 ), array( '.', ':' ), true );
        if ( $ip === $blocked || ( $prefix && 0 === strpos( $ip, $blocked ) ) ) {
            $errors['_wpide_blocked'] = array( 'Submissions from your network are not accepted.' );
            break;
        }
    }

    return $errors;
}, 5 );

$wpide_ff_daily_forms = array(); // Form IDs, e.g. array( 1 ).
$wpide_ff_daily_field = 'email';
$wpide_ff_daily_hours = 24;

$wpide_ff_daily_key = function ( $form_id, $email ) {
    return 'wpide_ff_once_' . md5( $form_id . '|' . strtolower( trim( $email ) ) );
};

add_filter( 'fluentform/validation_errors', function ( $errors, $data, $form ) use ( $wpide_ff_daily_forms, $wpide_ff_daily_field, $wpide_ff_daily_key ) {
    if ( ! in_array( (int) $form->id, array_map( 'intval', $wpide_ff_daily_forms ), true ) || empty( $data[ $wpide_ff_daily_field ] ) || ! is_string( $data[ $wpide_ff_daily_field ] ) ) {
        return $errors;
    }

    if ( get_transient( $wpide_ff_daily_key( $form->id, $data[ $wpide_ff_daily_field ] ) ) ) {
        $errors[ $wpide_ff_daily_field ] = array( 'This email address has already been used today.' );
    }

    return $errors;
}, 10, 3 );

add_action( 'fluentform/submission_inserted', function ( $entry_id, $data, $form ) use ( $wpide_ff_daily_forms, $wpide_ff_daily_field, $wpide_ff_daily_hours, $wpide_ff_daily_key ) {
    if ( in_array( (int) $form->id, array_map( 'intval', $wpide_ff_daily_forms ), true ) && ! empty( $data[ $wpide_ff_daily_field ] ) && is_string( $data[ $wpide_ff_daily_field ] ) ) {
        set_transient( $wpide_ff_daily_key( $form->id, $data[ $wpide_ff_daily_field ] ), 1, $wpide_ff_daily_hours * HOUR_IN_SECONDS );
    }
}, 10, 3 );

add_filter( 'fluentform/rendering_field_data_select', function ( $data, $form ) {
    $class = isset( $data['settings']['container_class'] ) ? (string) $data['settings']['container_class'] : '';

    if ( ! preg_match( '/\bwpide-posts-([a-z0-9_-]+)\b/', $class, $m ) || ! post_type_exists( $m[1] ) ) {
        return $data;
    }

    $cache   = 'wpide_ff_choices_' . $m[1];
    $options = get_transient( $cache );

    if ( false === $options ) {
        $options = array();
        $ids     = get_posts( array( 'post_type' => $m[1], 'post_status' => 'publish', 'numberposts' => 200, 'orderby' => 'title', 'order' => 'ASC', 'fields' => 'ids', 'no_found_rows' => true ) );
        foreach ( $ids as $id ) {
            $title     = wp_strip_all_tags( get_the_title( $id ) );
            $options[] = array( 'label' => $title, 'value' => $title, 'calc_value' => '' );
        }
        set_transient( $cache, $options, HOUR_IN_SECONDS );
    }

    $data['settings']['advanced_options'] = $options;

    return $data;
}, 10, 2 );

add_action( 'save_post', function ( $post_id, $post ) {
    delete_transient( 'wpide_ff_choices_' . $post->post_type );
}, 10, 2 );

