$wpide_contact = array(
    'to'           => '',                                   // Recipient; empty = Settings > General admin email.
    'subject'      => 'New message from your website',
    'max_per_hour' => 3,                                    // Messages allowed per visitor per hour.
    'min_seconds'  => 3,                                    // Faster submissions are treated as bots.
);

add_action( 'template_redirect', function () use ( $wpide_contact ) {
    if ( empty( $_POST['wpide_contact_nonce'] ) || 'POST' !== strtoupper( isset( $_SERVER['REQUEST_METHOD'] ) ? $_SERVER['REQUEST_METHOD'] : '' ) ) {
        return;
    }

    $back   = remove_query_arg( 'wpide_contact', wp_get_referer() ? wp_get_referer() : home_url( '/' ) );
    $finish = function ( $status ) use ( $back ) {
        wp_safe_redirect( add_query_arg( 'wpide_contact', $status, $back ) . '#wpide-contact' );
        exit;
    };

    if ( ! wp_verify_nonce( sanitize_key( wp_unslash( $_POST['wpide_contact_nonce'] ) ), 'wpide_contact' ) ) {
        $finish( 'expired' );
    }

    $stamp = isset( $_POST['wpide_ts'] ) ? sanitize_text_field( wp_unslash( $_POST['wpide_ts'] ) ) : '';
    $parts = explode( '.', $stamp, 2 );
    $human = 2 === count( $parts ) && hash_equals( wp_hash( 'contact' . $parts[0] ), $parts[1] ) && time() - (int) $parts[0] >= $wpide_contact['min_seconds'];

    if ( ! empty( $_POST['wpide_website'] ) || ! $human ) {
        $finish( 'sent' ); // Pretend success so bots learn nothing.
    }

    $ip  = isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : '';
    $key = 'wpide_contact_' . md5( wp_salt() . $ip );
    if ( (int) get_transient( $key ) >= $wpide_contact['max_per_hour'] ) {
        $finish( 'limit' );
    }

    $name    = str_replace( array( '<', '>', '"' ), '', sanitize_text_field( wp_unslash( isset( $_POST['wpide_name'] ) ? $_POST['wpide_name'] : '' ) ) );
    $email   = sanitize_email( wp_unslash( isset( $_POST['wpide_email'] ) ? $_POST['wpide_email'] : '' ) );
    $message = sanitize_textarea_field( wp_unslash( isset( $_POST['wpide_message'] ) ? $_POST['wpide_message'] : '' ) );

    if ( '' === $name || ! is_email( $email ) || strlen( $message ) < 10 ) {
        $finish( 'invalid' );
    }

    $to   = is_email( $wpide_contact['to'] ) ? $wpide_contact['to'] : get_option( 'admin_email' );
    $body = "Name: $name\nEmail: $email\nPage: $back\n\n$message";
    $sent = wp_mail( $to, $wpide_contact['subject'], $body, array( 'Reply-To: ' . $name . ' <' . $email . '>' ) );

    set_transient( $key, (int) get_transient( $key ) + 1, HOUR_IN_SECONDS );
    $finish( $sent ? 'sent' : 'error' );
} );

