$wpide_nl_subject = 'Please confirm your subscription';

add_action( 'init', function () {
    register_post_type( 'wpide_subscriber', array( 'public' => false, 'show_ui' => false, 'supports' => array( 'title' ) ) );
    if ( ! wp_next_scheduled( 'wpide_nl_cleanup' ) ) {
        wp_schedule_event( time() + HOUR_IN_SECONDS, 'daily', 'wpide_nl_cleanup' );
    }
} );

add_action( 'template_redirect', function () use ( $wpide_nl_subject ) {
    // Confirmation link.
    if ( isset( $_GET['wpide_nl_confirm'], $_GET['id'] ) ) {
        $id    = absint( $_GET['id'] );
        $token = sanitize_text_field( wp_unslash( $_GET['wpide_nl_confirm'] ) );
        $saved = (string) get_post_meta( $id, '_wpide_nl_token', true );
        if ( $saved && 'wpide_subscriber' === get_post_type( $id ) && hash_equals( $saved, $token ) ) {
            wp_update_post( array( 'ID' => $id, 'post_status' => 'publish' ) );
            delete_post_meta( $id, '_wpide_nl_token' );
            wp_safe_redirect( add_query_arg( 'wpide_nl', 'confirmed', home_url( '/' ) ) );
            exit;
        }
        return;
    }

    if ( empty( $_POST['wpide_nl_nonce'] ) ) {
        return;
    }

    $back = remove_query_arg( 'wpide_nl', wp_get_referer() ? wp_get_referer() : home_url( '/' ) );
    $done = function ( $status ) use ( $back ) {
        wp_safe_redirect( add_query_arg( 'wpide_nl', $status, $back ) . '#wpide-newsletter' );
        exit;
    };

    if ( ! wp_verify_nonce( sanitize_key( wp_unslash( $_POST['wpide_nl_nonce'] ) ), 'wpide_nl' ) ) {
        $done( 'expired' );
    }
    if ( ! empty( $_POST['wpide_nl_hp'] ) ) {
        $done( 'check' );
    }

    $email = strtolower( sanitize_email( wp_unslash( isset( $_POST['wpide_nl_email'] ) ? $_POST['wpide_nl_email'] : '' ) ) );
    if ( ! is_email( $email ) ) {
        $done( 'invalid' );
    }

    $ip  = isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : '';
    $key = 'wpide_nl_rate_' . md5( wp_salt() . $ip );
    if ( (int) get_transient( $key ) >= 5 ) {
        $done( 'check' );
    }
    set_transient( $key, (int) get_transient( $key ) + 1, HOUR_IN_SECONDS );

    $existing = get_posts( array( 'post_type' => 'wpide_subscriber', 'post_status' => array( 'publish', 'draft' ), 'title' => $email, 'numberposts' => 1, 'fields' => 'ids', 'no_found_rows' => true ) );
    if ( $existing ) {
        $done( 'check' ); // Same answer for known addresses, so the list cannot be probed.
    }

    $token = wp_generate_password( 32, false );
    $id    = wp_insert_post( array( 'post_type' => 'wpide_subscriber', 'post_status' => 'draft', 'post_title' => $email, 'meta_input' => array( '_wpide_nl_token' => $token ) ) );

    if ( $id && ! is_wp_error( $id ) ) {
        $link = add_query_arg( array( 'wpide_nl_confirm' => $token, 'id' => $id ), home_url( '/' ) );
        wp_mail( $email, $wpide_nl_subject, "Thanks for signing up to " . wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES ) . ".\n\nPlease confirm your subscription by opening this link:\n$link\n\nIf you did not sign up, ignore this email." );
    }

    $done( 'check' );
} );

