add_action( 'template_redirect', function () {
    if ( empty( $_POST['wpide_rsvp_nonce'] ) || empty( $_POST['wpide_rsvp_post'] ) ) {
        return;
    }

    $post_id = absint( $_POST['wpide_rsvp_post'] );
    $back    = remove_query_arg( 'wpide_rsvp', get_permalink( $post_id ) ? get_permalink( $post_id ) : home_url( '/' ) );
    $done    = function ( $status ) use ( $back ) {
        wp_safe_redirect( add_query_arg( 'wpide_rsvp', $status, $back ) . '#wpide-rsvp' );
        exit;
    };

    if ( ! wp_verify_nonce( sanitize_key( wp_unslash( $_POST['wpide_rsvp_nonce'] ) ), 'wpide_rsvp_' . $post_id ) || 'publish' !== get_post_status( $post_id ) ) {
        $done( 'expired' );
    }
    if ( ! empty( $_POST['wpide_rsvp_hp'] ) ) {
        $done( 'thanks' );
    }

    $name   = sanitize_text_field( wp_unslash( isset( $_POST['wpide_rsvp_name'] ) ? $_POST['wpide_rsvp_name'] : '' ) );
    $email  = strtolower( sanitize_email( wp_unslash( isset( $_POST['wpide_rsvp_email'] ) ? $_POST['wpide_rsvp_email'] : '' ) ) );
    $guests = max( 1, min( 10, absint( isset( $_POST['wpide_rsvp_guests'] ) ? $_POST['wpide_rsvp_guests'] : 1 ) ) );
    $limit  = absint( get_post_meta( $post_id, '_wpide_rsvp_limit', true ) );

    if ( '' === $name || ! is_email( $email ) ) {
        $done( 'invalid' );
    }

    $list  = get_post_meta( $post_id, '_wpide_rsvp_list', true );
    $list  = is_array( $list ) ? $list : array();
    $total = array_sum( wp_list_pluck( $list, 'guests' ) );

    if ( isset( $list[ md5( $email ) ] ) ) {
        $done( 'duplicate' );
    }
    if ( $limit && $total + $guests > $limit ) {
        $done( 'full' );
    }

    $list[ md5( $email ) ] = array( 'name' => $name, 'email' => $email, 'guests' => $guests, 'time' => time() );
    update_post_meta( $post_id, '_wpide_rsvp_list', $list );

    wp_mail( $email, 'Your RSVP for ' . wp_strip_all_tags( get_the_title( $post_id ) ), sprintf( "Hi %s,\n\nThanks for your RSVP for %d guest(s). See you there!\n\n%s", $name, $guests, get_permalink( $post_id ) ) );
    $done( 'thanks' );
} );

