add_action( 'template_redirect', function () use ( $wpide_jobs ) {
    if ( empty( $_POST['wpide_job_nonce'] ) ) {
        return;
    }

    $back = remove_query_arg( 'wpide_job', wp_get_referer() ? wp_get_referer() : home_url( '/' ) );
    $done = function ( $status ) use ( $back ) {
        wp_safe_redirect( add_query_arg( 'wpide_job', $status, $back ) . '#wpide-job' );
        exit;
    };

    if ( ! wp_verify_nonce( sanitize_key( wp_unslash( $_POST['wpide_job_nonce'] ) ), 'wpide_job' ) ) {
        $done( 'expired' );
    }
    if ( ! empty( $_POST['wpide_job_hp'] ) ) {
        $done( 'sent' );
    }

    $name     = str_replace( array( '<', '>', '"' ), '', sanitize_text_field( wp_unslash( isset( $_POST['wpide_job_name'] ) ? $_POST['wpide_job_name'] : '' ) ) );
    $email    = sanitize_email( wp_unslash( isset( $_POST['wpide_job_email'] ) ? $_POST['wpide_job_email'] : '' ) );
    $position = sanitize_text_field( wp_unslash( isset( $_POST['wpide_job_position'] ) ? $_POST['wpide_job_position'] : '' ) );
    $letter   = sanitize_textarea_field( wp_unslash( isset( $_POST['wpide_job_letter'] ) ? $_POST['wpide_job_letter'] : '' ) );
    $file     = isset( $_FILES['wpide_job_cv'] ) ? $_FILES['wpide_job_cv'] : null; // phpcs:ignore

    if ( '' === $name || ! is_email( $email ) || ! $file || UPLOAD_ERR_OK !== $file['error'] ) {
        $done( 'invalid' );
    }
    if ( $file['size'] > $wpide_jobs['max_mb'] * MB_IN_BYTES ) {
        $done( 'size' );
    }

    require_once ABSPATH . 'wp-admin/includes/file.php';
    $upload = wp_handle_upload( $file, array( 'test_form' => false, 'mimes' => $wpide_jobs['types'] ) );

    if ( empty( $upload['file'] ) ) {
        $done( 'type' );
    }

