add_action( 'template_redirect', function () {
    // Download link from the email.
    if ( isset( $_GET['wpide_dl'], $_GET['f'], $_GET['e'] ) ) {
        $file    = absint( $_GET['f'] );
        $expires = absint( $_GET['e'] );
        $sig     = sanitize_text_field( wp_unslash( $_GET['wpide_dl'] ) );

        if ( $expires >= time() && hash_equals( wp_hash( 'dl|' . $file . '|' . $expires ), $sig ) && 'attachment' === get_post_type( $file ) ) {
            wp_safe_redirect( wp_get_attachment_url( $file ) );
            exit;
        }
        wp_die( 'This download link has expired. Please request a new one.', 'Link expired', array( 'response' => 410 ) );
    }

    if ( empty( $_POST['wpide_gate_nonce'] ) || empty( $_POST['wpide_gate_file'] ) ) {
        return;
    }

    $file = absint( $_POST['wpide_gate_file'] );
    $back = remove_query_arg( 'wpide_gate', wp_get_referer() ? wp_get_referer() : home_url( '/' ) );
    $email = sanitize_email( wp_unslash( isset( $_POST['wpide_gate_email'] ) ? $_POST['wpide_gate_email'] : '' ) );

    if ( ! wp_verify_nonce( sanitize_key( wp_unslash( $_POST['wpide_gate_nonce'] ) ), 'wpide_gate_' . $file ) || 'attachment' !== get_post_type( $file ) || ! is_email( $email ) || ! empty( $_POST['wpide_gate_hp'] ) ) {
        wp_safe_redirect( add_query_arg( 'wpide_gate', 'invalid', $back ) );
        exit;
    }

    $ip  = isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : '';
    $key = 'wpide_gate_' . md5( wp_salt() . $ip );
    if ( (int) get_transient( $key ) < 5 ) {
        $expires = time() + 2 * DAY_IN_SECONDS;
        $link    = add_query_arg( array( 'wpide_dl' => wp_hash( 'dl|' . $file . '|' . $expires ), 'f' => $file, 'e' => $expires ), home_url( '/' ) );
        $title   = wp_strip_all_tags( get_the_title( $file ) );

        wp_mail( $email, 'Your download: ' . $title, "Here is your download link (valid for 48 hours):\n\n$link\n\nEnjoy!" );
        wp_mail( get_option( 'admin_email' ), 'New download request', "$email requested \"$title\"." );
        set_transient( $key, (int) get_transient( $key ) + 1, HOUR_IN_SECONDS );
    }

    wp_safe_redirect( add_query_arg( 'wpide_gate', 'sent', $back ) );
    exit;
} );

