$wpide_add_placeholder = function ( $html, $name ) use ( $wpide_comment_placeholders ) {
    if ( empty( $wpide_comment_placeholders[ $name ] ) || false !== strpos( $html, 'placeholder=' ) ) {
        return $html;
    }

    return preg_replace( '/<(input|textarea)\b/', '<$1 placeholder="' . esc_attr( $wpide_comment_placeholders[ $name ] ) . '"', $html, 1 );
};

add_filter( 'comment_form_default_fields', function ( $fields ) use ( $wpide_add_placeholder ) {
    foreach ( array( 'author', 'email', 'url' ) as $name ) {
