add_action( 'wp_ajax_wpide_comment', 'wpide_ajax_comment' );
add_action( 'wp_ajax_nopriv_wpide_comment', 'wpide_ajax_comment' );

function wpide_ajax_comment() {
    $comment = wp_handle_comment_submission( wp_unslash( $_POST ) );

    if ( is_wp_error( $comment ) ) {
        wp_send_json_error( array( 'message' => wp_strip_all_tags( $comment->get_error_message() ) ), 400 );
    }

    $user = wp_get_current_user();
    do_action( 'set_comment_cookies', $comment, $user, ! empty( $_POST['wp-comment-cookies-consent'] ) );

    $approved = '1' === (string) $comment->comment_approved;
    $html     = sprintf(
        '<li id="comment-%1$d" class="comment"><article class="comment-body"><footer class="comment-meta"><b class="fn">%2$s</b></footer><div class="comment-content">%3$s</div>%4$s</article></li>',
        (int) $comment->comment_ID,
        esc_html( get_comment_author( $comment ) ),
        wp_kses_post( wpautop( $comment->comment_content ) ),
        $approved ? '' : '<p class="comment-awaiting-moderation"><em>Your comment is awaiting moderation.</em></p>'
    );

    wp_send_json_success( array( 'html' => $html, 'approved' => $approved ) );
}

add_action( 'wp_footer', function () {
