(function () {
    var forms = document.querySelectorAll('form.wpide-save-progress, .wpide-save-progress form');
    if (!forms.length || !window.localStorage) {
        return;
    }

    forms.forEach(function (form, index) {
        var key = 'wpideForm:' + location.pathname + ':' + (form.id || index);
        var stored = {};
        try { stored = JSON.parse(localStorage.getItem(key) || '{}'); } catch (e) { stored = {}; }

        var fields = form.querySelectorAll('input:not([type="password"]):not([type="file"]):not([type="hidden"]):not([type="submit"]), textarea, select');

        fields.forEach(function (field) {
            if (!field.name || !(field.name in stored)) { return; }
            if (field.type === 'checkbox' || field.type === 'radio') {
                field.checked = stored[field.name].indexOf(field.value) !== -1;
            } else if (!field.value) {
                field.value = stored[field.name];
            }
        });

        var save = function () {
            var data = {};
            fields.forEach(function (field) {
                if (!field.name) { return; }
                if (field.type === 'checkbox' || field.type === 'radio') {
                    data[field.name] = data[field.name] || [];
                    if (field.checked) { data[field.name].push(field.value); }
                } else {
                    data[field.name] = field.value;
                }
            });
            try { localStorage.setItem(key, JSON.stringify(data)); } catch (e) {}
        };

        var timer;
        form.addEventListener('input', function () { clearTimeout(timer); timer = setTimeout(save, 400); });
        form.addEventListener('change', save);
        form.addEventListener('submit', function () { try { localStorage.removeItem(key); } catch (e) {} });
    });
})();

(function () {
    document.querySelectorAll('textarea[maxlength]').forEach(function (area) {
        var max = parseInt(area.getAttribute('maxlength'), 10);
        if (!max || max > 10000 || area.dataset.wpideCounter) {
            return;
        }
        area.dataset.wpideCounter = '1';

        var counter = document.createElement('p');
        counter.className = 'wpide-char-counter';
        counter.style.cssText = 'margin:.25em 0 0;font-size:.85em;opacity:.75;';
        counter.setAttribute('aria-live', 'polite');
        area.insertAdjacentElement('afterend', counter);

        var update = function () {
            var used = area.value.length;
            counter.textContent = used + ' / ' + max + ' characters';
            counter.style.opacity = used > max * 0.9 ? '1' : '.75';
            counter.setAttribute('aria-live', used > max * 0.9 ? 'polite' : 'off');
        };

        area.addEventListener('input', update);
        update();
    });
})();

