add_filter( 'wpcf7_spam', function ( $spam, $submission = null ) {
    if ( $spam || ! $submission ) {
        return $spam;
    }

    $keys = trim( (string) get_option( 'disallowed_keys' ) );
    if ( '' === $keys ) {
        return false;
    }

    $text = (string) $submission->get_meta( 'remote_ip' ) . ' ' . (string) $submission->get_meta( 'user_agent' );
    foreach ( (array) $submission->get_posted_data() as $value ) {
        $text .= ' ' . ( is_array( $value ) ? implode( ' ', $value ) : (string) $value );
    }

    foreach ( preg_split( '/\R/', $keys ) as $word ) {
        $word = trim( $word );
        if ( '' !== $word && false !== stripos( $text, $word ) ) {
            $submission->add_spam_log( array( 'agent' => 'wpide-disallowed-keys', 'reason' => 'Matches the Disallowed Comment Keys list.' ) );
            return true;
        }
    }

    return false;
}, 10, 2 );

add_filter( 'gform_entry_is_spam', function ( $is_spam, $form, $entry ) {
    if ( $is_spam ) {
        return $is_spam;
    }

    $keys = trim( (string) get_option( 'disallowed_keys' ) );
    if ( '' === $keys ) {
        return false;
    }

    $text = (string) rgar( $entry, 'ip' ) . ' ' . (string) rgar( $entry, 'user_agent' );
    foreach ( $form['fields'] as $field ) {
        $text .= ' ' . (string) $field->get_value_export( $entry );
    }

    foreach ( preg_split( '/\R/', $keys ) as $word ) {
        $word = trim( $word );
        if ( '' !== $word && false !== stripos( $text, $word ) ) {
            return true;
        }
    }

    return false;
}, 10, 3 );

