    }
    if ( defined( 'REST_REQUEST' ) && REST_REQUEST ) {
        return $approved;
    }

    $sent = isset( $_POST['wpide_cjs'] ) ? sanitize_text_field( wp_unslash( $_POST['wpide_cjs'] ) ) : '';

