$wpide_comment_blocked_domains = array( 'mailinator.com', 'yopmail.com', 'tempmail.com', 'guerrillamail.com', 'sharklasers.com', '10minutemail.com', 'trashmail.com', 'getnada.com' );

add_filter( 'pre_comment_approved', function ( $approved, $commentdata ) use ( $wpide_comment_blocked_domains ) {
    if ( 'spam' === $approved || empty( $commentdata['comment_author_email'] ) ) {
        return $approved;
    }

    $domain = strtolower( (string) substr( strrchr( $commentdata['comment_author_email'], '@' ), 1 ) );

    foreach ( $wpide_comment_blocked_domains as $blocked ) {
        if ( $domain === $blocked || substr( $domain, -strlen( '.' . $blocked ) ) === '.' . $blocked ) {
            return 'spam';
        }
    }

    return $approved;
}, 20, 2 );

$wpide_comment_scripts = array( 'Cyrillic', 'Han', 'Arabic', 'Hangul', 'Thai' );
$wpide_comment_share   = 0.3; // Share of letters that marks a comment as spam.

add_filter( 'pre_comment_approved', function ( $approved, $commentdata ) use ( $wpide_comment_scripts, $wpide_comment_share ) {
    if ( 'spam' === $approved || empty( $commentdata['comment_content'] ) ) {
        return $approved;
    }

    $text    = $commentdata['comment_content'] . ' ' . ( isset( $commentdata['comment_author'] ) ? $commentdata['comment_author'] : '' );
    $letters = preg_match_all( '/\p{L}/u', $text );

    if ( $letters < 10 ) {
        return $approved;
    }

    $foreign = 0;
    foreach ( $wpide_comment_scripts as $script ) {
        $foreign += (int) preg_match_all( '/\p{' . $script . '}/u', $text );
    }

    return $foreign / $letters >= $wpide_comment_share ? 'spam' : $approved;
}, 20, 2 );

$wpide_comment_daily_max = 10;

add_filter( 'pre_comment_approved', function ( $approved, $commentdata ) use ( $wpide_comment_daily_max ) {
    global $wpdb;

    if ( 'spam' === $approved || is_user_logged_in() || empty( $commentdata['comment_author_IP'] ) ) {
        return $approved;
    }

    $count = (int) $wpdb->get_var( $wpdb->prepare(
        "SELECT COUNT(*) FROM {$wpdb->comments} WHERE comment_author_IP = %s AND comment_date_gmt > %s",
        $commentdata['comment_author_IP'],
        gmdate( 'Y-m-d H:i:s', time() - DAY_IN_SECONDS )
    ) );

    return $count >= $wpide_comment_daily_max ? 0 : $approved;
}, 20, 2 );

