    $stamp = isset( $_POST['wpide_reg_ts'] ) ? sanitize_text_field( wp_unslash( $_POST['wpide_reg_ts'] ) ) : '';
    $parts = explode( '.', $stamp, 2 );
    $valid = 2 === count( $parts ) && ctype_digit( $parts[0] ) && hash_equals( wp_hash( 'reg-ts-' . $parts[0] ), $parts[1] );

    if ( ! $valid || time() - (int) $parts[0] < $wpide_reg_min_seconds ) {
        $errors->add( 'wpide_too_fast', '<strong>Error:</strong> Please take a moment and try again.' );
    }

    return $errors;
} );

add_filter( 'preprocess_comment', function ( $commentdata ) {
    if ( is_user_logged_in() || ( defined( 'REST_REQUEST' ) && REST_REQUEST ) || wp_doing_ajax() || ( isset( $commentdata['comment_type'] ) && in_array( $commentdata['comment_type'], array( 'pingback', 'trackback' ), true ) ) ) {
        return $commentdata;
    }

    $referer = isset( $_SERVER['HTTP_REFERER'] ) ? (string) wp_parse_url( esc_url_raw( wp_unslash( $_SERVER['HTTP_REFERER'] ) ), PHP_URL_HOST ) : '';
    $origin  = isset( $_SERVER['HTTP_ORIGIN'] ) ? (string) wp_parse_url( esc_url_raw( wp_unslash( $_SERVER['HTTP_ORIGIN'] ) ), PHP_URL_HOST ) : '';
    $host    = (string) wp_parse_url( home_url(), PHP_URL_HOST );

    if ( $host !== $referer && $host !== $origin ) {
        wp_die( 'Please post your comment from the article page.', 'Comment rejected', array( 'response' => 403, 'back_link' => true ) );
    }

    return $commentdata;
} );

$wpide_spam_tlds = array( 'xyz', 'top', 'click', 'loan', 'work', 'icu', 'buzz', 'cam', 'rest' );

add_filter( 'pre_comment_approved', function ( $approved, $commentdata ) use ( $wpide_spam_tlds ) {
    if ( 'spam' === $approved || empty( $commentdata['comment_author_url'] ) ) {
        return $approved;
    }

    $host = strtolower( (string) wp_parse_url( $commentdata['comment_author_url'], PHP_URL_HOST ) );
    $tld  = substr( strrchr( '.' . $host, '.' ), 1 );

    return in_array( $tld, $wpide_spam_tlds, true ) ? 'spam' : $approved;
}, 20, 2 );

add_filter( 'pre_comment_approved', function ( $approved, $commentdata ) {
    global $wpdb;

    if ( 'spam' === $approved || is_user_logged_in() || empty( $commentdata['comment_content'] ) || strlen( trim( $commentdata['comment_content'] ) ) < 30 ) {
        return $approved;
    }

    $found = $wpdb->get_var( $wpdb->prepare(
        "SELECT comment_ID FROM {$wpdb->comments} WHERE comment_date_gmt > %s AND comment_post_ID <> %d AND comment_content = %s LIMIT 1",
        gmdate( 'Y-m-d H:i:s', time() - DAY_IN_SECONDS ),
        (int) $commentdata['comment_post_ID'],
        $commentdata['comment_content']
    ) );

    return $found ? 'spam' : $approved;
}, 20, 2 );

$wpide_mail_log_days = 14; // Days of log files to keep.

$wpide_mail_log_write = function ( $line ) {
    $uploads = wp_upload_dir( null, false );
    $dir     = trailingslashit( $uploads['basedir'] ) . 'wpide-mail-logs';

    if ( ! is_dir( $dir ) ) {
        wp_mkdir_p( $dir );
        file_put_contents( $dir . '/index.php', "<?php\n// Silence is golden.\n" );
        file_put_contents( $dir . '/.htaccess', "Require all denied\nDeny from all\n" );
    }

    $file = sprintf( '%s/mail-%s-%s.log', $dir, gmdate( 'Y-m-d' ), substr( wp_hash( 'mail-log' ), 0, 12 ) );
    file_put_contents( $file, '[' . gmdate( 'c' ) . '] ' . str_replace( array( "\r", "\n" ), ' ', $line ) . "\n", FILE_APPEND | LOCK_EX );
};

add_filter( 'wp_mail', function ( $atts ) use ( $wpide_mail_log_write ) {
    $wpide_mail_log_write( sprintf( 'QUEUED to=%s subject="%s"', implode( ',', (array) $atts['to'] ), wp_strip_all_tags( (string) $atts['subject'] ) ) );

    return $atts;
}, PHP_INT_MAX );

add_action( 'wp_mail_succeeded', function ( $data ) use ( $wpide_mail_log_write ) {
    $wpide_mail_log_write( sprintf( 'SENT to=%s', implode( ',', (array) $data['to'] ) ) );
} );

add_action( 'wp_mail_failed', function ( $error ) use ( $wpide_mail_log_write ) {
    $data = (array) $error->get_error_data();
    $wpide_mail_log_write( sprintf( 'FAILED to=%s error="%s"', isset( $data['to'] ) ? implode( ',', (array) $data['to'] ) : '?', $error->get_error_message() ) );
} );

add_action( 'init', function () {
    if ( ! wp_next_scheduled( 'wpide_mail_log_rotate' ) ) {
        wp_schedule_event( time() + HOUR_IN_SECONDS, 'daily', 'wpide_mail_log_rotate' );
    }
} );

add_action( 'wpide_mail_log_rotate', function () use ( $wpide_mail_log_days ) {
    $uploads = wp_upload_dir( null, false );
    $files   = glob( trailingslashit( $uploads['basedir'] ) . 'wpide-mail-logs/mail-*.log' );

    foreach ( (array) $files as $file ) {
        if ( filemtime( $file ) < time() - $wpide_mail_log_days * DAY_IN_SECONDS ) {
            wp_delete_file( $file );
        }
    }
} );

$wpide_mlog_days  = 30; // Days to keep entries.
