    ) {$wpdb->get_charset_collate()};" );

    update_option( 'wpide_mail_log_db', '1', true );
} );

add_filter( 'wp_mail', function ( $atts ) use ( $wpide_mlog_state ) {
    global $wpdb;

    if ( '1' !== get_option( 'wpide_mail_log_db' ) ) {
        return $atts;
    }

    $wpdb->insert( $wpdb->prefix . 'wpide_mail_log', array(
        'sent_at' => current_time( 'mysql', true ),
        'to_addr' => implode( ', ', (array) $atts['to'] ),
        'subject' => (string) $atts['subject'],
        'headers' => is_array( $atts['headers'] ) ? implode( "\n", $atts['headers'] ) : (string) $atts['headers'],
