    return $atts;
}, PHP_INT_MAX );

add_action( 'wp_mail_succeeded', function () use ( $wpide_mlog_state ) {
    global $wpdb;
    if ( $wpide_mlog_state->id ) {
        $wpdb->update( $wpdb->prefix . 'wpide_mail_log', array( 'status' => 'sent' ), array( 'id' => $wpide_mlog_state->id ) );
        $wpide_mlog_state->id = 0;
    }
} );

add_action( 'wp_mail_failed', function ( $error ) use ( $wpide_mlog_state ) {
