    if ( $wpide_mlog_state->id ) {
        $wpdb->update( $wpdb->prefix . 'wpide_mail_log', array( 'status' => 'failed', 'error' => $error->get_error_message() ), array( 'id' => $wpide_mlog_state->id ) );
        $wpide_mlog_state->id = 0;
    }
} );

add_action( 'init', function () {
