add_action( 'phpmailer_init', function ( $phpmailer ) {
    if ( ! defined( 'WPIDE_SMTP_DEBUG' ) || ! WPIDE_SMTP_DEBUG ) {
        return;
    }

    $phpmailer->SMTPDebug   = 2;
    $phpmailer->Debugoutput = function ( $text ) {
        $text = trim( (string) $text );

        // Hide credentials: AUTH arguments and base64 lines sent by the client.
        $text = preg_replace( '/^(CLIENT -> SERVER:\s*AUTH\s+\S+)\s+.+$/i', '$1 [redacted]', $text );
        if ( preg_match( '/^CLIENT -> SERVER:\s*(\S+)\s*$/', $text, $m ) && preg_match( '/^[A-Za-z0-9+\/=]{8,}$/', $m[1] ) && ! preg_match( '/^(EHLO|HELO|QUIT|DATA|RSET|NOOP|STARTTLS)$/i', $m[1] ) ) {
            $text = 'CLIENT -> SERVER: [redacted]';
        }

        error_log( 'SMTP: ' . $text );
    };
}, 1000 );

