add_filter( 'comment_moderation_headers', function ( $headers, $comment_id ) {
    $comment = get_comment( $comment_id );

    if ( ! $comment || ! is_email( $comment->comment_author_email ) || false !== stripos( (string) $headers, 'Reply-To:' ) ) {
        return $headers;
    }

    $name = trim( str_replace( array( '"', "\r", "\n", '<', '>' ), '', $comment->comment_author ) );

    return rtrim( (string) $headers, "\n" ) . "\nReply-To: " . ( $name ? '"' . $name . '" ' : '' ) . '<' . $comment->comment_author_email . ">\n";
}, 10, 2 );

// Text found in the subject (case-insensitive) => Reply-To address.
$wpide_reply_rules = array(
    // 'order'   => 'orders@yourdomain.com',
    // 'support' => 'support@yourdomain.com',
);

add_filter( 'wp_mail', function ( $atts ) use ( $wpide_reply_rules ) {
    $headers = is_array( $atts['headers'] ) ? implode( "\n", $atts['headers'] ) : (string) $atts['headers'];

    if ( false !== stripos( $headers, 'Reply-To:' ) ) {
        return $atts;
    }

    foreach ( $wpide_reply_rules as $needle => $address ) {
        if ( false !== stripos( (string) $atts['subject'], $needle ) && is_email( $address ) ) {
            if ( is_array( $atts['headers'] ) ) {
                $atts['headers'][] = 'Reply-To: ' . $address;
            } else {
                $atts['headers'] = trim( $headers . "\nReply-To: " . $address );
            }
            break;
        }
    }

    return $atts;
} );

add_filter( 'wp_mail', function ( $atts ) {
    $template = locate_template( 'emails/wrapper.php' );
    $headers  = is_array( $atts['headers'] ) ? implode( "\n", $atts['headers'] ) : (string) $atts['headers'];

    if ( ! $template || false !== stripos( $headers, 'text/html' ) || preg_match( '/<(html|body|p|div|table)\b/i', (string) $atts['message'] ) ) {
        return $atts;
    }

    $subject = wp_strip_all_tags( (string) $atts['subject'] );
    $content = make_clickable( nl2br( esc_html( (string) $atts['message'] ) ) );

    ob_start();
    include $template;
    $html = trim( (string) ob_get_clean() );

    if ( '' === $html ) {
        return $atts;
    }

    $atts['message'] = $html;
    $type            = 'Content-Type: text/html; charset=' . get_bloginfo( 'charset' );

    if ( is_array( $atts['headers'] ) ) {
        $atts['headers'][] = $type;
    } else {
        $atts['headers'] = trim( $headers . "\n" . $type );
    }

    return $atts;
}, 20 );

$wpide_signature = array(
    'Example Ltd · 1 Main Street, Springfield',
    'Need help? support@example.com',
);

add_filter( 'wp_mail', function ( $atts ) use ( $wpide_signature ) {
    $message = (string) $atts['message'];
    $headers = is_array( $atts['headers'] ) ? implode( "\n", $atts['headers'] ) : (string) $atts['headers'];
    $is_html = false !== stripos( $headers, 'text/html' ) || 'text/html' === apply_filters( 'wp_mail_content_type', 'text/plain' );

    if ( $is_html ) {
        $block = '<p style="margin-top:24px;padding-top:12px;border-top:1px solid #ddd;color:#666;font-size:12px;">' . implode( '<br>', array_map( 'esc_html', $wpide_signature ) ) . '</p>';
        $atts['message'] = false !== stripos( $message, '</body>' ) ? preg_replace( '#</body>#i', $block . '</body>', $message, 1 ) : $message . $block;
    } else {
        $atts['message'] = rtrim( $message ) . "\n\n-- \n" . implode( "\n", $wpide_signature ) . "\n";
    }

    return $atts;
}, 30 );

$wpide_suppressed = array( 'bounced@example.com', '@old-company.com' );

$wpide_is_suppressed = function ( $recipient ) use ( $wpide_suppressed ) {
    $email = strtolower( trim( preg_match( '/<([^>]+)>/', $recipient, $m ) ? $m[1] : $recipient ) );

    foreach ( $wpide_suppressed as $entry ) {
        $entry = strtolower( trim( $entry ) );
        if ( $email === $entry || ( 0 === strpos( $entry, '@' ) && substr( $email, -strlen( $entry ) ) === $entry ) ) {
            return true;
        }
    }

    return false;
};

add_filter( 'wp_mail', function ( $atts ) use ( $wpide_is_suppressed ) {
    $to = is_array( $atts['to'] ) ? $atts['to'] : explode( ',', (string) $atts['to'] );

    $atts['to'] = array_values( array_filter( array_map( 'trim', $to ), function ( $recipient ) use ( $wpide_is_suppressed ) {
        return '' !== $recipient && ! $wpide_is_suppressed( $recipient );
    } ) );

    return $atts;
}, 5 );

add_filter( 'pre_wp_mail', function ( $return, $atts ) {
    return empty( $atts['to'] ) ? true : $return;
}, 5, 2 );

$wpide_mail_hourly_cap = 100;

add_filter( 'pre_wp_mail', function ( $return ) use ( $wpide_mail_hourly_cap ) {
    if ( null !== $return ) {
        return $return;
    }

    $key   = 'wpide_mail_count_' . gmdate( 'YmdH' );
    $count = (int) get_transient( $key );

    if ( $count >= $wpide_mail_hourly_cap ) {
        if ( ! get_transient( $key . '_noted' ) ) {
            error_log( sprintf( 'WPIDE: hourly email limit of %d reached; further emails this hour are blocked.', $wpide_mail_hourly_cap ) );
            set_transient( $key . '_noted', 1, HOUR_IN_SECONDS );
        }
        return false;
    }

    set_transient( $key, $count + 1, HOUR_IN_SECONDS );

    return $return;
}, 1 );

$wpide_reserved_domains = array( 'example.com', 'example.org', 'example.net', 'test', 'invalid', 'localhost', 'local' );

add_filter( 'wp_mail', function ( $atts ) use ( $wpide_reserved_domains ) {
    $list  = is_array( $atts['to'] ) ? $atts['to'] : explode( ',', (string) $atts['to'] );
    $clean = array();

    foreach ( $list as $recipient ) {
        $recipient = trim( (string) $recipient );
        $email     = strtolower( preg_match( '/<([^>]+)>/', $recipient, $m ) ? trim( $m[1] ) : $recipient );
        $domain    = (string) substr( strrchr( $email, '@' ), 1 );
        $tld       = substr( strrchr( '.' . $domain, '.' ), 1 );

        if ( ! is_email( $email ) || isset( $clean[ $email ] ) || in_array( $domain, $wpide_reserved_domains, true ) || in_array( $tld, $wpide_reserved_domains, true ) ) {
            continue;
        }

        $clean[ $email ] = $recipient;
    }

    $atts['to'] = array_values( $clean );

    return $atts;
}, 6 );

add_filter( 'pre_wp_mail', function ( $return, $atts ) {
    if ( null !== $return || ! defined( 'WPIDE_POSTMARK_TOKEN' ) || ! WPIDE_POSTMARK_TOKEN || ! empty( $atts['attachments'] ) ) {
        return $return;
    }

    $lines = is_array( $atts['headers'] ) ? $atts['headers'] : explode( "\n", str_replace( "\r\n", "\n", (string) $atts['headers'] ) );
    $h     = array( 'from' => '', 'reply-to' => array(), 'cc' => array(), 'bcc' => array(), 'content-type' => '' );
    foreach ( $lines as $line ) {
        if ( false === strpos( (string) $line, ':' ) ) {
            continue;
        }
        list( $name, $value ) = array_map( 'trim', explode( ':', $line, 2 ) );
        $name = strtolower( $name );
        if ( in_array( $name, array( 'reply-to', 'cc', 'bcc' ), true ) ) {
            $h[ $name ] = array_merge( $h[ $name ], array_filter( array_map( 'trim', explode( ',', $value ) ) ) );
        } elseif ( isset( $h[ $name ] ) ) {
            $h[ $name ] = $value;
        }
    }

    $from    = $h['from'] ? $h['from'] : sprintf( '%s <%s>', apply_filters( 'wp_mail_from_name', 'WordPress' ), apply_filters( 'wp_mail_from', get_option( 'admin_email' ) ) );
    $is_html = false !== stripos( $h['content-type'], 'text/html' ) || 'text/html' === apply_filters( 'wp_mail_content_type', 'text/plain' );
    $to      = is_array( $atts['to'] ) ? $atts['to'] : explode( ',', (string) $atts['to'] );

    $body = array(
        'From'          => $from,
        'To'            => implode( ',', array_map( 'trim', $to ) ),
        'Subject'       => (string) $atts['subject'],
        'MessageStream' => 'outbound',
    );
    $body[ $is_html ? 'HtmlBody' : 'TextBody' ] = (string) $atts['message'];
    if ( $h['cc'] ) {
        $body['Cc'] = implode( ',', $h['cc'] );
    }
    if ( $h['bcc'] ) {
        $body['Bcc'] = implode( ',', $h['bcc'] );
    }
    if ( $h['reply-to'] ) {
        $body['ReplyTo'] = implode( ',', $h['reply-to'] );
    }

    $response = wp_remote_post( 'https://api.postmarkapp.com/email', array(
        'timeout' => 15,
        'headers' => array( 'Accept' => 'application/json', 'Content-Type' => 'application/json', 'X-Postmark-Server-Token' => WPIDE_POSTMARK_TOKEN ),
        'body'    => wp_json_encode( $body ),
    ) );

    $code = (int) wp_remote_retrieve_response_code( $response );
    if ( 200 === $code ) {
        do_action( 'wp_mail_succeeded', $atts );
        return true;
    }

    $message = is_wp_error( $response ) ? $response->get_error_message() : 'Postmark returned HTTP ' . $code . ': ' . wp_remote_retrieve_body( $response );
    do_action( 'wp_mail_failed', new WP_Error( 'wp_mail_failed', $message, $atts ) );

    return false;
}, 10, 2 );

