add_filter( 'pre_wp_mail', function ( $return, $atts ) {
    if ( null !== $return || ! defined( 'WPIDE_SENDGRID_KEY' ) || ! WPIDE_SENDGRID_KEY || ! empty( $atts['attachments'] ) ) {
        return $return;
    }

    $address = function ( $value ) {
        $value = trim( (string) $value );
        if ( preg_match( '/^(.*)<([^>]+)>$/', $value, $m ) ) {
            $name = trim( $m[1], " \"'" );
            return $name ? array( 'email' => trim( $m[2] ), 'name' => $name ) : array( 'email' => trim( $m[2] ) );
        }
        return array( 'email' => $value );
    };

    $lines = is_array( $atts['headers'] ) ? $atts['headers'] : explode( "\n", str_replace( "\r\n", "\n", (string) $atts['headers'] ) );
    $h     = array( 'from' => '', 'reply-to' => array(), 'cc' => array(), 'bcc' => array(), 'content-type' => '' );
    foreach ( $lines as $line ) {
        if ( false === strpos( (string) $line, ':' ) ) {
            continue;
        }
        list( $name, $value ) = array_map( 'trim', explode( ':', $line, 2 ) );
        $name = strtolower( $name );
        if ( in_array( $name, array( 'reply-to', 'cc', 'bcc' ), true ) ) {
            $h[ $name ] = array_merge( $h[ $name ], array_filter( array_map( 'trim', explode( ',', $value ) ) ) );
        } elseif ( isset( $h[ $name ] ) ) {
            $h[ $name ] = $value;
        }
    }

    $to      = is_array( $atts['to'] ) ? $atts['to'] : explode( ',', (string) $atts['to'] );
    $is_html = false !== stripos( $h['content-type'], 'text/html' ) || 'text/html' === apply_filters( 'wp_mail_content_type', 'text/plain' );
    $from    = $h['from'] ? $address( $h['from'] ) : array( 'email' => apply_filters( 'wp_mail_from', get_option( 'admin_email' ) ), 'name' => apply_filters( 'wp_mail_from_name', 'WordPress' ) );

    $personalization = array( 'to' => array_map( $address, array_filter( array_map( 'trim', $to ) ) ) );
    if ( $h['cc'] ) {
        $personalization['cc'] = array_map( $address, $h['cc'] );
    }
    if ( $h['bcc'] ) {
        $personalization['bcc'] = array_map( $address, $h['bcc'] );
    }

    $body = array(
        'personalizations' => array( $personalization ),
        'from'             => $from,
        'subject'          => (string) $atts['subject'],
        'content'          => array( array( 'type' => $is_html ? 'text/html' : 'text/plain', 'value' => (string) $atts['message'] ) ),
    );
    if ( $h['reply-to'] ) {
        $body['reply_to'] = $address( $h['reply-to'][0] );
    }

    $response = wp_remote_post( 'https://api.sendgrid.com/v3/mail/send', array(
        'timeout' => 15,
        'headers' => array( 'Authorization' => 'Bearer ' . WPIDE_SENDGRID_KEY, 'Content-Type' => 'application/json' ),
        'body'    => wp_json_encode( $body ),
    ) );

    $code = (int) wp_remote_retrieve_response_code( $response );
    if ( $code >= 200 && $code < 300 ) {
        do_action( 'wp_mail_succeeded', $atts );
        return true;
    }

    $message = is_wp_error( $response ) ? $response->get_error_message() : 'SendGrid returned HTTP ' . $code . ': ' . wp_remote_retrieve_body( $response );
    do_action( 'wp_mail_failed', new WP_Error( 'wp_mail_failed', $message, $atts ) );

    return false;
}, 10, 2 );

