$wpide_recovery_devs       = array(); // e.g. array( 'dev@agency.com' ).
$wpide_recovery_keep_admin = true;

add_filter( 'recovery_mode_email', function ( $email ) use ( $wpide_recovery_devs, $wpide_recovery_keep_admin ) {
    $devs = array_filter( $wpide_recovery_devs, 'is_email' );

    if ( $devs ) {
        $current     = $wpide_recovery_keep_admin ? (array) $email['to'] : array();
        $email['to'] = array_values( array_unique( array_merge( $current, $devs ) ) );
    }

    return $email;
} );

