$wpide_update_recipients = array(); // e.g. array( 'dev@agency.com' ); empty = no change.

$wpide_update_to = function ( $email ) use ( $wpide_update_recipients ) {
    $to = array_values( array_filter( $wpide_update_recipients, 'is_email' ) );

    if ( $to ) {
        $email['to'] = $to;
    }

    return $email;
};

