} );

add_action( 'wpide_weekly_summary', function () use ( $wpide_summary_recipients ) {
    $since = gmdate( 'Y-m-d H:i:s', time() - WEEK_IN_SECONDS );

    $posts = new WP_Query( array( 'post_type' => 'post', 'post_status' => 'publish', 'date_query' => array( array( 'after' => $since, 'column' => 'post_date_gmt' ) ), 'fields' => 'ids', 'posts_per_page' => 1 ) );
    $users = new WP_User_Query( array( 'date_query' => array( array( 'after' => $since, 'column' => 'user_registered' ) ), 'fields' => 'ID', 'number' => 1, 'count_total' => true ) );

    $stats = array(
        'Posts published'             => (int) $posts->found_posts,
        'Comments approved'           => (int) get_comments( array( 'status' => 'approve', 'count' => true, 'date_query' => array( array( 'after' => $since, 'column' => 'comment_date_gmt' ) ) ) ),
        'Comments waiting'            => (int) wp_count_comments()->moderated,
        'Posts waiting for review'    => (int) wp_count_posts( 'post' )->pending,
        'New users'                   => (int) $users->get_total(),
    );

    $lines = array( 'Here is what happened on ' . home_url() . ' in the last 7 days:', '' );
    foreach ( $stats as $label => $value ) {
        $lines[] = sprintf( '%-28s %d', $label . ':', $value );
    }
    $lines[] = '';
    $lines[] = 'Dashboard: ' . admin_url();

    $to = array_merge( array( get_option( 'admin_email' ) ), array_filter( $wpide_summary_recipients, 'is_email' ) );
    wp_mail( $to, sprintf( '[%s] Weekly summary', wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES ) ), implode( "\n", $lines ) );
} );

