add_action( 'wpide_new_users_digest', function () {
    $users = get_users( array(
        'date_query' => array( array( 'after' => gmdate( 'Y-m-d H:i:s', time() - DAY_IN_SECONDS ), 'column' => 'user_registered' ) ),
        'number'     => 200,
        'orderby'    => 'registered',
        'order'      => 'DESC',
    ) );

    if ( ! $users ) {
        return;
    }

    $lines = array( sprintf( '%d new user(s) registered in the last 24 hours:', count( $users ) ), '' );
    foreach ( $users as $user ) {
        $lines[] = sprintf( '• %s <%s> – %s', $user->user_login, $user->user_email, implode( ', ', (array) $user->roles ) );
    }
    $lines[] = '';
    $lines[] = 'All users: ' . admin_url( 'users.php' );

    wp_mail( get_option( 'admin_email' ), sprintf( '[%s] %d new user(s)', wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES ), count( $users ) ), implode( "\n", $lines ) );
} );

