add_action( 'wpide_stale_drafts', function () use ( $wpide_stale_days ) {
    $drafts = get_posts( array(
        'post_type'     => 'post',
        'post_status'   => 'draft',
        'numberposts'   => 300,
        'no_found_rows' => true,
        'date_query'    => array( array( 'before' => gmdate( 'Y-m-d H:i:s', time() - $wpide_stale_days * DAY_IN_SECONDS ), 'column' => 'post_modified_gmt' ) ),
    ) );

    $by_author = array();
    foreach ( $drafts as $draft ) {
        $by_author[ (int) $draft->post_author ][] = $draft;
    }

    foreach ( $by_author as $author_id => $posts ) {
        $user = get_userdata( $author_id );
        if ( ! $user || ! is_email( $user->user_email ) ) {
            continue;
        }

        $lines = array( sprintf( 'Hi %s, these drafts have not been edited for over %d days:', $user->display_name, $wpide_stale_days ), '' );
        foreach ( array_slice( $posts, 0, 20 ) as $post ) {
            $lines[] = sprintf( '• %s – %s', $post->post_title ? $post->post_title : '(no title)', admin_url( 'post.php?post=' . $post->ID . '&action=edit' ) );
        }
        $lines[] = '';
        $lines[] = 'Finish them, schedule them or move them to the trash.';

        wp_mail( $user->user_email, 'Your drafts are waiting', implode( "\n", $lines ) );
    }
} );

