    $text = sprintf( "*%s*\n%s", $escape( wp_strip_all_tags( (string) $atts['subject'] ) ), $escape( wp_html_excerpt( trim( wp_strip_all_tags( (string) $atts['message'] ) ), 500, '…' ) ) );

    wp_safe_remote_post( $url, array(
        'body'     => wp_json_encode( array( 'text' => $text ) ),
