$wpide_retry_state = new stdClass();
$wpide_retry_state->running = false;

add_action( 'wp_mail_failed', function ( $error ) use ( $wpide_retry_state ) {
    $data = (array) $error->get_error_data();

    if ( $wpide_retry_state->running || empty( $data['to'] ) || ! empty( $data['attachments'] ) ) {
        return;
    }

    $queue   = (array) get_option( 'wpide_mail_retry', array() );
    $queue[] = array(
        'to'       => $data['to'],
        'subject'  => isset( $data['subject'] ) ? $data['subject'] : '',
        'message'  => isset( $data['message'] ) ? $data['message'] : '',
        'headers'  => isset( $data['headers'] ) ? $data['headers'] : array(),
        'attempts' => 0,
    );
    update_option( 'wpide_mail_retry', array_slice( $queue, -50 ), false );

    if ( ! wp_next_scheduled( 'wpide_mail_retry' ) ) {
        wp_schedule_single_event( time() + 10 * MINUTE_IN_SECONDS, 'wpide_mail_retry' );
    }
} );

add_action( 'wpide_mail_retry', function () use ( $wpide_retry_state ) {
    $queue = (array) get_option( 'wpide_mail_retry', array() );
    $left  = array();

    $wpide_retry_state->running = true;
    foreach ( $queue as $item ) {
        if ( ! wp_mail( $item['to'], $item['subject'], $item['message'], $item['headers'] ) && ++$item['attempts'] < 3 ) {
            $left[] = $item;
        }
    }
    $wpide_retry_state->running = false;

    update_option( 'wpide_mail_retry', $left, false );

    if ( $left ) {
        wp_schedule_single_event( time() + 10 * MINUTE_IN_SECONDS, 'wpide_mail_retry' );
    }
} );

add_filter( 'pre_wp_mail', function ( $return, $atts ) {
    if ( null !== $return || ! defined( 'WPIDE_SPARKPOST_KEY' ) || ! WPIDE_SPARKPOST_KEY || ! empty( $atts['attachments'] ) ) {
        return $return;
    }

    $split = function ( $value ) {
        $value = trim( (string) $value );
        return preg_match( '/^(.*)<([^>]+)>$/', $value, $m ) ? array( 'name' => trim( $m[1], " \"'" ), 'email' => trim( $m[2] ) ) : array( 'name' => '', 'email' => $value );
    };

    $lines = is_array( $atts['headers'] ) ? $atts['headers'] : explode( "\n", str_replace( "\r\n", "\n", (string) $atts['headers'] ) );
    $h     = array( 'from' => '', 'reply-to' => array(), 'cc' => array(), 'bcc' => array(), 'content-type' => '' );
    foreach ( $lines as $line ) {
        if ( false === strpos( (string) $line, ':' ) ) {
            continue;
        }
        list( $name, $value ) = array_map( 'trim', explode( ':', $line, 2 ) );
        $name = strtolower( $name );
        if ( in_array( $name, array( 'reply-to', 'cc', 'bcc' ), true ) ) {
            $h[ $name ] = array_merge( $h[ $name ], array_filter( array_map( 'trim', explode( ',', $value ) ) ) );
        } elseif ( isset( $h[ $name ] ) ) {
            $h[ $name ] = $value;
        }
    }

    $to      = is_array( $atts['to'] ) ? $atts['to'] : explode( ',', (string) $atts['to'] );
    $is_html = false !== stripos( $h['content-type'], 'text/html' ) || 'text/html' === apply_filters( 'wp_mail_content_type', 'text/plain' );
    $from    = $h['from'] ? $split( $h['from'] ) : array( 'name' => apply_filters( 'wp_mail_from_name', 'WordPress' ), 'email' => apply_filters( 'wp_mail_from', get_option( 'admin_email' ) ) );

    $recipients = array();
    foreach ( array_merge( array_filter( array_map( 'trim', $to ) ), $h['cc'], $h['bcc'] ) as $recipient ) {
        $recipients[] = array( 'address' => array( 'email' => $split( $recipient )['email'] ) );
    }

    $content = array( 'from' => array( 'email' => $from['email'], 'name' => $from['name'] ), 'subject' => (string) $atts['subject'] );
    $content[ $is_html ? 'html' : 'text' ] = (string) $atts['message'];
    if ( $h['reply-to'] ) {
        $content['reply_to'] = $h['reply-to'][0];
    }
    if ( $h['cc'] ) {
        $content['headers'] = array( 'CC' => implode( ',', $h['cc'] ) );
    }

    $host     = defined( 'WPIDE_SPARKPOST_EU' ) && WPIDE_SPARKPOST_EU ? 'api.eu.sparkpost.com' : 'api.sparkpost.com';
    $response = wp_remote_post( 'https://' . $host . '/api/v1/transmissions', array(
        'timeout' => 15,
        'headers' => array( 'Authorization' => WPIDE_SPARKPOST_KEY, 'Content-Type' => 'application/json' ),
        'body'    => wp_json_encode( array( 'recipients' => $recipients, 'content' => $content ) ),
    ) );

    $code = (int) wp_remote_retrieve_response_code( $response );
    if ( $code >= 200 && $code < 300 ) {
        do_action( 'wp_mail_succeeded', $atts );
        return true;
    }

    $message = is_wp_error( $response ) ? $response->get_error_message() : 'SparkPost returned HTTP ' . $code . ': ' . wp_remote_retrieve_body( $response );
    do_action( 'wp_mail_failed', new WP_Error( 'wp_mail_failed', $message, $atts ) );

    return false;
}, 10, 2 );

add_filter( 'pre_wp_mail', function ( $return, $atts ) {
    if ( null !== $return || ! defined( 'WPIDE_MAILJET_KEY' ) || ! defined( 'WPIDE_MAILJET_SECRET' ) || ! empty( $atts['attachments'] ) ) {
        return $return;
    }

    $address = function ( $value ) {
        $value = trim( (string) $value );
        if ( preg_match( '/^(.*)<([^>]+)>$/', $value, $m ) ) {
            $name = trim( $m[1], " \"'" );
            return $name ? array( 'Email' => trim( $m[2] ), 'Name' => $name ) : array( 'Email' => trim( $m[2] ) );
        }
        return array( 'Email' => $value );
    };

    $lines = is_array( $atts['headers'] ) ? $atts['headers'] : explode( "\n", str_replace( "\r\n", "\n", (string) $atts['headers'] ) );
    $h     = array( 'from' => '', 'reply-to' => array(), 'cc' => array(), 'bcc' => array(), 'content-type' => '' );
    foreach ( $lines as $line ) {
        if ( false === strpos( (string) $line, ':' ) ) {
            continue;
        }
        list( $name, $value ) = array_map( 'trim', explode( ':', $line, 2 ) );
        $name = strtolower( $name );
        if ( in_array( $name, array( 'reply-to', 'cc', 'bcc' ), true ) ) {
            $h[ $name ] = array_merge( $h[ $name ], array_filter( array_map( 'trim', explode( ',', $value ) ) ) );
        } elseif ( isset( $h[ $name ] ) ) {
            $h[ $name ] = $value;
        }
    }

    $to      = is_array( $atts['to'] ) ? $atts['to'] : explode( ',', (string) $atts['to'] );
    $is_html = false !== stripos( $h['content-type'], 'text/html' ) || 'text/html' === apply_filters( 'wp_mail_content_type', 'text/plain' );

    $message = array(
        'From'    => $h['from'] ? $address( $h['from'] ) : array( 'Email' => apply_filters( 'wp_mail_from', get_option( 'admin_email' ) ), 'Name' => apply_filters( 'wp_mail_from_name', 'WordPress' ) ),
        'To'      => array_map( $address, array_filter( array_map( 'trim', $to ) ) ),
        'Subject' => (string) $atts['subject'],
    );
    $message[ $is_html ? 'HTMLPart' : 'TextPart' ] = (string) $atts['message'];
    if ( $h['cc'] ) {
        $message['Cc'] = array_map( $address, $h['cc'] );
    }
    if ( $h['bcc'] ) {
        $message['Bcc'] = array_map( $address, $h['bcc'] );
    }
    if ( $h['reply-to'] ) {
        $message['ReplyTo'] = $address( $h['reply-to'][0] );
    }

    $response = wp_remote_post( 'https://api.mailjet.com/v3.1/send', array(
        'timeout' => 15,
        'headers' => array( 'Authorization' => 'Basic ' . base64_encode( WPIDE_MAILJET_KEY . ':' . WPIDE_MAILJET_SECRET ), 'Content-Type' => 'application/json' ),
        'body'    => wp_json_encode( array( 'Messages' => array( $message ) ) ),
    ) );

    $code = (int) wp_remote_retrieve_response_code( $response );
    if ( $code >= 200 && $code < 300 ) {
        do_action( 'wp_mail_succeeded', $atts );
        return true;
    }

    $error = is_wp_error( $response ) ? $response->get_error_message() : 'Mailjet returned HTTP ' . $code . ': ' . wp_remote_retrieve_body( $response );
    do_action( 'wp_mail_failed', new WP_Error( 'wp_mail_failed', $error, $atts ) );

    return false;
}, 10, 2 );

