$wpide_attachment_limit_mb = 15;

add_filter( 'wp_mail', function ( $atts ) use ( $wpide_attachment_limit_mb ) {
    if ( empty( $atts['attachments'] ) ) {
        return $atts;
    }

    $files   = is_array( $atts['attachments'] ) ? $atts['attachments'] : explode( "\n", str_replace( "\r\n", "\n", (string) $atts['attachments'] ) );
    $budget  = $wpide_attachment_limit_mb * MB_IN_BYTES;
    $kept    = array();
    $dropped = array();
    $used    = 0;

    foreach ( $files as $key => $file ) {
        $size = is_readable( $file ) ? (int) ceil( filesize( $file ) * 1.37 ) : 0;
        if ( $used + $size > $budget ) {
            $dropped[] = basename( $file );
            continue;
        }
        $used        += $size;
        $kept[ $key ] = $file;
    }

    if ( $dropped ) {
        $atts['attachments'] = $kept;
        $atts['message']    .= "\n\n(" . count( $dropped ) . ' attachment(s) were too large to send: ' . implode( ', ', $dropped ) . ')';
    }

    return $atts;
}, 40 );

add_filter( 'wp_mail', function ( $atts ) {
    $headers = is_array( $atts['headers'] ) ? implode( "\n", $atts['headers'] ) : (string) $atts['headers'];
    $is_html = false !== stripos( $headers, 'text/html' ) || ( false === stripos( $headers, 'content-type' ) && 'text/html' === apply_filters( 'wp_mail_content_type', 'text/plain' ) );
    $message = (string) $atts['message'];
    $probe   = preg_replace( '/<https?:[^>]+>/', '', $message );

    if ( ! $is_html || $probe !== strip_tags( $probe ) ) {
        return $atts;
    }

    $message         = preg_replace( '/<(https?:[^>]+)>/', '$1', $message );
    $atts['message'] = make_clickable( nl2br( esc_html( $message ) ) );

    return $atts;
}, 15 );

$wpide_max_recipients = 20;

add_filter( 'pre_wp_mail', function ( $return, $atts ) use ( $wpide_max_recipients ) {
    if ( null !== $return ) {
        return $return;
    }

    $count   = count( array_filter( is_array( $atts['to'] ) ? $atts['to'] : explode( ',', (string) $atts['to'] ) ) );
    $headers = is_array( $atts['headers'] ) ? $atts['headers'] : explode( "\n", (string) $atts['headers'] );

    foreach ( $headers as $line ) {
        if ( preg_match( '/^\s*(cc|bcc)\s*:(.*)$/i', (string) $line, $m ) ) {
            $count += count( array_filter( array_map( 'trim', explode( ',', $m[2] ) ) ) );
        }
    }

    if ( $count > $wpide_max_recipients ) {
        do_action( 'wp_mail_failed', new WP_Error( 'wp_mail_failed', sprintf( 'Blocked: %d recipients exceeds the limit of %d.', $count, $wpide_max_recipients ), $atts ) );
        return false;
    }

    return $return;
}, 2, 2 );

