add_action( 'wpide_disk_space_check', function () use ( $wpide_min_free_gb ) {
    if ( ! function_exists( 'disk_free_space' ) || get_transient( 'wpide_disk_alert_sent' ) ) {
        return;
    }

    $free = @disk_free_space( ABSPATH ); // phpcs:ignore WordPress.PHP.NoSilencedErrors
    if ( false === $free || $free >= $wpide_min_free_gb * GB_IN_BYTES ) {
        return;
    }

    set_transient( 'wpide_disk_alert_sent', 1, DAY_IN_SECONDS );
    wp_mail(
        get_option( 'admin_email' ),
        sprintf( '[%s] Low disk space: %s free', wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES ), size_format( $free ) ),
        sprintf( "The server hosting %s has only %s of free disk space left (alert threshold: %d GB).\n\nClear old backups, logs or unused media, or ask your host for more space.", home_url(), size_format( $free ), $wpide_min_free_gb )
    );
} );

$wpide_cron_late_minutes = 60;

add_action( 'admin_init', function () use ( $wpide_cron_late_minutes ) {
    if ( wp_doing_ajax() || ! current_user_can( 'manage_options' ) || get_transient( 'wpide_cron_checked' ) ) {
        return;
    }
    set_transient( 'wpide_cron_checked', 1, HOUR_IN_SECONDS );

    $crons = _get_cron_array();
    if ( ! is_array( $crons ) || ! $crons ) {
        return;
    }

    $oldest = (int) min( array_keys( $crons ) );
    $late   = time() - $oldest;

    if ( $late < $wpide_cron_late_minutes * MINUTE_IN_SECONDS || get_transient( 'wpide_cron_alert_sent' ) ) {
        return;
    }

    set_transient( 'wpide_cron_alert_sent', 1, DAY_IN_SECONDS );
    $hooks = array_keys( (array) $crons[ $oldest ] );

    wp_mail(
        get_option( 'admin_email' ),
        sprintf( '[%s] Scheduled tasks are not running', wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES ) ),
        sprintf( "The oldest scheduled task (%s) is %s overdue, which means WP-Cron is not running.\n\nCheck that DISABLE_WP_CRON is not set without a real server cron job, and that your site can make requests to itself.", implode( ', ', $hooks ), human_time_diff( $oldest ) )
    );
} );

