$wpide_cf7_sender = ''; // e.g. 'Website <hello@yourdomain.com>'; empty = wordpress@yourdomain.

add_filter( 'wpcf7_mail_components', function ( $components ) use ( $wpide_cf7_sender ) {
    $site = preg_replace( '/^www\./', '', (string) wp_parse_url( home_url(), PHP_URL_HOST ) );

    if ( ! preg_match( '/([^<\s]+@[^>\s]+)/', (string) $components['sender'], $m ) ) {
        return $components;
    }

    $address = strtolower( $m[1] );
    $domain  = (string) substr( strrchr( $address, '@' ), 1 );

    if ( '' === $site || $domain === $site || substr( $domain, -strlen( '.' . $site ) ) === '.' . $site ) {
        return $components;
    }

    if ( false === stripos( (string) $components['additional_headers'], 'Reply-To:' ) && is_email( $address ) ) {
        $components['additional_headers'] = trim( $components['additional_headers'] . "\nReply-To: " . $address );
    }

    $components['sender'] = $wpide_cf7_sender ? $wpide_cf7_sender : wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES ) . ' <wordpress@' . $site . '>';

    return $components;
} );

$wpide_gf_from = ''; // e.g. 'hello@yourdomain.com'; empty = wordpress@yourdomain.

add_filter( 'gform_notification', function ( $notification, $form, $entry ) use ( $wpide_gf_from ) {
    $site = preg_replace( '/^www\./', '', (string) wp_parse_url( home_url(), PHP_URL_HOST ) );
    $from = trim( GFCommon::replace_variables( (string) rgar( $notification, 'from' ), $form, $entry, false, false, false, 'text' ) );

    if ( '' === $site || ! is_email( $from ) ) {
        return $notification;
    }

    $domain = strtolower( (string) substr( strrchr( $from, '@' ), 1 ) );
    if ( $domain === $site || substr( $domain, -strlen( '.' . $site ) ) === '.' . $site ) {
        return $notification;
    }

    if ( '' === trim( (string) rgar( $notification, 'replyTo' ) ) ) {
        $notification['replyTo'] = $from;
    }
    $notification['from'] = is_email( $wpide_gf_from ) ? $wpide_gf_from : 'wordpress@' . $site;

    return $notification;
}, 20, 3 );

