add_filter( 'the_content', function ( $content ) {
    if ( false === stripos( $content, '_blank' ) || ! class_exists( 'WP_HTML_Tag_Processor' ) ) {
        return $content;
    }

    // Mark links first, then add the hidden text right before each closing </a>.
    $tags = new WP_HTML_Tag_Processor( $content );

    while ( $tags->next_tag( 'a' ) ) {
        if ( '_blank' === $tags->get_attribute( 'target' ) ) {
            $tags->add_class( 'wpide-new-tab' );
        }
    }

    $content = $tags->get_updated_html();

    return preg_replace_callback( '#(<a\b[^>]*class="[^"]*\bwpide-new-tab\b[^"]*"[^>]*>)(.*?)(</a>)#is', function ( $m ) {
        if ( false !== stripos( $m[2], 'opens in a new' ) ) {
            return $m[0];
        }

        return $m[1] . $m[2] . '<span class="screen-reader-text"> (opens in a new tab)</span>' . $m[3];
    }, $content );
}, 20 );

