add_action( 'enqueue_block_editor_assets', function () {
    wp_register_script( 'wpide-alt-check', '', array( 'wp-plugins', 'wp-editor', 'wp-element', 'wp-data', 'wp-components', 'wp-block-editor' ), null, true );
    wp_enqueue_script( 'wpide-alt-check' );
    wp_add_inline_script( 'wpide-alt-check', <<<'JS'
(function (wp) {
    var el = wp.element.createElement;
    var Panel = (wp.editor && wp.editor.PluginPrePublishPanel) || (wp.editPost && wp.editPost.PluginPrePublishPanel);
    if (!Panel) { return; }
    function collect(blocks, out) {
        blocks.forEach(function (b) {
            if ((b.name === 'core/image' || b.name === 'core/media-text' || b.name === 'core/cover') && !(b.attributes.alt || '').trim() && (b.attributes.url || b.attributes.mediaUrl)) {
                out.push(b);
            }
            if (b.innerBlocks && b.innerBlocks.length) { collect(b.innerBlocks, out); }
        });
        return out;
    }
    function AltPanel() {
