                missing.map(function (b, i) {
                    return el(wp.components.Button, { key: b.clientId, variant: 'link', onClick: function () { select(b.clientId); } }, 'Image ' + (i + 1));
                })
            )
        );
    }
    wp.plugins.registerPlugin('wpide-alt-check', { render: AltPanel });
})(window.wp);
JS
    );
} );

add_action( 'enqueue_block_editor_assets', function () {
    wp_register_script( 'wpide-alt-lock', '', array( 'wp-data', 'wp-editor', 'wp-notices' ), null, true );
    wp_enqueue_script( 'wpide-alt-lock' );
    wp_add_inline_script( 'wpide-alt-lock', <<<'JS'
(function (wp) {
    var locked = false;
    function missingAlt(blocks) {
        return blocks.some(function (b) {
            var noAlt = b.name === 'core/image' && b.attributes.url && !(b.attributes.alt || '').trim();
            return noAlt || (b.innerBlocks && missingAlt(b.innerBlocks));
        });
    }
    wp.data.subscribe(function () {
        var blocks = wp.data.select('core/block-editor').getBlocks();
        var missing = missingAlt(blocks);
        if (missing === locked) { return; }
        locked = missing;
        var editor = wp.data.dispatch('core/editor');
        var notices = wp.data.dispatch('core/notices');
        if (missing) {
            editor.lockPostSaving('wpide-alt');
            notices.createNotice('warning', 'Add alternative text to every image before publishing.', { id: 'wpide-alt', isDismissible: false });
        } else {
            editor.unlockPostSaving('wpide-alt');
            notices.removeNotice('wpide-alt');
        }
    });
})(window.wp);
JS
    );
} );

add_action( 'enqueue_block_editor_assets', function () {
    wp_register_script( 'wpide-heading-outline', '', array( 'wp-plugins', 'wp-editor', 'wp-element', 'wp-data' ), null, true );
    wp_enqueue_script( 'wpide-heading-outline' );
    wp_add_inline_script( 'wpide-heading-outline', <<<'JS'
(function (wp) {
    var el = wp.element.createElement;
    var Panel = (wp.editor && wp.editor.PluginDocumentSettingPanel) || (wp.editPost && wp.editPost.PluginDocumentSettingPanel);
    if (!Panel) { return; }
    function headings(blocks, out) {
        blocks.forEach(function (b) {
            if (b.name === 'core/heading') { out.push(b); }
            if (b.innerBlocks && b.innerBlocks.length) { headings(b.innerBlocks, out); }
        });
        return out;
    }
    function Outline() {
        var list = wp.data.useSelect(function (select) { return headings(select('core/block-editor').getBlocks(), []); }, []);
        var prev = 1;
        var items = list.map(function (b) {
            var level = b.attributes.level || 2;
            var text = String(b.attributes.content || '').replace(/<[^>]+>/g, '').trim();
            var problems = [];
            if (level > prev + 1) { problems.push('skips from H' + prev + ' to H' + level); }
            if (level === 1) { problems.push('extra H1'); }
            if (!text) { problems.push('empty'); }
            prev = level;
            return el('li', { key: b.clientId, style: { marginLeft: (level - 2) * 12 + 'px', color: problems.length ? '#b32d2e' : 'inherit' } },
                'H' + level + ' ' + (text || '(empty)') + (problems.length ? ' - ' + problems.join(', ') : ''));
        });
        return el(Panel, { name: 'wpide-heading-outline', title: 'Heading outline' },
            list.length ? el('ul', { style: { margin: 0 } }, items) : el('p', null, 'No headings yet.'));
    }
    wp.plugins.registerPlugin('wpide-heading-outline', { render: Outline });
})(window.wp);
JS
    );
} );

