add_action( 'pre_get_posts', function ( $query ) {
    if ( ! is_admin() || ! $query->is_main_query() || empty( $_GET['wpide_alt'] ) || 'missing' !== $_GET['wpide_alt'] ) {
        return;
    }

    if ( 'attachment' !== $query->get( 'post_type' ) ) {
        return;
    }

    $query->set( 'post_mime_type', 'image' );
    $query->set( 'meta_query', array(
        'relation' => 'OR',
        array( 'key' => '_wp_attachment_image_alt', 'compare' => 'NOT EXISTS' ),
        array( 'key' => '_wp_attachment_image_alt', 'value' => '' ),
    ) );
} );

$wpide_alt_count = function () {
    global $wpdb;

    $count = get_transient( 'wpide_missing_alt_count' );

    if ( false === $count ) {
        $count = (int) $wpdb->get_var(
            "SELECT COUNT(p.ID) FROM {$wpdb->posts} p
             LEFT JOIN {$wpdb->postmeta} m ON m.post_id = p.ID AND m.meta_key = '_wp_attachment_image_alt'
             WHERE p.post_type = 'attachment' AND p.post_mime_type LIKE 'image/%' AND ( m.meta_value IS NULL OR m.meta_value = '' )"
        );
        set_transient( 'wpide_missing_alt_count', $count, 12 * HOUR_IN_SECONDS );
    }

    return (int) $count;
};

$wpide_alt_flush = function ( $meta_id, $object_id, $meta_key ) {
    if ( '_wp_attachment_image_alt' === $meta_key ) {
        delete_transient( 'wpide_missing_alt_count' );
    }
};
