$wpide_adjacent_label = function ( $output, $format, $link, $post, $adjacent ) {
    if ( ! $output || ! $post || ! class_exists( 'WP_HTML_Tag_Processor' ) ) {
        return $output;
    }

    $tags = new WP_HTML_Tag_Processor( $output );

    if ( $tags->next_tag( 'a' ) && ! $tags->get_attribute( 'aria-label' ) ) {
        $prefix = 'previous' === $adjacent ? 'Previous post: ' : 'Next post: ';
        $tags->set_attribute( 'aria-label', $prefix . wp_strip_all_tags( get_the_title( $post ) ) );
    }

    return $tags->get_updated_html();
};

