// Host fragment => title used when the iframe has none.
$wpide_iframe_titles = array(
    'youtube'     => 'YouTube video',
    'vimeo'       => 'Vimeo video',
    'google.com/maps' => 'Embedded map',
    'spotify'     => 'Spotify player',
    'soundcloud'  => 'SoundCloud player',
    'calendar.google' => 'Embedded calendar',
);

add_filter( 'the_content', function ( $content ) use ( $wpide_iframe_titles ) {
    if ( false === stripos( $content, '<iframe' ) || ! class_exists( 'WP_HTML_Tag_Processor' ) ) {
        return $content;
    }

    $tags = new WP_HTML_Tag_Processor( $content );

    while ( $tags->next_tag( 'iframe' ) ) {
        if ( '' !== trim( (string) $tags->get_attribute( 'title' ) ) ) {
            continue;
        }

        $src   = (string) $tags->get_attribute( 'src' );
        $title = 'Embedded content';

        foreach ( $wpide_iframe_titles as $needle => $label ) {
            if ( false !== stripos( $src, $needle ) ) {
                $title = $label;
                break;
            }
        }

        $tags->set_attribute( 'title', $title );
    }

    return $tags->get_updated_html();
}, 20 );

add_action( 'save_post', function ( $post_id, $post ) {
    if ( wp_is_post_revision( $post_id ) || ! has_block( 'core/video', $post ) || ! current_user_can( 'edit_post', $post_id ) ) {
        return;
    }

    $missing = 0;

    foreach ( parse_blocks( $post->post_content ) as $block ) {
        if ( 'core/video' === $block['blockName'] && empty( $block['attrs']['tracks'] ) ) {
            $missing++;
        }
    }

    if ( $missing ) {
        set_transient( 'wpide_caption_notice_' . get_current_user_id(), $missing, MINUTE_IN_SECONDS );
    }
}, 20, 2 );

