add_filter( 'the_content', function ( $content ) {
    if ( false === stripos( $content, '<th' ) || ! class_exists( 'WP_HTML_Tag_Processor' ) ) {
        return $content;
    }

    $tags     = new WP_HTML_Tag_Processor( $content );
    $row      = 0;
    $in_thead = false;

    while ( $tags->next_tag( array( 'tag_closers' => 'visit' ) ) ) {
        $tag = $tags->get_tag();

        if ( 'THEAD' === $tag ) {
            $in_thead = ! $tags->is_tag_closer();
        } elseif ( 'TABLE' === $tag && ! $tags->is_tag_closer() ) {
            $row = 0;
        } elseif ( 'TR' === $tag && ! $tags->is_tag_closer() ) {
            $row++;
        } elseif ( 'TH' === $tag && ! $tags->is_tag_closer() && null === $tags->get_attribute( 'scope' ) ) {
            $tags->set_attribute( 'scope', ( $in_thead || 1 === $row ) ? 'col' : 'row' );
        }
    }

    return $tags->get_updated_html();
}, 20 );

add_filter( 'the_content', function ( $content ) {
    if ( false === stripos( $content, 'tabindex' ) || ! class_exists( 'WP_HTML_Tag_Processor' ) ) {
        return $content;
    }

    $tags = new WP_HTML_Tag_Processor( $content );

    while ( $tags->next_tag() ) {
        $value = $tags->get_attribute( 'tabindex' );

        if ( null !== $value && (int) $value > 0 ) {
            $tags->set_attribute( 'tabindex', '0' );
        }
    }

    return $tags->get_updated_html();
}, 20 );

