$wpide_strip_autoplay = function ( $html ) {
    if ( false === stripos( $html, 'autoplay' ) || ! class_exists( 'WP_HTML_Tag_Processor' ) ) {
        return $html;
    }

    $tags = new WP_HTML_Tag_Processor( $html );

    while ( $tags->next_tag( 'iframe' ) ) {
        $src = (string) $tags->get_attribute( 'src' );

        if ( preg_match( '#(youtube\.com|youtube-nocookie\.com|player\.vimeo\.com)#i', $src ) ) {
            $tags->set_attribute( 'src', remove_query_arg( array( 'autoplay', 'mute', 'muted', 'background' ), $src ) );
        }

        $allow = (string) $tags->get_attribute( 'allow' );
        if ( $allow ) {
            $tags->set_attribute( 'allow', trim( preg_replace( '/\s*autoplay;?/i', '', $allow ) ) );
        }
    }

    return $tags->get_updated_html();
};

