// Preferred caption language ('' lets YouTube decide).
$wpide_caption_lang = '';

add_filter( 'embed_oembed_html', function ( $html, $url ) use ( $wpide_caption_lang ) {
    if ( ! preg_match( '#youtu\.?be#i', $url ) || ! class_exists( 'WP_HTML_Tag_Processor' ) ) {
        return $html;
    }

    $tags = new WP_HTML_Tag_Processor( $html );

    if ( $tags->next_tag( 'iframe' ) ) {
        $args = array( 'cc_load_policy' => 1 );
        if ( $wpide_caption_lang ) {
            $args['cc_lang_pref'] = $wpide_caption_lang;
        }
        $tags->set_attribute( 'src', add_query_arg( $args, (string) $tags->get_attribute( 'src' ) ) );
    }

    return $tags->get_updated_html();
}, 10, 2 );

// Heading level used for widget titles.
$wpide_widget_heading = 'h2';

add_filter( 'dynamic_sidebar_params', function ( $params ) use ( $wpide_widget_heading ) {
    if ( empty( $params[0] ) || ! is_array( $params[0] ) ) {
        return $params;
    }

    $tag = tag_escape( $wpide_widget_heading );

    if ( isset( $params[0]['before_title'] ) && ! preg_match( '#^\s*<h[1-6]#i', $params[0]['before_title'] ) ) {
        $params[0]['before_title'] = '<' . $tag . ' class="widget-title widgettitle">';
        $params[0]['after_title']  = '</' . $tag . '>';
    }

    return $params;
} );

