add_filter( 'render_block_core/image', function ( $html ) {
    if ( false === stripos( $html, '<figcaption' ) || ! class_exists( 'WP_HTML_Tag_Processor' ) ) {
        return $html;
    }

    if ( ! preg_match( '#<figcaption[^>]*>(.*?)</figcaption>#is', $html, $m ) ) {
        return $html;
    }

    $caption = trim( wp_strip_all_tags( $m[1] ) );
    $tags    = new WP_HTML_Tag_Processor( $html );

    if ( $caption && $tags->next_tag( 'img' ) && '' === trim( (string) $tags->get_attribute( 'alt' ) ) ) {
        $tags->set_attribute( 'alt', wp_html_excerpt( $caption, 150, '' ) );
        return $tags->get_updated_html();
    }

    return $html;
} );

add_filter( 'the_content', function ( $content ) {
    if ( false === stripos( $content, 'title=' ) || ! class_exists( 'WP_HTML_Tag_Processor' ) ) {
        return $content;
    }

    $tags = new WP_HTML_Tag_Processor( $content );

    while ( $tags->next_tag( 'img' ) ) {
        $title = trim( (string) $tags->get_attribute( 'title' ) );

        if ( '' !== $title && strtolower( $title ) === strtolower( trim( (string) $tags->get_attribute( 'alt' ) ) ) ) {
            $tags->remove_attribute( 'title' );
        }
    }

    return $tags->get_updated_html();
}, 20 );

// Accessible name for the search field.
$wpide_search_label = 'Search this site';

add_filter( 'get_search_form', function ( $form ) use ( $wpide_search_label ) {
    if ( false !== stripos( $form, '<label' ) || ! class_exists( 'WP_HTML_Tag_Processor' ) ) {
        return $form;
    }

    $tags = new WP_HTML_Tag_Processor( $form );

    while ( $tags->next_tag( 'input' ) ) {
        if ( ( 's' === $tags->get_attribute( 'name' ) || 'search' === $tags->get_attribute( 'type' ) ) && ! $tags->get_attribute( 'aria-label' ) ) {
            $tags->set_attribute( 'aria-label', $wpide_search_label );
        }
    }

    return $tags->get_updated_html();
}, 20 );

