if ( defined( 'WP_CLI' ) && WP_CLI && class_exists( 'WP_HTML_Tag_Processor' ) ) {
    WP_CLI::add_command( 'a11y-scan', function ( $args, $assoc ) {
        $type   = isset( $assoc['post_type'] ) ? sanitize_key( $assoc['post_type'] ) : 'post,page';
        $format = isset( $assoc['format'] ) ? $assoc['format'] : 'table';
        $rows   = array();
        $paged  = 1;

        do {
            $posts = get_posts( array(
                'post_type'      => explode( ',', $type ),
                'post_status'    => 'publish',
                'posts_per_page' => 100,
                'paged'          => $paged++,
                'orderby'        => 'ID',
                'order'          => 'ASC',
            ) );

            foreach ( $posts as $post ) {
                $issues = array();
                $tags   = new WP_HTML_Tag_Processor( $post->post_content );
                $level  = 1;
                while ( $tags->next_tag() ) {
                    $tag = $tags->get_tag();
                    if ( 'IMG' === $tag && null === $tags->get_attribute( 'alt' ) ) {
                        $issues['img'] = 'image without alt';
                    } elseif ( 'IFRAME' === $tag && ! $tags->get_attribute( 'title' ) ) {
                        $issues['iframe'] = 'iframe without title';
                    } elseif ( preg_match( '/^H([1-6])$/', (string) $tag, $m ) ) {
                        if ( (int) $m[1] > $level + 1 ) {
                            $issues['heading'] = 'skipped heading level';
                        }
                        $level = (int) $m[1];
                    }
                    if ( (int) $tags->get_attribute( 'tabindex' ) > 0 ) {
                        $issues['tabindex'] = 'positive tabindex';
                    }
                }
                if ( preg_match( '#<a\b[^>]*>\s*</a>#i', $post->post_content ) ) {
                    $issues['link'] = 'empty link';
                }
                if ( $issues ) {
                    $rows[] = array( 'ID' => $post->ID, 'type' => $post->post_type, 'title' => $post->post_title, 'issues' => implode( '; ', $issues ), 'url' => get_permalink( $post ) );
                }
            }
        } while ( count( $posts ) === 100 );

        if ( ! $rows ) {
            WP_CLI::success( 'No problems found.' );
            return;
        }

        WP_CLI\Utils\format_items( $format, $rows, array( 'ID', 'type', 'title', 'issues', 'url' ) );
    }, array( 'shortdesc' => 'Scan published content for common accessibility problems.' ) );
}

add_action( 'admin_menu', function () {
    add_management_page( 'Accessibility Report', 'Accessibility Report', 'edit_others_posts', 'wpide-a11y-report', function () {
        $paged = max( 1, isset( $_GET['paged'] ) ? absint( $_GET['paged'] ) : 1 );
        $query = new WP_Query( array(
            'post_type'      => array( 'post', 'page' ),
            'post_status'    => 'publish',
            'posts_per_page' => 100,
            'paged'          => $paged,
            'orderby'        => 'modified',
        ) );

        echo '<div class="wrap"><h1>Accessibility Report</h1><table class="widefat striped"><thead><tr><th>Content</th><th>Problems</th></tr></thead><tbody>';
        $found = 0;
        foreach ( $query->posts as $post ) {
            $issues = array();
            if ( class_exists( 'WP_HTML_Tag_Processor' ) ) {
                $tags  = new WP_HTML_Tag_Processor( $post->post_content );
                $level = 1;
                while ( $tags->next_tag() ) {
                    $tag = $tags->get_tag();
                    if ( 'IMG' === $tag && null === $tags->get_attribute( 'alt' ) ) {
                        $issues['img'] = 'image without alt text';
                    } elseif ( 'IFRAME' === $tag && ! $tags->get_attribute( 'title' ) ) {
                        $issues['iframe'] = 'embed without a title';
                    } elseif ( preg_match( '/^H([1-6])$/', (string) $tag, $m ) ) {
                        if ( (int) $m[1] > $level + 1 ) {
                            $issues['heading'] = 'skipped heading level';
                        }
                        $level = (int) $m[1];
                    }
                }
            }
            if ( preg_match( '#<a\b[^>]*>\s*</a>#i', $post->post_content ) ) {
                $issues['link'] = 'empty link';
            }
            if ( ! $issues ) {
                continue;
            }
            $found++;
            printf( '<tr><td><a href="%s">%s</a> <span class="description">(%s)</span></td><td>%s</td></tr>', esc_url( get_edit_post_link( $post->ID ) ), esc_html( $post->post_title ? $post->post_title : '#' . $post->ID ), esc_html( $post->post_type ), esc_html( implode( ', ', $issues ) ) );
        }
        if ( ! $found ) {
            echo '<tr><td colspan="2">No problems found on this page of results.</td></tr>';
        }
        echo '</tbody></table>';
        if ( $query->max_num_pages > 1 ) {
            echo '<p>' . wp_kses_post( paginate_links( array( 'base' => add_query_arg( 'paged', '%#%' ), 'format' => '', 'current' => $paged, 'total' => $query->max_num_pages ) ) ) . '</p>';
        }
        echo '</div>';
    } );
} );

