@function wpide-text-on($bg) {
    $brightness: (red($bg) * 299 + green($bg) * 587 + blue($bg) * 114) / 1000;
    @if $brightness > 150 {
        @return #111111;
    }
    @return #ffffff;
}

@mixin wpide-button($bg) {
    background-color: $bg;
    color: wpide-text-on($bg);
    border: 2px solid darken($bg, 12%);

    &:hover {
        background-color: darken($bg, 8%);
        color: wpide-text-on(darken($bg, 8%));
    }

    &:focus-visible {
        outline: 3px solid wpide-text-on($bg);
        outline-offset: -5px;
        box-shadow: 0 0 0 3px darken($bg, 20%);
    }
}

