$wpide_hash_version = function ( $src ) {
    if ( ! is_string( $src ) || false === strpos( $src, 'ver=' ) || false === strpos( $src, '/wp-content/' ) ) {
        return $src;
    }

    $query = (string) wp_parse_url( $src, PHP_URL_QUERY );
    parse_str( $query, $args );

    if ( empty( $args['ver'] ) ) {
        return $src;
    }

    return add_query_arg( 'ver', substr( wp_hash( $args['ver'] . '|' . strtok( $src, '?' ) ), 0, 8 ), $src );
};

