add_filter( 'the_content', function ( $content ) {
    if ( false === stripos( $content, '<img' ) ) {
        return $content;
    }

    return preg_replace_callback( '#<a\b([^>]*)>\s*(<img\b[^>]*>)\s*</a>#i', function ( $m ) {
        if ( preg_match( '#\baria-label=#i', $m[1] ) || ( preg_match( '#\balt=(["\'])(.*?)\1#i', $m[2], $alt ) && '' !== trim( $alt[2] ) ) ) {
            return $m[0];
        }

        if ( ! preg_match( '#\bhref=(["\'])(.*?)\1#i', $m[1], $href ) ) {
            return $m[0];
        }

        $url     = html_entity_decode( $href[2] );
        $key     = 'wpide_linkname_' . md5( $url );
        $post_id = wp_cache_get( $key, 'wpide' );

        if ( false === $post_id ) {
            $post_id = (int) url_to_postid( $url );
            wp_cache_set( $key, $post_id, 'wpide', HOUR_IN_SECONDS );
        }

        if ( ! $post_id ) {
            return $m[0];
        }

        return '<a' . $m[1] . ' aria-label="' . esc_attr( wp_strip_all_tags( get_the_title( $post_id ) ) ) . '">' . $m[2] . '</a>';
    }, $content );
}, 20 );

