// Uploads allowed per user per hour.
$wpide_upload_hourly = 30;

add_filter( 'wp_handle_upload_prefilter', function ( $file ) use ( $wpide_upload_hourly ) {
    if ( ! empty( $file['error'] ) || ! is_user_logged_in() || current_user_can( 'manage_options' ) ) {
        return $file;
    }

    $key   = 'wpide_uploads_' . get_current_user_id();
    $count = (int) get_transient( $key );

    if ( $count >= $wpide_upload_hourly ) {
        $file['error'] = sprintf( 'You have reached the limit of %d uploads per hour. Please try again later.', $wpide_upload_hourly );
        return $file;
    }

    set_transient( $key, $count + 1, HOUR_IN_SECONDS );

    return $file;
}, 20 );

// Hosts whose iframes are left alone (subdomains included).
$wpide_trusted_frames = array( 'youtube.com', 'youtube-nocookie.com', 'vimeo.com', 'google.com', 'spotify.com', 'soundcloud.com' );

add_filter( 'the_content', function ( $content ) use ( $wpide_trusted_frames ) {
    if ( false === stripos( $content, '<iframe' ) || ! class_exists( 'WP_HTML_Tag_Processor' ) ) {
        return $content;
    }

    $own  = wp_parse_url( home_url(), PHP_URL_HOST );
    $tags = new WP_HTML_Tag_Processor( $content );

    while ( $tags->next_tag( 'iframe' ) ) {
        $host = strtolower( (string) wp_parse_url( (string) $tags->get_attribute( 'src' ), PHP_URL_HOST ) );

        if ( ! $host || $host === $own || null !== $tags->get_attribute( 'sandbox' ) ) {
            continue;
        }

        foreach ( $wpide_trusted_frames as $trusted ) {
            if ( $host === $trusted || substr( $host, -strlen( '.' . $trusted ) ) === '.' . $trusted ) {
                continue 2;
            }
        }

        $tags->set_attribute( 'sandbox', 'allow-scripts allow-same-origin allow-forms' );
        $tags->set_attribute( 'referrerpolicy', 'no-referrer' );
    }

    return $tags->get_updated_html();
}, 20 );

