        global $wpdb;

        $prefix  = isset( $_POST['wpide_prefix'] ) ? sanitize_key( wp_unslash( $_POST['wpide_prefix'] ) ) : '';
        $blocked = array( 'wp_', 'wp', '_wp', 'widget', 'theme', 'user', 'site', 'blog', 'woocommerce', 'wc_', '_transient', '_site_transient' );
        $valid   = strlen( $prefix ) >= 4 && ! in_array( $prefix, $blocked, true ) && 0 !== strpos( $prefix, $wpdb->prefix );
        $counts  = array();

        if ( $prefix && isset( $_POST['_wpnonce'] ) && check_admin_referer( 'wpide_leftovers' ) ) {
            if ( ! $valid ) {
                echo '<div class="notice notice-error"><p>Please use a more specific prefix (at least 4 characters, not a WordPress prefix).</p></div>';
            } else {
                $like   = $wpdb->esc_like( $prefix ) . '%';
                $counts = array(
                    'Options'   => (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$wpdb->options} WHERE option_name LIKE %s", $like ) ),
                    'Post meta' => (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$wpdb->postmeta} WHERE meta_key LIKE %s", $like ) ),
                    'User meta' => (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$wpdb->usermeta} WHERE meta_key LIKE %s", $like ) ),
                );
                $cron = 0;
                foreach ( (array) _get_cron_array() as $hooks ) {
                    foreach ( array_keys( (array) $hooks ) as $hook ) {
                        $cron += 0 === strpos( $hook, $prefix ) ? 1 : 0;
                    }
                }
                $counts['Scheduled tasks'] = $cron;

                if ( isset( $_POST['wpide_delete_leftovers'] ) && current_user_can( 'manage_options' ) ) {
                    $wpdb->query( $wpdb->prepare( "DELETE FROM {$wpdb->options} WHERE option_name LIKE %s", $like ) );
                    $wpdb->query( $wpdb->prepare( "DELETE FROM {$wpdb->postmeta} WHERE meta_key LIKE %s", $like ) );
                    $wpdb->query( $wpdb->prepare( "DELETE FROM {$wpdb->usermeta} WHERE meta_key LIKE %s", $like ) );
                    foreach ( (array) _get_cron_array() as $hooks ) {
                        foreach ( array_keys( (array) $hooks ) as $hook ) {
                            if ( 0 === strpos( $hook, $prefix ) ) {
                                wp_unschedule_hook( $hook );
                            }
                        }
                    }
                    wp_cache_flush();
                    printf( '<div class="notice notice-success"><p>%s</p></div>', esc_html( sprintf( 'Deleted %d item(s) starting with "%s".', array_sum( $counts ), $prefix ) ) );
                    $counts = array();
