// User agent fragments (lowercase) that are never real browsers.
$wpide_script_agents = array( 'curl/', 'wget/', 'python-requests', 'python-urllib', 'go-http-client', 'libwww-perl', 'java/', 'okhttp', 'httpclient', 'scrapy', 'masscan', 'nikto', 'wpscan' );

add_action( 'login_init', function () use ( $wpide_script_agents ) {
    if ( 'POST' !== ( isset( $_SERVER['REQUEST_METHOD'] ) ? $_SERVER['REQUEST_METHOD'] : '' ) ) {
        return;
    }

    $agent = isset( $_SERVER['HTTP_USER_AGENT'] ) ? strtolower( sanitize_text_field( wp_unslash( $_SERVER['HTTP_USER_AGENT'] ) ) ) : '';
    $block = '' === $agent;

    foreach ( $wpide_script_agents as $fragment ) {
        if ( false !== strpos( $agent, $fragment ) ) {
            $block = true;
            break;
        }
    }

    if ( $block ) {
        status_header( 403 );
        nocache_headers();
        exit( 'Forbidden.' );
    }
}, 0 );

