add_action( 'user_profile_update_errors', function ( $errors, $update, $user ) {
    if ( ! $update || empty( $user->ID ) || get_current_user_id() !== (int) $user->ID ) {
        return;
    }

    $current = get_userdata( $user->ID );
    $changes = ( ! empty( $user->user_pass ) ) || ( isset( $user->user_email ) && strtolower( $user->user_email ) !== strtolower( $current->user_email ) );

    if ( ! $changes ) {
        return;
    }

    $given = isset( $_POST['wpide_current_pass'] ) ? (string) wp_unslash( $_POST['wpide_current_pass'] ) : '';

    if ( '' === $given || ! wp_check_password( $given, $current->user_pass, $current->ID ) ) {
        $errors->add( 'wpide_current_pass', '<strong>Error:</strong> Enter your current password to change your email address or password.' );
    }
}, 10, 3 );

