                esc_html( number_format_i18n( (int) $t->row_count ) ),
                esc_html( size_format( (int) $t->data, 1 ) ),
                esc_html( size_format( (int) $t->idx, 1 ) ),
                esc_html( $t->free ? size_format( (int) $t->free, 1 ) : '-' )
            );
            if ( $t->free > MB_IN_BYTES ) {
                echo '<form method="post" style="margin:0">';
                wp_nonce_field( 'wpide_optimize_table' );
                echo '<button class="button button-small" name="wpide_optimize" value="' . esc_attr( $t->name ) . '">Optimize</button></form>';
            }
            echo '</td></tr>';
        }
        printf( '</tbody></table><p><strong>%s</strong></p></div>', esc_html( 'Total size: ' . size_format( $total, 1 ) ) );
    } );
} );

