add_action( 'wpide_purge_sessions', function () {
    global $wpdb;

    $rows = $wpdb->get_results( "SELECT user_id, meta_value FROM {$wpdb->usermeta} WHERE meta_key = 'session_tokens' LIMIT 500" );

    foreach ( $rows as $row ) {
        $sessions = maybe_unserialize( $row->meta_value );

        if ( ! is_array( $sessions ) ) {
            continue;
        }

        $active = array_filter( $sessions, function ( $session ) {
            return isset( $session['expiration'] ) && $session['expiration'] >= time();
        } );

        if ( count( $active ) === count( $sessions ) ) {
            continue;
        }

        if ( $active ) {
            update_user_meta( (int) $row->user_id, 'session_tokens', $active );
        } else {
            delete_user_meta( (int) $row->user_id, 'session_tokens' );
        }
    }
} );

