$wpide_query_report = function () {
    global $wpdb;

    if ( ! isset( $_GET['wpide_queries'] ) || ! current_user_can( 'manage_options' ) || empty( $wpdb->queries ) ) {
        return;
    }

    $groups = array();
    foreach ( $wpdb->queries as $q ) {
        $sql = preg_replace( '/\s+/', ' ', trim( $q[0] ) );
        if ( ! isset( $groups[ $sql ] ) ) {
            $groups[ $sql ] = array( 'count' => 0, 'time' => 0.0, 'caller' => $q[2] );
        }
        $groups[ $sql ]['count']++;
        $groups[ $sql ]['time'] += (float) $q[1];
    }

    $dupes = array_filter( $groups, function ( $g ) {
        return $g['count'] > 1;
    } );
    uasort( $dupes, function ( $a, $b ) {
        return $b['count'] <=> $a['count'];
    } );
    $slow = $wpdb->queries;
    usort( $slow, function ( $a, $b ) {
        return $b[1] <=> $a[1];
    } );

    echo '<div style="position:relative;z-index:99999;background:#fff;color:#1d2327;padding:16px;font:13px/1.5 monospace;border-top:4px solid #2271b1;">';
    printf( '<p><strong>%s</strong></p>', esc_html( sprintf( '%d queries, %d duplicated statements.', count( $wpdb->queries ), count( $dupes ) ) ) );
    echo '<p><strong>Duplicated queries</strong></p><ol>';
    foreach ( array_slice( $dupes, 0, 25, true ) as $sql => $g ) {
        printf( '<li>%s &times; %s <br><small>%s</small></li>', (int) $g['count'], esc_html( wp_html_excerpt( $sql, 300, '...' ) ), esc_html( $g['caller'] ) );
    }
    echo '</ol><p><strong>Slowest queries</strong></p><ol>';
    foreach ( array_slice( $slow, 0, 10 ) as $q ) {
        printf( '<li>%.4fs %s <br><small>%s</small></li>', (float) $q[1], esc_html( wp_html_excerpt( preg_replace( '/\s+/', ' ', $q[0] ), 300, '...' ) ), esc_html( $q[2] ) );
    }
    echo '</ol></div>';
};

