// Requests slower than this many seconds are logged.
$wpide_http_slow = 1.0;

add_filter( 'pre_http_request', function ( $pre, $args, $url ) {
    $GLOBALS['wpide_http_timers'][ md5( $url ) ] = microtime( true );
    return $pre;
}, 1, 3 );

add_action( 'http_api_debug', function ( $response, $context, $class, $args, $url ) use ( $wpide_http_slow ) {
    $key = md5( $url );

    if ( empty( $GLOBALS['wpide_http_timers'][ $key ] ) ) {
        return;
    }

    $time = microtime( true ) - $GLOBALS['wpide_http_timers'][ $key ];
    unset( $GLOBALS['wpide_http_timers'][ $key ] );

    if ( $time < $wpide_http_slow ) {
        return;
    }

    $parts   = wp_parse_url( $url );
    $clean   = ( isset( $parts['host'] ) ? $parts['host'] : '' ) . ( isset( $parts['path'] ) ? $parts['path'] : '' );
    $where   = is_admin() ? 'admin' : ( wp_doing_cron() ? 'cron' : 'front' );
    $log     = (array) get_option( 'wpide_slow_http', array() );
    $log[]   = array(
        'url'    => $clean,
        'method' => isset( $args['method'] ) ? $args['method'] : 'GET',
        'time'   => round( $time, 2 ),
        'status' => is_wp_error( $response ) ? $response->get_error_message() : wp_remote_retrieve_response_code( $response ),
        'where'  => $where,
        'when'   => time(),
    );

    update_option( 'wpide_slow_http', array_slice( $log, -100 ), false );
}, 10, 5 );

