add_filter( 'script_loader_tag', function ( $tag, $handle, $src ) use ( $wpide_delay_scripts ) {
    $match = false;

    foreach ( $wpide_delay_scripts as $needle ) {
        if ( $handle === $needle || ( $src && false !== strpos( $src, $needle ) ) ) {
            $match = true;
            break;
        }
