(function () {
    var done = false, events = ['scroll', 'pointerdown', 'keydown', 'touchstart', 'mousemove'];
    function run() {
        if (done) { return; }
        done = true;
        events.forEach(function (e) { window.removeEventListener(e, run, { passive: true }); });
        var list = Array.prototype.slice.call(document.querySelectorAll('script[type="text/wpide-delay"]'));
        (function next() {
