            if (old.src) { s.onload = s.onerror = next; s.async = false; } else { s.text = old.text; }
            old.parentNode.replaceChild(s, old);
            if (!old.src) { next(); }
        })();
    }
    events.forEach(function (e) { window.addEventListener(e, run, { passive: true }); });
    <?php if ( $wpide_delay_timeout > 0 ) : ?>
