add_filter( 'wp_preload_resources', function ( $resources ) use ( $wpide_preload_handles ) {
    foreach ( $wpide_preload_handles as $handle => $type ) {
        $registry = 'script' === $type ? wp_scripts() : wp_styles();

        if ( empty( $registry->registered[ $handle ] ) || ! in_array( $handle, $registry->queue, true ) || ! $registry->registered[ $handle ]->src ) {
            continue;
        }

        $item = $registry->registered[ $handle ];
        $src  = $item->src;

        if ( ! preg_match( '#^(https?:)?//#', $src ) ) {
            $src = $registry->base_url . $src;
        }

        $ver = $item->ver ? $item->ver : $registry->default_version;
        $resources[] = array(
            'href' => add_query_arg( 'ver', $ver, $src ),
            'as'   => 'script' === $type ? 'script' : 'style',
        );
    }

    return $resources;
} );

