add_filter( 'the_content', function ( $content ) {
    if ( false === stripos( $content, '<img' ) || ! class_exists( 'WP_HTML_Tag_Processor' ) ) {
        return $content;
    }

    $uploads = wp_get_upload_dir();
    $base    = set_url_scheme( $uploads['baseurl'], 'https' );
    $tags    = new WP_HTML_Tag_Processor( $content );

    while ( $tags->next_tag( 'img' ) ) {
        if ( $tags->get_attribute( 'width' ) && $tags->get_attribute( 'height' ) ) {
            continue;
        }

        $src = set_url_scheme( strtok( (string) $tags->get_attribute( 'src' ), '?' ), 'https' );

        if ( 0 !== strpos( $src, $base ) ) {
            continue;
        }

        $key  = 'wpide_dim_' . md5( $src );
        $size = wp_cache_get( $key, 'wpide' );

        if ( false === $size ) {
            $size = get_transient( $key );
        }

        if ( false === $size ) {
            $path = $uploads['basedir'] . substr( $src, strlen( $base ) );
            $info = ( false === strpos( $path, '..' ) && is_readable( $path ) ) ? wp_getimagesize( $path ) : false;
            $size = $info ? array( (int) $info[0], (int) $info[1] ) : array( 0, 0 );
            set_transient( $key, $size, MONTH_IN_SECONDS );
        }

        wp_cache_set( $key, $size, 'wpide' );

        if ( $size[0] && $size[1] ) {
            $tags->set_attribute( 'width', (string) $size[0] );
            $tags->set_attribute( 'height', (string) $size[1] );
        }
    }

    return $tags->get_updated_html();
}, 20 );

// Your CDN address, without a trailing slash.
$wpide_cdn_url = 'https://cdn.example.com';
// Folders whose files are served from the CDN.
$wpide_cdn_dirs = array( 'wp-content/uploads', 'wp-content/themes', 'wp-content/plugins', 'wp-includes' );

if ( 'https://cdn.example.com' !== $wpide_cdn_url ) {
    $wpide_cdn_rewrite = function ( $url ) use ( $wpide_cdn_url, $wpide_cdn_dirs ) {
        if ( ! is_string( $url ) || is_admin() || is_preview() || is_customize_preview() ) {
            return $url;
        }

        $site = untrailingslashit( set_url_scheme( site_url(), 'https' ) );

        foreach ( $wpide_cdn_dirs as $dir ) {
            foreach ( array( $site, set_url_scheme( $site, 'http' ) ) as $origin ) {
                if ( 0 === strpos( $url, $origin . '/' . $dir . '/' ) ) {
                    return untrailingslashit( $wpide_cdn_url ) . substr( $url, strlen( $origin ) );
                }
            }
        }

        return $url;
    };

    add_filter( 'wp_get_attachment_url', $wpide_cdn_rewrite, 99 );
    add_filter( 'script_loader_src', $wpide_cdn_rewrite, 99 );
    add_filter( 'style_loader_src', $wpide_cdn_rewrite, 99 );
    add_filter( 'wp_calculate_image_srcset', function ( $sources ) use ( $wpide_cdn_rewrite ) {
        foreach ( (array) $sources as $width => $source ) {
            $sources[ $width ]['url'] = $wpide_cdn_rewrite( $source['url'] );
        }
        return $sources;
    }, 99 );
    add_filter( 'the_content', function ( $content ) use ( $wpide_cdn_url ) {
        $uploads = wp_get_upload_dir();
        $from    = set_url_scheme( $uploads['baseurl'], 'https' );
        $to      = untrailingslashit( $wpide_cdn_url ) . wp_make_link_relative( $from );

        return str_replace( array( $from, set_url_scheme( $from, 'http' ) ), $to, $content );
    }, 99 );
}

$wpide_mtime_version = function ( $src ) {
    if ( ! is_string( $src ) || false !== strpos( $src, '/wp-includes/' ) || false !== strpos( $src, '/wp-admin/' ) ) {
        return $src;
    }

    $content_url = set_url_scheme( content_url(), 'https' );
    $clean       = set_url_scheme( strtok( $src, '?' ), 'https' );

    if ( 0 !== strpos( $clean, $content_url ) ) {
        return $src;
    }

    $path = WP_CONTENT_DIR . substr( $clean, strlen( $content_url ) );

    if ( false !== strpos( $path, '..' ) || ! is_file( $path ) ) {
        return $src;
    }

    return add_query_arg( 'ver', (string) filemtime( $path ), $src );
};

