        'callback'               => function ( $email ) use ( $wpide_export_user_meta ) {
            $user = get_user_by( 'email', $email );
            $data = array();

            if ( $user ) {
                foreach ( $wpide_export_user_meta as $key => $label ) {
                    $value = get_user_meta( $user->ID, $key, true );
                    if ( '' !== $value && null !== $value ) {
                        $data[] = array( 'name' => $label, 'value' => is_scalar( $value ) ? (string) $value : wp_json_encode( $value ) );
                    }
                }
            }

            return array(
                'data' => $data ? array( array( 'group_id' => 'wpide-profile', 'group_label' => 'Extra profile fields', 'item_id' => 'user-' . ( $user ? $user->ID : 0 ), 'data' => $data ) ) : array(),
                'done' => true,
            );
