                $data = array();
                foreach ( $wpide_comment_meta_fields as $key => $label ) {
                    $value = get_comment_meta( $id, $key, true );
                    if ( '' !== $value ) {
                        $data[] = array( 'name' => $label, 'value' => is_scalar( $value ) ? (string) $value : wp_json_encode( $value ) );
                    }
                }
                if ( $data ) {
                    $items[] = array( 'group_id' => 'comments', 'group_label' => 'Comments', 'item_id' => 'comment-' . $id, 'data' => $data );
                }
            }

            return array( 'data' => $items, 'done' => count( $ids ) < 100 );
        },
    );

    return $exporters;
} );

add_filter( 'wp_privacy_personal_data_erasers', function ( $erasers ) use ( $wpide_comment_meta_fields, $wpide_comment_ids_for ) {
    $erasers['wpide-comment-meta'] = array(
