add_filter( 'style_loader_src', function ( $src ) {
    if ( ! is_string( $src ) || false === strpos( $src, 'fonts.googleapis.com' ) ) {
        return $src;
    }

    $key   = md5( html_entity_decode( $src ) );
    $local = (array) get_option( 'wpide_local_gfonts', array() );

    if ( ! empty( $local[ $key ] ) ) {
        $uploads = wp_get_upload_dir();
        return $uploads['baseurl'] . '/wpide-fonts/' . $key . '.css';
    }

    $found = (array) get_option( 'wpide_found_gfonts', array() );
    if ( ! isset( $found[ $key ] ) && count( $found ) < 20 ) {
        $found[ $key ] = html_entity_decode( $src );
        update_option( 'wpide_found_gfonts', $found, false );
    }

    return $src;
}, 99 );

