}, 99 );

add_action( 'admin_menu', function () {
    add_management_page( 'Local Google Fonts', 'Local Google Fonts', 'manage_options', 'wpide-local-fonts', function () {
        $found   = (array) get_option( 'wpide_found_gfonts', array() );
        $local   = (array) get_option( 'wpide_local_gfonts', array() );
        $uploads = wp_get_upload_dir();
        $dir     = trailingslashit( $uploads['basedir'] ) . 'wpide-fonts';

        if ( isset( $_POST['wpide_font_key'] ) && check_admin_referer( 'wpide_local_fonts' ) && current_user_can( 'manage_options' ) ) {
            $key = sanitize_key( wp_unslash( $_POST['wpide_font_key'] ) );

            if ( isset( $found[ $key ] ) && wp_mkdir_p( $dir ) ) {
                $agent    = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36';
                $response = wp_safe_remote_get( set_url_scheme( $found[ $key ], 'https' ), array( 'timeout' => 15, 'user-agent' => $agent ) );
                $css      = wp_remote_retrieve_body( $response );
                $ok       = 200 === wp_remote_retrieve_response_code( $response ) && false !== strpos( $css, '@font-face' );

                if ( $ok && preg_match_all( '#url\((https://fonts\.gstatic\.com/[^)]+)\)#', $css, $m ) ) {
                    foreach ( array_unique( $m[1] ) as $font_url ) {
                        $file = $key . '-' . md5( $font_url ) . '.' . pathinfo( wp_parse_url( $font_url, PHP_URL_PATH ), PATHINFO_EXTENSION );
                        $get  = wp_safe_remote_get( $font_url, array( 'timeout' => 15, 'stream' => true, 'filename' => $dir . '/' . $file ) );
                        if ( is_wp_error( $get ) || 200 !== wp_remote_retrieve_response_code( $get ) ) {
                            $ok = false;
                            break;
                        }
                        $css = str_replace( $font_url, $uploads['baseurl'] . '/wpide-fonts/' . $file, $css );
                    }
                }

                if ( $ok && false !== file_put_contents( $dir . '/' . $key . '.css', $css ) ) {
                    $local[ $key ] = time();
                    update_option( 'wpide_local_gfonts', $local, false );
                    echo '<div class="notice notice-success"><p>Fonts downloaded. Your site now serves them locally.</p></div>';
