                    echo '<div class="notice notice-error"><p>The fonts could not be downloaded. Check that your server can reach fonts.googleapis.com.</p></div>';
                }
            }
        }

        echo '<div class="wrap"><h1>Local Google Fonts</h1>';
        if ( ! $found ) {
            echo '<p>No Google Fonts detected yet. Visit some pages of your site, then come back.</p></div>';
            return;
        }
        echo '<table class="widefat striped"><thead><tr><th>Stylesheet</th><th>Status</th><th></th></tr></thead><tbody>';
        foreach ( $found as $key => $url ) {
            echo '<tr><td><code>' . esc_html( $url ) . '</code></td><td>' . ( isset( $local[ $key ] ) ? 'Served locally' : 'Loaded from Google' ) . '</td><td>';
            echo '<form method="post">';
            wp_nonce_field( 'wpide_local_fonts' );
            echo '<input type="hidden" name="wpide_font_key" value="' . esc_attr( $key ) . '">';
            submit_button( isset( $local[ $key ] ) ? 'Download again' : 'Download and serve locally', 'secondary small', 'submit', false );
            echo '</form></td></tr>';
        }
        echo '</tbody></table></div>';
    } );
} );

// Domains that should still receive the referrer.
$wpide_referrer_allowed = array( 'amazon.com' );

add_filter( 'the_content', function ( $content ) use ( $wpide_referrer_allowed ) {
    if ( false === stripos( $content, '<a' ) || ! class_exists( 'WP_HTML_Tag_Processor' ) ) {
        return $content;
    }

    $own  = wp_parse_url( home_url(), PHP_URL_HOST );
    $tags = new WP_HTML_Tag_Processor( $content );

    while ( $tags->next_tag( 'a' ) ) {
        $host = wp_parse_url( (string) $tags->get_attribute( 'href' ), PHP_URL_HOST );

        if ( ! $host || $host === $own ) {
            continue;
        }

        foreach ( $wpide_referrer_allowed as $domain ) {
            if ( $host === $domain || substr( $host, -strlen( '.' . $domain ) ) === '.' . $domain ) {
                continue 2;
            }
        }

        $rel = preg_split( '/\s+/', trim( (string) $tags->get_attribute( 'rel' ) ), -1, PREG_SPLIT_NO_EMPTY );
        $rel = array_unique( array_merge( $rel, array( 'noreferrer', 'noopener' ) ) );
        $tags->set_attribute( 'rel', implode( ' ', $rel ) );
    }

    return $tags->get_updated_html();
}, 20 );

