add_action( 'rest_api_init', function () use ( $wpide_consent_table ) {
    register_rest_route( 'wpide/v1', '/consent', array(
        'methods'             => 'POST',
        'permission_callback' => '__return_true',
        'args'                => array(
            'choice'     => array( 'type' => 'string', 'enum' => array( 'granted', 'denied', 'partial' ), 'required' => true ),
            'categories' => array( 'type' => 'string', 'default' => '' ),
        ),
        'callback'            => function ( WP_REST_Request $request ) use ( $wpide_consent_table ) {
            global $wpdb;

            $ip   = isset( $_SERVER['REMOTE_ADDR'] ) ? wp_privacy_anonymize_ip( sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) ) : '';
            $rate = 'wpide_consent_rate_' . md5( $ip );
            if ( (int) get_transient( $rate ) >= 10 ) {
                return new WP_REST_Response( array( 'ok' => false ), 429 );
            }
            set_transient( $rate, (int) get_transient( $rate ) + 1, HOUR_IN_SECONDS );

            if ( '1' !== get_option( 'wpide_consent_log_db' ) ) {
                return new WP_REST_Response( array( 'ok' => false ), 503 );
            }

            $policy_id = (int) get_option( 'wp_page_for_privacy_policy' );
            $wpdb->insert( $wpide_consent_table(), array(
                'created'    => current_time( 'mysql', true ),
                'choice'     => $request['choice'],
                'categories' => substr( sanitize_text_field( $request['categories'] ), 0, 190 ),
                'ip'         => $ip,
                'policy'     => $policy_id ? (string) get_post_modified_time( 'Y-m-d', true, $policy_id ) : '',
            ) );

            return array( 'ok' => true );
        },
    ) );
} );

add_action( 'wp_footer', function () {
    ?>
<script>
(function () {
    var url = <?php echo wp_json_encode( esc_url_raw( rest_url( 'wpide/v1/consent' ) ) ); ?>;
    var timer;
    function send(choice, categories) {
        clearTimeout(timer);
        timer = setTimeout(function () {
            var body = new URLSearchParams({ choice: choice, categories: categories || '' });
            if (navigator.sendBeacon) { navigator.sendBeacon(url, body); } else { fetch(url, { method: 'POST', body: body, keepalive: true }); }
        }, 500);
    }
    document.addEventListener('wpide:consent', function (e) { send(e.detail === 'granted' ? 'granted' : 'denied', 'all'); });
    document.addEventListener('wp_listen_for_consent_change', function (e) {
        var detail = e.detail || {};
        var cats = Object.keys(detail);
        var granted = cats.filter(function (c) { return detail[c] === 'allow' || detail[c] === 'granted'; });
        send(granted.length === cats.length ? 'granted' : (granted.length ? 'partial' : 'denied'), granted.join(','));
    });
})();
</script>
    <?php
}, 99 );

