            var l = allowed();
            if (l.indexOf(service) === -1) { l.push(service); }
            try { localStorage.setItem(key, JSON.stringify(l)); } catch (err) {}
            document.querySelectorAll('.wpide-2click[data-service="' + service + '"]').forEach(show);
