add_action( 'template_redirect', function () {
    if ( empty( $_POST['wpide_privacy_request'] ) ) {
        return;
    }

    $back = wp_get_referer() ? wp_get_referer() : home_url( '/' );

    if ( ! isset( $_POST['_wpide_pr_nonce'] ) || ! wp_verify_nonce( sanitize_key( $_POST['_wpide_pr_nonce'] ), 'wpide_privacy_request' ) || ! empty( $_POST['wpide_website'] ) ) {
        wp_safe_redirect( add_query_arg( 'privacy_request', 'error', $back ) );
        exit;
    }

    $ip    = isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : '';
    $rate  = 'wpide_pr_' . md5( $ip );
    $email = isset( $_POST['wpide_pr_email'] ) ? sanitize_email( wp_unslash( $_POST['wpide_pr_email'] ) ) : '';
    $type  = isset( $_POST['wpide_pr_type'] ) && 'remove' === $_POST['wpide_pr_type'] ? 'remove_personal_data' : 'export_personal_data';

    if ( (int) get_transient( $rate ) >= 3 || ! is_email( $email ) ) {
        wp_safe_redirect( add_query_arg( 'privacy_request', 'error', $back ) );
        exit;
    }

    set_transient( $rate, (int) get_transient( $rate ) + 1, HOUR_IN_SECONDS );
    $request_id = wp_create_user_request( $email, $type );

    if ( ! is_wp_error( $request_id ) ) {
        wp_send_user_request( $request_id );
    }

    // Same message whether or not a request already existed, so the form reveals nothing.
    wp_safe_redirect( add_query_arg( 'privacy_request', 'sent', $back ) );
    exit;
} );

