add_action( 'admin_menu', function () {
    global $menu, $submenu, $wpdb;

    if ( ! current_user_can( 'export_others_personal_data' ) && ! current_user_can( 'erase_others_personal_data' ) ) {
        return;
    }

    $counts = get_transient( 'wpide_privacy_request_counts' );

    if ( false === $counts ) {
        $counts = array( 'export_personal_data' => 0, 'remove_personal_data' => 0 );
        $rows   = $wpdb->get_results( "SELECT post_name, COUNT(*) AS total FROM {$wpdb->posts} WHERE post_type = 'user_request' AND post_status = 'request-confirmed' GROUP BY post_name" );
        foreach ( $rows as $row ) {
            $counts[ $row->post_name ] = (int) $row->total;
        }
        set_transient( 'wpide_privacy_request_counts', $counts, 10 * MINUTE_IN_SECONDS );
    }

    $bubble = function ( $count ) {
        return $count ? ' <span class="awaiting-mod"><span class="pending-count">' . (int) $count . '</span></span>' : '';
    };
    $total = array_sum( $counts );

    if ( ! $total || empty( $submenu['tools.php'] ) ) {
        return;
    }

    foreach ( $submenu['tools.php'] as &$item ) {
        if ( 'export-personal-data.php' === $item[2] ) {
            $item[0] .= $bubble( $counts['export_personal_data'] );
        } elseif ( 'erase-personal-data.php' === $item[2] ) {
            $item[0] .= $bubble( $counts['remove_personal_data'] );
        }
    }
    unset( $item );

    foreach ( (array) $menu as $key => $item ) {
        if ( isset( $item[2] ) && 'tools.php' === $item[2] ) {
            $menu[ $key ][0] .= $bubble( $total );
        }
    }
}, 99 );

