add_filter( 'the_content', function ( $content ) use ( $wpide_click_ids ) {
    if ( ! preg_match( '/[?&](' . implode( '|', array_map( 'preg_quote', $wpide_click_ids ) ) . ')=/', $content ) || ! class_exists( 'WP_HTML_Tag_Processor' ) ) {
        return $content;
    }

    $tags = new WP_HTML_Tag_Processor( $content );

    while ( $tags->next_tag( 'a' ) ) {
        $href = (string) $tags->get_attribute( 'href' );
        if ( false !== strpos( $href, '?' ) ) {
            $clean = remove_query_arg( $wpide_click_ids, $href );
            if ( $clean !== $href ) {
                $tags->set_attribute( 'href', $clean );
            }
        }
    }

    return $tags->get_updated_html();
}, 20 );

