            return $result( 'wpide_comment_ips', $ok, 'New comments do not store full IP addresses', 'Full IP addresses are stored with comments', 'Store shortened IP addresses for comments, or none at all, unless your spam protection needs them.' );
        },
    );

    $tests['direct']['wpide_comment_cookies'] = array(
        'label' => 'Comment cookie consent',
        'test'  => function () use ( $result ) {
            $ok = ! get_option( 'default_comment_status' ) || 'closed' === get_option( 'default_comment_status' ) || get_option( 'show_comments_cookies_opt_in' );
            return $result( 'wpide_comment_cookies', (bool) $ok, 'Commenters are asked before their details are saved in a cookie', 'Comment cookies are set without asking', 'Turn on "Show comments cookies opt-in checkbox" under Settings > Discussion.' );
        },
    );

    return $tests;
} );

add_action( 'template_redirect', function () {
    if ( ! function_exists( 'is_checkout' ) || headers_sent() ) {
        return;
    }

    if ( is_checkout() || is_account_page() || is_wc_endpoint_url( 'order-received' ) ) {
        header( 'Referrer-Policy: no-referrer' );
        add_action( 'wp_head', function () {
            echo '<meta name="referrer" content="no-referrer">' . "\n";
        }, 0 );
    }
}, 20 );

// Starting policy (report-only). Sources reported as blocked are suggested additions.
$wpide_csp_policy = array(
    'default-src' => "'self'",
    'script-src'  => "'self' 'unsafe-inline'",
    'style-src'   => "'self' 'unsafe-inline'",
    'img-src'     => "'self' data:",
    'font-src'    => "'self' data:",
    'connect-src' => "'self'",
    'frame-src'   => "'self'",
    'object-src'  => "'none'",
    'base-uri'    => "'self'",
);

add_action( 'send_headers', function () use ( $wpide_csp_policy ) {
    if ( headers_sent() || is_user_logged_in() ) {
        return;
    }

    $parts = array();
    foreach ( $wpide_csp_policy as $directive => $sources ) {
        $parts[] = $directive . ' ' . $sources;
    }
    $parts[] = 'report-uri ' . esc_url_raw( rest_url( 'wpide/v1/csp-report' ) );

    header( 'Content-Security-Policy-Report-Only: ' . implode( '; ', $parts ) );
} );

add_action( 'rest_api_init', function () {
    register_rest_route( 'wpide/v1', '/csp-report', array(
        'methods'             => 'POST',
        'permission_callback' => '__return_true',
        'callback'            => function ( WP_REST_Request $request ) {
            $ip   = isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : '';
            $rate = 'wpide_csp_rate_' . md5( $ip );
            if ( (int) get_transient( $rate ) > 60 ) {
                return new WP_REST_Response( null, 204 );
            }
            set_transient( $rate, (int) get_transient( $rate ) + 1, MINUTE_IN_SECONDS );

            $body    = json_decode( (string) $request->get_body(), true );
            $reports = isset( $body['csp-report'] ) ? array( $body['csp-report'] ) : ( is_array( $body ) ? wp_list_pluck( array_filter( $body, 'is_array' ), 'body' ) : array() );
            $store   = (array) get_option( 'wpide_csp_reports', array() );

            foreach ( $reports as $report ) {
                if ( ! is_array( $report ) ) {
                    continue;
                }
                $directive = isset( $report['effective-directive'] ) ? $report['effective-directive'] : ( isset( $report['effectiveDirective'] ) ? $report['effectiveDirective'] : ( isset( $report['violated-directive'] ) ? $report['violated-directive'] : '' ) );
                $blocked   = isset( $report['blocked-uri'] ) ? $report['blocked-uri'] : ( isset( $report['blockedURL'] ) ? $report['blockedURL'] : '' );
                $directive = sanitize_key( strtok( (string) $directive, ' ' ) );
                $host      = wp_parse_url( (string) $blocked, PHP_URL_HOST );
                $source    = $host ? 'https://' . strtolower( $host ) : sanitize_key( (string) $blocked );

                if ( ! $directive || ! $source ) {
                    continue;
                }
                $key = $directive . '|' . $source;
                if ( ! isset( $store[ $key ] ) && count( $store ) >= 200 ) {
                    continue;
                }
                $store[ $key ] = array( 'count' => ( isset( $store[ $key ]['count'] ) ? (int) $store[ $key ]['count'] : 0 ) + 1, 'last' => time() );
            }

            update_option( 'wpide_csp_reports', $store, false );

            return new WP_REST_Response( null, 204 );
        },
    ) );
} );

add_action( 'admin_menu', function () use ( $wpide_csp_policy ) {
    add_management_page( 'CSP Reports', 'CSP Reports', 'manage_options', 'wpide-csp-reports', function () use ( $wpide_csp_policy ) {
        if ( isset( $_POST['wpide_csp_clear'] ) && check_admin_referer( 'wpide_csp_clear' ) ) {
            delete_option( 'wpide_csp_reports' );
        }

        $store   = (array) get_option( 'wpide_csp_reports', array() );
        $suggest = $wpide_csp_policy;

        echo '<div class="wrap"><h1>CSP Reports</h1><table class="widefat striped"><thead><tr><th>Directive</th><th>Blocked source</th><th>Reports</th><th>Last seen</th></tr></thead><tbody>';
        if ( ! $store ) {
            echo '<tr><td colspan="4">No violations reported yet.</td></tr>';
        }
        foreach ( $store as $key => $row ) {
            list( $directive, $source ) = explode( '|', $key, 2 );
            $target = isset( $suggest[ $directive ] ) ? $directive : 'default-src';
            if ( false === strpos( $suggest[ $target ], $source ) && in_array( $source, array( 'inline', 'eval', 'data', 'blob' ), true ) === false ) {
                $suggest[ $target ] .= ' ' . $source;
            }
            printf( '<tr><td><code>%s</code></td><td>%s</td><td>%d</td><td>%s</td></tr>', esc_html( $directive ), esc_html( $source ), (int) $row['count'], esc_html( human_time_diff( (int) $row['last'] ) . ' ago' ) );
        }
        echo '</tbody></table><h2>Suggested policy</h2><textarea readonly rows="6" class="large-text code">';
        $lines = array();
        foreach ( $suggest as $directive => $sources ) {
            $lines[] = $directive . ' ' . $sources;
        }
        echo esc_textarea( implode( '; ', $lines ) );
        echo '</textarea><form method="post">';
        wp_nonce_field( 'wpide_csp_clear' );
        submit_button( 'Clear reports', 'secondary', 'wpide_csp_clear' );
        echo '</form></div>';
    } );
} );

// Switch to true to enforce the policy once nothing legitimate is reported.
$wpide_nonce_enforce = false;

$wpide_csp_nonce = function () {
    static $nonce = null;

    if ( null === $nonce ) {
        $nonce = rtrim( strtr( base64_encode( random_bytes( 18 ) ), '+/', '-_' ), '=' );
    }

    return $nonce;
};

$wpide_add_nonce = function ( $attributes ) use ( $wpide_csp_nonce ) {
    if ( is_array( $attributes ) && ! isset( $attributes['nonce'] ) ) {
        $attributes['nonce'] = $wpide_csp_nonce();
    }

    return $attributes;
};

add_filter( 'wp_script_attributes', $wpide_add_nonce );
add_filter( 'wp_inline_script_attributes', $wpide_add_nonce );

add_action( 'send_headers', function () use ( $wpide_csp_nonce, $wpide_nonce_enforce ) {
    if ( headers_sent() ) {
        return;
    }

    $policy = sprintf( "script-src 'nonce-%s' 'strict-dynamic' https: 'unsafe-inline'; object-src 'none'; base-uri 'self'", $wpide_csp_nonce() );
    header( ( $wpide_nonce_enforce ? 'Content-Security-Policy: ' : 'Content-Security-Policy-Report-Only: ' ) . $policy );
} );

$wpide_admin_headers = function () {
    if ( headers_sent() ) {
        return;
    }

    header( 'X-Content-Type-Options: nosniff' );
    header( 'Referrer-Policy: same-origin' );
    header( 'Permissions-Policy: camera=(), microphone=(), geolocation=(), payment=(), usb=()' );
    header( 'Cross-Origin-Opener-Policy: same-origin-allow-popups' );
};

add_action( 'admin_init', $wpide_admin_headers, 1 );
add_action( 'login_init', $wpide_admin_headers, 1 );

// 'same-origin-allow-popups' is safe for most sites; 'same-origin' is stricter.
$wpide_coop = 'same-origin-allow-popups';

add_action( 'send_headers', function () use ( $wpide_coop ) {
    if ( headers_sent() ) {
        return;
    }

    header( 'Cross-Origin-Opener-Policy: ' . $wpide_coop );
    header( 'Origin-Agent-Cluster: ?1' );
    header( 'X-Permitted-Cross-Domain-Policies: none' );
} );

add_filter( 'site_status_tests', function ( $tests ) {
    $tests['direct']['wpide_security_headers'] = array(
        'label' => 'Security headers',
        'test'  => function () {
            $headers = get_transient( 'wpide_sh_headers' );

            if ( false === $headers ) {
                $response = wp_remote_get( home_url( '/' ), array( 'timeout' => 8, 'redirection' => 2, 'sslverify' => apply_filters( 'https_local_ssl_verify', false ) ) );
                $headers  = is_wp_error( $response ) ? array() : array_change_key_case( wp_remote_retrieve_headers( $response )->getAll(), CASE_LOWER );
                set_transient( 'wpide_sh_headers', $headers, 12 * HOUR_IN_SECONDS );
            }

            $wanted = array(
                'x-content-type-options'  => 'X-Content-Type-Options',
                'referrer-policy'         => 'Referrer-Policy',
                'permissions-policy'      => 'Permissions-Policy',
                'content-security-policy' => 'Content-Security-Policy',
            );
            if ( is_ssl() || 0 === strpos( home_url(), 'https:' ) ) {
                $wanted['strict-transport-security'] = 'Strict-Transport-Security';
            }

            $missing = array();
            foreach ( $wanted as $key => $label ) {
                if ( empty( $headers[ $key ] ) && ! ( 'content-security-policy' === $key && ! empty( $headers['content-security-policy-report-only'] ) ) ) {
                    $missing[] = $label;
                }
            }
            $csp = isset( $headers['content-security-policy'] ) ? implode( ' ', (array) $headers['content-security-policy'] ) : '';
            if ( empty( $headers['x-frame-options'] ) && false === strpos( $csp, 'frame-ancestors' ) ) {
                $missing[] = 'X-Frame-Options (or CSP frame-ancestors)';
            }

            return array(
                'label'       => $missing ? 'Some security headers are missing' : 'Security headers are in place',
                'status'      => $missing ? 'recommended' : 'good',
                'badge'       => array( 'label' => 'Security', 'color' => 'blue' ),
                'description' => $missing
                    ? '<p>' . esc_html( 'Your homepage does not send: ' . implode( ', ', $missing ) . '.' ) . '</p>'
                    : '<p>Your homepage sends the common security headers.</p>',
                'test'        => 'wpide_security_headers',
            );
        },
    );

    return $tests;
} );

// Paths (relative to the site root) that should never be public.
$wpide_sensitive_paths = array( '.env', '.git/HEAD', 'wp-content/debug.log', 'wp-config.php.bak', 'wp-config.php.old', 'wp-config.php~', 'wp-config.bak', 'backup.sql', 'database.sql', '.htpasswd', 'phpinfo.php' );

add_filter( 'site_status_tests', function ( $tests ) use ( $wpide_sensitive_paths ) {
    $tests['direct']['wpide_exposed_files'] = array(
        'label' => 'Exposed sensitive files',
        'test'  => function () use ( $wpide_sensitive_paths ) {
            $exposed = get_transient( 'wpide_exposed_files' );

            if ( false === $exposed ) {
                $exposed = array();
                foreach ( $wpide_sensitive_paths as $path ) {
                    $response = wp_remote_get( site_url( '/' . $path ), array(
                        'timeout'     => 4,
                        'redirection' => 0,
                        'sslverify'   => apply_filters( 'https_local_ssl_verify', false ),
                        'headers'     => array( 'Range' => 'bytes=0-255' ),
                    ) );
                    $code = (int) wp_remote_retrieve_response_code( $response );
                    $type = (string) wp_remote_retrieve_header( $response, 'content-type' );
                    if ( in_array( $code, array( 200, 206 ), true ) && false === stripos( $type, 'text/html' ) && '' !== wp_remote_retrieve_body( $response ) ) {
                        $exposed[] = $path;
                    }
                }
                set_transient( 'wpide_exposed_files', $exposed, 12 * HOUR_IN_SECONDS );
            }

            return array(
                'label'       => $exposed ? 'Sensitive files can be downloaded publicly' : 'No sensitive files are exposed',
                'status'      => $exposed ? 'critical' : 'good',
                'badge'       => array( 'label' => 'Security', 'color' => $exposed ? 'red' : 'blue' ),
                'description' => $exposed
                    ? '<p>' . esc_html( 'Anyone can download: ' . implode( ', ', $exposed ) . '. Delete these files or block access to them on your server.' ) . '</p>'
                    : '<p>None of the common sensitive files could be downloaded.</p>',
                'test'        => 'wpide_exposed_files',
            );
        },
    );

    return $tests;
} );

add_filter( 'site_status_tests', function ( $tests ) {
    $result = function ( $id, $ok, $good, $bad, $fix, $level = 'recommended' ) {
        return array(
            'label'       => $ok ? $good : $bad,
            'status'      => $ok ? 'good' : $level,
            'badge'       => array( 'label' => 'Security', 'color' => $ok ? 'blue' : 'orange' ),
            'description' => '<p>' . esc_html( $ok ? $good . '.' : $fix ) . '</p>',
            'test'        => $id,
        );
    };

    $tests['direct']['wpide_salts'] = array(
        'label' => 'Security keys',
        'test'  => function () use ( $result ) {
            $values = array();
            foreach ( array( 'AUTH_KEY', 'SECURE_AUTH_KEY', 'LOGGED_IN_KEY', 'NONCE_KEY', 'AUTH_SALT', 'SECURE_AUTH_SALT', 'LOGGED_IN_SALT', 'NONCE_SALT' ) as $name ) {
                $values[] = defined( $name ) ? (string) constant( $name ) : '';
            }
            $weak = array_filter( $values, function ( $v ) {
                return strlen( $v ) < 32 || false !== stripos( $v, 'put your unique phrase here' );
            } );
            $ok = ! $weak && count( array_unique( $values ) ) === count( $values );

            return $result( 'wpide_salts', $ok, 'Security keys are unique and long', 'Security keys are weak or missing', 'Generate new keys at api.wordpress.org/secret-key/1.1/salt/ and replace the ones in wp-config.php. Everyone will be logged out once.', 'critical' );
        },
    );

    $tests['direct']['wpide_admin_user'] = array(
        'label' => 'Admin username',
        'test'  => function () use ( $result ) {
            return $result( 'wpide_admin_user', ! username_exists( 'admin' ), 'No account uses the username "admin"', 'An account uses the username "admin"', 'Attackers try "admin" first. Create a new administrator with a different username, log in with it and delete the old account, attributing its content to the new one.' );
        },
    );

    $tests['direct']['wpide_file_edit'] = array(
        'label' => 'File editor',
        'test'  => function () use ( $result ) {
            $ok = ( defined( 'DISALLOW_FILE_EDIT' ) && DISALLOW_FILE_EDIT ) || ( defined( 'DISALLOW_FILE_MODS' ) && DISALLOW_FILE_MODS );
            return $result( 'wpide_file_edit', $ok, 'The theme and plugin file editor is disabled', 'The theme and plugin file editor is enabled', "Add define( 'DISALLOW_FILE_EDIT', true ); to wp-config.php so a stolen admin login cannot be used to edit PHP files." );
        },
    );

    $tests['direct']['wpide_config_perms'] = array(
        'label' => 'wp-config.php permissions',
        'test'  => function () use ( $result ) {
            $file = file_exists( ABSPATH . 'wp-config.php' ) ? ABSPATH . 'wp-config.php' : dirname( ABSPATH ) . '/wp-config.php';
            $ok   = ! file_exists( $file ) || 0 === ( fileperms( $file ) & 0007 );
            return $result( 'wpide_config_perms', $ok, 'wp-config.php is not readable by other users on the server', 'wp-config.php can be read by any user on the server', 'Change the file permissions of wp-config.php to 640 or 600 so other accounts on a shared server cannot read your database password.' );
        },
    );

    return $tests;
} );

// Maximum age of the login, and the admin screens that need a fresh one.
$wpide_reauth_minutes = 30;
$wpide_reauth_screens = array( 'plugins.php', 'plugin-install.php', 'plugin-editor.php', 'theme-install.php', 'theme-editor.php', 'user-new.php', 'update-core.php', 'users.php' );

foreach ( $wpide_reauth_screens as $wpide_screen ) {
    add_action( 'load-' . $wpide_screen, function () use ( $wpide_reauth_minutes ) {
        if ( wp_doing_ajax() || 'POST' === ( isset( $_SERVER['REQUEST_METHOD'] ) ? $_SERVER['REQUEST_METHOD'] : 'GET' ) ) {
            return;
        }

        $token   = wp_get_session_token();
        $session = $token ? WP_Session_Tokens::get_instance( get_current_user_id() )->get( $token ) : null;

        if ( ! empty( $session['login'] ) && ( time() - (int) $session['login'] ) <= $wpide_reauth_minutes * MINUTE_IN_SECONDS ) {
            return;
        }

        $here = set_url_scheme( 'http://' . ( isset( $_SERVER['HTTP_HOST'] ) ? sanitize_text_field( wp_unslash( $_SERVER['HTTP_HOST'] ) ) : '' ) . ( isset( $_SERVER['REQUEST_URI'] ) ? esc_url_raw( wp_unslash( $_SERVER['REQUEST_URI'] ) ) : '' ) );
        wp_safe_redirect( wp_login_url( $here, true ) );
        exit;
    } );
}

add_action( 'admin_menu', function () {
