add_action( 'admin_menu', function () {
    add_users_page( 'Active Sessions', 'Active Sessions', 'edit_users', 'wpide-sessions', function () {
        if ( isset( $_POST['wpide_end_user'] ) && check_admin_referer( 'wpide_end_sessions' ) && current_user_can( 'edit_users' ) ) {
            $target = absint( $_POST['wpide_end_user'] );
            if ( $target && $target !== get_current_user_id() && current_user_can( 'edit_user', $target ) ) {
                WP_Session_Tokens::get_instance( $target )->destroy_all();
                echo '<div class="notice notice-success"><p>Sessions ended.</p></div>';
            }
        }

        $rows = array();
        foreach ( get_users( array( 'meta_key' => 'session_tokens', 'number' => 200, 'fields' => array( 'ID', 'user_login' ) ) ) as $user ) {
            foreach ( WP_Session_Tokens::get_instance( (int) $user->ID )->get_all() as $session ) {
                $rows[] = array( $user, $session );
            }
        }
        usort( $rows, function ( $a, $b ) {
            return (int) $b[1]['login'] - (int) $a[1]['login'];
        } );

        echo '<div class="wrap"><h1>Active Sessions</h1><table class="widefat striped"><thead><tr><th>User</th><th>Logged in</th><th>Expires</th><th>IP address</th><th>Browser</th><th></th></tr></thead><tbody>';
        if ( ! $rows ) {
            echo '<tr><td colspan="6">No active sessions.</td></tr>';
        }
        foreach ( $rows as list( $user, $session ) ) {
            echo '<tr><td>' . esc_html( $user->user_login ) . '</td>';
            echo '<td>' . esc_html( human_time_diff( (int) $session['login'] ) . ' ago' ) . '</td>';
            echo '<td>' . esc_html( wp_date( 'Y-m-d H:i', (int) $session['expiration'] ) ) . '</td>';
            echo '<td>' . esc_html( isset( $session['ip'] ) ? $session['ip'] : '' ) . '</td>';
            echo '<td>' . esc_html( isset( $session['ua'] ) ? wp_html_excerpt( $session['ua'], 60, '...' ) : '' ) . '</td><td>';
            if ( (int) $user->ID !== get_current_user_id() ) {
                echo '<form method="post">';
                wp_nonce_field( 'wpide_end_sessions' );
                echo '<button class="button" name="wpide_end_user" value="' . (int) $user->ID . '">End sessions</button></form>';
            }
            echo '</td></tr>';
        }
        echo '</tbody></table></div>';
    } );
} );

$wpide_safe_slug = function ( $user ) {
    $slug = sanitize_title( $user->display_name );

    if ( ! $slug || $slug === sanitize_title( $user->user_login ) ) {
        $slug = 'author';
    }

    return $slug . '-' . $user->ID;
};

add_action( 'user_register', function ( $user_id ) use ( $wpide_safe_slug ) {
    $user = get_userdata( $user_id );

    if ( $user && $user->user_nicename === sanitize_title( $user->user_login ) ) {
        wp_update_user( array( 'ID' => $user_id, 'user_nicename' => $wpide_safe_slug( $user ) ) );
    }
}, 20 );

add_action( 'admin_notices', function () use ( $wpide_safe_slug ) {
    global $wpdb;

    $screen = get_current_screen();

    if ( ! $screen || 'users' !== $screen->id || ! current_user_can( 'edit_users' ) ) {
        return;
    }

    if ( isset( $_POST['wpide_fix_slugs'] ) && check_admin_referer( 'wpide_fix_slugs' ) ) {
        $fixed = 0;
        foreach ( $wpdb->get_col( "SELECT ID FROM {$wpdb->users} WHERE user_nicename = user_login LIMIT 500" ) as $id ) {
            $user = get_userdata( (int) $id );
            if ( $user && ! is_wp_error( wp_update_user( array( 'ID' => $user->ID, 'user_nicename' => $wpide_safe_slug( $user ) ) ) ) ) {
                $fixed++;
            }
        }
        printf( '<div class="notice notice-success"><p>%s</p></div>', esc_html( sprintf( 'Updated the author URL of %d user(s).', $fixed ) ) );
        return;
    }

    $count = (int) $wpdb->get_var( "SELECT COUNT(*) FROM {$wpdb->users} WHERE user_nicename = user_login" );

    if ( $count ) {
        echo '<div class="notice notice-warning"><form method="post"><p>' . esc_html( sprintf( '%d user(s) have an author URL that shows their login name.', $count ) ) . ' ';
        wp_nonce_field( 'wpide_fix_slugs' );
        echo '<button class="button" name="wpide_fix_slugs" value="1">Hide login names in author URLs</button></p></form></div>';
    }
} );

add_filter( 'wp_handle_upload_prefilter', function ( $file ) {
    if ( ! empty( $file['error'] ) || empty( $file['tmp_name'] ) || ! is_readable( $file['tmp_name'] ) ) {
        return $file;
    }

    $handle = fopen( $file['tmp_name'], 'rb' );

    if ( ! $handle ) {
        return $file;
    }

    $chunk = (string) fread( $handle, 2 * MB_IN_BYTES );
    fclose( $handle );

    // "<?=" is only checked in text files: in binary data those three bytes can occur by chance.
    $binary  = (bool) preg_match( '/\.(jpe?g|png|gif|webp|avif|heic|mp[34]|m4a|mov|webm|zip|pdf|docx?|xlsx?|pptx?)$/i', (string) $file['name'] );
    $pattern = $binary ? '/<\?php\b|<script\s+language\s*=\s*["\']?php/i' : '/<\?(php\b|=)|<script\s+language\s*=\s*["\']?php/i';

    if ( preg_match( $pattern, $chunk ) ) {
        $file['error'] = 'This file contains code that is not allowed in uploads.';
    }

    return $file;
}, 5 );

