// Extensions to rename; leave empty to rename every upload.
$wpide_random_types = array( 'pdf', 'doc', 'docx', 'xls', 'xlsx', 'csv', 'zip', 'txt' );

add_filter( 'wp_handle_upload_prefilter', function ( $file ) use ( $wpide_random_types ) {
    if ( ! empty( $file['error'] ) || empty( $file['name'] ) ) {
        return $file;
    }

    $info = pathinfo( $file['name'] );
    $ext  = isset( $info['extension'] ) ? strtolower( $info['extension'] ) : '';

    if ( $wpide_random_types && ! in_array( $ext, $wpide_random_types, true ) ) {
        return $file;
    }

    $file['name'] = $info['filename'] . '-' . strtolower( wp_generate_password( 6, false ) ) . ( $ext ? '.' . $ext : '' );

    return $file;
} );

// Days to keep log entries, and settings whose changes are logged.
$wpide_log_days    = 90;
$wpide_log_options = array( 'siteurl', 'home', 'admin_email', 'users_can_register', 'default_role', 'blog_public', 'permalink_structure' );

$wpide_log_table = function () {
    global $wpdb;
    return $wpdb->prefix . 'wpide_activity';
};

$wpide_log = function ( $action, $object = '', $details = '', $user_id = null ) use ( $wpide_log_table ) {
    global $wpdb;

    if ( '1' !== get_option( 'wpide_activity_db' ) ) {
        return;
    }

    $user_id = null === $user_id ? get_current_user_id() : (int) $user_id;
    $user    = $user_id ? get_userdata( $user_id ) : false;

    $wpdb->insert( $wpide_log_table(), array(
        'created'    => current_time( 'mysql', true ),
        'user_id'    => $user_id,
        'user_login' => $user ? $user->user_login : '',
        'ip'         => isset( $_SERVER['REMOTE_ADDR'] ) ? substr( sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ), 0, 45 ) : '',
        'action'     => substr( $action, 0, 40 ),
        'object'     => substr( (string) $object, 0, 190 ),
        'details'    => substr( (string) $details, 0, 1000 ),
    ) );
};

add_action( 'admin_init', function () use ( $wpide_log_table ) {
