// Number of previous passwords that cannot be reused.
$wpide_history_size = 5;

$wpide_is_reused = function ( $user_id, $password ) {
    $user = get_userdata( $user_id );

    if ( ! $user || '' === (string) $password ) {
        return false;
    }

    $hashes   = (array) get_user_meta( $user_id, 'wpide_password_history', true );
    $hashes[] = $user->user_pass;

    foreach ( array_filter( $hashes ) as $hash ) {
        if ( wp_check_password( $password, $hash, $user_id ) ) {
            return true;
        }
    }

    return false;
};

$wpide_remember = function ( $user_id, $old_hash ) use ( $wpide_history_size ) {
    $hashes   = array_filter( (array) get_user_meta( $user_id, 'wpide_password_history', true ) );
    $hashes[] = $old_hash;
    update_user_meta( $user_id, 'wpide_password_history', array_slice( array_values( array_unique( $hashes ) ), -$wpide_history_size ) );
};

add_action( 'user_profile_update_errors', function ( $errors, $update, $user ) use ( $wpide_is_reused ) {
    if ( $update && ! empty( $user->user_pass ) && ! empty( $user->ID ) && $wpide_is_reused( $user->ID, $user->user_pass ) ) {
        $errors->add( 'wpide_password_reused', '<strong>Error:</strong> Please choose a password you have not used recently.' );
    }
}, 10, 3 );

add_action( 'validate_password_reset', function ( $errors, $user ) use ( $wpide_is_reused ) {
    $pass = isset( $_POST['pass1'] ) ? (string) wp_unslash( $_POST['pass1'] ) : '';
    if ( $pass && $user instanceof WP_User && $wpide_is_reused( $user->ID, $pass ) ) {
        $errors->add( 'wpide_password_reused', 'Please choose a password you have not used recently.' );
    }
}, 10, 2 );

add_action( 'profile_update', function ( $user_id, $old_data ) use ( $wpide_remember ) {
    $user = get_userdata( $user_id );
    if ( $user && $old_data && $old_data->user_pass && $user->user_pass !== $old_data->user_pass ) {
        $wpide_remember( $user_id, $old_data->user_pass );
    }
}, 10, 2 );

add_action( 'password_reset', function ( $user ) use ( $wpide_remember ) {
    $wpide_remember( $user->ID, $user->user_pass );
} );

$wpide_breach_count = function ( $password ) {
    $hash   = strtoupper( sha1( (string) $password ) );
    $prefix = substr( $hash, 0, 5 );
    $cache  = 'wpide_hibp_' . $prefix;
    $body   = get_transient( $cache );

    if ( false === $body ) {
        $response = wp_remote_get( 'https://api.pwnedpasswords.com/range/' . $prefix, array(
            'timeout' => 4,
            'headers' => array( 'Add-Padding' => 'true', 'User-Agent' => 'WordPress password check' ),
        ) );
        if ( is_wp_error( $response ) || 200 !== wp_remote_retrieve_response_code( $response ) ) {
            return 0;
        }
        $body = wp_remote_retrieve_body( $response );
        set_transient( $cache, $body, 12 * HOUR_IN_SECONDS );
    }

    if ( preg_match( '/^' . substr( $hash, 5 ) . ':(\d+)/m', $body, $m ) ) {
        return (int) $m[1];
    }

    return 0;
};

$wpide_breach_message = 'This password has appeared in a data breach and is unsafe. Please choose a different one.';

add_action( 'user_profile_update_errors', function ( $errors, $update, $user ) use ( $wpide_breach_count, $wpide_breach_message ) {
    if ( ! empty( $user->user_pass ) && $wpide_breach_count( $user->user_pass ) > 0 ) {
        $errors->add( 'wpide_pwned', '<strong>Error:</strong> ' . $wpide_breach_message );
    }
}, 10, 3 );

add_action( 'validate_password_reset', function ( $errors ) use ( $wpide_breach_count, $wpide_breach_message ) {
    $pass = isset( $_POST['pass1'] ) ? (string) wp_unslash( $_POST['pass1'] ) : '';
    if ( $pass && $wpide_breach_count( $pass ) > 0 ) {
        $errors->add( 'wpide_pwned', $wpide_breach_message );
    }
} );

// Folders to watch and the maximum number of files to fingerprint.
$wpide_watch_dirs  = array( WP_PLUGIN_DIR, get_theme_root() );
$wpide_watch_limit = 30000;

$wpide_fingerprint = function () use ( $wpide_watch_dirs, $wpide_watch_limit ) {
    $map = array();

    foreach ( $wpide_watch_dirs as $dir ) {
        if ( ! is_dir( $dir ) ) {
            continue;
        }
        $files = new RecursiveIteratorIterator( new RecursiveDirectoryIterator( $dir, FilesystemIterator::SKIP_DOTS ) );
        foreach ( $files as $file ) {
            if ( count( $map ) >= $wpide_watch_limit ) {
                break 2;
            }
            if ( $file->isFile() && preg_match( '/\.(php|phtml|phar)$/i', $file->getFilename() ) && false === strpos( $file->getPathname(), '/node_modules/' ) ) {
                $map[ str_replace( WP_CONTENT_DIR, '', $file->getPathname() ) ] = substr( md5_file( $file->getPathname() ), 0, 12 );
            }
        }
    }

    return $map;
};

$wpide_save_baseline = function ( $map ) {
    update_option( 'wpide_file_baseline', base64_encode( gzcompress( wp_json_encode( $map ), 6 ) ), false );
};

add_action( 'init', function () {
    if ( ! wp_next_scheduled( 'wpide_file_change_scan' ) ) {
        wp_schedule_event( time() + HOUR_IN_SECONDS, 'daily', 'wpide_file_change_scan' );
    }
} );

add_action( 'upgrader_process_complete', function () use ( $wpide_fingerprint, $wpide_save_baseline ) {
    $wpide_save_baseline( $wpide_fingerprint() );
}, 99 );

add_action( 'wpide_file_change_scan', function () use ( $wpide_fingerprint, $wpide_save_baseline ) {
    $stored = get_option( 'wpide_file_baseline' );
    $now    = $wpide_fingerprint();
    $wpide_save_baseline( $now );

    if ( ! $stored ) {
        return;
    }

    $old = json_decode( (string) gzuncompress( base64_decode( $stored ) ), true );
    if ( ! is_array( $old ) ) {
        return;
    }

    $added   = array_keys( array_diff_key( $now, $old ) );
    $removed = array_keys( array_diff_key( $old, $now ) );
    $changed = array_keys( array_diff_assoc( array_intersect_key( $now, $old ), $old ) );

    if ( ! $added && ! $removed && ! $changed ) {
        return;
    }

    $lines = array();
    foreach ( array( 'Added' => $added, 'Changed' => $changed, 'Removed' => $removed ) as $label => $list ) {
        if ( $list ) {
            $lines[] = $label . ' (' . count( $list ) . "):\n  " . implode( "\n  ", array_slice( $list, 0, 50 ) );
        }
    }

    wp_mail(
        get_option( 'admin_email' ),
        sprintf( '[%s] Plugin or theme files changed', wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES ) ),
        "These PHP files changed since yesterday without a dashboard update:\n\n" . implode( "\n\n", $lines ) . "\n\nIf you did not make these changes, check the files for malware."
    );
} );

add_action( 'init', function () {
    if ( ! wp_next_scheduled( 'wpide_uploads_php_scan' ) ) {
        wp_schedule_event( time() + HOUR_IN_SECONDS, 'daily', 'wpide_uploads_php_scan' );
    }
} );

add_action( 'wpide_uploads_php_scan', function () {
    $uploads = wp_get_upload_dir();
    $base    = $uploads['basedir'];
    $found   = array();

    if ( ! is_dir( $base ) ) {
        return;
    }

    $files = new RecursiveIteratorIterator( new RecursiveDirectoryIterator( $base, FilesystemIterator::SKIP_DOTS ) );
    foreach ( $files as $file ) {
        if ( ! $file->isFile() || ! preg_match( '/\.(php\d?|phtml|phar|pht)$/i', $file->getFilename() ) ) {
            continue;
        }
        if ( 'index.php' === strtolower( $file->getFilename() ) && $file->getSize() < 200 ) {
            continue;
        }
        $found[] = str_replace( $base, '', $file->getPathname() );
        if ( count( $found ) >= 100 ) {
            break;
        }
    }

    $previous = (array) get_option( 'wpide_uploads_php_found', array() );
    update_option( 'wpide_uploads_php_found', $found, false );
    $new = array_diff( $found, $previous );

    if ( $new ) {
        wp_mail(
            get_option( 'admin_email' ),
            sprintf( '[%s] PHP files found in uploads', wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES ) ),
            "These PHP files were found in your uploads folder, where PHP files should never be:\n\n" . implode( "\n", $new ) . "\n\nCheck and remove them."
        );
    }
} );

add_action( 'admin_notices', function () {
    $found = (array) get_option( 'wpide_uploads_php_found', array() );

    if ( $found && current_user_can( 'manage_options' ) ) {
        printf( '<div class="notice notice-error"><p>%s</p></div>', esc_html( sprintf( 'Security: %d PHP file(s) found in the uploads folder, for example %s. Check and remove them.', count( $found ), $found[0] ) ) );
    }
} );

// User IDs allowed to manage code and users.
$wpide_trusted_admins = array( 1 );

add_filter( 'map_meta_cap', function ( $caps, $cap, $user_id ) use ( $wpide_trusted_admins ) {
    static $guarded = array( 'install_plugins', 'activate_plugins', 'deactivate_plugins', 'delete_plugins', 'update_plugins', 'edit_plugins', 'install_themes', 'switch_themes', 'delete_themes', 'update_themes', 'edit_themes', 'update_core', 'create_users', 'promote_users', 'delete_users', 'edit_users', 'remove_users' );

    if ( ! in_array( $cap, $guarded, true ) || in_array( (int) $user_id, array_map( 'intval', $wpide_trusted_admins ), true ) ) {
        return $caps;
    }

    static $any_trusted = null;
    if ( null === $any_trusted ) {
        $any_trusted = false;
        foreach ( $wpide_trusted_admins as $id ) {
            $trusted = get_userdata( (int) $id );
            if ( $trusted && in_array( 'administrator', (array) $trusted->roles, true ) ) {
                $any_trusted = true;
                break;
            }
        }
    }

    return $any_trusted ? array( 'do_not_allow' ) : $caps;
}, 20, 3 );

// Namespaces visitors may use.
$wpide_public_namespaces = array( 'oembed/1.0', 'contact-form-7/v1', 'wc/store', 'wc/store/v1', 'wpide/v1', 'jetpack/v4' );

add_filter( 'rest_pre_dispatch', function ( $result, $server, $request ) use ( $wpide_public_namespaces ) {
    if ( null !== $result || is_user_logged_in() ) {
        return $result;
    }

    $route = ltrim( $request->get_route(), '/' );

    if ( '' === $route ) {
        return new WP_Error( 'rest_forbidden', 'The REST API index is not available.', array( 'status' => 401 ) );
    }

    foreach ( $wpide_public_namespaces as $namespace ) {
        if ( 0 === strpos( $route, trim( $namespace, '/' ) . '/' ) || trim( $namespace, '/' ) === $route ) {
            return $result;
        }
    }

    return new WP_Error( 'rest_forbidden', 'Authentication required.', array( 'status' => 401 ) );
}, 10, 3 );

$wpide_admin_ids = function () {
    return array_map( 'intval', get_users( array( 'role' => 'administrator', 'fields' => 'ID', 'number' => -1 ) ) );
};

$wpide_approved = function () use ( $wpide_admin_ids ) {
    $approved = get_option( 'wpide_approved_admins' );

    if ( ! is_array( $approved ) ) {
        $approved = $wpide_admin_ids();
        update_option( 'wpide_approved_admins', $approved, false );
    }

    return array_map( 'intval', $approved );
};

$wpide_approve = function ( $user_id ) use ( $wpide_approved ) {
    $list = $wpide_approved();
    if ( ! in_array( (int) $user_id, $list, true ) ) {
        $list[] = (int) $user_id;
        update_option( 'wpide_approved_admins', $list, false );
    }
};

$wpide_trusted_actor = function () use ( $wpide_approved ) {
