// Methods that are allowed.
$wpide_allowed_methods = array( 'GET', 'POST', 'HEAD', 'OPTIONS', 'PUT', 'PATCH', 'DELETE' );

add_action( 'init', function () use ( $wpide_allowed_methods ) {
    if ( ( defined( 'WP_CLI' ) && WP_CLI ) || empty( $_SERVER['REQUEST_METHOD'] ) ) {
        return;
    }

    $method = strtoupper( sanitize_key( $_SERVER['REQUEST_METHOD'] ) );

    if ( ! in_array( $method, $wpide_allowed_methods, true ) ) {
        status_header( 405 );
        header( 'Allow: ' . implode( ', ', $wpide_allowed_methods ) );
        exit;
    }
}, 0 );

// Extra host names allowed besides the site and home URL hosts.
$wpide_allowed_hosts = array();

add_action( 'init', function () use ( $wpide_allowed_hosts ) {
    if ( ( defined( 'WP_CLI' ) && WP_CLI ) || wp_doing_cron() || empty( $_SERVER['HTTP_HOST'] ) ) {
        return;
    }

    $host    = strtolower( preg_replace( '/:\d+$/', '', sanitize_text_field( wp_unslash( $_SERVER['HTTP_HOST'] ) ) ) );
    $allowed = array_merge( $wpide_allowed_hosts, array( wp_parse_url( home_url(), PHP_URL_HOST ), wp_parse_url( site_url(), PHP_URL_HOST ) ) );
    $allowed = array_map( 'strtolower', array_filter( $allowed ) );

    foreach ( $allowed as $name ) {
        $allowed[] = 0 === strpos( $name, 'www.' ) ? substr( $name, 4 ) : 'www.' . $name;
    }

    if ( ! in_array( $host, $allowed, true ) ) {
        status_header( 400 );
        nocache_headers();
        exit( 'Unknown host.' );
    }
}, 0 );

add_action( 'login_init', function () {
    if ( 'POST' !== ( isset( $_SERVER['REQUEST_METHOD'] ) ? $_SERVER['REQUEST_METHOD'] : '' ) || empty( $_POST['log'] ) ) {
        return;
    }

    $own    = wp_parse_url( site_url(), PHP_URL_HOST );
    $origin = isset( $_SERVER['HTTP_ORIGIN'] ) ? wp_parse_url( esc_url_raw( wp_unslash( $_SERVER['HTTP_ORIGIN'] ) ), PHP_URL_HOST ) : '';
    $ref    = isset( $_SERVER['HTTP_REFERER'] ) ? wp_parse_url( esc_url_raw( wp_unslash( $_SERVER['HTTP_REFERER'] ) ), PHP_URL_HOST ) : '';
    $home   = wp_parse_url( home_url(), PHP_URL_HOST );

    if ( in_array( $origin ? $origin : $ref, array( $own, $home ), true ) ) {
        return;
    }

    status_header( 403 );
    wp_die( esc_html__( 'Please log in using the login form on this site.' ), 403 );
}, 1 );

// Hours a trapped IP stays blocked.
$wpide_trap_hours = 24;

$wpide_trap_ip = function () {
    return isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : '';
};

add_action( 'init', function () use ( $wpide_trap_ip, $wpide_trap_hours ) {
    if ( is_admin() || is_user_logged_in() || ( defined( 'WP_CLI' ) && WP_CLI ) || wp_doing_cron() ) {
        return;
    }

    $key = 'wpide_trap_' . md5( $wpide_trap_ip() );

    if ( isset( $_GET['wpide-trap'] ) ) {
        set_transient( $key, 1, $wpide_trap_hours * HOUR_IN_SECONDS );
    }

    if ( get_transient( $key ) ) {
        status_header( 403 );
        nocache_headers();
        exit( 'Access denied.' );
    }
}, 1 );

