// Send the summary only when at least this many attempts failed.
$wpide_digest_minimum = 10;

add_action( 'wp_login_failed', function ( $username ) {
    $day  = wp_date( 'Y-m-d' );
    $data = get_option( 'wpide_failed_logins' );
    $data = is_array( $data ) && isset( $data['day'] ) && $data['day'] === $day ? $data : array( 'day' => $day, 'total' => 0, 'users' => array(), 'ips' => array() );
    $ip   = isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : 'unknown';
    $user = substr( sanitize_user( (string) $username ), 0, 60 );

    $data['total']++;
    if ( count( $data['users'] ) < 200 || isset( $data['users'][ $user ] ) ) {
        $data['users'][ $user ] = ( isset( $data['users'][ $user ] ) ? $data['users'][ $user ] : 0 ) + 1;
    }
    if ( count( $data['ips'] ) < 200 || isset( $data['ips'][ $ip ] ) ) {
        $data['ips'][ $ip ] = ( isset( $data['ips'][ $ip ] ) ? $data['ips'][ $ip ] : 0 ) + 1;
    }

    update_option( 'wpide_failed_logins', $data, false );
} );

add_action( 'init', function () {
    if ( ! wp_next_scheduled( 'wpide_failed_login_digest' ) ) {
        wp_schedule_event( strtotime( 'tomorrow 07:00' ) - (int) ( get_option( 'gmt_offset' ) * HOUR_IN_SECONDS ), 'daily', 'wpide_failed_login_digest' );
    }
} );

add_action( 'wpide_failed_login_digest', function () use ( $wpide_digest_minimum ) {
    $data = get_option( 'wpide_failed_logins' );

    if ( ! is_array( $data ) || empty( $data['day'] ) || $data['day'] === wp_date( 'Y-m-d' ) ) {
        return;
    }

    delete_option( 'wpide_failed_logins' );

    if ( $data['total'] < $wpide_digest_minimum ) {
        return;
    }

    arsort( $data['users'] );
    arsort( $data['ips'] );
    $lines = array( sprintf( '%d failed login attempts on %s.', $data['total'], $data['day'] ), '', 'Most tried usernames:' );
    foreach ( array_slice( $data['users'], 0, 10, true ) as $name => $count ) {
        $lines[] = sprintf( '  %s: %d%s', $name, $count, username_exists( $name ) ? ' (existing account)' : '' );
    }
    $lines[] = '';
    $lines[] = 'Busiest IP addresses:';
    foreach ( array_slice( $data['ips'], 0, 10, true ) as $ip => $count ) {
        $lines[] = sprintf( '  %s: %d', $ip, $count );
    }

    wp_mail( get_option( 'admin_email' ), sprintf( '[%s] Failed login summary', wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES ) ), implode( "\n", $lines ) );
} );

add_filter( 'wp_pre_insert_user_data', function ( $data, $update, $user_id, $userdata ) {
    if ( empty( $data['user_login'] ) || empty( $data['display_name'] ) || strtolower( $data['display_name'] ) !== strtolower( $data['user_login'] ) ) {
        return $data;
    }

    $first = isset( $userdata['first_name'] ) ? trim( (string) $userdata['first_name'] ) : '';
    $last  = isset( $userdata['last_name'] ) ? trim( (string) $userdata['last_name'] ) : '';

    if ( $user_id && ! $first && ! $last ) {
        $first = (string) get_user_meta( $user_id, 'first_name', true );
        $last  = (string) get_user_meta( $user_id, 'last_name', true );
    }

    $name = trim( $first . ' ' . $last );

    $data['display_name'] = '' !== $name ? $name : 'Member ' . strtoupper( substr( md5( $data['user_login'] . wp_salt() ), 0, 5 ) );

    return $data;
}, 10, 4 );

add_filter( 'rest_pre_dispatch', function ( $result, $server, $request ) {
    $route = $request->get_route();

    if ( null !== $result || 0 !== strpos( $route, '/wp/v2/users' ) || ! is_user_logged_in() || current_user_can( 'edit_posts' ) ) {
        return $result;
    }

    if ( '/wp/v2/users/me' === untrailingslashit( $route ) ) {
        return $result;
    }

    return new WP_Error( 'rest_user_cannot_view', 'Sorry, you are not allowed to list users.', array( 'status' => 403 ) );
}, 10, 3 );

$wpide_root_snapshot = function () {
    $root  = ABSPATH;
    $files = array();

    foreach ( (array) glob( $root . '{*.php,.htaccess,.user.ini,php.ini}', GLOB_BRACE ) as $path ) {
        if ( is_file( $path ) ) {
            $files[ basename( $path ) ] = md5_file( $path );
        }
    }

    $config = dirname( ABSPATH ) . '/wp-config.php';
    if ( ! isset( $files['wp-config.php'] ) && is_file( $config ) ) {
        $files['../wp-config.php'] = md5_file( $config );
    }

    return $files;
};

add_action( 'init', function () {
    if ( ! wp_next_scheduled( 'wpide_root_files_check' ) ) {
        wp_schedule_event( time() + HOUR_IN_SECONDS, 'daily', 'wpide_root_files_check' );
    }
} );

add_action( 'wpide_root_files_check', function () use ( $wpide_root_snapshot ) {
    $now = $wpide_root_snapshot();
    $old = get_option( 'wpide_root_files' );
    update_option( 'wpide_root_files', $now, false );

    if ( ! is_array( $old ) ) {
        return;
    }

    $lines = array();
    foreach ( array_diff_key( $now, $old ) as $file => $hash ) {
        $lines[] = 'New file: ' . $file;
    }
    foreach ( array_diff_key( $old, $now ) as $file => $hash ) {
        $lines[] = 'Removed: ' . $file;
    }
    foreach ( array_intersect_key( $now, $old ) as $file => $hash ) {
        if ( $old[ $file ] !== $hash ) {
            $lines[] = 'Changed: ' . $file;
        }
    }

    if ( $lines ) {
        wp_mail( get_option( 'admin_email' ), sprintf( '[%s] Files in the site root changed', wp_specialchars_decode( get_bloginfo( 'name' ), ENT_QUOTES ) ), implode( "\n", $lines ) . "\n\nCore updates change some of these files; if you did not update WordPress or edit them, check them now." );
    }
} );

add_action( 'init', function () {
