} );

add_action( 'wpide_weekly_security_summary', function () {
    if ( ! function_exists( 'get_plugins' ) ) {
        require_once ABSPATH . 'wp-admin/includes/plugin.php';
    }

    $core    = get_site_transient( 'update_core' );
    $plugins = get_site_transient( 'update_plugins' );
    $themes  = get_site_transient( 'update_themes' );
    $core_up = ! empty( $core->updates[0]->response ) && 'upgrade' === $core->updates[0]->response;
    $admins  = get_users( array( 'role' => 'administrator', 'fields' => array( 'user_login' ) ) );
    $new     = get_users( array( 'date_query' => array( array( 'after' => '1 week ago' ) ), 'fields' => 'ID', 'number' => 500 ) );
    $active  = (array) get_option( 'active_plugins', array() );

    $lines = array(
        'WordPress update available: ' . ( $core_up ? 'yes (' . $core->updates[0]->current . ')' : 'no' ),
        'Plugin updates pending: ' . ( empty( $plugins->response ) ? 0 : count( $plugins->response ) ),
        'Theme updates pending: ' . ( empty( $themes->response ) ? 0 : count( $themes->response ) ),
        'Inactive plugins installed: ' . max( 0, count( get_plugins() ) - count( $active ) ),
        'Administrator accounts (' . count( $admins ) . '): ' . implode( ', ', wp_list_pluck( $admins, 'user_login' ) ),
        'New users this week: ' . count( $new ),
        'Debug mode: ' . ( defined( 'WP_DEBUG' ) && WP_DEBUG ? 'ON - turn it off on a live site' : 'off' ),
    );

    if ( ! empty( $plugins->response ) ) {
        $lines[] = '';
        $lines[] = 'Plugins to update:';
