$wpide_auto_update_slugs = array( 'wordfence', 'updraftplus', 'akismet' );

add_filter( 'auto_update_plugin', function ( $update, $item ) use ( $wpide_auto_update_slugs ) {
    $slug = isset( $item->slug ) ? $item->slug : ( isset( $item->plugin ) ? dirname( $item->plugin ) : '' );

    return in_array( $slug, $wpide_auto_update_slugs, true ) ? true : $update;
}, 20, 2 );

$wpide_domain_has_mail = function ( $email ) {
    $domain = strtolower( (string) substr( strrchr( (string) $email, '@' ), 1 ) );

    if ( ! $domain || ! function_exists( 'checkdnsrr' ) ) {
        return true;
    }

    $key    = 'wpide_mx_' . md5( $domain );
    $cached = get_transient( $key );

    if ( false !== $cached ) {
        return 'yes' === $cached;
    }

    $ok = checkdnsrr( $domain . '.', 'MX' ) || checkdnsrr( $domain . '.', 'A' );
    set_transient( $key, $ok ? 'yes' : 'no', DAY_IN_SECONDS );

    return $ok;
};

$wpide_mx_check = function ( $errors, $username, $email ) use ( $wpide_domain_has_mail ) {
    if ( is_wp_error( $errors ) && is_email( $email ) && ! $wpide_domain_has_mail( $email ) ) {
        $errors->add( 'wpide_email_domain', '<strong>Error:</strong> This email domain cannot receive email. Please check your address.' );
    }

    return $errors;
};

add_filter( 'registration_errors', $wpide_mx_check, 20, 3 );
add_filter( 'woocommerce_registration_errors', $wpide_mx_check, 20, 3 );

// IP addresses or IPv4 CIDR ranges allowed to use xmlrpc.php.
$wpide_xmlrpc_ips = array( '127.0.0.1', '192.0.64.0/18' );

$wpide_xmlrpc_check = function () use ( $wpide_xmlrpc_ips ) {
    if ( ! defined( 'XMLRPC_REQUEST' ) || ! XMLRPC_REQUEST ) {
        return;
    }

    $ip = isset( $_SERVER['REMOTE_ADDR'] ) ? sanitize_text_field( wp_unslash( $_SERVER['REMOTE_ADDR'] ) ) : '';

    foreach ( $wpide_xmlrpc_ips as $rule ) {
        if ( $rule === $ip ) {
            return;
        }
        if ( false !== strpos( $rule, '/' ) && filter_var( $ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4 ) ) {
            list( $subnet, $bits ) = explode( '/', $rule, 2 );
            $mask = -1 << ( 32 - (int) $bits );
            if ( ( ip2long( $ip ) & $mask ) === ( ip2long( $subnet ) & $mask ) ) {
                return;
            }
        }
    }

    status_header( 403 );
    exit;
};

if ( did_action( 'init' ) ) {
    $wpide_xmlrpc_check();
} else {
    add_action( 'init', $wpide_xmlrpc_check, 0 );
}

