}

WP_CLI::add_command( 'check-internal-links', function ( $args, $assoc_args ) {
    $home       = untrailingslashit( home_url() );
    $post_types = isset( $assoc_args['post_type'] ) ? array_map( 'sanitize_key', explode( ',', $assoc_args['post_type'] ) ) : array( 'post', 'page' );
    $items      = array();
    $paged      = 1;

    do {
        $query = new WP_Query( array(
            'post_type'      => $post_types,
            'post_status'    => 'publish',
            'posts_per_page' => 100,
            'paged'          => $paged++,
            'no_found_rows'  => true,
        ) );

        foreach ( $query->posts as $post ) {
            if ( ! preg_match_all( '/href=["\']([^"\'#]+)/i', $post->post_content, $matches ) ) {
                continue;
            }
            foreach ( array_unique( $matches[1] ) as $url ) {
                if ( 0 === strpos( $url, '/' ) && 0 !== strpos( $url, '//' ) ) {
                    $url = $home . $url;
                }
                if ( 0 !== strpos( $url, $home ) ) {
                    continue; // External link.
                }
                $path = (string) wp_parse_url( $url, PHP_URL_PATH );
                if ( '' === trim( $path, '/' ) || false !== strpos( $path, '/wp-' ) ) {
                    continue; // Homepage, admin or uploads.
                }
                if ( url_to_postid( $url ) || file_exists( ABSPATH . ltrim( $path, '/' ) ) ) {
                    continue;
                }
                $items[] = array( 'post_id' => $post->ID, 'post_title' => $post->post_title, 'link' => $url );
            }
        }
    } while ( count( $query->posts ) === 100 );

    if ( ! $items ) {
        WP_CLI::success( 'No broken internal links found.' );
        return;
    }

