WP_CLI::add_command( 'meta-keys', function ( $args, $assoc_args ) {
    global $wpdb;

    $post_type = sanitize_key( $assoc_args['post_type'] ?? 'post' );
    $hidden    = ! empty( $assoc_args['hidden'] ) ? '' : "AND pm.meta_key NOT LIKE '\\_%'";

    $rows = $wpdb->get_results( $wpdb->prepare(
        "SELECT pm.meta_key, COUNT(DISTINCT pm.post_id) AS posts FROM {$wpdb->postmeta} pm
        INNER JOIN {$wpdb->posts} p ON p.ID = pm.post_id
        WHERE p.post_type = %s $hidden GROUP BY pm.meta_key ORDER BY posts DESC, pm.meta_key",
        $post_type
    ), ARRAY_A );

    if ( ! $rows ) {
        WP_CLI::success( sprintf( 'No custom fields found for %s.', $post_type ) );
        return;
