WP_CLI::add_command( 'content-audit', function ( $args, $assoc_args ) {
    global $wpdb;

    $stale_days = max( 1, (int) ( $assoc_args['stale-days'] ?? 730 ) );
    $cutoff     = gmdate( 'Y-m-d H:i:s', time() - $stale_days * DAY_IN_SECONDS );
    $items      = array();

    foreach ( get_post_types( array( 'public' => true ), 'objects' ) as $type ) {
        if ( 'attachment' === $type->name ) {
            continue;
        }
        $counts = wp_count_posts( $type->name );
        $row    = $wpdb->get_row( $wpdb->prepare(
            "SELECT
                SUM( t.meta_id IS NULL ) AS no_image,
                SUM( p.post_excerpt = '' ) AS no_excerpt,
                SUM( p.post_modified_gmt < %s ) AS stale
            FROM {$wpdb->posts} p
            LEFT JOIN {$wpdb->postmeta} t ON t.post_id = p.ID AND t.meta_key = '_thumbnail_id'
            WHERE p.post_type = %s AND p.post_status = 'publish'",
            $cutoff,
            $type->name
        ) );

        $items[] = array(
            'post_type'  => $type->name,
            'published'  => (int) $counts->publish,
            'drafts'     => (int) $counts->draft,
            'no_image'   => post_type_supports( $type->name, 'thumbnail' ) ? (int) $row->no_image : '-',
            'no_excerpt' => (int) $row->no_excerpt,
            'stale'      => (int) $row->stale,
        );
    }

    WP_CLI\Utils\format_items( $assoc_args['format'] ?? 'table', $items, array( 'post_type', 'published', 'drafts', 'no_image', 'no_excerpt', 'stale' ) );
}, array(
    'shortdesc' => 'Summarizes content health per post type.',
    'synopsis'  => array(
        array( 'type' => 'assoc', 'name' => 'stale-days', 'optional' => true, 'default' => 730 ),
        array( 'type' => 'assoc', 'name' => 'format', 'optional' => true, 'default' => 'table', 'options' => array( 'table', 'csv', 'json' ) ),
    ),
) );

if ( ! defined( 'WP_CLI' ) || ! WP_CLI ) {
    return;
}

WP_CLI::add_command( 'change-status', function ( $args, $assoc_args ) {
    $from     = sanitize_key( $assoc_args['from'] );
    $to       = sanitize_key( $assoc_args['to'] );
    $statuses = get_post_stati();

    if ( ! isset( $statuses[ $from ], $statuses[ $to ] ) ) {
        WP_CLI::error( 'Unknown post status.' );
    }

    $query_args = array(
        'post_type'      => sanitize_key( $assoc_args['post_type'] ?? 'post' ),
        'post_status'    => $from,
        'posts_per_page' => -1,
        'fields'         => 'ids',
        'no_found_rows'  => true,
    );
    if ( ! empty( $assoc_args['before'] ) ) {
        $query_args['date_query'] = array( array( 'before' => sanitize_text_field( $assoc_args['before'] ) ) );
    }

    $ids = get_posts( $query_args );

    if ( empty( $assoc_args['yes'] ) ) {
        WP_CLI::log( sprintf( '%d posts would change from %s to %s. Add --yes to apply.', count( $ids ), $from, $to ) );
        return;
    }

    foreach ( $ids as $id ) {
        wp_update_post( array( 'ID' => $id, 'post_status' => $to ) );
    }

    WP_CLI::success( sprintf( 'Changed %d posts from %s to %s.', count( $ids ), $from, $to ) );
}, array(
    'shortdesc' => 'Moves posts from one status to another.',
    'synopsis'  => array(
        array( 'type' => 'assoc', 'name' => 'from', 'description' => 'Current status, for example draft.' ),
        array( 'type' => 'assoc', 'name' => 'to', 'description' => 'New status, for example pending.' ),
        array( 'type' => 'assoc', 'name' => 'post_type', 'optional' => true, 'default' => 'post' ),
        array( 'type' => 'assoc', 'name' => 'before', 'optional' => true, 'description' => 'Only posts dated before this date (Y-m-d).' ),
