// Keep this many entries.
$wpide_rest_log_size = 100;
// Log 404 responses too.
$wpide_rest_log_404 = true;

add_filter( 'rest_request_after_callbacks', function ( $response, $handler, $request ) use ( $wpide_rest_log_size, $wpide_rest_log_404 ) {
    if ( is_wp_error( $response ) ) {
        $data   = $response->get_error_data();
        $status = is_array( $data ) && isset( $data['status'] ) ? (int) $data['status'] : 500;
        $code   = $response->get_error_code();
    } elseif ( $response instanceof WP_HTTP_Response ) {
        $data   = $response->get_data();
        $status = $response->get_status();
        $code   = is_array( $data ) && isset( $data['code'] ) ? $data['code'] : '';
    } else {
        return $response;
    }

    if ( $status < 400 || ( 404 === $status && ! $wpide_rest_log_404 ) ) {
        return $response;
    }

    $log   = (array) get_option( 'wpide_rest_error_log', array() );
    $log[] = array(
        'time'   => time(),
        'method' => $request->get_method(),
        'route'  => $request->get_route(),
        'status' => $status,
        'code'   => (string) $code,
        'user'   => get_current_user_id(),
    );

    update_option( 'wpide_rest_error_log', array_slice( $log, -$wpide_rest_log_size ), false );

    return $response;
}, 10, 3 );

