        'get_callback' => function ( $object, $field, $request ) {
            // Skip collection requests: adjacent-post lookups are one query each.
            if ( ! $request->get_param( 'id' ) ) {
                return null;
            }

            $current = get_post( $object['id'] );
            if ( ! $current ) {
                return null;
            }

            $GLOBALS['post'] = $current;
            $format          = function ( $post ) {
                return $post ? array( 'id' => $post->ID, 'title' => get_the_title( $post ), 'link' => get_permalink( $post ) ) : null;
            };
            $result = array(
                'previous' => $format( get_previous_post() ),
                'next'     => $format( get_next_post() ),
            );
            wp_reset_postdata();

            return $result;
        },
        'schema'       => array( 'type' => array( 'object', 'null' ), 'context' => array( 'view' ), 'readonly' => true ),
    ) );
} );

// Where to send the webhook (leave empty to disable).
$wpide_webhook_url = 'https://example.com/hooks/wordpress';
