add_action( 'transition_post_status', function ( $new_status, $old_status, $post ) use ( $wpide_webhook_url, $wpide_webhook_post_types ) {
    if ( '' === $wpide_webhook_url || 'publish' !== $new_status || 'publish' === $old_status || ! in_array( $post->post_type, $wpide_webhook_post_types, true ) ) {
        return;
    }
    if ( wp_is_post_revision( $post ) || wp_is_post_autosave( $post ) ) {
        return;
    }

    wp_remote_post( $wpide_webhook_url, array(
        'timeout'  => 3,
        'blocking' => false,
        'headers'  => array( 'Content-Type' => 'application/json' ),
        'body'     => wp_json_encode( array(
            'event'  => 'post_published',
            'id'     => $post->ID,
            'title'  => get_the_title( $post ),
            'link'   => get_permalink( $post ),
            'author' => get_the_author_meta( 'display_name', $post->post_author ),
            'date'   => get_post_time( 'c', true, $post ),
            'site'   => home_url( '/' ),
        ) ),
    ) );
}, 10, 3 );

