if ( ! function_exists( 'wpide_run_later' ) ) {
    /**
     * Schedules $hook to run once after $delay seconds with $args.
     * Returns true when scheduled, false if the same task is already queued.
     */
    function wpide_run_later( $hook, $delay = 60, $args = array() ) {
        $args = array_values( (array) $args );

        if ( wp_next_scheduled( $hook, $args ) ) {
            return false;
        }

        return true === wp_schedule_single_event( time() + max( 1, (int) $delay ), $hook, $args, true );
    }
}

