$wpide_log_notice = function ( $kind, $message ) {
    static $seen = array();
    $key = md5( $kind . $message );
    if ( isset( $seen[ $key ] ) ) {
        return;
    }
    $seen[ $key ] = true;

    // Find the first frame outside WordPress core.
    $source = '';
    foreach ( debug_backtrace( DEBUG_BACKTRACE_IGNORE_ARGS, 25 ) as $frame ) {
        if ( empty( $frame['file'] ) || false !== strpos( $frame['file'], ABSPATH . WPINC ) || false !== strpos( $frame['file'], ABSPATH . 'wp-admin' ) ) {
            continue;
        }
        $source = str_replace( ABSPATH, '', $frame['file'] ) . ':' . ( $frame['line'] ?? 0 );
        break;
    }

    error_log( sprintf( '[WP %s] %s%s', $kind, $message, $source ? ' (from ' . $source . ')' : '' ) );
};

