$wpide_console_flush = function () {
    if ( empty( $GLOBALS['wpide_console_queue'] ) ) {
        return;
    }
    echo '<script>';
    foreach ( $GLOBALS['wpide_console_queue'] as $entry ) {
        list( $label, $value ) = $entry;
        printf( 'console.log(%s, %s);', wp_json_encode( $label ? "PHP: $label" : 'PHP:' ), wp_json_encode( $value, JSON_PARTIAL_OUTPUT_ON_ERROR | JSON_HEX_TAG | JSON_HEX_AMP ) );
    }
    echo '</script>';
    $GLOBALS['wpide_console_queue'] = array();
};

