if ( ! function_exists( 'wpide_log' ) ) {
    function wpide_log( $message, $context = array(), $level = 'info' ) {
        $folder = get_option( 'wpide_log_dir' );
        if ( ! $folder ) {
            $folder = 'wpide-logs-' . wp_generate_password( 12, false );
            update_option( 'wpide_log_dir', $folder, false );
        }

        $uploads = wp_upload_dir( null, false );
        $dir     = trailingslashit( $uploads['basedir'] ) . $folder;

        if ( ! is_dir( $dir ) ) {
            if ( ! wp_mkdir_p( $dir ) ) {
                return false;
            }
            file_put_contents( $dir . '/.htaccess', "Require all denied\nDeny from all\n" );
            file_put_contents( $dir . '/index.php', "<?php\n// Silence is golden.\n" );
        }

        $line = sprintf(
            "[%s] %s: %s%s\n",
            wp_date( 'Y-m-d H:i:s' ),
            strtoupper( sanitize_key( $level ) ),
            is_scalar( $message ) ? (string) $message : wp_json_encode( $message ),
            $context ? ' ' . wp_json_encode( $context, JSON_PARTIAL_OUTPUT_ON_ERROR ) : ''
        );

        return false !== file_put_contents( $dir . '/log-' . wp_date( 'Y-m-d' ) . '.log', $line, FILE_APPEND | LOCK_EX );
    }
}

if ( ! function_exists( 'wpide_dump' ) ) {
    function wpide_dump( $value, $stop = false ) {
        if ( ! current_user_can( 'manage_options' ) ) {
