        $trace = debug_backtrace( DEBUG_BACKTRACE_IGNORE_ARGS, 1 );
        $where = isset( $trace[0]['file'] ) ? str_replace( ABSPATH, '', $trace[0]['file'] ) . ':' . $trace[0]['line'] : '';

        printf(
            '<details open style="margin:1rem 0;padding:.75rem 1rem;background:#1d2327;color:#f0f0f1;border-radius:4px;font:12px/1.5 monospace;text-align:left;position:relative;z-index:99999"><summary>%s</summary><pre style="white-space:pre-wrap;margin:.5rem 0 0;color:inherit;background:none">%s</pre></details>',
            esc_html( 'Dump ' . $where ),
            esc_html( print_r( $value, true ) )
        );

        if ( $stop ) {
            exit;
        }
    }
}

