add_filter( 'site_status_tests', function ( $tests ) use ( $wpide_required_plugins ) {
    $tests['direct']['wpide_required_plugins'] = array(
        'label' => 'Essential plugins are active',
        'test'  => function () use ( $wpide_required_plugins ) {
            if ( ! function_exists( 'is_plugin_active' ) ) {
                require_once ABSPATH . 'wp-admin/includes/plugin.php';
            }

            $missing = array();
            foreach ( $wpide_required_plugins as $file => $name ) {
                if ( ! is_plugin_active( $file ) ) {
                    $missing[] = $name;
                }
            }

            $result = array(
                'label'       => 'All essential plugins are active',
                'status'      => 'good',
                'badge'       => array( 'label' => 'Maintenance', 'color' => 'blue' ),
                'description' => '<p>The plugins this site depends on are installed and active.</p>',
                'test'        => 'wpide_required_plugins',
            );

            if ( $missing ) {
                $result['label']       = 'Essential plugins are inactive';
                $result['status']      = 'critical';
                $result['badge']['color'] = 'red';
                $result['description'] = '<p>These plugins should always be active: ' . esc_html( implode( ', ', $missing ) ) . '.</p>';
                $result['actions']     = '<a href="' . esc_url( admin_url( 'plugins.php' ) ) . '">Go to Plugins</a>';
            }

            return $result;
        },
    );

    return $tests;
} );

