// Added just before the bar renders, so most of the page's cache calls are counted.
add_action( 'wp_before_admin_bar_render', function () {
    global $wp_object_cache, $wp_admin_bar;

    if ( ! current_user_can( 'manage_options' ) || ! is_object( $wp_object_cache ) || ! $wp_admin_bar ) {
        return;
    }

    $hits   = isset( $wp_object_cache->cache_hits ) ? (int) $wp_object_cache->cache_hits : 0;
    $misses = isset( $wp_object_cache->cache_misses ) ? (int) $wp_object_cache->cache_misses : 0;
    $total  = $hits + $misses;
    $rate   = $total ? round( $hits / $total * 100, 1 ) : 0;

    $wp_admin_bar->add_node( array(
        'id'     => 'wpide-object-cache',
        'parent' => 'top-secondary',
        'title'  => esc_html( sprintf( 'Cache %s%% %s', $rate, wp_using_ext_object_cache() ? '(persistent)' : '(runtime)' ) ),
        'meta'   => array( 'title' => sprintf( '%d hits, %d misses', $hits, $misses ) ),
    ) );
} );

// Meta keys whose values are never shown.
$wpide_masked_meta = array( 'session_tokens', '_application_passwords', 'wp_user-settings', 'default_password_nag' );

$wpide_user_meta_table = function ( $user ) use ( $wpide_masked_meta ) {
    if ( ! current_user_can( 'manage_options' ) ) {
        return;
    }

    $meta = get_user_meta( $user->ID );
    ksort( $meta );

    echo '<h2>User meta</h2><table class="widefat striped" style="table-layout:fixed;max-width:1000px"><thead><tr><th style="width:30%">Key</th><th>Value</th></tr></thead><tbody>';
    foreach ( $meta as $key => $values ) {
        $masked = in_array( $key, $wpide_masked_meta, true ) || false !== stripos( $key, 'token' ) || false !== stripos( $key, 'secret' ) || false !== stripos( $key, 'pass' );
        foreach ( $values as $value ) {
            $display = $masked ? '(hidden)' : ( is_serialized( $value ) ? print_r( maybe_unserialize( $value ), true ) : $value );
            printf( '<tr><td><code>%s</code></td><td><code style="white-space:pre-wrap;word-break:break-all">%s</code></td></tr>', esc_html( $key ), esc_html( mb_strimwidth( (string) $display, 0, 400, '...' ) ) );
        }
    }
    echo '</tbody></table>';
};

