if ( ! function_exists( 'wpide_timer_start' ) ) {
    function wpide_timer_start( $name ) {
        $GLOBALS['wpide_timers'][ $name ] = array( microtime( true ), memory_get_usage() );
    }

    function wpide_timer_stop( $name, $log = true ) {
        if ( empty( $GLOBALS['wpide_timers'][ $name ] ) ) {
            return null;
        }

        list( $started, $memory ) = $GLOBALS['wpide_timers'][ $name ];
        unset( $GLOBALS['wpide_timers'][ $name ] );

        $ms = round( ( microtime( true ) - $started ) * 1000, 2 );

        if ( $log ) {
            error_log( sprintf( '[timer] %s: %s ms, %s memory', $name, $ms, size_format( max( 0, memory_get_usage() - $memory ), 1 ) ) );
        }

        return $ms;
    }
}

if ( ! function_exists( 'wpide_flash_notice' ) ) {
    function wpide_flash_notice( $message, $type = 'success' ) {
        $user_id = get_current_user_id();
        if ( ! $user_id ) {
            return;
        }
        $queue   = (array) get_transient( 'wpide_flash_' . $user_id );
        $queue[] = array( 'message' => (string) $message, 'type' => in_array( $type, array( 'success', 'warning', 'error', 'info' ), true ) ? $type : 'info' );
        set_transient( 'wpide_flash_' . $user_id, array_filter( $queue ), 5 * MINUTE_IN_SECONDS );
    }
}

