add_filter( 'single_template', function ( $template ) {
    $post = get_queried_object();
    if ( ! $post instanceof WP_Post || 'post' !== $post->post_type ) {
        return $template;
    }

    $candidates = array();
    foreach ( (array) get_the_category( $post->ID ) as $category ) {
        $candidates[] = 'single-cat-' . $category->slug . '.php';
    }

    $found = $candidates ? locate_template( $candidates ) : '';

    return $found ? $found : $template;
} );

// Folder that holds the templates.
$wpide_template_dir = WP_CONTENT_DIR . '/page-templates';

$wpide_find_templates = function () use ( $wpide_template_dir ) {
    static $found = null;
    if ( null !== $found ) {
        return $found;
    }
    $found = array();
    foreach ( (array) glob( trailingslashit( $wpide_template_dir ) . '*.php' ) as $file ) {
        $data = get_file_data( $file, array( 'name' => 'Template Name' ) );
        if ( $data['name'] ) {
            $found[ 'wpide/' . basename( $file ) ] = $data['name'];
        }
    }
    return $found;
};

add_filter( 'theme_page_templates', function ( $templates ) use ( $wpide_find_templates ) {
    return array_merge( $templates, $wpide_find_templates() );
} );

add_filter( 'template_include', function ( $template ) use ( $wpide_template_dir ) {
    if ( ! is_page() ) {
        return $template;
    }

    $chosen = get_page_template_slug( get_queried_object_id() );
    if ( 0 !== strpos( (string) $chosen, 'wpide/' ) ) {
        return $template;
    }

    $file = trailingslashit( $wpide_template_dir ) . basename( $chosen );

    return is_readable( $file ) ? $file : $template;
}, 99 );

