        }

        $rows = $wpdb->get_results(
            "SELECT o.option_name, LENGTH(o.option_value) AS bytes, t.option_value AS expires
            FROM {$wpdb->options} o
            LEFT JOIN {$wpdb->options} t ON t.option_name = CONCAT('_transient_timeout_', SUBSTRING(o.option_name, 12))
            WHERE o.option_name LIKE '\\_transient\\_%' AND o.option_name NOT LIKE '\\_transient\\_timeout\\_%'
            ORDER BY bytes DESC LIMIT 200"
        );

