$wpide_rebuild_slugs = function ( $redirect, $action, $post_ids ) {
    if ( 'wpide_rebuild_slug' !== $action ) {
        return $redirect;
    }

    $done = 0;
    foreach ( $post_ids as $post_id ) {
        $post = get_post( $post_id );
        if ( ! $post || ! current_user_can( 'edit_post', $post_id ) || '' === trim( $post->post_title ) ) {
            continue;
        }
        $slug = wp_unique_post_slug( sanitize_title( $post->post_title ), $post->ID, $post->post_status, $post->post_type, $post->post_parent );
        if ( $slug !== $post->post_name ) {
            wp_update_post( array( 'ID' => $post->ID, 'post_name' => $slug ) );
            $done++;
        }
    }

    return add_query_arg( 'wpide_slugs_rebuilt', $done, $redirect );
};
add_filter( 'handle_bulk_actions-edit-post', $wpide_rebuild_slugs, 10, 3 );
add_filter( 'handle_bulk_actions-edit-page', $wpide_rebuild_slugs, 10, 3 );

