// Taxonomies to protect.
$wpide_protected_taxonomies = array( 'category', 'post_tag' );

add_filter( 'map_meta_cap', function ( $caps, $cap, $user_id, $args ) use ( $wpide_protected_taxonomies ) {
    if ( 'delete_term' !== $cap || empty( $args[0] ) ) {
        return $caps;
    }

    $term = get_term( (int) $args[0] );
    if ( $term && ! is_wp_error( $term ) && in_array( $term->taxonomy, $wpide_protected_taxonomies, true ) && $term->count > 0 ) {
        $caps[] = 'do_not_allow';
    }

    return $caps;
}, 10, 4 );

add_action( 'set_object_terms', function ( $object_id, $terms, $tt_ids, $taxonomy ) {
    static $running = false;

    if ( 'category' !== $taxonomy || count( $tt_ids ) < 2 || $running || 'post' !== get_post_type( $object_id ) ) {
        return;
    }

    $chosen = null;
    $depth  = -1;
    foreach ( wp_get_object_terms( $object_id, 'category' ) as $term ) {
        $d = count( get_ancestors( $term->term_id, 'category', 'taxonomy' ) );
        if ( $d > $depth || ( $d === $depth && $term->term_id < $chosen ) ) {
            $depth  = $d;
            $chosen = $term->term_id;
        }
    }

    if ( $chosen ) {
        $running = true;
        wp_set_object_terms( $object_id, array( (int) $chosen ), 'category' );
        $running = false;
    }
}, 10, 4 );

