add_action( 'admin_post_wpide_duplicate_menu', function () {
    $menu_id = isset( $_GET['menu'] ) ? absint( $_GET['menu'] ) : 0;
    check_admin_referer( 'wpide_duplicate_menu_' . $menu_id );
    if ( ! current_user_can( 'edit_theme_options' ) || ! is_nav_menu( $menu_id ) ) {
        wp_die( 'Not allowed.', 403 );
    }

    $source = wp_get_nav_menu_object( $menu_id );
    $new_id = wp_create_nav_menu( $source->name . ' (Copy)' );
    if ( is_wp_error( $new_id ) ) {
        wp_die( esc_html( $new_id->get_error_message() ) );
    }

    $map = array();
    foreach ( (array) wp_get_nav_menu_items( $menu_id, array( 'post_status' => 'any' ) ) as $item ) {
        $map[ $item->ID ] = wp_update_nav_menu_item( $new_id, 0, array(
            'menu-item-object-id'   => $item->object_id,
            'menu-item-object'      => $item->object,
            'menu-item-type'        => $item->type,
            'menu-item-title'       => $item->title,
            'menu-item-url'         => $item->url,
            'menu-item-description' => $item->description,
            'menu-item-attr-title'  => $item->attr_title,
            'menu-item-target'      => $item->target,
            'menu-item-classes'     => implode( ' ', (array) $item->classes ),
            'menu-item-xfn'         => $item->xfn,
            'menu-item-position'    => $item->menu_order,
            'menu-item-parent-id'   => $item->menu_item_parent ? ( $map[ $item->menu_item_parent ] ?? 0 ) : 0,
            'menu-item-status'      => 'publish',
        ) );
    }

    wp_safe_redirect( admin_url( 'nav-menus.php?action=edit&menu=' . (int) $new_id ) );
    exit;
} );

// Posts not modified for this many months need a review.
$wpide_review_months = 12;

add_filter( 'views_edit-post', function ( $views ) use ( $wpide_review_months ) {
    $count = get_transient( 'wpide_needs_review_count' );
    if ( false === $count ) {
        $query = new WP_Query( array(
            'post_type'      => 'post',
            'post_status'    => 'publish',
            'posts_per_page' => 1,
            'fields'         => 'ids',
            'date_query'     => array( array( 'column' => 'post_modified_gmt', 'before' => $wpide_review_months . ' months ago' ) ),
        ) );
        $count = (int) $query->found_posts;
        set_transient( 'wpide_needs_review_count', $count, HOUR_IN_SECONDS );
    }

    $current = ! empty( $_GET['wpide_review'] );
    $views['wpide_review'] = sprintf(
        '<a href="%s"%s>Needs review <span class="count">(%d)</span></a>',
        esc_url( admin_url( 'edit.php?post_status=publish&wpide_review=1&orderby=modified&order=asc' ) ),
        $current ? ' class="current" aria-current="page"' : '',
        (int) $count
    );
    return $views;
} );

add_action( 'pre_get_posts', function ( $query ) use ( $wpide_review_months ) {
    if ( ! is_admin() || ! $query->is_main_query() || empty( $_GET['wpide_review'] ) ) {
        return;
    }
    $query->set( 'date_query', array( array( 'column' => 'post_modified_gmt', 'before' => $wpide_review_months . ' months ago' ) ) );
} );

