// Number of events to show.
$wpide_timeline_count = 12;

add_action( 'wp_dashboard_setup', function () use ( $wpide_timeline_count ) {
    wp_add_dashboard_widget( 'wpide_activity_timeline', 'Activity timeline', function () use ( $wpide_timeline_count ) {
        $events = array();

        foreach ( get_posts( array( 'post_type' => array( 'post', 'page' ), 'posts_per_page' => $wpide_timeline_count, 'no_found_rows' => true ) ) as $post ) {
            $events[] = array( get_post_time( 'U', true, $post ), 'dashicons-edit', sprintf( 'Published <a href="%s">%s</a>', esc_url( get_edit_post_link( $post ) ), esc_html( get_the_title( $post ) ) ) );
        }
        foreach ( get_comments( array( 'status' => 'approve', 'number' => $wpide_timeline_count, 'type' => 'comment' ) ) as $comment ) {
            $events[] = array( strtotime( $comment->comment_date_gmt . ' UTC' ), 'dashicons-admin-comments', sprintf( '%s commented on <a href="%s">%s</a>', esc_html( $comment->comment_author ), esc_url( get_comment_link( $comment ) ), esc_html( get_the_title( $comment->comment_post_ID ) ) ) );
        }
        if ( current_user_can( 'list_users' ) ) {
            foreach ( get_users( array( 'number' => $wpide_timeline_count, 'orderby' => 'registered', 'order' => 'DESC' ) ) as $user ) {
                $events[] = array( strtotime( $user->user_registered . ' UTC' ), 'dashicons-admin-users', sprintf( '<a href="%s">%s</a> signed up', esc_url( get_edit_user_link( $user->ID ) ), esc_html( $user->display_name ) ) );
            }
        }

        usort( $events, function ( $a, $b ) {
            return $b[0] <=> $a[0];
        } );

        if ( ! $events ) {
            echo '<p>No activity yet.</p>';
            return;
        }

        echo '<ul style="margin:0">';
        foreach ( array_slice( $events, 0, $wpide_timeline_count ) as $event ) {
            printf(
                '<li style="display:flex;gap:8px;align-items:flex-start;padding:6px 0;border-bottom:1px solid #f0f0f1"><span class="dashicons %s" style="color:#787c82" aria-hidden="true"></span><span style="flex:1">%s<br><small style="color:#646970">%s ago</small></span></li>',
                esc_attr( $event[1] ),
                $event[2],
                esc_html( human_time_diff( $event[0] ) )
            );
        }
        echo '</ul>';
    } );
} );

add_action( 'wp_dashboard_setup', function () {
    if ( ! current_user_can( 'update_plugins' ) ) {
        return;
    }

    wp_add_dashboard_widget( 'wpide_pending_updates', 'Pending updates', function () {
        $plugins      = get_site_transient( 'update_plugins' );
        $themes       = get_site_transient( 'update_themes' );
        $core         = get_site_transient( 'update_core' );
        $plugin_list  = ! empty( $plugins->response ) ? $plugins->response : array();
        $theme_count  = ! empty( $themes->response ) ? count( $themes->response ) : 0;
        $core_update  = ! empty( $core->updates[0] ) && 'upgrade' === $core->updates[0]->response;
        $translations = count( wp_get_translation_updates() );

        if ( ! $plugin_list && ! $theme_count && ! $core_update && ! $translations ) {
            echo '<p><span class="dashicons dashicons-yes-alt" style="color:#00a32a" aria-hidden="true"></span> Everything is up to date.</p>';
            return;
        }

        echo '<ul>';
        if ( $core_update ) {
            printf( '<li><strong>WordPress %s</strong> is available.</li>', esc_html( $core->updates[0]->version ) );
        }
        if ( $plugin_list ) {
            if ( ! function_exists( 'get_plugins' ) ) {
                require_once ABSPATH . 'wp-admin/includes/plugin.php';
            }
            $all   = get_plugins();
            $names = array();
            foreach ( $plugin_list as $file => $update ) {
                $names[] = ( $all[ $file ]['Name'] ?? $file ) . ' ' . $update->new_version;
            }
            printf( '<li><strong>%d plugin updates:</strong> %s</li>', count( $plugin_list ), esc_html( implode( ', ', $names ) ) );
        }
        if ( $theme_count ) {
            printf( '<li><strong>%d theme updates</strong></li>', (int) $theme_count );
        }
        if ( $translations ) {
            printf( '<li><strong>%d translation updates</strong></li>', (int) $translations );
        }
        echo '</ul>';
        printf( '<p><a class="button button-primary" href="%s">Go to updates</a></p>', esc_url( admin_url( 'update-core.php' ) ) );
    } );
} );

