add_action( 'wp_ajax_wpide_todo', function () {
    check_ajax_referer( 'wpide_todo', 'nonce' );
    if ( ! current_user_can( 'edit_others_posts' ) ) {
        wp_send_json_error( null, 403 );
    }

    $items = (array) get_option( 'wpide_todo_items', array() );
    $op    = isset( $_POST['op'] ) ? sanitize_key( $_POST['op'] ) : '';

    if ( 'add' === $op && ! empty( $_POST['text'] ) ) {
        $items[] = array( 'text' => mb_substr( sanitize_text_field( wp_unslash( $_POST['text'] ) ), 0, 200 ), 'done' => false );
    } elseif ( 'toggle' === $op && isset( $_POST['index'], $items[ absint( $_POST['index'] ) ] ) ) {
        $items[ absint( $_POST['index'] ) ]['done'] = empty( $items[ absint( $_POST['index'] ) ]['done'] );
    } elseif ( 'clear' === $op ) {
        $items = array_filter( $items, function ( $item ) {
            return empty( $item['done'] );
        } );
    }

    update_option( 'wpide_todo_items', array_values( $items ), false );
    wp_send_json_success();
} );

