);
// Post types that get the checklist.
$wpide_checklist_types = array( 'post' );

add_action( 'enqueue_block_editor_assets', function () use ( $wpide_checklist_items, $wpide_checklist_types ) {
    $screen = get_current_screen();
    if ( ! $screen || 'post' !== $screen->base || ! in_array( $screen->post_type, $wpide_checklist_types, true ) ) {
        return;
    }

    wp_register_script( 'wpide-prepublish-checklist', false, array( 'wp-plugins', 'wp-element', 'wp-components', 'wp-data', 'wp-editor' ), '1.0', true );
    wp_enqueue_script( 'wpide-prepublish-checklist' );
    wp_add_inline_script( 'wpide-prepublish-checklist', 'var wpideChecklistItems = ' . wp_json_encode( array_values( $wpide_checklist_items ) ) . ';' . <<<'JS'
( function ( wp ) {
    var el = wp.element.createElement;
    var Panel = ( wp.editor && wp.editor.PluginPrePublishPanel ) || ( wp.editPost && wp.editPost.PluginPrePublishPanel );
    if ( ! Panel ) { return; }

    function Checklist() {
        var state = wp.element.useState( {} );
        var checked = state[0], setChecked = state[1];
        var done = wpideChecklistItems.every( function ( item, i ) { return checked[ i ]; } );
        var isPublished = wp.data.useSelect( function ( select ) { return select( 'core/editor' ).isCurrentPostPublished(); }, [] );

        wp.element.useEffect( function () {
            var editor = wp.data.dispatch( 'core/editor' );
            if ( done || isPublished ) { editor.unlockPostSaving( 'wpide-checklist' ); } else { editor.lockPostSaving( 'wpide-checklist' ); }
            return function () { editor.unlockPostSaving( 'wpide-checklist' ); };
        }, [ done, isPublished ] );

        return el( Panel, { title: 'Checklist', initialOpen: true },
            wpideChecklistItems.map( function ( item, i ) {
                return el( wp.components.CheckboxControl, {
                    key: i,
                    label: item,
                    checked: !! checked[ i ],
                    onChange: function ( value ) { var next = Object.assign( {}, checked ); next[ i ] = value; setChecked( next ); }
                } );
            } ),
            done ? null : el( 'p', { style: { color: '#b32d2e' } }, 'Tick every item to enable publishing.' )
        );
    }

    wp.plugins.registerPlugin( 'wpide-prepublish-checklist', { render: Checklist } );
} )( window.wp );
JS
    );
} );

$wpide_has_real_category = function ( $category_ids ) {
    $category_ids = array_filter( array_map( 'absint', (array) $category_ids ) );
    return (bool) array_diff( $category_ids, array( (int) get_option( 'default_category' ) ) );
};

// Block editor and REST API.
add_filter( 'rest_pre_insert_post', function ( $prepared, $request ) use ( $wpide_has_real_category ) {
    $status = $request->get_param( 'status' ) ? $request->get_param( 'status' ) : get_post_status( $prepared->ID ?? 0 );
    if ( ! in_array( $status, array( 'publish', 'future' ), true ) ) {
        return $prepared;
    }

    $categories = null !== $request->get_param( 'categories' ) ? $request->get_param( 'categories' ) : wp_get_post_categories( (int) ( $prepared->ID ?? 0 ) );

    if ( ! $wpide_has_real_category( $categories ) ) {
        return new WP_Error( 'wpide_category_required', 'Please choose a category other than "Uncategorized" before publishing.', array( 'status' => 400 ) );
    }

    return $prepared;
}, 10, 2 );

// Classic editor.
add_filter( 'wp_insert_post_data', function ( $data, $postarr ) use ( $wpide_has_real_category ) {
    if ( 'post' !== $data['post_type'] || ! in_array( $data['post_status'], array( 'publish', 'future' ), true ) || ! isset( $_POST['post_category'] ) || wp_is_serving_rest_request() ) {
        return $data;
    }

    if ( ! $wpide_has_real_category( wp_unslash( $_POST['post_category'] ) ) ) {
        $data['post_status'] = 'draft';
        set_transient( 'wpide_category_notice_' . get_current_user_id(), 1, 60 );
    }

    return $data;
}, 10, 2 );

