} );

// Minimum excerpt length in characters.
$wpide_excerpt_min_chars = 50;
// Post types that need an excerpt.
$wpide_excerpt_types = array( 'post' );

add_filter( 'rest_pre_insert_post', function ( $prepared, $request ) use ( $wpide_excerpt_min_chars, $wpide_excerpt_types ) {
    $post_id = (int) ( $prepared->ID ?? 0 );
    $type    = $post_id ? get_post_type( $post_id ) : 'post';
    $status  = $request->get_param( 'status' ) ? $request->get_param( 'status' ) : get_post_status( $post_id );

    if ( ! in_array( $type, $wpide_excerpt_types, true ) || ! in_array( $status, array( 'publish', 'future' ), true ) ) {
        return $prepared;
    }

    $excerpt = null !== $request->get_param( 'excerpt' ) ? $request->get_param( 'excerpt' ) : get_post_field( 'post_excerpt', $post_id, 'raw' );
    $excerpt = is_array( $excerpt ) ? ( $excerpt['raw'] ?? '' ) : (string) $excerpt;

    if ( mb_strlen( trim( wp_strip_all_tags( $excerpt ) ) ) < $wpide_excerpt_min_chars ) {
        return new WP_Error( 'wpide_excerpt_required', sprintf( 'Please write an excerpt of at least %d characters before publishing.', $wpide_excerpt_min_chars ), array( 'status' => 400 ) );
    }

    return $prepared;
}, 10, 2 );

// Phrases that mean a post is not finished.
$wpide_placeholder_phrases = array( 'lorem ipsum', 'todo', 'tk tk', '[insert', 'xxx', 'placeholder' );

$wpide_find_placeholder = function ( $text ) use ( $wpide_placeholder_phrases ) {
    $text = wp_strip_all_tags( (string) $text );
    foreach ( $wpide_placeholder_phrases as $phrase ) {
        if ( preg_match( '/(^|\W)' . preg_quote( $phrase, '/' ) . '($|\W)/i', $text ) ) {
            return $phrase;
        }
    }
    return '';
};

add_filter( 'rest_pre_insert_post', function ( $prepared, $request ) use ( $wpide_find_placeholder ) {
    $status = $request->get_param( 'status' ) ? $request->get_param( 'status' ) : get_post_status( (int) ( $prepared->ID ?? 0 ) );
    if ( ! in_array( $status, array( 'publish', 'future' ), true ) ) {
        return $prepared;
    }

    $content = $prepared->post_content ?? get_post_field( 'post_content', (int) ( $prepared->ID ?? 0 ), 'raw' );
    $found   = $wpide_find_placeholder( ( $prepared->post_title ?? '' ) . ' ' . $content );

    return $found
        ? new WP_Error( 'wpide_placeholder_text', sprintf( 'This post still contains placeholder text ("%s"). Replace it before publishing.', $found ), array( 'status' => 400 ) )
        : $prepared;
}, 10, 2 );

add_filter( 'wp_insert_post_data', function ( $data ) use ( $wpide_find_placeholder ) {
