// Publishing days (1 = Monday ... 7 = Sunday) and times (24h, site time zone).
$wpide_queue_days  = array( 1, 2, 3, 4, 5 );
$wpide_queue_times = array( '09:00', '15:00' );

add_filter( 'post_row_actions', function ( $actions, $post ) {
    if ( 'draft' === $post->post_status && 'post' === $post->post_type && current_user_can( 'publish_post', $post->ID ) ) {
        $actions['wpide_queue'] = sprintf(
            '<a href="%s">Add to queue</a>',
            esc_url( wp_nonce_url( admin_url( 'admin-post.php?action=wpide_queue_post&post=' . $post->ID ), 'wpide_queue_' . $post->ID ) )
        );
    }
    return $actions;
}, 10, 2 );

add_action( 'admin_post_wpide_queue_post', function () use ( $wpide_queue_days, $wpide_queue_times ) {
    $post_id = isset( $_GET['post'] ) ? absint( $_GET['post'] ) : 0;
    check_admin_referer( 'wpide_queue_' . $post_id );
    if ( ! current_user_can( 'publish_post', $post_id ) || 'draft' !== get_post_status( $post_id ) ) {
        wp_die( 'Not allowed.', 403 );
    }

    // Slots already taken by scheduled posts.
    $taken = array();
    foreach ( get_posts( array( 'post_status' => 'future', 'posts_per_page' => -1, 'fields' => 'ids', 'no_found_rows' => true ) ) as $id ) {
        $taken[ get_post_field( 'post_date', $id ) ] = true;
    }

    $tz   = wp_timezone();
    $day  = new DateTimeImmutable( 'now', $tz );
    $slot = null;
    for ( $i = 0; $i < 90 && ! $slot; $i++ ) {
        $date = $day->modify( "+$i days" );
        if ( ! in_array( (int) $date->format( 'N' ), $wpide_queue_days, true ) ) {
            continue;
        }
        foreach ( $wpide_queue_times as $time ) {
            list( $h, $m ) = array_map( 'intval', explode( ':', $time ) );
            $candidate     = $date->setTime( $h, $m );
            if ( $candidate->getTimestamp() > time() + 5 * MINUTE_IN_SECONDS && empty( $taken[ $candidate->format( 'Y-m-d H:i:s' ) ] ) ) {
                $slot = $candidate;
                break;
            }
        }
    }

    if ( $slot ) {
        wp_update_post( array(
            'ID'            => $post_id,
            'post_status'   => 'future',
            'post_date'     => $slot->format( 'Y-m-d H:i:s' ),
            'post_date_gmt' => get_gmt_from_date( $slot->format( 'Y-m-d H:i:s' ) ),
            'edit_date'     => true,
        ) );
    }

    wp_safe_redirect( add_query_arg( 'wpide_queued', $slot ? rawurlencode( $slot->format( 'Y-m-d H:i' ) ) : 'none', admin_url( 'edit.php' ) ) );
    exit;
} );

add_action( 'admin_notices', function () {
    if ( empty( $_GET['wpide_queued'] ) ) {
        return;
    }
    $slot = sanitize_text_field( wp_unslash( $_GET['wpide_queued'] ) );
    echo 'none' === $slot
        ? '<div class="notice notice-warning is-dismissible"><p>No free slot found in the next 90 days.</p></div>'
        : '<div class="notice notice-success is-dismissible"><p>Scheduled for ' . esc_html( $slot ) . '.</p></div>';
} );

add_action( 'admin_menu', function () {
    add_posts_page( 'Editorial Calendar', 'Calendar', 'edit_posts', 'wpide-calendar', function () {
        $month = isset( $_GET['month'] ) && preg_match( '/^\d{4}-\d{2}$/', $_GET['month'] ) ? sanitize_text_field( wp_unslash( $_GET['month'] ) ) : wp_date( 'Y-m' );
        $first = new DateTimeImmutable( $month . '-01', wp_timezone() );
        $last  = $first->modify( 'last day of this month' );

        $posts = get_posts( array(
            'post_type'      => 'post',
            'post_status'    => array( 'publish', 'future', 'draft', 'pending' ),
            'posts_per_page' => 300,
            'no_found_rows'  => true,
            'date_query'     => array( array( 'after' => $first->format( 'Y-m-d 00:00:00' ), 'before' => $last->format( 'Y-m-d 23:59:59' ), 'inclusive' => true ) ),
        ) );

        $by_day = array();
        foreach ( $posts as $post ) {
            $by_day[ (int) mysql2date( 'j', $post->post_date ) ][] = $post;
        }

        $colors = array( 'publish' => '#00a32a', 'future' => '#2271b1', 'draft' => '#8c8f94', 'pending' => '#dba617' );
        $nav    = function ( $offset, $label ) use ( $first ) {
            return sprintf( '<a class="button" href="%s">%s</a>', esc_url( add_query_arg( array( 'page' => 'wpide-calendar', 'month' => $first->modify( $offset . ' month' )->format( 'Y-m' ) ), admin_url( 'edit.php' ) ) ), esc_html( $label ) );
        };

        echo '<div class="wrap"><h1>Editorial Calendar</h1>';
        printf( '<p style="display:flex;gap:8px;align-items:center">%s <strong style="font-size:16px">%s</strong> %s</p>', $nav( -1, '&larr; Previous' ), esc_html( wp_date( 'F Y', $first->getTimestamp() ) ), $nav( 1, 'Next &rarr;' ) );
        echo '<div style="display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:4px">';

        $start_of_week = (int) get_option( 'start_of_week', 1 );
        for ( $i = 0; $i < 7; $i++ ) {
            printf( '<div style="font-weight:600;padding:4px">%s</div>', esc_html( $GLOBALS['wp_locale']->get_weekday_abbrev( $GLOBALS['wp_locale']->get_weekday( ( $start_of_week + $i ) % 7 ) ) ) );
        }
        $blank = ( (int) $first->format( 'w' ) - $start_of_week + 7 ) % 7;
        echo str_repeat( '<div></div>', $blank );

        for ( $day = 1; $day <= (int) $last->format( 'j' ); $day++ ) {
            echo '<div style="background:#fff;border:1px solid #dcdcde;min-height:90px;padding:4px;overflow:hidden"><div style="color:#646970">' . (int) $day . '</div>';
