add_action( 'admin_post_wpide_rewrite', function () {
    $post_id = isset( $_GET['post'] ) ? absint( $_GET['post'] ) : 0;
    check_admin_referer( 'wpide_rewrite_' . $post_id );
    $post = get_post( $post_id );
    if ( ! $post || ! current_user_can( 'edit_post', $post_id ) ) {
        wp_die( 'Not allowed.', 403 );
    }

    $copy_id = wp_insert_post( wp_slash( array(
        'post_type'     => $post->post_type,
        'post_status'   => 'draft',
        'post_title'    => $post->post_title,
        'post_content'  => $post->post_content,
        'post_excerpt'  => $post->post_excerpt,
        'post_author'   => get_current_user_id(),
        'post_category' => wp_get_post_categories( $post_id ),
        'tags_input'    => wp_get_post_tags( $post_id, array( 'fields' => 'names' ) ),
    ) ) );
    update_post_meta( $copy_id, '_wpide_rewrite_of', $post_id );
    if ( has_post_thumbnail( $post_id ) ) {
        set_post_thumbnail( $copy_id, get_post_thumbnail_id( $post_id ) );
    }

    wp_safe_redirect( get_edit_post_link( $copy_id, 'url' ) );
    exit;
} );

add_action( 'transition_post_status', function ( $new_status, $old_status, $copy ) {
    if ( 'publish' !== $new_status || 'publish' === $old_status ) {
        return;
    }
    $original_id = (int) get_post_meta( $copy->ID, '_wpide_rewrite_of', true );
    if ( ! $original_id || ! get_post( $original_id ) ) {
        return;
    }

    // Copy the new version onto the original, keeping its URL and date.
    wp_update_post( wp_slash( array(
        'ID'           => $original_id,
        'post_title'   => $copy->post_title,
        'post_content' => $copy->post_content,
        'post_excerpt' => $copy->post_excerpt,
    ) ) );
    wp_set_post_categories( $original_id, wp_get_post_categories( $copy->ID ) );
    wp_set_post_tags( $original_id, wp_get_post_tags( $copy->ID, array( 'fields' => 'names' ) ) );
    if ( has_post_thumbnail( $copy->ID ) ) {
        set_post_thumbnail( $original_id, get_post_thumbnail_id( $copy->ID ) );
    }

    delete_post_meta( $copy->ID, '_wpide_rewrite_of' );
    wp_trash_post( $copy->ID );
}, 10, 3 );

add_action( 'admin_notices', function () {
    $post = get_post();
    $screen = get_current_screen();
    if ( $post && $screen && 'post' === $screen->base && ( $original = (int) get_post_meta( $post->ID, '_wpide_rewrite_of', true ) ) ) {
        printf( '<div class="notice notice-info"><p>This is a working copy of <a href="%s">%s</a>. Publishing it will update the original.</p></div>', esc_url( get_permalink( $original ) ), esc_html( get_the_title( $original ) ) );
    }
} );

// Minimum featured image size in pixels.
$wpide_min_thumb_width  = 1200;
$wpide_min_thumb_height = 630;

add_filter( 'rest_pre_insert_post', function ( $prepared, $request ) use ( $wpide_min_thumb_width, $wpide_min_thumb_height ) {
    $post_id = (int) ( $prepared->ID ?? 0 );
    $status  = $request->get_param( 'status' ) ? $request->get_param( 'status' ) : get_post_status( $post_id );
    if ( ! in_array( $status, array( 'publish', 'future' ), true ) ) {
        return $prepared;
    }

    $image_id = null !== $request->get_param( 'featured_media' ) ? (int) $request->get_param( 'featured_media' ) : (int) get_post_thumbnail_id( $post_id );
    if ( ! $image_id ) {
        return $prepared;
    }

    $meta = wp_get_attachment_metadata( $image_id );
    if ( empty( $meta['width'] ) || ( $meta['width'] >= $wpide_min_thumb_width && $meta['height'] >= $wpide_min_thumb_height ) ) {
        return $prepared;
    }

    return new WP_Error(
        'wpide_featured_image_too_small',
        sprintf( 'The featured image is %1$d x %2$d pixels; please use one of at least %3$d x %4$d.', $meta['width'], $meta['height'], $wpide_min_thumb_width, $wpide_min_thumb_height ),
        array( 'status' => 400 )
    );
}, 10, 2 );

// Age in years that triggers the reminder.
$wpide_old_post_years = 2;

add_action( 'enqueue_block_editor_assets', function () use ( $wpide_old_post_years ) {
    $post = get_post();
    if ( ! $post || 'publish' !== $post->post_status || get_post_time( 'U', true, $post ) > strtotime( "-{$wpide_old_post_years} years" ) ) {
        return;
    }

    $message = sprintf( 'This post was published %s ago. Please check that facts, prices, links and screenshots are still correct.', human_time_diff( get_post_time( 'U', true, $post ) ) );

    wp_add_inline_script(
        'wp-notices',
        sprintf( 'wp.domReady(function(){wp.data.dispatch("core/notices").createWarningNotice(%s,{id:"wpide-old-post",isDismissible:true});});', wp_json_encode( $message ) ),
        'after'
    );
    wp_enqueue_script( 'wp-notices' );
    wp_enqueue_script( 'wp-dom-ready' );
} );

// Length of the generated excerpt.
$wpide_auto_excerpt_words = 35;
// Post types to fill.
$wpide_auto_excerpt_types = array( 'post' );

add_filter( 'wp_insert_post_data', function ( $data ) use ( $wpide_auto_excerpt_words, $wpide_auto_excerpt_types ) {
    if ( '' !== trim( $data['post_excerpt'] ) || ! in_array( $data['post_type'], $wpide_auto_excerpt_types, true ) || ! in_array( $data['post_status'], array( 'publish', 'future', 'pending' ), true ) ) {
        return $data;
    }

    $content = wp_unslash( $data['post_content'] );
    $content = excerpt_remove_blocks( strip_shortcodes( $content ) );
    // Skip headings so the summary starts with real text.
    $content = preg_replace( '#<h[1-6][^>]*>.*?</h[1-6]>#is', '', $content );
    $text    = trim( preg_replace( '/\s+/', ' ', wp_strip_all_tags( $content ) ) );

    if ( '' !== $text ) {
        $data['post_excerpt'] = wp_slash( wp_trim_words( $text, $wpide_auto_excerpt_words, '...' ) );
    }

    return $data;
} );

