add_action( 'init', function () {
    add_shortcode( 'show_date', function ( $atts ) {
        $atts = shortcode_atts( array( 'format' => get_option( 'date_format' ), 'offset' => '' ), $atts, 'show_date' );

        $now = new DateTimeImmutable( 'now', wp_timezone() );
        if ( '' !== trim( $atts['offset'] ) ) {
            $offset = sanitize_text_field( $atts['offset'] );
            // Reject text PHP cannot parse instead of letting modify() warn.
            if ( false === strtotime( $offset ) ) {
                return '';
            }
            $now = $now->modify( $offset );
        }

        return '<time datetime="' . esc_attr( $now->format( 'Y-m-d' ) ) . '">' . esc_html( wp_date( $atts['format'], $now->getTimestamp() ) ) . '</time>';
    } );
} );

