        'editor_script_handles' => array( 'wpide-block-sibling-pages' ),
        'render_callback'       => function ( $attributes, $content, $block ) {
            $page_id = ! empty( $block->context['postId'] ) ? (int) $block->context['postId'] : ( isset( $_GET['post_id'] ) ? absint( $_GET['post_id'] ) : get_the_ID() );
            if ( ! $page_id || 'page' !== get_post_type( $page_id ) ) {
                return '';
            }

            $parent = (int) wp_get_post_parent_id( $page_id );
            $pages  = get_pages( array(
                'parent'      => $parent ? $parent : $page_id,
                'sort_column' => 'menu_order,post_title',
