                );
            }

            $label = $parent ? get_the_title( $parent ) : get_the_title( $page_id );

            return sprintf( '<nav %s aria-label="%s"><ul>%s</ul></nav>', get_block_wrapper_attributes( array( 'class' => 'wpide-sibling-pages' ) ), esc_attr( $label ), $items );
        },
    ) );
