    wp_add_inline_script( 'wpide-convert-classic', <<<'JS'
wp.domReady( function () {
    var done = false;
    var unsubscribe = wp.data.subscribe( function () {
        if ( done ) { return; }
        var editor = wp.data.select( 'core/editor' );
        if ( ! editor || ! editor.getCurrentPostId() ) { return; }
        var blocks = wp.data.select( 'core/block-editor' ).getBlocks();
        if ( ! blocks.length ) { return; }
        done = true;
        unsubscribe();

        var count = 0;
        blocks.forEach( function ( block ) {
            if ( block.name !== 'core/freeform' ) { return; }
            var converted = wp.blocks.rawHandler( { HTML: wp.blocks.serialize( block ) } );
            if ( converted.length ) {
                wp.data.dispatch( 'core/block-editor' ).replaceBlocks( block.clientId, converted );
                count++;
            }
        } );

        if ( count ) {
            wp.data.dispatch( 'core/notices' ).createInfoNotice( count + ' classic block(s) converted to blocks. Review the content, then save.', { type: 'snackbar' } );
        }
    } );
} );
JS
    );
} );

