add_action( 'edit_attachment', function ( $attachment_id ) {
    if ( empty( $_FILES['wpide_replace_file']['tmp_name'] ) || ! isset( $_POST['wpide_replace_nonce'] ) || ! wp_verify_nonce( sanitize_key( $_POST['wpide_replace_nonce'] ), 'wpide_replace_' . $attachment_id ) || ! current_user_can( 'edit_post', $attachment_id ) ) {
        return;
    }

    $upload = $_FILES['wpide_replace_file']; // phpcs:ignore WordPress.Security.ValidatedSanitizedInput
    $old    = get_attached_file( $attachment_id );
    $check  = wp_check_filetype_and_ext( $upload['tmp_name'], $upload['name'] );

    if ( UPLOAD_ERR_OK !== (int) $upload['error'] || ! $check['type'] || $check['type'] !== get_post_mime_type( $attachment_id ) || ! is_uploaded_file( $upload['tmp_name'] ) ) {
        set_transient( 'wpide_replace_error_' . get_current_user_id(), 'The new file must be a valid ' . get_post_mime_type( $attachment_id ) . ' file.', 60 );
        return;
    }

    // Remove the old intermediate sizes before writing the new original.
    $meta = wp_get_attachment_metadata( $attachment_id );
    if ( ! empty( $meta['sizes'] ) ) {
        foreach ( $meta['sizes'] as $size ) {
            wp_delete_file( path_join( dirname( $old ), $size['file'] ) );
        }
    }
    if ( ! empty( $meta['original_image'] ) ) {
        $old = path_join( dirname( $old ), $meta['original_image'] );
        update_attached_file( $attachment_id, $old );
    }

    if ( move_uploaded_file( $upload['tmp_name'], $old ) ) {
        require_once ABSPATH . 'wp-admin/includes/image.php';
        wp_update_attachment_metadata( $attachment_id, wp_generate_attachment_metadata( $attachment_id, $old ) );
        clean_post_cache( $attachment_id );
    }
} );

