add_filter( 'wp_generate_attachment_metadata', function ( $metadata, $attachment_id ) {
    if ( 'image/svg+xml' !== get_post_mime_type( $attachment_id ) ) {
        return $metadata;
    }

    $file = get_attached_file( $attachment_id );
    $svg  = $file && is_readable( $file ) ? (string) file_get_contents( $file, false, null, 0, 64 * KB_IN_BYTES ) : '';

    if ( preg_match( '/viewBox=["\']\s*[-\d.]+[\s,]+[-\d.]+[\s,]+([\d.]+)[\s,]+([\d.]+)/i', $svg, $box ) ) {
        $metadata['width']  = (int) round( (float) $box[1] );
        $metadata['height'] = (int) round( (float) $box[2] );
    } elseif ( preg_match( '/<svg[^>]*\swidth=["\']([\d.]+)[^>]*\sheight=["\']([\d.]+)/i', $svg, $size ) ) {
        $metadata['width']  = (int) $size[1];
        $metadata['height'] = (int) $size[2];
    }
    $metadata['file'] = _wp_relative_upload_path( $file );

    return $metadata;
}, 10, 2 );

add_filter( 'wp_prepare_attachment_for_js', function ( $response ) {
    if ( 'image/svg+xml' !== ( $response['mime'] ?? '' ) ) {
        return $response;
    }

    $full = array(
        'url'         => $response['url'],
        'width'       => (int) ( $response['width'] ?? 0 ),
        'height'      => (int) ( $response['height'] ?? 0 ),
        'orientation' => ( $response['height'] ?? 0 ) > ( $response['width'] ?? 0 ) ? 'portrait' : 'landscape',
    );
    $response['image'] = array( 'src' => $response['url'] );
    $response['sizes'] = array( 'full' => $full, 'medium' => $full, 'thumbnail' => $full );

    return $response;
} );

