add_filter( 'wp_editor_set_quality', function ( $quality, $mime_type, $size = array() ) use ( $wpide_small_size_px, $wpide_small_quality, $wpide_large_quality ) {
    if ( ! in_array( $mime_type, array( 'image/jpeg', 'image/webp' ), true ) || empty( $size['width'] ) ) {
