add_filter( 'posts_search', function ( $search, $query ) {
    global $wpdb, $pagenow;

    $is_media_screen = 'upload.php' === $pagenow || ( wp_doing_ajax() && isset( $_REQUEST['action'] ) && 'query-attachments' === $_REQUEST['action'] );
    if ( ! is_admin() || '' === $search || ! $is_media_screen || 'attachment' !== $query->get( 'post_type' ) ) {
        return $search;
    }

    $term = trim( (string) $query->get( 's' ) );
    if ( '' === $term ) {
        return $search;
    }

    $match = $wpdb->prepare(
        "{$wpdb->posts}.ID IN ( SELECT post_id FROM {$wpdb->postmeta} WHERE meta_key = '_wp_attachment_image_alt' AND meta_value LIKE %s )",
        '%' . $wpdb->esc_like( $term ) . '%'
    );

    return preg_replace( '/^\s*AND\s*/', ' AND ( ( ', $search, 1 ) . " ) OR $match )";
}, 10, 2 );

// Longest allowed name, without the extension.
$wpide_max_file_name_length = 60;

add_filter( 'sanitize_file_name', function ( $filename ) use ( $wpide_max_file_name_length ) {
    $info = pathinfo( $filename );
    $name = $info['filename'] ?? $filename;

    if ( mb_strlen( $name ) <= $wpide_max_file_name_length ) {
        return $filename;
    }

    $name = rtrim( mb_substr( $name, 0, $wpide_max_file_name_length ), '-_.' );

    return $name . ( ! empty( $info['extension'] ) ? '.' . $info['extension'] : '' );
}, 20 );

