WP_CLI::add_command( 'media-usage', function ( $args, $assoc_args ) {
    $by     = ( $assoc_args['by'] ?? 'type' ) === 'year' ? 'year' : 'type';
    $totals = array();
    $paged  = 1;

    do {
        $ids = get_posts( array(
            'post_type'      => 'attachment',
            'post_status'    => 'inherit',
            'posts_per_page' => 500,
            'paged'          => $paged++,
            'fields'         => 'ids',
            'no_found_rows'  => true,
        ) );

        foreach ( $ids as $id ) {
            $file  = get_attached_file( $id );
            $bytes = $file && file_exists( $file ) ? filesize( $file ) : 0;
            $meta  = wp_get_attachment_metadata( $id );
            foreach ( (array) ( $meta['sizes'] ?? array() ) as $size ) {
                $path   = $file ? path_join( dirname( $file ), $size['file'] ) : '';
                $bytes += $path && file_exists( $path ) ? filesize( $path ) : 0;
            }
            if ( ! empty( $meta['original_image'] ) && $file ) {
                $original = path_join( dirname( $file ), $meta['original_image'] );
                $bytes   += file_exists( $original ) ? filesize( $original ) : 0;
            }

            $group = 'year' === $by ? get_the_date( 'Y', $id ) : ( get_post_mime_type( $id ) ? get_post_mime_type( $id ) : 'unknown' );
            $totals[ $group ]['files'] = ( $totals[ $group ]['files'] ?? 0 ) + 1;
            $totals[ $group ]['bytes'] = ( $totals[ $group ]['bytes'] ?? 0 ) + $bytes;
        }
    } while ( count( $ids ) === 500 );

    uasort( $totals, function ( $a, $b ) {
        return $b['bytes'] <=> $a['bytes'];
    } );

    $rows = array();
    foreach ( $totals as $group => $data ) {
        $rows[] = array( $by => $group, 'files' => $data['files'], 'size' => size_format( $data['bytes'], 1 ) );
    }

    if ( ! $rows ) {
        WP_CLI::success( 'The Media Library is empty.' );
        return;
    }

    WP_CLI\Utils\format_items( $assoc_args['format'] ?? 'table', $rows, array( $by, 'files', 'size' ) );
}, array(
    'shortdesc' => 'Shows Media Library disk usage grouped by type or year.',
    'synopsis'  => array(
        array( 'type' => 'assoc', 'name' => 'by', 'optional' => true, 'default' => 'type', 'options' => array( 'type', 'year' ) ),
        array( 'type' => 'assoc', 'name' => 'format', 'optional' => true, 'default' => 'table', 'options' => array( 'table', 'csv', 'json' ) ),
    ),
) );

if ( ! defined( 'WP_CLI' ) || ! WP_CLI ) {
    return;
}

WP_CLI::add_command( 'largest-meta', function ( $args, $assoc_args ) {
    global $wpdb;

    $tables = array(
        'post' => array( $wpdb->postmeta, 'post_id' ),
        'user' => array( $wpdb->usermeta, 'user_id' ),
        'term' => array( $wpdb->termmeta, 'term_id' ),
    );
    $which = $assoc_args['table'] ?? 'post';
    if ( ! isset( $tables[ $which ] ) ) {
        WP_CLI::error( 'Use --table=post, user or term.' );
    }
    list( $table, $owner ) = $tables[ $which ];
    $limit = max( 1, min( 200, (int) ( $assoc_args['limit'] ?? 15 ) ) );

    $rows = $wpdb->get_results( $wpdb->prepare(
        "SELECT $owner AS owner_id, meta_key, LENGTH(meta_value) AS bytes FROM $table ORDER BY bytes DESC LIMIT %d",
        $limit
    ), ARRAY_A );

    foreach ( $rows as &$row ) {
        $row['size'] = size_format( (int) $row['bytes'], 1 );
        unset( $row['bytes'] );
    }

    WP_CLI\Utils\format_items( $assoc_args['format'] ?? 'table', $rows, array( 'owner_id', 'meta_key', 'size' ) );
}, array(
    'shortdesc' => 'Lists the largest meta rows.',
    'synopsis'  => array(
        array( 'type' => 'assoc', 'name' => 'table', 'optional' => true, 'default' => 'post', 'options' => array( 'post', 'user', 'term' ) ),
        array( 'type' => 'assoc', 'name' => 'limit', 'optional' => true, 'default' => 15 ),
