}

WP_CLI::add_command( 'rename-shortcode', function ( $args, $assoc_args ) {
    global $wpdb;

    list( $old, $new ) = array_map( 'sanitize_key', $args );
    if ( ! $old || ! $new || $old === $new ) {
        WP_CLI::error( 'Give two different shortcode tags.' );
    }

    // Matches [old ...], [old] and [/old] but not [old_more].
    $pattern = '/\[(\/?)' . preg_quote( $old, '/' ) . '(?=[\s\]\/])/';
    $rows    = $wpdb->get_results( $wpdb->prepare(
        "SELECT ID, post_content FROM {$wpdb->posts} WHERE post_type NOT IN ('revision') AND post_status NOT IN ('trash','auto-draft') AND post_content LIKE %s",
        '%[' . $wpdb->esc_like( $old ) . '%'
    ) );

    $changed = 0;
    foreach ( $rows as $row ) {
        $content = preg_replace( $pattern, '[$1' . $new, $row->post_content, -1, $count );
        if ( ! $count ) {
            continue;
        }
        $changed++;
        if ( ! empty( $assoc_args['yes'] ) ) {
            wp_update_post( array( 'ID' => (int) $row->ID, 'post_content' => wp_slash( $content ) ) );
        }
    }

    if ( empty( $assoc_args['yes'] ) ) {
        WP_CLI::log( sprintf( '%d posts use [%s] and would be updated. Add --yes to apply.', $changed, $old ) );
        return;
    }
    WP_CLI::success( sprintf( 'Renamed [%s] to [%s] in %d posts.', $old, $new, $changed ) );
}, array(
    'shortdesc' => 'Renames a shortcode tag in all content.',
    'synopsis'  => array(
        array( 'type' => 'positional', 'name' => 'old' ),
        array( 'type' => 'positional', 'name' => 'new' ),
        array( 'type' => 'flag', 'name' => 'yes', 'optional' => true ),
    ),
) );

if ( ! defined( 'WP_CLI' ) || ! WP_CLI ) {
    return;
}

WP_CLI::add_command( 'shortcodes-in-use', function ( $args, $assoc_args ) {
    global $wpdb;

    $usage = array();
    $last  = 0;
    do {
        $rows = $wpdb->get_results( $wpdb->prepare(
            "SELECT ID, post_content FROM {$wpdb->posts} WHERE ID > %d AND post_type NOT IN ('revision','attachment','nav_menu_item')
            AND post_status NOT IN ('trash','auto-draft') AND post_content LIKE '%%[%%' ORDER BY ID LIMIT 500",
            $last
        ) );
        foreach ( $rows as $row ) {
            $last = (int) $row->ID;
            // Strip block comments so JSON in them is not mistaken for shortcodes.
            $text = preg_replace( '/<!--.*?-->/s', '', $row->post_content );
            if ( preg_match_all( '/\[([a-zA-Z][\w-]*)(?=[\s\]\/])/', $text, $matches ) ) {
                foreach ( array_unique( $matches[1] ) as $tag ) {
                    $usage[ $tag ] = ( $usage[ $tag ] ?? 0 ) + 1;
                }
            }
        }
    } while ( count( $rows ) === 500 );

    if ( ! $usage ) {
        WP_CLI::success( 'No shortcodes found in content.' );
        return;
    }

    arsort( $usage );
    $items = array();
    foreach ( $usage as $tag => $posts ) {
        $items[] = array( 'shortcode' => $tag, 'posts' => $posts, 'status' => shortcode_exists( $tag ) ? 'registered' : 'missing' );
    }

    WP_CLI\Utils\format_items( $assoc_args['format'] ?? 'table', $items, array( 'shortcode', 'posts', 'status' ) );
}, array(
    'shortdesc' => 'Lists shortcode tags used in content.',
    'synopsis'  => array(
        array( 'type' => 'assoc', 'name' => 'format', 'optional' => true, 'default' => 'table', 'options' => array( 'table', 'csv', 'json' ) ),
    ),
) );

if ( ! defined( 'WP_CLI' ) || ! WP_CLI ) {
    return;
}

