if ( ! function_exists( 'wpide_remember' ) ) {
    function wpide_remember( $key, $seconds, callable $callback ) {
        $cache_key = 'wpide_rmb_' . md5( $key );
        $cached    = get_transient( $cache_key );

        // Wrapped so that false and empty results are cached too.
        if ( is_array( $cached ) && array_key_exists( 'value', $cached ) ) {
            return $cached['value'];
        }

        $value = call_user_func( $callback );
        if ( ! is_wp_error( $value ) ) {
            set_transient( $cache_key, array( 'value' => $value ), max( 1, (int) $seconds ) );
        }

        return $value;
    }

    function wpide_forget( $key ) {
        return delete_transient( 'wpide_rmb_' . md5( $key ) );
    }
}

