// Query arguments worth remembering.
$wpide_remembered_args = array( 'post_status', 'cat', 'category_name', 'author', 'm', 's', 'orderby', 'order', 'tag', 'post_format', 'mode', 'attachment-filter' );

$wpide_remember_filters = function () use ( $wpide_remembered_args ) {
    global $pagenow;

    $post_type = isset( $_GET['post_type'] ) ? sanitize_key( $_GET['post_type'] ) : ( 'upload.php' === $pagenow ? 'attachment' : 'post' );
    $screen    = $pagenow . ':' . $post_type;
    $saved     = (array) get_user_meta( get_current_user_id(), 'wpide_list_filters', true );
    $current   = array_intersect_key( wp_unslash( $_GET ), array_flip( $wpide_remembered_args ) );

    if ( $current ) {
        $saved[ $screen ] = array_map( 'sanitize_text_field', $current );
        update_user_meta( get_current_user_id(), 'wpide_list_filters', $saved );
        return;
    }

    // A plain visit restores the last filters, unless "All" was clicked from the list itself.
    $from_list = wp_get_referer() && false !== strpos( wp_get_referer(), $pagenow );
    if ( ! empty( $saved[ $screen ] ) && ! $from_list && empty( $_GET['paged'] ) ) {
        $args = $saved[ $screen ];
        if ( 'attachment' !== $post_type && 'post' !== $post_type ) {
            $args['post_type'] = $post_type;
        }
        wp_safe_redirect( add_query_arg( array_map( 'rawurlencode', $args ), admin_url( $pagenow ) ) );
        exit;
    }

    if ( $from_list && isset( $saved[ $screen ] ) ) {
        unset( $saved[ $screen ] );
        update_user_meta( get_current_user_id(), 'wpide_list_filters', $saved );
    }
};

