// Maximum number of tags per post.
$wpide_max_tags = 5;

add_action( 'set_object_terms', function ( $object_id, $terms, $tt_ids, $taxonomy ) use ( $wpide_max_tags ) {
    static $running = false;

    if ( 'post_tag' !== $taxonomy || $running || count( $tt_ids ) <= $wpide_max_tags ) {
        return;
    }

    $running = true;
    $keep    = array_slice( array_map( 'intval', $tt_ids ), 0, $wpide_max_tags );
    $ids     = array();
    foreach ( $keep as $tt_id ) {
        $term = get_term_by( 'term_taxonomy_id', $tt_id, 'post_tag' );
        if ( $term ) {
            $ids[] = (int) $term->term_id;
        }
    }
    wp_set_object_terms( $object_id, $ids, 'post_tag' );
    set_transient( 'wpide_tags_trimmed_' . get_current_user_id(), 1, 60 );
    $running = false;
}, 10, 4 );

