// Leave administrators' content untouched.
$wpide_clean_skip_admins = false;
// Post types to clean.
$wpide_clean_post_types = array( 'post', 'page' );

add_filter( 'wp_insert_post_data', function ( $data ) use ( $wpide_clean_skip_admins, $wpide_clean_post_types ) {
    if ( ! in_array( $data['post_type'], $wpide_clean_post_types, true ) || ( $wpide_clean_skip_admins && current_user_can( 'manage_options' ) ) ) {
        return $data;
    }

    $content = wp_unslash( $data['post_content'] );

    // Process only the HTML between block comments, so block attributes stay valid.
    $parts = preg_split( '/(<!--.*?-->)/s', $content, -1, PREG_SPLIT_DELIM_CAPTURE );
    $depth = 0;
    foreach ( $parts as $i => $part ) {
        if ( 0 === strpos( $part, '<!--' ) ) {
            if ( preg_match( '/^<!--\s+wp:[^\s]+\s+\{.*"style"/s', $part ) ) {
                $depth++; // Styled block: keep its markup as is.
            } elseif ( $depth && preg_match( '/^<!--\s+\/wp:/', $part ) ) {
                $depth--;
            }
            continue;
        }
        if ( $depth ) {
            continue;
        }
        // Keep only text alignment, which the classic editor stores as an inline style.
        $part = preg_replace_callback( '/\sstyle=("|\')([^"\']*)\1/i', function ( $m ) {
            return preg_match( '/text-align\s*:\s*(left|right|center|justify)/i', $m[2], $align ) ? ' style="text-align:' . strtolower( $align[1] ) . '"' : '';
        }, $part );
        $part = preg_replace( '/\sclass=("|\')\s*Mso[^"\']*\1/i', '', $part );
        $part = preg_replace( '#</?font[^>]*>#i', '', $part );
        $part = preg_replace( '#<span>(.*?)</span>#is', '$1', $part );
        $parts[ $i ] = $part;
    }

    $data['post_content'] = wp_slash( implode( '', $parts ) );
    return $data;
}, 20 );

add_action( 'rest_api_init', function () {
    register_rest_route( 'site/v1', '/title-check', array(
        'methods'             => WP_REST_Server::READABLE,
        'permission_callback' => function () {
            return current_user_can( 'edit_posts' );
        },
        'args'                => array(
            'title'   => array( 'type' => 'string', 'required' => true, 'sanitize_callback' => 'sanitize_text_field' ),
            'exclude' => array( 'type' => 'integer', 'default' => 0 ),
            'type'    => array( 'type' => 'string', 'default' => 'post', 'sanitize_callback' => 'sanitize_key' ),
        ),
        'callback'            => function ( WP_REST_Request $request ) {
            global $wpdb;
            $title = trim( $request['title'] );
            if ( mb_strlen( $title ) < 3 ) {
                return rest_ensure_response( array() );
            }
            $rows = $wpdb->get_results( $wpdb->prepare(
                "SELECT ID, post_status FROM {$wpdb->posts} WHERE post_title = %s AND post_type = %s AND ID <> %d AND post_status IN ('publish','future','draft','pending','private') LIMIT 5",
                $title,
                $request['type'],
                (int) $request['exclude']
            ) );
            return rest_ensure_response( array_map( function ( $row ) {
                return array( 'id' => (int) $row->ID, 'status' => $row->post_status, 'edit' => get_edit_post_link( $row->ID, 'raw' ) );
            }, $rows ) );
        },
    ) );
} );

add_action( 'enqueue_block_editor_assets', function () {
    $screen = get_current_screen();
    if ( ! $screen || 'post' !== $screen->base ) {
        return;
    }

    wp_register_script( 'wpide-title-check', false, array( 'wp-data', 'wp-api-fetch', 'wp-url', 'wp-notices', 'wp-dom-ready', 'wp-editor' ), '1.0', true );
    wp_enqueue_script( 'wpide-title-check' );
    wp_add_inline_script( 'wpide-title-check', <<<'JS'
wp.domReady( function () {
    var lastTitle = null, timer = null;
    wp.data.subscribe( function () {
        var editor = wp.data.select( 'core/editor' );
        if ( ! editor || ! editor.getCurrentPostId() ) { return; }
        var title = ( editor.getEditedPostAttribute( 'title' ) || '' ).trim();
        if ( title === lastTitle ) { return; }
        lastTitle = title;
        clearTimeout( timer );
        timer = setTimeout( function () {
            var notices = wp.data.dispatch( 'core/notices' );
            notices.removeNotice( 'wpide-duplicate-title' );
            if ( title.length < 3 ) { return; }
            wp.apiFetch( { path: wp.url.addQueryArgs( '/site/v1/title-check', { title: title, exclude: editor.getCurrentPostId(), type: editor.getCurrentPostType() } ) } ).then( function ( matches ) {
                if ( matches.length ) {
                    notices.createWarningNotice( 'Another item already uses this title (' + matches.map( function ( m ) { return '#' + m.id + ' ' + m.status; } ).join( ', ' ) + ').', { id: 'wpide-duplicate-title', isDismissible: true } );
                }
            } ).catch( function () {} );
        }, 800 );
    } );
} );
JS
    );
} );

add_action( 'init', function () {
    add_shortcode( 'attached_files', function ( $atts ) {
        $atts    = shortcode_atts( array( 'type' => '', 'title' => '', 'images' => 'no', 'id' => 0 ), $atts, 'attached_files' );
        $post_id = $atts['id'] ? absint( $atts['id'] ) : get_the_ID();
        if ( ! $post_id ) {
            return '';
        }

        $files = get_children( array(
            'post_parent'    => $post_id,
            'post_type'      => 'attachment',
            'post_mime_type' => $atts['type'] ? sanitize_mime_type( $atts['type'] ) : '',
            'orderby'        => 'menu_order title',
            'order'          => 'ASC',
            'numberposts'    => 100,
        ) );

        if ( 'yes' !== $atts['images'] ) {
            $files = array_filter( $files, function ( $file ) {
                return 0 !== strpos( $file->post_mime_type, 'image/' );
            } );
        }
        if ( ! $files ) {
            return '';
        }

        $html = '' !== $atts['title'] ? '<h3 class="wpide-files-title">' . esc_html( $atts['title'] ) . '</h3>' : '';
        $html .= '<ul class="wpide-attached-files">';
        foreach ( $files as $file ) {
            $path = get_attached_file( $file->ID );
            $meta = wp_get_attachment_metadata( $file->ID );
            $size = ! empty( $meta['filesize'] ) ? (int) $meta['filesize'] : ( $path && file_exists( $path ) ? filesize( $path ) : 0 );
            $html .= sprintf(
                '<li><a href="%s" download>%s</a> <small>(%s%s)</small></li>',
                esc_url( wp_get_attachment_url( $file->ID ) ),
