                esc_html( strtoupper( pathinfo( (string) $path, PATHINFO_EXTENSION ) ) ),
                $size ? esc_html( ', ' . size_format( $size, 1 ) ) : ''
            );
        }
        return $html . '</ul>';
    } );
} );

