        $cache_key = 'wpide_recent_upd_' . md5( wp_json_encode( $atts ) . get_option( 'wpide_recent_upd_ver', '1' ) );
        $html      = get_transient( $cache_key );
        if ( false !== $html ) {
            return $html;
        }

        global $wpdb;
        $types = array_filter( array_map( 'sanitize_key', explode( ',', $atts['post_type'] ) ) );
        $in    = implode( ',', array_fill( 0, count( $types ), '%s' ) );
        $ids   = $wpdb->get_col( $wpdb->prepare(
            "SELECT ID FROM {$wpdb->posts} WHERE post_status = 'publish' AND post_type IN ($in) AND post_password = ''
            AND post_modified_gmt > DATE_ADD(post_date_gmt, INTERVAL 1 DAY) ORDER BY post_modified_gmt DESC LIMIT %d",
            array_merge( $types, array( max( 1, min( 20, (int) $atts['count'] ) ) ) )
        ) );

        $html = '';
        if ( $ids ) {
            _prime_post_caches( $ids, false, false );
            $html = '<ul class="wpide-recently-updated">';
            foreach ( $ids as $id ) {
                $html .= sprintf(
                    '<li><a href="%s">%s</a> <small>updated <time datetime="%s">%s</time></small></li>',
