    $actions['wpide_export_media'] = 'Export to CSV';
    return $actions;
} );

add_filter( 'handle_bulk_actions-upload', function ( $redirect, $action, $ids ) {
    if ( 'wpide_export_media' !== $action || ! current_user_can( 'upload_files' ) ) {
        return $redirect;
    }

    $rows = array( array( 'ID', 'URL', 'Title', 'Alt text', 'Caption', 'Type', 'File size', 'Width', 'Height', 'Uploaded' ) );
    foreach ( $ids as $id ) {
        if ( 'attachment' !== get_post_type( $id ) ) {
            continue;
        }
        $meta   = wp_get_attachment_metadata( $id );
        $file   = get_attached_file( $id );
        $rows[] = array(
            $id,
            wp_get_attachment_url( $id ),
            get_the_title( $id ),
            get_post_meta( $id, '_wp_attachment_image_alt', true ),
            wp_get_attachment_caption( $id ),
            get_post_mime_type( $id ),
            ! empty( $meta['filesize'] ) ? $meta['filesize'] : ( $file && file_exists( $file ) ? filesize( $file ) : '' ),
            $meta['width'] ?? '',
            $meta['height'] ?? '',
            get_the_date( 'Y-m-d', $id ),
        );
    }

    if ( defined( 'WP_CLI' ) && WP_CLI ) {
        return $redirect;
    }

    nocache_headers();
    header( 'Content-Type: text/csv; charset=utf-8' );
    header( 'Content-Disposition: attachment; filename=media-' . gmdate( 'Y-m-d' ) . '.csv' );
    $out = fopen( 'php://output', 'w' );
    fwrite( $out, "\xEF\xBB\xBF" );
    foreach ( $rows as $row ) {
        fputcsv( $out, array_map( function ( $cell ) {
            return is_string( $cell ) && preg_match( '/^[=+\-@]/', $cell ) ? "'" . $cell : $cell;
        }, $row ) );
    }
    fclose( $out );
    exit;
}, 10, 3 );

// Largest total size to zip, in megabytes.
$wpide_zip_limit_mb = 200;

add_filter( 'bulk_actions-upload', function ( $actions ) {
    if ( class_exists( 'ZipArchive' ) ) {
        $actions['wpide_zip_media'] = 'Download as ZIP';
    }
    return $actions;
} );

add_filter( 'handle_bulk_actions-upload', function ( $redirect, $action, $ids ) use ( $wpide_zip_limit_mb ) {
    if ( 'wpide_zip_media' !== $action || ! class_exists( 'ZipArchive' ) || ! current_user_can( 'upload_files' ) ) {
        return $redirect;
    }

    $files = array();
    $total = 0;
    foreach ( $ids as $id ) {
        $path = function_exists( 'wp_get_original_image_path' ) && wp_attachment_is_image( $id ) ? wp_get_original_image_path( $id ) : get_attached_file( $id );
        if ( $path && is_readable( $path ) && current_user_can( 'read_post', $id ) ) {
            $files[] = $path;
            $total  += filesize( $path );
        }
    }

    if ( ! $files || $total > $wpide_zip_limit_mb * MB_IN_BYTES ) {
        return add_query_arg( 'wpide_zip', $files ? 'too_big' : 'empty', $redirect );
    }
    if ( defined( 'WP_CLI' ) && WP_CLI ) {
        return $redirect;
    }

    $zip_path = wp_tempnam( 'media.zip' );
    $zip      = new ZipArchive();
    if ( true !== $zip->open( $zip_path, ZipArchive::OVERWRITE ) ) {
        return add_query_arg( 'wpide_zip', 'failed', $redirect );
    }
    $used = array();
    foreach ( $files as $path ) {
        $name = wp_basename( $path );
        // Avoid collisions between files with the same name in different months.
        $name = isset( $used[ $name ] ) ? pathinfo( $name, PATHINFO_FILENAME ) . '-' . count( $used ) . '.' . pathinfo( $name, PATHINFO_EXTENSION ) : $name;
        $used[ $name ] = true;
        $zip->addFile( $path, $name );
    }
    $zip->close();

    nocache_headers();
    header( 'Content-Type: application/zip' );
    header( 'Content-Disposition: attachment; filename=media-' . gmdate( 'Y-m-d' ) . '.zip' );
    header( 'Content-Length: ' . filesize( $zip_path ) );
    readfile( $zip_path );
    wp_delete_file( $zip_path );
    exit;
}, 10, 3 );

