$wpide_user_folder = function ( $dirs ) {
    $user = wp_get_current_user();
    if ( ! $user->exists() ) {
        return $dirs;
    }

    $folder = '/users/' . sanitize_file_name( $user->user_nicename );
    if ( 0 === strpos( $dirs['subdir'], $folder ) ) {
        return $dirs;
    }

    $dirs['subdir'] = $folder . $dirs['subdir'];
    $dirs['path']   = $dirs['basedir'] . $dirs['subdir'];
    $dirs['url']    = $dirs['baseurl'] . $dirs['subdir'];

    return $dirs;
};

// Only change the folder while a file is being uploaded.
$wpide_user_folder_on = function ( $file ) use ( $wpide_user_folder ) {
    add_filter( 'upload_dir', $wpide_user_folder );
    return $file;
};
$wpide_user_folder_off = function ( $upload ) use ( $wpide_user_folder ) {
    remove_filter( 'upload_dir', $wpide_user_folder );
    return $upload;
};
add_filter( 'wp_handle_upload_prefilter', $wpide_user_folder_on );
