add_filter( 'pre_delete_attachment', function ( $delete, $post ) {
    global $wpdb;

    if ( ! $post instanceof WP_Post || 'attachment' !== $post->post_type ) {
        return $delete;
    }

    $used_by = (int) $wpdb->get_var( $wpdb->prepare(
        "SELECT pm.post_id FROM {$wpdb->postmeta} pm INNER JOIN {$wpdb->posts} p ON p.ID = pm.post_id
        WHERE pm.meta_key = '_thumbnail_id' AND pm.meta_value = %d AND p.post_status NOT IN ('trash','auto-draft') AND p.post_type <> 'revision' LIMIT 1",
        $post->ID
    ) );

    if ( ! $used_by ) {
        return $delete;
    }

    if ( wp_doing_ajax() || ( defined( 'REST_REQUEST' ) && REST_REQUEST ) || ( defined( 'WP_CLI' ) && WP_CLI ) ) {
        return false; // The deletion simply fails.
    }

    wp_die(
        esc_html( sprintf( 'This image is the featured image of "%s". Choose another featured image before deleting it.', get_the_title( $used_by ) ) ),
        'Image in use',
        array( 'response' => 409, 'back_link' => true )
    );
}, 10, 2 );

add_action( 'wp_dashboard_setup', function () {
    if ( ! current_user_can( 'edit_posts' ) ) {
        return;
    }

    wp_add_dashboard_widget( 'wpide_writing_stats', 'Your writing stats', function () {
        global $wpdb;

        $user_id = get_current_user_id();
        $stats   = get_transient( 'wpide_writing_stats_' . $user_id );

        if ( false === $stats ) {
            $year_start  = wp_date( 'Y-01-01 00:00:00' );
            $month_start = wp_date( 'Y-m-01 00:00:00' );
            $rows        = $wpdb->get_results( $wpdb->prepare(
                "SELECT post_date, post_content FROM {$wpdb->posts} WHERE post_author = %d AND post_type = 'post' AND post_status = 'publish' AND post_date >= %s",
                $user_id,
                $year_start
            ) );
            $stats = array( 'month_posts' => 0, 'month_words' => 0, 'year_posts' => 0, 'year_words' => 0 );
            foreach ( $rows as $row ) {
                $words = str_word_count( wp_strip_all_tags( strip_shortcodes( $row->post_content ) ) );
                $stats['year_posts']++;
                $stats['year_words'] += $words;
                if ( $row->post_date >= $month_start ) {
                    $stats['month_posts']++;
                    $stats['month_words'] += $words;
                }
            }
            $stats['drafts'] = (int) $wpdb->get_var( $wpdb->prepare( "SELECT COUNT(*) FROM {$wpdb->posts} WHERE post_author = %d AND post_type = 'post' AND post_status = 'draft'", $user_id ) );
            set_transient( 'wpide_writing_stats_' . $user_id, $stats, HOUR_IN_SECONDS );
        }

        $cells = array(
            'Posts this month' => $stats['month_posts'],
            'Words this month' => $stats['month_words'],
            'Posts this year'  => $stats['year_posts'],
            'Words this year'  => $stats['year_words'],
            'Drafts waiting'   => $stats['drafts'],
        );
        echo '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:8px">';
        foreach ( $cells as $label => $value ) {
            printf( '<div style="border:1px solid #dcdcde;border-radius:4px;padding:10px;text-align:center"><div style="font-size:20px;font-weight:600">%s</div><div style="color:#646970">%s</div></div>', esc_html( number_format_i18n( $value ) ), esc_html( $label ) );
        }
        echo '</div>';
    } );
} );

add_action( 'wp_dashboard_setup', function () {
    if ( ! current_user_can( 'moderate_comments' ) ) {
        return;
    }

    wp_add_dashboard_widget( 'wpide_comments_trend', 'Comments in the last 30 days', function () {
        global $wpdb;

        $rows = get_transient( 'wpide_comments_trend' );
        if ( false === $rows ) {
            $rows = $wpdb->get_results( $wpdb->prepare(
                "SELECT DATE(comment_date) AS day, COUNT(*) AS total FROM {$wpdb->comments}
                WHERE comment_approved = '1' AND comment_type IN ('comment','') AND comment_date >= %s GROUP BY day",
                wp_date( 'Y-m-d 00:00:00', strtotime( '-29 days', current_time( 'timestamp' ) ) )
            ), OBJECT_K );
            set_transient( 'wpide_comments_trend', $rows, HOUR_IN_SECONDS );
        }

        $days = array();
        for ( $i = 29; $i >= 0; $i-- ) {
            $day          = wp_date( 'Y-m-d', strtotime( "-$i days", current_time( 'timestamp' ) ) );
            $days[ $day ] = isset( $rows[ $day ] ) ? (int) $rows[ $day ]->total : 0;
        }
        $max   = max( 1, max( $days ) );
        $total = array_sum( $days );

        printf( '<p><strong>%s</strong> comments in 30 days</p>', esc_html( number_format_i18n( $total ) ) );
        echo '<div style="display:flex;align-items:flex-end;gap:2px;height:80px" role="img" aria-label="' . esc_attr( sprintf( '%d comments in the last 30 days', $total ) ) . '">';
        foreach ( $days as $day => $count ) {
            printf(
                '<div title="%s: %d" style="flex:1;height:%d%%;min-height:2px;background:%s;border-radius:2px 2px 0 0"></div>',
                esc_attr( mysql2date( get_option( 'date_format' ), $day ) ),
                (int) $count,
                (int) round( $count / $max * 100 ),
                $count ? '#2271b1' : '#dcdcde'
            );
        }
        echo '</div>';
    } );
} );

