// Folders whose deprecation notices are silenced.
$wpide_quiet_paths = array( WP_PLUGIN_DIR, get_theme_root() );

$wpide_previous_handler = set_error_handler( function ( $errno, $errstr, $errfile = '', $errline = 0 ) use ( $wpide_quiet_paths, &$wpide_previous_handler ) {
    if ( in_array( $errno, array( E_DEPRECATED, E_USER_DEPRECATED ), true ) ) {
        foreach ( $wpide_quiet_paths as $path ) {
            if ( 0 === strpos( (string) $errfile, $path ) ) {
                return true; // Handled: do not log.
            }
        }
    }
    // Hand everything else to the previous handler, or to PHP itself.
    return $wpide_previous_handler ? call_user_func( $wpide_previous_handler, $errno, $errstr, $errfile, $errline ) : false;
} );

