add_action( 'admin_bar_menu', function ( $admin_bar ) {
    if ( ! current_user_can( 'manage_options' ) ) {
        return;
    }

    foreach ( array( ABSPATH, trailingslashit( get_stylesheet_directory() ) ) as $root ) {
        $head = $root . '.git/HEAD';
        if ( ! is_readable( $head ) ) {
            continue;
        }

        $ref = trim( (string) file_get_contents( $head ) );
        if ( 0 === strpos( $ref, 'ref:' ) ) {
            $branch = basename( trim( substr( $ref, 4 ) ) );
            $file   = $root . '.git/' . trim( substr( $ref, 4 ) );
            $commit = is_readable( $file ) ? substr( trim( (string) file_get_contents( $file ) ), 0, 7 ) : '';
        } else {
            $branch = 'detached';
            $commit = substr( $ref, 0, 7 );
        }

        $admin_bar->add_node( array(
            'id'     => 'wpide-git',
            'parent' => 'top-secondary',
            'title'  => '<span class="ab-icon dashicons dashicons-randomize" style="margin-top:2px" aria-hidden="true"></span>' . esc_html( $branch . ( $commit ? ' @ ' . $commit : '' ) ),
            'meta'   => array( 'title' => esc_attr( 'Git repository: ' . str_replace( ABSPATH, '/', $root ) ) ),
        ) );
        return;
    }
}, 100 );

// Production site address, without a trailing slash.
$wpide_live_url = 'https://www.example.com';

$wpide_live_media = function ( $url ) use ( $wpide_live_url ) {
    static $uploads = null;

    if ( 'production' === wp_get_environment_type() || ! is_string( $url ) || '' === $url ) {
        return $url;
    }
    if ( null === $uploads ) {
        $uploads = wp_get_upload_dir();
    }
    if ( 0 !== strpos( $url, $uploads['baseurl'] ) ) {
        return $url;
    }

    $relative = substr( $url, strlen( $uploads['baseurl'] ) );
    $local    = $uploads['basedir'] . strtok( $relative, '?' );
    if ( file_exists( $local ) ) {
        return $url;
    }

    $live_base = untrailingslashit( $wpide_live_url ) . wp_parse_url( $uploads['baseurl'], PHP_URL_PATH );
    return $live_base . $relative;
};

add_filter( 'wp_get_attachment_url', $wpide_live_media );

add_filter( 'wp_calculate_image_srcset', function ( $sources ) use ( $wpide_live_media ) {
    foreach ( (array) $sources as $width => $source ) {
        $sources[ $width ]['url'] = $wpide_live_media( $source['url'] );
    }
    return $sources;
} );

add_filter( 'the_content', function ( $content ) use ( $wpide_live_media ) {
    if ( 'production' === wp_get_environment_type() || false === strpos( $content, '/uploads/' ) ) {
        return $content;
    }
    return preg_replace_callback( '#(?<=["\'\s(])https?://[^"\'\s)]+/uploads/[^"\'\s)]+#i', function ( $match ) use ( $wpide_live_media ) {
        return $wpide_live_media( $match[0] );
    }, $content );
}, 99 );

// Source post type => target post type.
$wpide_copy_targets = array(
