    'page' => 'post',
);

$wpide_copy_link = function ( $actions, $post ) use ( $wpide_copy_targets ) {
    $target = $wpide_copy_targets[ $post->post_type ] ?? '';
    $object = $target ? get_post_type_object( $target ) : null;
    if ( $object && current_user_can( $object->cap->create_posts ) && current_user_can( 'read_post', $post->ID ) ) {
        $actions['wpide_copy_as'] = sprintf(
            '<a href="%s">Copy as %s</a>',
            esc_url( wp_nonce_url( admin_url( 'admin-post.php?action=wpide_copy_as&post=' . $post->ID . '&to=' . $target ), 'wpide_copy_as_' . $post->ID ) ),
            esc_html( strtolower( $object->labels->singular_name ) )
        );
