add_action( 'admin_notices', function () use ( $wpide_inactive_allowed ) {
    $screen = get_current_screen();
    if ( ! current_user_can( 'delete_plugins' ) || ! $screen || ! in_array( $screen->id, array( 'dashboard', 'plugins' ), true ) ) {
        return;
    }

    if ( isset( $_GET['wpide_dismiss_inactive'] ) && check_admin_referer( 'wpide_dismiss_inactive' ) ) {
        set_transient( 'wpide_inactive_dismissed_' . get_current_user_id(), 1, 30 * DAY_IN_SECONDS );
    }
    if ( get_transient( 'wpide_inactive_dismissed_' . get_current_user_id() ) ) {
        return;
    }

    if ( ! function_exists( 'get_plugins' ) ) {
