// Post types that need a title.
$wpide_title_required_types = array( 'post', 'page' );

foreach ( $wpide_title_required_types as $wpide_type ) {
    add_filter( "rest_pre_insert_{$wpide_type}", function ( $prepared, $request ) {
        $status = $request->get_param( 'status' ) ? $request->get_param( 'status' ) : get_post_status( (int) ( $prepared->ID ?? 0 ) );
        if ( ! in_array( $status, array( 'publish', 'future' ), true ) ) {
            return $prepared;
        }
        $title = null !== $request->get_param( 'title' ) ? $request->get_param( 'title' ) : get_post_field( 'post_title', (int) ( $prepared->ID ?? 0 ), 'raw' );
        $title = is_array( $title ) ? ( $title['raw'] ?? '' ) : (string) $title;

        return '' === trim( wp_strip_all_tags( $title ) )
            ? new WP_Error( 'wpide_title_required', 'Please add a title before publishing.', array( 'status' => 400 ) )
            : $prepared;
    }, 10, 2 );
}

// Classic editor and other code paths.
