add_action( 'enqueue_block_editor_assets', function () {
    $screen = get_current_screen();
    if ( ! $screen || 'post' !== $screen->base || ! post_type_supports( $screen->post_type, 'thumbnail' ) ) {
        return;
    }

    wp_register_script( 'wpide-hide-thumb', false, array( 'wp-plugins', 'wp-element', 'wp-components', 'wp-data', 'wp-editor' ), '1.0', true );
    wp_enqueue_script( 'wpide-hide-thumb' );
    wp_add_inline_script( 'wpide-hide-thumb', <<<'JS'
( function ( wp ) {
    var el = wp.element.createElement;
    var Panel = ( wp.editor && wp.editor.PluginPostStatusInfo ) || ( wp.editPost && wp.editPost.PluginPostStatusInfo );
    if ( ! Panel ) { return; }

    function HideThumb() {
        var hidden = wp.data.useSelect( function ( select ) { return !! ( select( 'core/editor' ).getEditedPostAttribute( 'meta' ) || {} )._wpide_hide_thumbnail; }, [] );
        var editPost = wp.data.useDispatch( 'core/editor' ).editPost;
        return el( Panel, null,
            el( wp.components.CheckboxControl, {
                label: 'Hide featured image on this post',
                checked: hidden,
                onChange: function ( value ) { editPost( { meta: { _wpide_hide_thumbnail: value } } ); }
            } )
        );
    }

    wp.plugins.registerPlugin( 'wpide-hide-thumb', { render: HideThumb } );
} )( window.wp );
JS
    );
} );

$wpide_https_fix = function ( $content ) {
    if ( ! is_ssl() && 'https' !== wp_parse_url( home_url(), PHP_URL_SCHEME ) ) {
        return $content;
    }
    $host = wp_parse_url( home_url(), PHP_URL_HOST );
    if ( ! $host || false === stripos( $content, 'http://' . $host ) && false === stripos( $content, 'http://www.' . $host ) ) {
        return $content;
    }
    return preg_replace( '#http://((?:www\.)?' . preg_quote( preg_replace( '/^www\./', '', $host ), '#' ) . ')(?=[/"\'\s:]|$)#i', 'https://$1', $content );
};

add_filter( 'the_content', $wpide_https_fix, 99 );
add_filter( 'widget_text_content', $wpide_https_fix, 99 );
add_filter( 'widget_block_content', $wpide_https_fix, 99 );

