} );

add_filter( 'render_block', function ( $content, $block ) {
    if ( empty( $block['blockName'] ) || ! isset( $_GET['wpide_blocks'] ) || ! current_user_can( 'manage_options' ) ) {
        return $content;
    }

    $name  = sanitize_text_field( $block['blockName'] );
    $attrs = ! empty( $block['attrs'] ) ? ' ' . wp_json_encode( array_keys( $block['attrs'] ) ) : '';

    // Strip "--" so attribute names cannot close the comment early.
    return "\n<!-- block: " . str_replace( '--', '', $name . $attrs ) . " -->\n" . $content . "\n<!-- /block: " . str_replace( '--', '', $name ) . " -->\n";
}, 999, 2 );

