add_action( 'manage_page_posts_custom_column', function ( $column, $post_id ) use ( &$wpide_menu_map ) {
    if ( 'wpide_in_menus' !== $column ) {
        return;
    }

    // Build the page => menus map once per screen.
    if ( null === $wpide_menu_map ) {
        $wpide_menu_map = array();
        foreach ( wp_get_nav_menus() as $menu ) {
            foreach ( (array) wp_get_nav_menu_items( $menu->term_id ) as $item ) {
                if ( 'post_type' === $item->type && 'page' === $item->object ) {
                    $wpide_menu_map[ (int) $item->object_id ][ $menu->term_id ] = $menu->name;
                }
            }
        }
    }

    $menus = $wpide_menu_map[ (int) $post_id ] ?? array();
    if ( ! $menus ) {
        echo '&ndash;';
        return;
    }
    $links = array();
    foreach ( $menus as $menu_id => $name ) {
        $links[] = current_user_can( 'edit_theme_options' )
            ? '<a href="' . esc_url( admin_url( 'nav-menus.php?action=edit&menu=' . (int) $menu_id ) ) . '">' . esc_html( $name ) . '</a>'
            : esc_html( $name );
    }
    echo implode( ', ', $links ); // phpcs:ignore WordPress.Security.EscapeOutput -- escaped above.
}, 10, 2 );

// Keyword (whole word) => tag name.
$wpide_keyword_tags = array(
    'woocommerce'  => 'WooCommerce',
    'block editor' => 'Gutenberg',
    'gutenberg'    => 'Gutenberg',
    'seo'          => 'SEO',
);

// Runs after the editor has saved its own tags, so they are never overwritten.
add_action( 'wp_after_insert_post', function ( $post_id, $post ) use ( $wpide_keyword_tags ) {
    if ( 'post' !== $post->post_type || wp_is_post_revision( $post_id ) || wp_is_post_autosave( $post_id ) || 'auto-draft' === $post->post_status ) {
        return;
    }

    $text = wp_strip_all_tags( $post->post_title . ' ' . $post->post_content );
    $add  = array();
    foreach ( $wpide_keyword_tags as $keyword => $tag ) {
        if ( preg_match( '/\b' . preg_quote( $keyword, '/' ) . '\b/i', $text ) ) {
            $add[] = $tag;
        }
    }

    if ( $add ) {
        wp_set_post_tags( $post_id, array_unique( $add ), true ); // Append, keep existing tags.
    }
}, 20, 2 );

add_filter( 'wp_generate_attachment_metadata', function ( $metadata, $attachment_id, $context = 'create' ) {
    if ( 'create' !== $context || ! wp_attachment_is_image( $attachment_id ) || '' !== (string) get_post_meta( $attachment_id, '_wp_attachment_image_alt', true ) ) {
        return $metadata;
    }

    $info = $metadata['image_meta'] ?? array();
    $text = '';
    foreach ( array( 'caption', 'title' ) as $field ) {
        if ( ! empty( $info[ $field ] ) && ! preg_match( '/^(DSC|IMG|DCIM|P\d{6,})[_-]?\d*/i', $info[ $field ] ) ) {
            $text = $info[ $field ];
            break;
        }
    }

    if ( '' !== trim( $text ) ) {
        update_post_meta( $attachment_id, '_wp_attachment_image_alt', sanitize_text_field( wp_trim_words( $text, 25, '' ) ) );
    }

    return $metadata;
}, 10, 3 );

if ( ! defined( 'WP_CLI' ) || ! WP_CLI ) {
    return;
}

WP_CLI::add_command( 'find-http-links', function ( $args, $assoc_args ) {
    global $wpdb;

    $host  = (string) wp_parse_url( home_url(), PHP_URL_HOST );
    $bare  = preg_replace( '/^www\./', '', $host );
    $items = array();

    $rows = $wpdb->get_results(
        "SELECT ID, post_type, post_title, post_content FROM {$wpdb->posts}
        WHERE post_status IN ('publish','draft','future','private','pending') AND post_type NOT IN ('revision','nav_menu_item')
        AND ( post_content LIKE '%src=\"http://%' OR post_content LIKE '%href=\"http://%' OR post_content LIKE '%src=''http://%' OR post_content LIKE '%href=''http://%' )"
    );

    foreach ( $rows as $row ) {
        if ( ! preg_match_all( '/(?:src|href)=["\']http:\/\/([^\/"\']+)/i', $row->post_content, $matches ) ) {
            continue;
        }
        $own   = 0;
        $other = 0;
        foreach ( $matches[1] as $domain ) {
            if ( preg_replace( '/^www\./', '', strtolower( $domain ) ) === strtolower( $bare ) ) {
                $own++;
            } else {
                $other++;
            }
        }
        if ( ! empty( $assoc_args['own'] ) && ! $own ) {
            continue;
        }
        $items[] = array( 'ID' => $row->ID, 'type' => $row->post_type, 'own_domain' => $own, 'other_domains' => $other, 'title' => $row->post_title );
    }

    if ( ! $items ) {
        WP_CLI::success( 'No http:// links found.' );
        return;
    }

    WP_CLI\Utils\format_items( $assoc_args['format'] ?? 'table', $items, array( 'ID', 'type', 'own_domain', 'other_domains', 'title' ) );
}, array(
    'shortdesc' => 'Lists content with http:// links and images.',
    'synopsis'  => array(
        array( 'type' => 'flag', 'name' => 'own', 'optional' => true, 'description' => 'Only links to this site.' ),
        array( 'type' => 'assoc', 'name' => 'format', 'optional' => true, 'default' => 'table', 'options' => array( 'table', 'csv', 'json', 'count' ) ),
    ),
) );

