// Sites allowed to read your feeds with JavaScript. '*' allows any site; or list origins such as 'https://app.example.com'.
$wpide_feed_cors_origins = array( '*' );

add_action( 'template_redirect', function () use ( $wpide_feed_cors_origins ) {
    if ( ! is_feed() || headers_sent() ) {
        return;
    }

    if ( in_array( '*', $wpide_feed_cors_origins, true ) ) {
        header( 'Access-Control-Allow-Origin: *' );
    } else {
        $origin  = isset( $_SERVER['HTTP_ORIGIN'] ) ? untrailingslashit( esc_url_raw( wp_unslash( $_SERVER['HTTP_ORIGIN'] ) ) ) : '';
        $allowed = array_map( 'untrailingslashit', $wpide_feed_cors_origins );

        header( 'Vary: Origin', false );

        if ( '' === $origin || ! in_array( $origin, $allowed, true ) ) {
            return;
        }

        header( 'Access-Control-Allow-Origin: ' . $origin );
    }

    header( 'Access-Control-Allow-Methods: GET, HEAD, OPTIONS' );
}, 1 );

// Your feed's address at the feed service (FeedPress, Follow.it, Feedburner ...). Leave empty to turn the redirect off.
$wpide_feed_service_url = '';
// Parts of the service's user agent; these requests get your real feed so the service can read it.
$wpide_feed_service_agents = array( 'feedpress', 'feedburner', 'follow.it', 'feedvalidator' );

add_action( 'template_redirect', function () use ( $wpide_feed_service_url, $wpide_feed_service_agents ) {
    if ( '' === $wpide_feed_service_url || ! is_feed() || is_comment_feed() || is_archive() || is_search() || is_singular() ) {
        return;
    }

    // The service can also read the original feed at /feed/?origin-feed=1.
    if ( isset( $_GET['origin-feed'] ) ) {
        return;
    }

    $agent = isset( $_SERVER['HTTP_USER_AGENT'] ) ? strtolower( sanitize_text_field( wp_unslash( $_SERVER['HTTP_USER_AGENT'] ) ) ) : '';

    foreach ( $wpide_feed_service_agents as $needle ) {
        if ( '' !== $agent && false !== strpos( $agent, strtolower( $needle ) ) ) {
            return;
        }
    }

    // 302 keeps subscribers on your own feed address, so you can switch services later.
    wp_redirect( esc_url_raw( $wpide_feed_service_url ), 302 ); // phpcs:ignore WordPress.Security.SafeRedirect -- external address set by the site owner.
    exit;
}, 1 );

// Custom field key => element name in the feed (lowercase letters, digits and dashes). Empty = off. Examples:
// 'event_date'  => 'event-date',
// 'location'    => 'location',
$wpide_feed_fields = array();
// Prefix of the elements, for example <site:event-date>.
$wpide_feed_fields_prefix = 'site';

if ( $wpide_feed_fields ) {
    add_action( 'rss2_ns', function () use ( $wpide_feed_fields_prefix ) {
        echo 'xmlns:' . esc_attr( sanitize_key( $wpide_feed_fields_prefix ) ) . '="' . esc_url( home_url( '/' ) ) . '"' . "\n\t";
    } );

    add_action( 'rss2_item', function () use ( $wpide_feed_fields, $wpide_feed_fields_prefix ) {
        $post_id = get_the_ID();

        if ( ! $post_id || post_password_required( $post_id ) ) {
            return;
        }

        $prefix = sanitize_key( $wpide_feed_fields_prefix );

        foreach ( $wpide_feed_fields as $key => $element ) {
            $element = preg_replace( '/[^a-z0-9-]/', '', strtolower( (string) $element ) );
            $value   = get_post_meta( $post_id, $key, true );

            if ( '' === $element || ! is_scalar( $value ) || '' === trim( (string) $value ) ) {
                continue;
            }

            printf( "\t\t<%1\$s:%2\$s>%3\$s</%1\$s:%2\$s>\n", $prefix, $element, esc_xml( wp_strip_all_tags( (string) $value ) ) ); // phpcs:ignore WordPress.Security.EscapeOutput -- names are sanitized above.
        }
    } );
}

