add_filter( 'widget_posts_args', function ( $args ) use ( $wpide_recent_widget_types ) {
    $types = $wpide_recent_widget_types;

    if ( ! $types ) {
        $types = array_merge( array( 'post' ), array_values( get_post_types( array( 'public' => true, '_builtin' => false ) ) ) );
    }

    $args['post_type'] = array_values( array_filter( $types, 'post_type_exists' ) );

    return $args;
} );

