// true = order categories by number of posts, busiest first, instead of A to Z.
$wpide_cat_widget_by_count = true;

$wpide_cat_widget_args = function ( $args ) use ( $wpide_cat_widget_top_level, $wpide_cat_widget_by_count ) {
    if ( $wpide_cat_widget_top_level ) {
        $args['depth']  = 1;
        $args['parent'] = 0;
    }

    if ( $wpide_cat_widget_by_count ) {
        $args['orderby'] = 'count';
