if ( ! class_exists( 'WPIDE_Social_Profiles_Widget' ) ) {
    class WPIDE_Social_Profiles_Widget extends WP_Widget {
        // Networks offered in the widget form, in display order.
        const NETWORKS = array(
            'facebook'  => 'Facebook',
            'instagram' => 'Instagram',
            'x'         => 'X',
            'linkedin'  => 'LinkedIn',
            'youtube'   => 'YouTube',
            'tiktok'    => 'TikTok',
            'pinterest' => 'Pinterest',
            'bluesky'   => 'Bluesky',
            'mastodon'  => 'Mastodon',
            'threads'   => 'Threads',
            'github'    => 'GitHub',
        );

        public function __construct() {
            parent::__construct( 'wpide_social_profiles', 'Social Profiles', array(
                'description'                 => 'Links to your profiles on social networks.',
                'customize_selective_refresh' => true,
            ) );
        }

        public function widget( $args, $instance ) {
            $links = array();

            foreach ( self::NETWORKS as $key => $label ) {
                if ( ! empty( $instance[ $key ] ) ) {
                    // rel="me" lets Mastodon and similar services verify the link back to your site.
                    $links[] = '<li><a href="' . esc_url( $instance[ $key ] ) . '" rel="me noopener" target="_blank">' . esc_html( $label ) . '<span class="screen-reader-text"> (opens in a new tab)</span></a></li>';
                }
