            $clean = array( 'title' => isset( $new_instance['title'] ) ? sanitize_text_field( $new_instance['title'] ) : '' );

            foreach ( array_keys( self::NETWORKS ) as $key ) {
                $clean[ $key ] = isset( $new_instance[ $key ] ) ? esc_url_raw( trim( $new_instance[ $key ] ), array( 'https', 'http' ) ) : '';
