            echo '<p><label for="' . esc_attr( $this->get_field_id( 'title' ) ) . '">Title:</label><input class="widefat" type="text" id="' . esc_attr( $this->get_field_id( 'title' ) ) . '" name="' . esc_attr( $this->get_field_name( 'title' ) ) . '" value="' . esc_attr( $title ) . '" /></p>';
            echo '<p><label for="' . esc_attr( $this->get_field_id( 'post_id' ) ) . '">Post or page:</label><select class="widefat" id="' . esc_attr( $this->get_field_id( 'post_id' ) ) . '" name="' . esc_attr( $this->get_field_name( 'post_id' ) ) . '"><option value="0">— Select —</option>';

            foreach ( $choices as $choice ) {
                echo '<option value="' . esc_attr( $choice->ID ) . '"' . selected( $post_id, $choice->ID, false ) . '>' . esc_html( get_the_title( $choice ) . ' (' . $choice->post_type . ')' ) . '</option>';
            }

            echo '</select></p>';
            echo '<p><label for="' . esc_attr( $this->get_field_id( 'more' ) ) . '">Link text:</label><input class="widefat" type="text" id="' . esc_attr( $this->get_field_id( 'more' ) ) . '" name="' . esc_attr( $this->get_field_name( 'more' ) ) . '" value="' . esc_attr( $more ) . '" /></p>';

            return '';
        }

        public function update( $new_instance, $old_instance ) {
            return array(
                'title'   => isset( $new_instance['title'] ) ? sanitize_text_field( $new_instance['title'] ) : '',
                'post_id' => isset( $new_instance['post_id'] ) ? absint( $new_instance['post_id'] ) : 0,
                'more'    => isset( $new_instance['more'] ) ? sanitize_text_field( $new_instance['more'] ) : '',
            );
        }
    }
}

