    if ( ! wp_is_block_theme() ) {
        echo $wpide_prefooter_html(); // phpcs:ignore WordPress.Security.EscapeOutput -- widget output.
    }
} );

// Block themes: added before the footer template part.
add_filter( 'render_block_core/template-part', function ( $content, $block ) use ( $wpide_prefooter_html ) {
    static $done = false;

    $slug = isset( $block['attrs']['slug'] ) ? (string) $block['attrs']['slug'] : '';
    $area = isset( $block['attrs']['area'] ) ? (string) $block['attrs']['area'] : '';

    if ( $done || is_admin() || ( 'footer' !== $area && 0 !== strpos( $slug, 'footer' ) ) ) {
        return $content;
    }

    $done = true;

    return $wpide_prefooter_html() . $content;
}, 10, 2 );

add_action( 'template_redirect', function () {
    $uri = isset( $_SERVER['REQUEST_URI'] ) ? wp_unslash( $_SERVER['REQUEST_URI'] ) : '';
    $pos = strpos( $uri, '?' );

    $path  = false === $pos ? $uri : substr( $uri, 0, $pos );
    $query = false === $pos ? '' : substr( $uri, $pos );

    if ( false === strpos( $path, '//' ) ) {
        return;
    }

    // /blog//my-post/ and /blog///my-post/ become /blog/my-post/.
    $home = wp_parse_url( home_url() );
    $base = $home['scheme'] . '://' . $home['host'] . ( isset( $home['port'] ) ? ':' . $home['port'] : '' );

    wp_safe_redirect( $base . preg_replace( '#/{2,}#', '/', $path ) . $query, 301 );
    exit;
}, 1 );

// Two-letter country code => address to send those visitors to. Empty = off. Examples:
// 'CA' => 'https://example.ca/',
// 'DE' => '/de/',
$wpide_country_redirects = array();
// true = only redirect visitors who land on the homepage; false = every page.
$wpide_country_homepage_only = true;
// Server headers that carry the visitor's country (Cloudflare, CloudFront, nginx GeoIP, many hosts).
$wpide_country_headers = array( 'HTTP_CF_IPCOUNTRY', 'HTTP_CLOUDFRONT_VIEWER_COUNTRY', 'HTTP_X_COUNTRY_CODE', 'GEOIP_COUNTRY_CODE' );

add_action( 'template_redirect', function () use ( $wpide_country_redirects, $wpide_country_homepage_only, $wpide_country_headers ) {
    if ( ! $wpide_country_redirects || is_user_logged_in() || is_feed() || is_robots() || ( $wpide_country_homepage_only && ! is_front_page() ) ) {
        return;
    }

    // ?stay=1 remembers that the visitor wants this version of the site for 30 days.
    if ( isset( $_GET['stay'] ) ) {
        setcookie( 'wpide_geo_stay', '1', time() + 30 * DAY_IN_SECONDS, COOKIEPATH ? COOKIEPATH : '/', COOKIE_DOMAIN, is_ssl(), true );
        return;
    }

    if ( isset( $_COOKIE['wpide_geo_stay'] ) ) {
        return;
    }

    $agent = isset( $_SERVER['HTTP_USER_AGENT'] ) ? strtolower( sanitize_text_field( wp_unslash( $_SERVER['HTTP_USER_AGENT'] ) ) ) : '';

    // Never redirect search engine crawlers, so every version stays indexable.
    if ( '' === $agent || preg_match( '/bot|crawl|spider|slurp|facebookexternalhit|preview/', $agent ) ) {
        return;
    }

    $country = '';

    foreach ( $wpide_country_headers as $header ) {
        if ( ! empty( $_SERVER[ $header ] ) ) {
            $country = strtoupper( substr( sanitize_text_field( wp_unslash( $_SERVER[ $header ] ) ), 0, 2 ) );
            break;
        }
    }

    if ( '' === $country || empty( $wpide_country_redirects[ $country ] ) ) {
        return;
    }

    $target = $wpide_country_redirects[ $country ];
    $target = preg_match( '#^https?://#i', $target ) ? $target : home_url( $target );

    nocache_headers();
    wp_redirect( esc_url_raw( $target ), 302 ); // phpcs:ignore WordPress.Security.SafeRedirect -- targets are set by the site owner.
    exit;
}, 1 );

// The short address to share, for example on posters, QR codes and email signatures.
$wpide_app_link_path = '/app/';
// Store pages of your app. Leave a value empty to skip that platform.
$wpide_app_link_ios     = ''; // e.g. https://apps.apple.com/app/id0000000000
$wpide_app_link_android = ''; // e.g. https://play.google.com/store/apps/details?id=com.example.app
// Where everyone else goes (desktop browsers); empty = let WordPress show the page at that address.
$wpide_app_link_other = '';

add_action( 'template_redirect', function () use ( $wpide_app_link_path, $wpide_app_link_ios, $wpide_app_link_android, $wpide_app_link_other ) {
    if ( '' === $wpide_app_link_ios && '' === $wpide_app_link_android ) {
        return;
    }

    $path = isset( $_SERVER['REQUEST_URI'] ) ? (string) wp_parse_url( wp_unslash( $_SERVER['REQUEST_URI'] ), PHP_URL_PATH ) : '';
    $want = (string) wp_parse_url( home_url( $wpide_app_link_path ), PHP_URL_PATH );

    if ( '' === $path || strtolower( untrailingslashit( $path ) ) !== strtolower( untrailingslashit( $want ) ) ) {
        return;
    }

    $agent  = isset( $_SERVER['HTTP_USER_AGENT'] ) ? sanitize_text_field( wp_unslash( $_SERVER['HTTP_USER_AGENT'] ) ) : '';
    $target = $wpide_app_link_other;

    if ( preg_match( '/iPhone|iPad|iPod/i', $agent ) && '' !== $wpide_app_link_ios ) {
        $target = $wpide_app_link_ios;
    } elseif ( false !== stripos( $agent, 'Android' ) && '' !== $wpide_app_link_android ) {
        $target = $wpide_app_link_android;
    }

    if ( '' === $target ) {
        return;
    }

    nocache_headers();
    header( 'Vary: User-Agent', false );
    wp_redirect( esc_url_raw( $target ), 302 ); // phpcs:ignore WordPress.Security.SafeRedirect -- store links set by the site owner.
    exit;
}, 1 );

// Prefix of your short links: /go/amazon/ and so on.
$wpide_go_prefix = 'go';
// Short name => destination. Empty = off. Examples:
// 'amazon'  => 'https://www.amazon.com/dp/B000000000?tag=yourtag-20',
// 'hosting' => 'https://partner.example.com/?ref=you',
$wpide_go_links = array();

add_action( 'template_redirect', function () use ( $wpide_go_prefix, $wpide_go_links ) {
    // Only when no real page uses the address.
    if ( ! $wpide_go_links || ! is_404() ) {
        return;
    }

    $path = isset( $_SERVER['REQUEST_URI'] ) ? (string) wp_parse_url( wp_unslash( $_SERVER['REQUEST_URI'] ), PHP_URL_PATH ) : '';
    $base = (string) wp_parse_url( home_url( '/' . trim( $wpide_go_prefix, '/' ) . '/' ), PHP_URL_PATH );

    if ( 0 !== stripos( $path, $base ) ) {
        return;
    }

    $slug = strtolower( trim( substr( $path, strlen( $base ) ), '/' ) );

    if ( '' === $slug || empty( $wpide_go_links[ $slug ] ) ) {
        return;
    }

    nocache_headers();
    header( 'X-Robots-Tag: noindex, nofollow' );
    // 307 is temporary: browsers and search engines do not remember it, so you can change destinations any time.
    wp_redirect( esc_url_raw( $wpide_go_links[ $slug ] ), 307 ); // phpcs:ignore WordPress.Security.SafeRedirect -- destinations set by the site owner.
    exit;
}, 1 );

// Ask search engines not to crawl the short links.
add_filter( 'robots_txt', function ( $output, $public ) use ( $wpide_go_prefix, $wpide_go_links ) {
    if ( ! $public || ! $wpide_go_links ) {
        return $output;
    }

    $path = (string) wp_parse_url( home_url( '/' . trim( $wpide_go_prefix, '/' ) . '/' ), PHP_URL_PATH );

    return $output . "\nUser-agent: *\nDisallow: " . $path . "\n";
}, 10, 2 );

// Post types to remember; when one is trashed, its old address leads to its first category (posts)
// or its parent page (pages), and otherwise to the blog page.
$wpide_removed_types = array( 'post', 'page' );
// How many old addresses to remember (oldest are dropped first).
$wpide_removed_limit = 500;

add_action( 'wp_trash_post', function ( $post_id ) use ( $wpide_removed_types, $wpide_removed_limit ) {
    $post = get_post( $post_id );

    if ( ! $post || 'publish' !== $post->post_status || ! in_array( $post->post_type, $wpide_removed_types, true ) ) {
        return;
    }

    $target = '';

    if ( 'post' === $post->post_type ) {
        $cats   = wp_get_post_categories( $post->ID );
        $target = $cats ? get_category_link( (int) $cats[0] ) : '';
    } elseif ( $post->post_parent && 'publish' === get_post_status( $post->post_parent ) ) {
        $target = get_permalink( $post->post_parent );
    }

    if ( ! $target ) {
        $blog   = (int) get_option( 'page_for_posts' );
        $target = $blog ? get_permalink( $blog ) : home_url( '/' );
    }

    $path = untrailingslashit( (string) wp_parse_url( get_permalink( $post ), PHP_URL_PATH ) );
    $map  = (array) get_option( 'wpide_removed_post_redirects', array() );

    unset( $map[ $path ] );
    $map[ $path ] = array( 'to' => $target, 'id' => $post->ID );

    update_option( 'wpide_removed_post_redirects', array_slice( $map, -absint( $wpide_removed_limit ), null, true ), false );
} );

// Restoring a post from the trash removes its redirect.
add_action( 'untrashed_post', function ( $post_id ) {
    $map = (array) get_option( 'wpide_removed_post_redirects', array() );

    foreach ( $map as $path => $item ) {
        if ( isset( $item['id'] ) && (int) $item['id'] === (int) $post_id ) {
            unset( $map[ $path ] );
        }
    }

    update_option( 'wpide_removed_post_redirects', $map, false );
} );

add_action( 'template_redirect', function () {
    if ( ! is_404() ) {
        return;
    }

    $map  = get_option( 'wpide_removed_post_redirects', array() );
    $path = isset( $_SERVER['REQUEST_URI'] ) ? untrailingslashit( (string) wp_parse_url( wp_unslash( $_SERVER['REQUEST_URI'] ), PHP_URL_PATH ) ) : '';

    if ( ! is_array( $map ) || '' === $path || empty( $map[ $path ]['to'] ) ) {
        return;
    }

    wp_safe_redirect( $map[ $path ]['to'], 301 );
    exit;
} );

// Status code: 301 (permanent) or 302 (temporary).
$wpide_parent_redirect_status = 301;

add_action( 'template_redirect', function () use ( $wpide_parent_redirect_status ) {
    if ( ! is_404() || ! get_option( 'permalink_structure' ) ) {
        return;
    }

    $path = isset( $_SERVER['REQUEST_URI'] ) ? (string) wp_parse_url( wp_unslash( $_SERVER['REQUEST_URI'] ), PHP_URL_PATH ) : '';
    $base = untrailingslashit( (string) wp_parse_url( home_url(), PHP_URL_PATH ) );
    $path = trim( substr( $path, strlen( $base ) ), '/' );

    // Skip missing files such as images and scripts, and very deep or empty paths.
    if ( '' === $path || preg_match( '/\.[a-z0-9]{2,5}$/i', $path ) || substr_count( $path, '/' ) > 6 ) {
        return;
    }

    $parts = explode( '/', $path );

    while ( count( $parts ) > 1 ) {
        array_pop( $parts );

        $url = home_url( user_trailingslashit( implode( '/', $parts ) ) );

        if ( url_to_postid( $url ) || get_page_by_path( implode( '/', $parts ) ) ) {
            wp_safe_redirect( $url, (int) $wpide_parent_redirect_status );
            exit;
        }

        $term = get_term_by( 'slug', end( $parts ), 'category' );

        if ( $term && untrailingslashit( get_term_link( $term ) ) === untrailingslashit( $url ) ) {
            wp_safe_redirect( $url, (int) $wpide_parent_redirect_status );
            exit;
        }
    }
} );

// The redirect file: one rule per line as  old-path,new-address[,status]  for example
// /old-page/,/new-page/,301
// /spring-sale/,https://shop.example.com/sale/,302
// Kept outside the uploads folder so only people with file access can change it.
$wpide_redirects_file = WP_CONTENT_DIR . '/redirects.csv';

add_action( 'template_redirect', function () use ( $wpide_redirects_file ) {
    if ( ! is_readable( $wpide_redirects_file ) ) {
        return;
    }

    $stamp = filemtime( $wpide_redirects_file ) . '-' . filesize( $wpide_redirects_file );
    $cache = get_transient( 'wpide_csv_redirects' );

    // Parse the file only when it changes.
    if ( ! is_array( $cache ) || ! isset( $cache['stamp'] ) || $cache['stamp'] !== $stamp ) {
        $rules  = array();
        $handle = fopen( $wpide_redirects_file, 'r' ); // phpcs:ignore WordPress.WP.AlternativeFunctions

        while ( $handle && false !== ( $row = fgetcsv( $handle, 2048, ',', '"', '' ) ) ) {
            if ( count( $row ) < 2 || '' === trim( (string) $row[0] ) || 0 === strpos( trim( (string) $row[0] ), '#' ) ) {
                continue;
            }

            $from   = strtolower( untrailingslashit( (string) wp_parse_url( trim( $row[0] ), PHP_URL_PATH ) ) );
            $status = isset( $row[2] ) ? (int) $row[2] : 301;

            $rules[ '' === $from ? '/' : $from ] = array(
                'to'     => trim( $row[1] ),
                'status' => in_array( $status, array( 301, 302, 307, 308, 410 ), true ) ? $status : 301,
            );
        }

        if ( $handle ) {
            fclose( $handle ); // phpcs:ignore WordPress.WP.AlternativeFunctions
        }

        $cache = array( 'stamp' => $stamp, 'rules' => $rules );
        set_transient( 'wpide_csv_redirects', $cache, DAY_IN_SECONDS );
    }

    $path = isset( $_SERVER['REQUEST_URI'] ) ? strtolower( untrailingslashit( (string) wp_parse_url( wp_unslash( $_SERVER['REQUEST_URI'] ), PHP_URL_PATH ) ) ) : '';
    $path = '' === $path ? '/' : $path;

    if ( empty( $cache['rules'][ $path ] ) ) {
        return;
    }

    $rule = $cache['rules'][ $path ];

    if ( 410 === $rule['status'] ) {
        status_header( 410 );
        nocache_headers();
        return;
    }

    $to = preg_match( '#^https?://#i', $rule['to'] ) ? $rule['to'] : home_url( $rule['to'] );

    if ( strtolower( untrailingslashit( (string) wp_parse_url( $to, PHP_URL_PATH ) ) ) === $path && wp_parse_url( $to, PHP_URL_HOST ) === wp_parse_url( home_url(), PHP_URL_HOST ) ) {
        return; // Would redirect to itself.
    }

    wp_redirect( esc_url_raw( $to ), $rule['status'] ); // phpcs:ignore WordPress.Security.SafeRedirect -- rules come from the site owner's file.
    exit;
}, 1 );

// /latest/ opens your newest post; /latest/news/ opens the newest post in the News category.
$wpide_latest_path = 'latest';

add_action( 'template_redirect', function () use ( $wpide_latest_path ) {
    // Only when no real page uses the address.
    if ( ! is_404() ) {
        return;
    }

    $path = isset( $_SERVER['REQUEST_URI'] ) ? (string) wp_parse_url( wp_unslash( $_SERVER['REQUEST_URI'] ), PHP_URL_PATH ) : '';
    $base = untrailingslashit( (string) wp_parse_url( home_url( '/' . trim( $wpide_latest_path, '/' ) ), PHP_URL_PATH ) );

    if ( '' === $path || ( strtolower( untrailingslashit( $path ) ) !== strtolower( $base ) && 0 !== stripos( $path, $base . '/' ) ) ) {
        return;
    }

    $category = sanitize_title( trim( substr( $path, strlen( $base ) ), '/' ) );
    $cache    = get_transient( 'wpide_latest_posts' );
    $cache    = is_array( $cache ) ? $cache : array();
    $post_id  = isset( $cache[ $category ] ) ? (int) $cache[ $category ] : null;

    if ( null === $post_id ) {
        $args = array(
            'post_type'           => 'post',
            'posts_per_page'      => 1,
            'has_password'        => false,
            'ignore_sticky_posts' => true,
            'no_found_rows'       => true,
            'fields'              => 'ids',
        );

        if ( '' !== $category ) {
            $args['category_name'] = $category;
        }

        $ids     = get_posts( $args );
        $post_id = $ids ? (int) $ids[0] : 0;

        // Keep at most 50 category answers in the cache.
        $cache[ $category ] = $post_id;
        set_transient( 'wpide_latest_posts', array_slice( $cache, -50, null, true ), DAY_IN_SECONDS );
    }

    if ( ! $post_id ) {
        return;
    }

    nocache_headers();
    wp_safe_redirect( get_permalink( $post_id ), 302 );
    exit;
}, 1 );

// Forget the cached answers whenever a post is published, updated or removed.
add_action( 'transition_post_status', function ( $new_status, $old_status, $post ) {
    if ( 'post' === $post->post_type && ( 'publish' === $new_status || 'publish' === $old_status ) ) {
        delete_transient( 'wpide_latest_posts' );
    }
}, 10, 3 );

// Addresses you removed on purpose and that will not come back. Empty = off. A trailing * matches everything below. Examples:
// '/old-promo/',
// '/discontinued-products/*',
$wpide_gone_paths = array();

add_action( 'template_redirect', function () use ( $wpide_gone_paths ) {
    // Only for addresses that are missing anyway, so live content can never be hidden by mistake.
    if ( ! $wpide_gone_paths || ! is_404() ) {
        return;
    }

    $path = isset( $_SERVER['REQUEST_URI'] ) ? strtolower( (string) wp_parse_url( wp_unslash( $_SERVER['REQUEST_URI'] ), PHP_URL_PATH ) ) : '';

    foreach ( $wpide_gone_paths as $gone ) {
        $gone = strtolower( (string) wp_parse_url( home_url( $gone ), PHP_URL_PATH ) );

        $match = '*' === substr( $gone, -1 )
            ? 0 === strpos( $path, rtrim( $gone, '*' ) )
            : untrailingslashit( $gone ) === untrailingslashit( $path );

        if ( $match ) {
            // 410 tells search engines the page is gone for good, so they drop it faster than a 404.
            status_header( 410 );
            nocache_headers();
            header( 'X-Robots-Tag: noindex' );
            return;
        }
    }
} );

// /random/ opens a random published post: a fun "Surprise me" link for menus.
$wpide_random_path = 'random';
// Pick from this many of your newest posts.
$wpide_random_pool = 500;

add_action( 'template_redirect', function () use ( $wpide_random_path, $wpide_random_pool ) {
    if ( ! is_404() ) {
        return;
    }

    $path = isset( $_SERVER['REQUEST_URI'] ) ? (string) wp_parse_url( wp_unslash( $_SERVER['REQUEST_URI'] ), PHP_URL_PATH ) : '';
    $want = (string) wp_parse_url( home_url( '/' . trim( $wpide_random_path, '/' ) ), PHP_URL_PATH );

    if ( strtolower( untrailingslashit( $path ) ) !== strtolower( untrailingslashit( $want ) ) ) {
        return;
    }

    $ids = get_transient( 'wpide_random_post_pool' );

    if ( ! is_array( $ids ) ) {
        $ids = get_posts( array(
            'post_type'           => 'post',
            'posts_per_page'      => max( 1, (int) $wpide_random_pool ),
            'has_password'        => false,
            'ignore_sticky_posts' => true,
            'no_found_rows'       => true,
            'fields'              => 'ids',
        ) );
        set_transient( 'wpide_random_post_pool', $ids, 6 * HOUR_IN_SECONDS );
    }

    if ( ! $ids ) {
        return;
    }

    nocache_headers();
    wp_safe_redirect( get_permalink( $ids[ array_rand( $ids ) ] ), 302 );
    exit;
} );

add_action( 'transition_post_status', function ( $new_status, $old_status, $post ) {
    if ( 'post' === $post->post_type && ( 'publish' === $new_status || 'publish' === $old_status ) ) {
        delete_transient( 'wpide_random_post_pool' );
    }
}, 10, 3 );

add_action( 'template_redirect', function () {
    global $wp_query;

    $paged = (int) get_query_var( 'paged' );

    // A list page (blog, archive, search) asked for a page number that does not exist.
    if ( ! is_404() || $paged < 2 ) {
        return;
    }

    $vars = $wp_query->query_vars;

    $vars['paged']          = 1;
    $vars['fields']         = 'ids';
    $vars['no_found_rows']  = false;
    $vars['posts_per_page'] = max( 1, (int) $wp_query->get( 'posts_per_page' ) );

    $check = new WP_Query( $vars );
    $last  = (int) $check->max_num_pages;

    if ( $last < 1 || $paged <= $last ) {
        return;
    }

    // /category/news/page/40/ goes to the real last page, for example /category/news/page/7/.
    wp_safe_redirect( get_pagenum_link( $last, false ), 301 );
    exit;
} );

add_action( 'template_redirect', function () {
    if ( ! is_404() ) {
        return;
    }

    $path    = isset( $_SERVER['REQUEST_URI'] ) ? rawurldecode( (string) wp_parse_url( wp_unslash( $_SERVER['REQUEST_URI'] ), PHP_URL_PATH ) ) : '';
    $uploads = wp_get_upload_dir();
    $base    = (string) wp_parse_url( $uploads['baseurl'], PHP_URL_PATH );

    // Only resized copies such as photo-300x200.jpg inside the uploads folder.
    if ( '' === $path || 0 !== strpos( $path, trailingslashit( $base ) ) || ! preg_match( '/^(.+)-\d+x\d+(\.(?:jpe?g|png|gif|webp|avif))$/i', $path, $m ) ) {
        return;
    }

    $relative = substr( $m[1], strlen( $base ) );

    if ( false !== strpos( $relative, '..' ) ) {
        return;
    }

    // Large uploads keep their original as name-scaled.jpg; check that first.
    foreach ( array( '-scaled', '' ) as $suffix ) {
        $file = $relative . $suffix . $m[2];

        if ( file_exists( $uploads['basedir'] . $file ) ) {
            wp_safe_redirect( $uploads['baseurl'] . implode( '/', array_map( 'rawurlencode', explode( '/', $file ) ) ), 301 );
            exit;
        }
    }
} );

add_action( 'template_redirect', function () {
    // Leave everything alone while an AMP plugin is active.
    if ( function_exists( 'amp_is_request' ) || function_exists( 'is_amp_endpoint' ) || defined( 'AMPFORWP_VERSION' ) ) {
        return;
    }

    $uri  = isset( $_SERVER['REQUEST_URI'] ) ? wp_unslash( $_SERVER['REQUEST_URI'] ) : '';
    $path = (string) wp_parse_url( $uri, PHP_URL_PATH );
    $home = wp_parse_url( home_url() );
    $base = $home['scheme'] . '://' . $home['host'] . ( isset( $home['port'] ) ? ':' . $home['port'] : '' );

    // ?amp=1 or ?amp on any page: drop the parameter.
    if ( isset( $_GET['amp'] ) ) {
        wp_safe_redirect( remove_query_arg( 'amp', $base . $uri ), 301 );
        exit;
    }

    // /my-post/amp/ that no longer exists: go to /my-post/.
    if ( is_404() && preg_match( '#^(.*)/amp/?$#i', $path, $m ) && '' !== $m[1] ) {
        $query = (string) wp_parse_url( $uri, PHP_URL_QUERY );

        wp_safe_redirect( $base . user_trailingslashit( $m[1] ) . ( '' !== $query ? '?' . $query : '' ), 301 );
        exit;
    }
}, 1 );

// Content types in the order they should appear in search results; anything else follows.
$wpide_search_type_order = array( 'page', 'post' );

add_filter( 'posts_orderby', function ( $orderby, $query ) use ( $wpide_search_type_order ) {
    global $wpdb;

    if ( is_admin() || ! $query->is_main_query() || ! $query->is_search() || ! $wpide_search_type_order ) {
        return $orderby;
    }

    $case = "CASE {$wpdb->posts}.post_type";

    foreach ( array_values( $wpide_search_type_order ) as $i => $type ) {
        $case .= $wpdb->prepare( ' WHEN %s THEN %d', $type, $i );
    }

    $case .= ' ELSE ' . count( $wpide_search_type_order ) . ' END ASC';

    // Within each type, WordPress's own relevance order is kept.
    return '' !== trim( $orderby ) ? $case . ', ' . $orderby : $case;
}, 10, 2 );

// Groups of words that mean the same thing on your site; a search for any of them finds them all. Empty = off. Examples:
// array( 'sofa', 'couch', 'settee' ),
// array( 'tv', 'television' ),
$wpide_search_synonyms = array();

add_filter( 'posts_search', function ( $search, $query ) use ( $wpide_search_synonyms ) {
    global $wpdb;

    if ( '' === $search || ! $wpide_search_synonyms || is_admin() || ! $query->is_main_query() || ! $query->is_search() ) {
        return $search;
    }

    $terms = (array) $query->get( 'search_terms' );

    // Leave exclusions ("-word") and exact-phrase searches to WordPress.
    if ( ! $terms || $query->get( 'exact' ) || $query->get( 'sentence' ) || preg_grep( '/^-/', $terms ) ) {
        return $search;
    }

    $lookup = array();

    foreach ( $wpide_search_synonyms as $group ) {
        $group = array_map( 'strtolower', array_map( 'trim', (array) $group ) );

        foreach ( $group as $word ) {
            $lookup[ $word ] = $group;
        }
    }

    $changed = false;
    $parts   = array();

    foreach ( $terms as $term ) {
        $words = isset( $lookup[ strtolower( $term ) ] ) ? $lookup[ strtolower( $term ) ] : array( $term );
        $ors   = array();

        $changed = $changed || count( $words ) > 1;

        foreach ( $words as $word ) {
            $like = '%' . $wpdb->esc_like( $word ) . '%';

            $ors[] = $wpdb->prepare( "({$wpdb->posts}.post_title LIKE %s) OR ({$wpdb->posts}.post_excerpt LIKE %s) OR ({$wpdb->posts}.post_content LIKE %s)", $like, $like, $like );
        }

        $parts[] = '(' . implode( ' OR ', $ors ) . ')';
    }

    if ( ! $changed ) {
        return $search;
    }

    $search = ' AND (' . implode( ' AND ', $parts ) . ') ';

    if ( ! is_user_logged_in() ) {
        $search .= " AND ({$wpdb->posts}.post_password = '') ";
    }

    return $search;
}, 10, 2 );

// Text of the first option, which searches everything.
$wpide_search_cat_all = 'All categories';

$wpide_search_cat_select = function () use ( $wpide_search_cat_all ) {
    static $html = null;

    if ( null === $html ) {
        $id   = wp_unique_id( 'wpide-search-cat-' );
        $html = '<label class="screen-reader-text" for="' . esc_attr( $id ) . '">Category</label>' . wp_dropdown_categories( array(
            'show_option_all' => $wpide_search_cat_all,
            'name'            => 'cat',
            'id'              => $id,
            'class'           => 'wpide-search-cat',
            'selected'        => absint( get_query_var( 'cat' ) ),
            'hierarchical'    => true,
            'hide_empty'      => true,
            'echo'            => false,
        ) );
    }

    return $html;
};

$wpide_search_cat_insert = function ( $form ) use ( $wpide_search_cat_select ) {
    if ( false !== strpos( $form, 'wpide-search-cat' ) ) {
        return $form;
    }

    // Before the search button, or before the end of the form when there is no button.
    $count = 0;
    $form  = preg_replace( '#(<button|<input[^>]+type=["\']submit)#i', $wpide_search_cat_select() . '$1', $form, 1, $count );

    return $count ? $form : str_replace( '</form>', $wpide_search_cat_select() . '</form>', $form );
};

add_filter( 'get_search_form', $wpide_search_cat_insert );
add_filter( 'render_block_core/search', $wpide_search_cat_insert );

add_action( 'wp_head', function () {
    echo '<style>.wpide-search-cat{max-width:100%;margin:0 .25em}.wp-block-search__inside-wrapper .wpide-search-cat{border:0;background:transparent}</style>';
} );

// Text before the suggestion.
$wpide_dym_label = 'Did you mean';

$wpide_dym_vocabulary = function () {
    $words = get_transient( 'wpide_dym_words' );

    if ( is_array( $words ) ) {
        return $words;
    }

    global $wpdb;

    $types  = array_values( get_post_types( array( 'exclude_from_search' => false ) ) );
    $holder = implode( ',', array_fill( 0, count( $types ), '%s' ) );
    $titles = $wpdb->get_col( $wpdb->prepare( "SELECT post_title FROM {$wpdb->posts} WHERE post_status = 'publish' AND post_type IN ($holder) ORDER BY post_date DESC LIMIT 3000", $types ) ); // phpcs:ignore WordPress.DB

    $words = array();

    foreach ( $titles as $title ) {
        foreach ( preg_split( '/[^\p{L}\p{N}]+/u', strtolower( $title ), -1, PREG_SPLIT_NO_EMPTY ) as $word ) {
            if ( strlen( $word ) > 2 ) {
                $words[ $word ] = true;
            }
        }
    }

    $words = array_keys( $words );
    set_transient( 'wpide_dym_words', $words, DAY_IN_SECONDS );

    return $words;
};

add_action( 'save_post', function ( $post_id, $post ) {
    if ( 'publish' === $post->post_status ) {
        delete_transient( 'wpide_dym_words' );
    }
}, 10, 2 );

$wpide_dym_html = function () use ( $wpide_dym_vocabulary, $wpide_dym_label ) {
    static $html = null;

    if ( null !== $html ) {
        return $html;
    }

    $html  = '';
    $terms = (array) get_query_var( 'search_terms' );
    $vocab = $wpide_dym_vocabulary();

    if ( ! $terms || ! $vocab || count( $terms ) > 6 ) {
        return $html;
    }

    $lookup  = array_flip( $vocab );
    $changed = false;
    $fixed   = array();

    foreach ( $terms as $term ) {
        $term = strtolower( $term );
        $best = $term;

        if ( strlen( $term ) > 3 && ! isset( $lookup[ $term ] ) ) {
            // Allow 1 typo in short words and 2 in longer ones.
            $limit = strlen( $term ) >= 7 ? 2 : 1;
            $score = $limit + 1;

            foreach ( $vocab as $word ) {
                if ( abs( strlen( $word ) - strlen( $term ) ) > $limit ) {
                    continue;
                }

                $distance = levenshtein( $term, $word );

                if ( $distance < $score ) {
                    $score = $distance;
                    $best  = $word;
                }
            }
        }

        $changed = $changed || $best !== $term;
        $fixed[] = $best;
    }

    if ( $changed ) {
        $suggestion = implode( ' ', $fixed );
        $html       = '<p class="wpide-did-you-mean">' . esc_html( $wpide_dym_label ) . ' <a href="' . esc_url( get_search_link( $suggestion ) ) . '"><strong>' . esc_html( $suggestion ) . '</strong></a>?</p>';
    }

    return $html;
};

// Classic themes: printed where the "nothing found" message starts.
add_action( 'loop_no_results', function ( $query ) use ( $wpide_dym_html ) {
    static $printed = false;

    if ( $printed || wp_is_block_theme() || ! $query->is_main_query() || ! $query->is_search() ) {
        return;
    }

    $printed = true;
    echo $wpide_dym_html(); // phpcs:ignore WordPress.Security.EscapeOutput -- escaped when built.
} );

// Block themes: added to the Query block's "No results" area.
add_filter( 'render_block_core/query-no-results', function ( $content ) use ( $wpide_dym_html ) {
    return is_search() && '' !== trim( $content ) ? $wpide_dym_html() . $content : $content;
} );

add_filter( 'post_class', function ( $classes, $extra, $post_id ) {
    if ( is_search() && ! is_admin() ) {
        $classes[] = 'wpide-result-type-' . sanitize_html_class( get_post_type( $post_id ) );
    }

    return $classes;
}, 10, 3 );

add_action( 'wp_head', function () {
    if ( ! is_search() ) {
        return;
    }

    $css = '';

    foreach ( get_post_types( array( 'exclude_from_search' => false ), 'objects' ) as $type ) {
        $label = str_replace( array( '\\', '"', '<', '>' ), '', $type->labels->singular_name );

        $css .= '.wpide-result-type-' . sanitize_html_class( $type->name ) . ' :is(.entry-title,.wp-block-post-title)::before{content:"' . $label . '";}';
    }

    // A small pill in front of each result title, such as "Page" or "Product".
    $css .= '[class*="wpide-result-type-"] :is(.entry-title,.wp-block-post-title)::before{display:inline-block;margin-right:.5em;padding:.15em .6em;border-radius:999px;border:1px solid currentColor;font-size:.55em;font-weight:600;letter-spacing:.03em;line-height:1.4;text-transform:uppercase;vertical-align:middle}';

    echo '<style id="wpide-result-type-labels">' . $css . '</style>'; // phpcs:ignore WordPress.Security.EscapeOutput -- labels stripped of quotes and markup above.
} );

// File types to include, as the start of their MIME type: PDF, Word, Excel and PowerPoint by default. Add 'image/' for images.
$wpide_search_file_types = array( 'application/pdf', 'application/msword', 'application/vnd.openxmlformats-officedocument', 'application/vnd.ms-' );

add_action( 'pre_get_posts', function ( $query ) {
    if ( is_admin() || ! $query->is_main_query() || ! $query->is_search() ) {
        return;
    }

    $types = $query->get( 'post_type' );

    if ( $types && 'any' !== $types ) {
        $query->set( 'post_type', array_unique( array_merge( (array) $types, array( 'attachment' ) ) ) );
    }

    // Uploaded files have the status "inherit".
    $query->set( 'post_status', array( 'publish', 'inherit' ) );
    $query->set( 'wpide_search_files', true );
} );

add_filter( 'posts_where', function ( $where, $query ) use ( $wpide_search_file_types ) {
    global $wpdb;

    if ( ! $query->get( 'wpide_search_files' ) ) {
        return $where;
    }

    $mimes = array();

    foreach ( $wpide_search_file_types as $type ) {
        $mimes[] = $wpdb->prepare( "{$wpdb->posts}.post_mime_type LIKE %s", $wpdb->esc_like( $type ) . '%' );
    }

    $mimes = $mimes ? '(' . implode( ' OR ', $mimes ) . ')' : '1=0';

    // Files must have a matching type and be unattached or attached to published content; other "inherit" items (revisions) are left out.
    $where .= " AND ( {$wpdb->posts}.post_status = 'publish' OR ( {$wpdb->posts}.post_type = 'attachment' AND {$mimes} AND ( {$wpdb->posts}.post_parent = 0 OR {$wpdb->posts}.post_parent IN ( SELECT ID FROM ( SELECT ID FROM {$wpdb->posts} WHERE post_status = 'publish' ) AS wpide_published ) ) ) )";

    return $where;
}, 10, 2 );

// Extra words to ignore in multi-word searches, so "how can I reset my password" searches for "reset password".
$wpide_extra_stopwords = array( 'can', 'do', 'does', 'i', 'my', 'me', 'you', 'your', 'want', 'need', 'please', 'why', 'which', 'get' );
// Words WordPress ignores by default that matter on your site (for example 'who' for a band site).
$wpide_keep_words = array();

add_filter( 'wp_search_stopwords', function ( $stopwords ) use ( $wpide_extra_stopwords, $wpide_keep_words ) {
    $stopwords = array_merge( $stopwords, array_map( 'strtolower', $wpide_extra_stopwords ) );

    return array_values( array_diff( array_unique( $stopwords ), array_map( 'strtolower', $wpide_keep_words ) ) );
} );

add_filter( 'posts_search', function ( $search, $query ) {
    global $wpdb;

    if ( '' === $search || is_admin() || ! $query->is_main_query() || ! $query->is_search() ) {
        return $search;
    }

    $phrase = trim( (string) $query->get( 's' ) );

    if ( strlen( $phrase ) < 3 ) {
        return $search;
    }

    // Authors whose display name contains the search, for example "maria" finds posts by Maria Lopez.
    $authors = get_users( array(
        'search'              => '*' . $phrase . '*',
        'search_columns'      => array( 'display_name' ),
        'has_published_posts' => true,
        'number'              => 20,
        'fields'              => 'ID',
    ) );

    if ( ! $authors ) {
        return $search;
    }

    $password = '';
    $marker   = " AND ({$wpdb->posts}.post_password = '') ";

    if ( substr( $search, -strlen( $marker ) ) === $marker ) {
        $password = $marker;
        $search   = substr( $search, 0, -strlen( $marker ) );
    }

    $inner = preg_replace( '/^\s*AND\s*/', '', $search );
    $ids   = implode( ',', array_map( 'absint', $authors ) );

    return " AND ( {$wpdb->posts}.post_author IN ({$ids}) OR {$inner} ){$password}";
}, 10, 2 );

// Label of the checkbox; %s is the category name.
$wpide_search_in_cat_label = 'Only in %s';

$wpide_search_in_cat = function ( $form ) use ( $wpide_search_in_cat_label ) {
    $cat_id = is_category() ? get_queried_object_id() : ( is_search() ? absint( get_query_var( 'cat' ) ) : 0 );
    $cat    = $cat_id ? get_category( $cat_id ) : null;

    if ( ! $cat || is_wp_error( $cat ) || false !== strpos( $form, 'wpide-search-in-cat' ) ) {
        return $form;
    }

    $box = '<label class="wpide-search-in-cat" style="display:block;flex-basis:100%;margin-top:.4em;font-size:.9em;"><input type="checkbox" name="cat" value="' . esc_attr( $cat->term_id ) . '" checked /> ' . esc_html( sprintf( $wpide_search_in_cat_label, $cat->name ) ) . '</label>';

    return str_replace( '</form>', $box . '</form>', $form );
};

add_filter( 'get_search_form', $wpide_search_in_cat );
add_filter( 'render_block_core/search', $wpide_search_in_cat );

add_filter( 'posts_where', function ( $where, $query ) {
    global $wpdb;

    if ( is_admin() || ! $query->is_main_query() || ! $query->is_search() ) {
        return $where;
    }

    // Yoast SEO: "Allow search engines to show this content" set to No.
    if ( defined( 'WPSEO_VERSION' ) ) {
        $where .= " AND NOT EXISTS ( SELECT 1 FROM {$wpdb->postmeta} wpide_ny WHERE wpide_ny.post_id = {$wpdb->posts}.ID AND wpide_ny.meta_key = '_yoast_wpseo_meta-robots-noindex' AND wpide_ny.meta_value = '1' )";
    }

    // Rank Math: "No Index" ticked in the robots meta.
    if ( defined( 'RANK_MATH_VERSION' ) ) {
        $where .= " AND NOT EXISTS ( SELECT 1 FROM {$wpdb->postmeta} wpide_nr WHERE wpide_nr.post_id = {$wpdb->posts}.ID AND wpide_nr.meta_key = 'rank_math_robots' AND wpide_nr.meta_value LIKE '%noindex%' )";
    }

    return $where;
}, 10, 2 );

// Blog posts older than this many months are left out of search results. Pages and other content types are not affected.
$wpide_search_max_age_months = 36;

add_filter( 'posts_where', function ( $where, $query ) use ( $wpide_search_max_age_months ) {
    global $wpdb;

    if ( $wpide_search_max_age_months < 1 || is_admin() || ! $query->is_main_query() || ! $query->is_search() ) {
        return $where;
    }

    $cutoff = wp_date( 'Y-m-d H:i:s', strtotime( '-' . absint( $wpide_search_max_age_months ) . ' months' ) );

    return $where . $wpdb->prepare( " AND ( {$wpdb->posts}.post_type <> 'post' OR {$wpdb->posts}.post_date >= %s )", $cutoff );
}, 10, 2 );

// Search words => page to open instead of the results. Matching ignores upper/lower case. Empty = off. Examples:
// 'contact'  => '/contact/',
// 'opening hours' => '/visit/#hours',
$wpide_search_shortcuts = array();

add_action( 'template_redirect', function () use ( $wpide_search_shortcuts ) {
    if ( ! $wpide_search_shortcuts || ! is_search() || is_paged() ) {
        return;
    }

    $phrase = strtolower( trim( preg_replace( '/\s+/', ' ', (string) get_search_query( false ) ) ) );

    foreach ( $wpide_search_shortcuts as $words => $target ) {
        if ( strtolower( trim( $words ) ) === $phrase ) {
            wp_safe_redirect( preg_match( '#^https?://#i', $target ) ? $target : home_url( $target ), 302 );
            exit;
        }
    }
} );

// Size of the author photo in pixels.
$wpide_author_archive_avatar = 96;

$wpide_author_archive_box = function () use ( $wpide_author_archive_avatar ) {
    $user = get_queried_object();

    if ( ! $user instanceof WP_User ) {
        return '';
    }

    $bio     = get_the_author_meta( 'description', $user->ID );
    $website = $user->user_url;
    $count   = count_user_posts( $user->ID, 'post', true );

    $html  = '<section class="wpide-author-intro" style="display:flex;flex-wrap:wrap;gap:1em;align-items:flex-start;margin:0 0 2em;padding:1.25em;border:1px solid rgba(127,127,127,.3);border-radius:8px;">';
    $html .= get_avatar( $user->ID, $wpide_author_archive_avatar, '', '', array( 'extra_attr' => 'style="border-radius:50%;flex:0 0 auto;"' ) );
    $html .= '<div style="flex:1 1 240px;min-width:0;">';
    $html .= '<p style="margin:0 0 .25em;"><strong>' . esc_html( $user->display_name ) . '</strong> · ' . esc_html( sprintf( _n( '%s post', '%s posts', $count ), number_format_i18n( $count ) ) ) . '</p>';

    if ( '' !== $bio ) {
        $html .= wpautop( wp_kses_post( $bio ) );
    }

    if ( $website ) {
        $html .= '<p style="margin:.5em 0 0;"><a href="' . esc_url( $website ) . '" rel="me">' . esc_html( preg_replace( '#^https?://(www\.)?#', '', untrailingslashit( $website ) ) ) . '</a></p>';
    }

    return $html . '</div></section>';
};

// Classic themes: before the list of posts.
add_action( 'loop_start', function ( $query ) use ( $wpide_author_archive_box ) {
    static $done = false;

