// Adds an "Archive intros" section to Settings > Reading with a text box for every custom post type that has an archive.
$wpide_archive_intro_types = function () {
    return array_filter( get_post_types( array( 'public' => true, '_builtin' => false ), 'objects' ), function ( $type ) {
        return ! empty( $type->has_archive );
    } );
};

add_action( 'admin_init', function () use ( $wpide_archive_intro_types ) {
    $types = $wpide_archive_intro_types();

    if ( ! $types ) {
        return;
    }

    register_setting( 'reading', 'wpide_archive_intros', array(
        'type'              => 'array',
        'default'           => array(),
        'sanitize_callback' => function ( $value ) {
            $clean = array();

            foreach ( (array) $value as $type => $html ) {
                if ( post_type_exists( $type ) && '' !== trim( (string) $html ) ) {
                    $clean[ sanitize_key( $type ) ] = wp_kses_post( $html );
                }
            }

            return $clean;
        },
    ) );

    add_settings_section( 'wpide_archive_intros', 'Archive intros', function () {
        echo '<p>Text shown at the top of each content type\'s archive page. Basic HTML is allowed.</p>';
    }, 'reading' );

    $saved = (array) get_option( 'wpide_archive_intros', array() );

    foreach ( $types as $type ) {
        add_settings_field( 'wpide_archive_intro_' . $type->name, esc_html( $type->labels->name ), function () use ( $type, $saved ) {
            printf(
                '<textarea name="wpide_archive_intros[%1$s]" id="wpide_archive_intro_%1$s" rows="4" class="large-text">%2$s</textarea><p class="description"><a href="%3$s">%3$s</a></p>',
                esc_attr( $type->name ),
                esc_textarea( isset( $saved[ $type->name ] ) ? $saved[ $type->name ] : '' ),
                esc_url( get_post_type_archive_link( $type->name ) )
            );
        }, 'reading', 'wpide_archive_intros', array( 'label_for' => 'wpide_archive_intro_' . $type->name ) );
    }
} );

// The saved intro for the post type archive being viewed (first page only).
$wpide_archive_intro_text = function () {
    if ( ! is_post_type_archive() || is_paged() ) {
        return '';
    }

    $type   = get_query_var( 'post_type' );
    $type   = is_array( $type ) ? reset( $type ) : $type;
    $intros = (array) get_option( 'wpide_archive_intros', array() );

    return ! empty( $intros[ $type ] ) ? wpautop( wp_kses_post( $intros[ $type ] ) ) : '';
};

// Classic themes that print the archive description.
add_filter( 'get_the_archive_description', function ( $description ) use ( $wpide_archive_intro_text ) {
    $intro = $wpide_archive_intro_text();

    return '' !== $intro ? $intro : $description;
} );

// Block themes: after the archive title.
add_filter( 'render_block_core/query-title', function ( $content ) use ( $wpide_archive_intro_text ) {
    $intro = wp_is_block_theme() ? $wpide_archive_intro_text() : '';

    return '' !== $intro ? $content . '<div class="wpide-archive-intro">' . $intro . '</div>' : $content;
} );

add_action( 'template_redirect', function () {
    global $wp_query;

    if ( ! is_author() ) {
        return;
    }

    $user = get_queried_object();

    if ( ! $user instanceof WP_User ) {
        return;
    }

    // Users who never published anything (subscribers, customers, new staff) get no public profile page.
    $types = array_values( get_post_types( array( 'public' => true ) ) );

    if ( count_user_posts( $user->ID, $types, true ) > 0 ) {
        return;
    }

    $wp_query->set_404();
    status_header( 404 );
    nocache_headers();
}, 1 );

