// Example: array( 'my-novel', 'beginner-course' )
$wpide_oldest_first_categories = array();

add_action( 'pre_get_posts', function ( $query ) use ( $wpide_oldest_first_categories ) {
    if ( ! $wpide_oldest_first_categories || is_admin() || ! $query->is_main_query() || ! $query->is_category( $wpide_oldest_first_categories ) ) {
