$wpide_cat_image_save = function ( $term_id ) {
    if ( ! isset( $_POST['wpide_cat_image_nonce'] ) || ! wp_verify_nonce( sanitize_key( $_POST['wpide_cat_image_nonce'] ), 'wpide_cat_image' ) || ! current_user_can( 'manage_categories' ) ) {
        return;
    }

    $image_id = isset( $_POST['wpide_header_image_id'] ) ? absint( $_POST['wpide_header_image_id'] ) : 0;

    if ( $image_id && wp_attachment_is_image( $image_id ) ) {
        update_term_meta( $term_id, 'wpide_header_image_id', $image_id );
    } else {
        delete_term_meta( $term_id, 'wpide_header_image_id' );
    }
};

add_action( 'created_category', $wpide_cat_image_save );
add_action( 'edited_category', $wpide_cat_image_save );

add_action( 'admin_enqueue_scripts', function ( $hook ) {
    if ( ! in_array( $hook, array( 'edit-tags.php', 'term.php' ), true ) || 'category' !== get_current_screen()->taxonomy ) {
        return;
    }

    wp_enqueue_media();
    $script = <<<'JS'
jQuery( function ( $ ) {
    var style = 'max-width:300px;height:auto;display:block;margin-bottom:8px;';

    $( document ).on( 'click', '.wpide-cat-image__choose', function ( e ) {
        e.preventDefault();

        var box   = $( this ).closest( '.wpide-cat-image' );
        var frame = wp.media( { title: 'Header image', library: { type: 'image' }, multiple: false } );

        frame.on( 'select', function () {
            var img = frame.state().get( 'selection' ).first().toJSON();
            var src = img.sizes && img.sizes.medium ? img.sizes.medium.url : img.url;

            box.find( 'input' ).val( img.id );
            box.find( '.wpide-cat-image__preview' ).html( $( '<img>', { src: src, alt: '', style: style } ) );
            box.find( '.wpide-cat-image__remove' ).prop( 'hidden', false );
        } );

        frame.open();
    } );

    $( document ).on( 'click', '.wpide-cat-image__remove', function ( e ) {
        e.preventDefault();

        var box = $( this ).closest( '.wpide-cat-image' );

        box.find( 'input' ).val( '' );
        box.find( '.wpide-cat-image__preview' ).empty();
        $( this ).prop( 'hidden', true );
    } );

    // The "Add New Category" form is submitted with AJAX; clear the picker afterwards.
    $( document ).ajaxComplete( function ( event, xhr, options ) {
        if ( options.data && 'string' === typeof options.data && -1 !== options.data.indexOf( 'action=add-tag' ) ) {
            $( '#addtag .wpide-cat-image input' ).val( '' );
            $( '#addtag .wpide-cat-image__preview' ).empty();
            $( '#addtag .wpide-cat-image__remove' ).prop( 'hidden', true );
        }
    } );
} );
JS;

    wp_add_inline_script( 'media-editor', $script );
} );

