// Templates for categories and other hierarchical taxonomies fall back to the parent term's template:
// /category/news/local/ uses category-news.php (or the category-news block template) when there is no category-local one.
foreach ( array( 'category', 'taxonomy' ) as $wpide_tpl_type ) {
    add_filter( $wpide_tpl_type . '_template_hierarchy', function ( $templates ) {
        $term = get_queried_object();

        if ( ! $term instanceof WP_Term || ! $term->parent || ! is_taxonomy_hierarchical( $term->taxonomy ) ) {
            return $templates;
        }

        $prefix = 'category' === $term->taxonomy ? 'category-' : 'taxonomy-' . $term->taxonomy . '-';
        $extra  = array();

        foreach ( get_ancestors( $term->term_id, $term->taxonomy, 'taxonomy' ) as $ancestor_id ) {
            $ancestor = get_term( $ancestor_id, $term->taxonomy );

            if ( $ancestor && ! is_wp_error( $ancestor ) ) {
                $extra[] = $prefix . rawurldecode( $ancestor->slug ) . '.php';
                $extra[] = $prefix . $ancestor->term_id . '.php';
            }
        }

        // Right after the term's own templates, before the generic ones.
        $own = array( $prefix . rawurldecode( $term->slug ) . '.php', $prefix . $term->slug . '.php', $prefix . $term->term_id . '.php' );
        $pos = 0;

        foreach ( $templates as $i => $file ) {
            if ( in_array( $file, $own, true ) ) {
                $pos = $i + 1;
            }
        }

        array_splice( $templates, $pos, 0, $extra );

        return array_values( array_unique( $templates ) );
    } );
}

// Heading level used for the year dividers.
$wpide_year_heading_tag = 'h2';

add_action( 'the_post', function ( $post, $query ) use ( $wpide_year_heading_tag ) {
    static $last = null;

    // Classic themes only; lists in date order only (blog, category, tag and other archives).
    if ( wp_is_block_theme() || is_admin() || ! $query->is_main_query() || ! ( $query->is_home() || $query->is_archive() ) || $query->is_year() || ! in_array( $query->get( 'orderby' ), array( '', 'date', 'post_date' ), true ) || ! in_the_loop() ) {
        return;
    }

    $year = get_the_date( 'Y', $post );

    if ( $year === $last ) {
        return;
    }

    // No divider above the first post on the first page when it is from the current year.
    $show = null !== $last || $query->is_paged() || wp_date( 'Y' ) !== $year;
    $last = $year;

    if ( $show ) {
        $tag = in_array( $wpide_year_heading_tag, array( 'h2', 'h3', 'h4', 'p' ), true ) ? $wpide_year_heading_tag : 'h2';

        echo '<' . $tag . ' class="wpide-year-divider" style="margin:2em 0 1em;padding-bottom:.25em;border-bottom:1px solid rgba(127,127,127,.35);font-size:1.25em;">' . esc_html( $year ) . '</' . $tag . '>'; // phpcs:ignore WordPress.Security.EscapeOutput -- tag from a fixed list.
    }
}, 10, 2 );

// Show the "View all" option only when the archive has no more than this many posts.
$wpide_view_all_max = 150;
// Link text; %d is the number of posts.
$wpide_view_all_label = 'View all %d posts on one page';

$wpide_view_all_on = function () {
    return isset( $_GET['view'] ) && 'all' === sanitize_key( wp_unslash( $_GET['view'] ) );
};

add_action( 'pre_get_posts', function ( $query ) use ( $wpide_view_all_max, $wpide_view_all_on ) {
    if ( ! $wpide_view_all_on() || is_admin() || ! $query->is_main_query() || ! $query->is_archive() ) {
        return;
    }

    $query->set( 'posts_per_page', absint( $wpide_view_all_max ) );
    $query->set( 'paged', 1 );
} );

// The single-page copy is for readers; search engines keep the normal paginated pages.
add_filter( 'wp_robots', function ( $robots ) use ( $wpide_view_all_on ) {
    if ( $wpide_view_all_on() ) {
        $robots['noindex'] = true;
        $robots['follow']  = true;
    }

    return $robots;
} );

$wpide_view_all_link = function () use ( $wpide_view_all_max, $wpide_view_all_label ) {
    global $wp_query;

    if ( ! is_archive() || isset( $_GET['view'] ) || $wp_query->max_num_pages < 2 || $wp_query->found_posts > $wpide_view_all_max ) {
        return '';
    }

    $url = add_query_arg( 'view', 'all', get_pagenum_link( 1, false ) );

    return '<p class="wpide-view-all" style="text-align:center;margin:1.5em 0;"><a href="' . esc_url( $url ) . '">' . esc_html( sprintf( $wpide_view_all_label, (int) $wp_query->found_posts ) ) . '</a></p>';
};

// Classic themes: after the last post.
add_action( 'loop_end', function ( $query ) use ( $wpide_view_all_link ) {
    static $done = false;

    if ( $done || wp_is_block_theme() || ! $query->is_main_query() ) {
        return;
    }

    $done = true;
    echo $wpide_view_all_link(); // phpcs:ignore WordPress.Security.EscapeOutput -- escaped when built.
} );

// Block themes: after the page numbers.
add_filter( 'render_block_core/query-pagination', function ( $content ) use ( $wpide_view_all_link ) {
    static $done = false;

    if ( $done || '' === trim( $content ) ) {
        return $content;
    }

    $done = true;

    return $content . $wpide_view_all_link();
} );

// Hierarchical post types whose archive lists only top-level items (child items stay reachable through their parents).
// Empty = every public hierarchical custom post type with an archive.
$wpide_top_level_archive_types = array();

add_action( 'pre_get_posts', function ( $query ) use ( $wpide_top_level_archive_types ) {
    if ( is_admin() || ! $query->is_main_query() || ! $query->is_post_type_archive() ) {
        return;
    }

    $type = $query->get( 'post_type' );
    $type = is_array( $type ) ? reset( $type ) : $type;
    $obj  = $type ? get_post_type_object( $type ) : null;

    if ( ! $obj || ! $obj->hierarchical || ( $wpide_top_level_archive_types && ! in_array( $type, $wpide_top_level_archive_types, true ) ) ) {
        return;
    }

    $query->set( 'post_parent', 0 );
} );
